 REFERENCES public.store_operating_version_stations(restaurant_id,version_id,station_id) ON DELETE CASCADE;

-- A transition table checks the entire deleted set, avoiding a lookup for
-- every baseline/assignment. A direct deletion rolls back even for an owner.
CREATE FUNCTION public.store_operating_guard_delete_v1() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM deleted_operating_rows d JOIN public.restaurants r ON r.id=d.restaurant_id) THEN
  RAISE EXCEPTION 'OPERATING_PROFILE_IMMUTABLE';
 END IF;
 RETURN NULL;
END;
$$;
REVOKE ALL ON FUNCTION public.store_operating_guard_delete_v1() FROM PUBLIC,anon,authenticated,service_role;

DROP TRIGGER operating_version_immutable ON public.store_operating_versions;
CREATE TRIGGER operating_version_immutable BEFORE UPDATE ON public.store_operating_versions
 FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TRIGGER operating_version_delete_guard AFTER DELETE ON public.store_operating_versions
 REFERENCING OLD TABLE AS deleted_operating_rows FOR EACH STATEMENT EXECUTE FUNCTION public.store_operating_guard_delete_v1();
DROP TRIGGER operating_membership_immutable ON public.store_operating_version_stations;
CREATE TRIGGER operating_membership_immutable BEFORE UPDATE ON public.store_operating_version_stations
 FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TRIGGER operating_membership_delete_guard AFTER DELETE ON public.store_operating_version_stations
 REFERENCING OLD TABLE AS deleted_operating_rows FOR EACH STATEMENT EXECUTE FUNCTION public.store_operating_guard_delete_v1();
DROP TRIGGER operating_assignment_immutable ON public.store_operating_version_assignments;
CREATE TRIGGER operating_assignment_immutable BEFORE UPDATE ON public.store_operating_version_assignments
 FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TRIGGER operating_assignment_delete_guard AFTER DELETE ON public.store_operating_version_assignments
 REFERENCING OLD TABLE AS deleted_operating_rows FOR EACH STATEMENT EXECUTE FUNCTION public.store_operating_guard_delete_v1();
DROP TRIGGER operating_area_immutable ON public.store_service_areas;
CREATE TRIGGER operating_area_immutable BEFORE UPDATE ON public.store_service_areas
 FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TRIGGER operating_area_delete_guard AFTER DELETE ON public.store_service_areas
 REFERENCING OLD TABLE AS deleted_operating_rows FOR EACH STATEMENT EXECUTE FUNCTION public.store_operating_guard_delete_v1();
DROP TRIGGER operating_station_immutable ON public.store_service_stations;
CREATE TRIGGER operating_station_immutable BEFORE UPDATE ON public.store_service_stations
 FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TRIGGER operating_station_delete_guard AFTER DELETE ON public.store_service_stations
 REFERENCING OLD TABLE AS deleted_operating_rows FOR EACH STATEMENT EXECUTE FUNCTION public.store_operating_guard_delete_v1();

DO $$ BEGIN
 IF has_function_privilege('authenticated','public.store_operating_guard_delete_v1()','EXECUTE')
 OR has_table_privilege('authenticated','public.store_operating_versions','DELETE')
 OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.store_operating_versions'::regclass
  AND conname='store_operating_versions_restaurant_id_fkey' AND confdeltype='c') THEN
  RAISE EXCEPTION 'OPERATING_PROFILE_PURGE_CONTRACT_INVALID';
 END IF;
END $$;

-- COMPONENT 20261021173000_batch_promotion_payment_allocations.sql
-- Preserve scheduled-promotion allocations using one VAT update per payment.
-- Complements the payment-core batch without changing authorization or totals.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
CREATE OR REPLACE FUNCTION public.process_payment_before_promotion_read_split(
 p_order_id uuid,p_store_id uuid,p_amount numeric,p_method text
) RETURNS public.payments LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth AS $$
DECLARE
 v_discount public.order_discounts%ROWTYPE;
 v_original_mode text;
 v_original_value numeric(12,2);
 v_allocation_total numeric(15,2);
 v_has_allocations boolean:=false;
 v_vat_pricing_mode text:='exclusive';
 v_payment public.payments%ROWTYPE;
BEGIN
 SELECT * INTO v_discount FROM public.order_discounts discount
 WHERE discount.order_id=p_order_id AND discount.restaurant_id=p_store_id AND discount.status='active' FOR UPDATE;
 IF FOUND AND v_discount.approved_via='scheduled_promotion' THEN
  SELECT count(*)>0,round(coalesce(sum(allocation.discount_amount),0),2)
  INTO v_has_allocations,v_allocation_total FROM public.order_discount_lines allocation
  WHERE allocation.order_discount_id=v_discount.id;
  IF v_has_allocations AND v_allocation_total IS DISTINCT FROM round(v_discount.discount_amount,2) THEN
   RAISE EXCEPTION 'PROMOTION_ALLOCATION_MISMATCH';
  END IF;
 END IF;
 IF v_has_allocations THEN
  v_original_mode:=v_discount.discount_mode;
  v_original_value:=v_discount.discount_value;
  UPDATE public.order_discounts SET discount_mode='amount',discount_value=v_allocation_total,
   discount_amount=v_allocation_total,updated_at=now() WHERE id=v_discount.id;
 END IF;
 v_payment:=public.process_payment_without_scoped_promotions(p_order_id,p_store_id,p_amount,p_method);
 IF NOT v_has_allocations THEN RETURN v_payment; END IF;
 UPDATE public.order_discounts SET discount_mode=v_original_mode,discount_value=v_original_value,
  discount_amount=v_allocation_total,updated_at=now() WHERE id=v_discount.id;
 SELECT coalesce(restaurant.vat_pricing_mode,'exclusive') INTO v_vat_pricing_mode
 FROM public.restaurants restaurant WHERE restaurant.id=p_store_id;
 WITH priced AS MATERIALIZED (
  SELECT item.id,public.direct_order_payment_vat(
   coalesce(item.vat_profile_snapshot,jsonb_build_array(jsonb_build_object('rate',menu.effective_vat_rate,'weight',1))),
   round(item.unit_price*item.quantity,2),v_vat_pricing_mode,coalesce(allocation.discount_amount,0)) tax
  FROM public.order_items item
  LEFT JOIN public.menu_items menu ON menu.id=item.menu_item_id
  LEFT JOIN public.order_discount_lines allocation ON allocation.order_discount_id=v_discount.id AND allocation.order_item_id=item.id
  WHERE item.order_id=p_order_id AND item.restaurant_id=p_store_id AND item.status<>'cancelled'
   AND item.item_type='menu_item' AND coalesce(item.is_service_item,false)=false
 ) UPDATE public.order_items item SET vat_rate=(p.tax->>'vat_rate')::numeric,vat_amount=(p.tax->>'vat')::numeric,
  total_amount_ex_tax=(p.tax->>'supply')::numeric,paying_amount_inc_tax=(p.tax->>'total')::numeric,vat_breakdown=p.tax->'parts'
 FROM priced p WHERE item.id=p.id;
 RETURN v_payment;
END;
$$;
DO $$ BEGIN
 IF has_function_privilege('anon','public.process_payment_before_promotion_read_split(uuid,uuid,numeric,text)','EXECUTE') THEN
  RAISE EXCEPTION 'OPERATING_PAYMENT_WRAPPER_ACCESS_INVALID';
 END IF;
END $$;

-- COMPONENT 20261021180000_registered_menu_choices.sql
-- Registered selections are data, not one column or sellable menu per taste.
-- Empty definitions preserve the exact legacy key and all existing sellable IDs.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';

ALTER TABLE public.menu_items ADD COLUMN choice_definition jsonb NOT NULL DEFAULT '{}';

CREATE FUNCTION public.menu_choice_definition_valid(p_definition jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $$
BEGIN
 IF p_definition='{}'::jsonb THEN RETURN true; END IF;
 IF p_definition IS NULL OR jsonb_typeof(p_definition)<>'object' OR octet_length(p_definition::text)>16384
  OR p_definition->>'schema_version' IS DISTINCT FROM '1' OR jsonb_typeof(p_definition->'groups') IS DISTINCT FROM 'array'
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_definition)k WHERE k NOT IN('schema_version','groups','rules')) THEN RETURN false; END IF;
 IF jsonb_array_length(p_definition->'groups') NOT BETWEEN 1 AND 8
  OR jsonb_typeof(coalesce(p_definition->'rules','[]'))<>'array' THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'groups')g WHERE jsonb_typeof(g)<>'object'
  OR coalesce(g->>'id','') !~ '^[A-Za-z0-9_-]{1,64}$'
  OR coalesce(g->>'min','') !~ '^[0-8]$' OR coalesce(g->>'max','') !~ '^[1-8]$'
  OR coalesce(g->>'min','0')::int>coalesce(g->>'max','0')::int
  OR jsonb_typeof(g->'values') IS DISTINCT FROM 'array'
  OR jsonb_typeof(g->'channels') IS DISTINCT FROM 'array'
  OR jsonb_typeof(g->'repeat') IS DISTINCT FROM 'boolean'
  OR coalesce(length(g->>'name_ko'),0) NOT BETWEEN 1 AND 80
  OR coalesce(length(g->>'name_vi'),0) NOT BETWEEN 1 AND 80
  OR coalesce(length(g->>'name_en'),0) NOT BETWEEN 1 AND 80
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(g)k WHERE k NOT IN('id','min','max','values','channels','repeat','name_ko','name_vi','name_en'))
 ) THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'groups')g
  WHERE jsonb_array_length(g->'values') NOT BETWEEN 1 AND 32 OR jsonb_array_length(g->'channels') NOT BETWEEN 1 AND 3
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(g->'channels')c WHERE c NOT IN('pos','qr','direct'))
   OR (SELECT count(DISTINCT c) FROM jsonb_array_elements_text(g->'channels')c)<>jsonb_array_length(g->'channels'))
 OR (SELECT count(DISTINCT g->>'id') FROM jsonb_array_elements(p_definition->'groups')g)<>jsonb_array_length(p_definition->'groups')
 THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'groups')g CROSS JOIN LATERAL jsonb_array_elements(g->'values')v
  WHERE jsonb_typeof(v)<>'object' OR coalesce(v->>'id','') !~ '^[A-Za-z0-9_-]{1,64}$'
   OR jsonb_typeof(v->'available') IS DISTINCT FROM 'boolean'
   OR coalesce(v->>'price_delta','') !~ '^[0-9]{1,9}(\.[0-9]{1,2})?$'
   OR coalesce(v->>'default_quantity','0') !~ '^[0-8]$'
   OR coalesce(length(v->>'name_ko'),0) NOT BETWEEN 1 AND 80
   OR coalesce(length(v->>'name_vi'),0) NOT BETWEEN 1 AND 80
   OR coalesce(length(v->>'name_en'),0) NOT BETWEEN 1 AND 80
   OR jsonb_typeof(coalesce(v->'recipe_additions','[]'))<>'array'
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(v)k WHERE k NOT IN('id','name_ko','name_vi','name_en','price_delta','available','default_quantity','recipe_additions'))
 ) THEN RETURN false; END IF;
 IF (SELECT count(*)>64 OR count(*)<>count(DISTINCT v->>'id')
  FROM jsonb_array_elements(p_definition->'groups')g CROSS JOIN LATERAL jsonb_array_elements(g->'values')v)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'groups')g WHERE
   (SELECT sum(coalesce((v->>'default_quantity')::int,0)) FROM jsonb_array_elements(g->'values')v)>(g->>'max')::int
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(g->'values')v WHERE
    (NOT (g->>'repeat')::boolean AND coalesce((v->>'default_quantity')::int,0)>1)
    OR (NOT (v->>'available')::boolean AND coalesce((v->>'default_quantity')::int,0)>0)
    OR jsonb_array_length(coalesce(v->'recipe_additions','[]'))>8)) THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'groups')g
  CROSS JOIN LATERAL jsonb_array_elements(g->'values')v CROSS JOIN LATERAL jsonb_array_elements(coalesce(v->'recipe_additions','[]'))r
  WHERE jsonb_typeof(r)<>'object' OR coalesce(r->>'ingredient_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   OR coalesce(r->>'quantity_g','') !~ '^[0-9]{1,6}(\.[0-9]{1,3})?$' OR (r->>'quantity_g')::numeric<=0
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(r)k WHERE k NOT IN('ingredient_id','quantity_g')))
 THEN RETURN false; END IF;
 IF jsonb_array_length(coalesce(p_definition->'rules','[]'))>32 OR EXISTS(
  WITH ids AS (SELECT v->>'id' id FROM jsonb_array_elements(p_definition->'groups')g CROSS JOIN LATERAL jsonb_array_elements(g->'values')v)
  SELECT 1 FROM jsonb_array_elements(coalesce(p_definition->'rules','[]'))r WHERE jsonb_typeof(r)<>'object'
   OR r->>'kind' NOT IN('requires','excludes') OR coalesce(r->>'kind','')=''
   OR r->>'from'=r->>'to' OR NOT EXISTS(SELECT 1 FROM ids WHERE id=r->>'from')
   OR NOT EXISTS(SELECT 1 FROM ids WHERE id=r->>'to')
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(r)k WHERE k NOT IN('kind','from','to'))
 ) THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN false;
END $$;
ALTER TABLE public.menu_items ADD CONSTRAINT menu_choice_definition_valid CHECK(public.menu_choice_definition_valid(choice_definition));

CREATE FUNCTION public.menu_choice_catalog_key(p_legacy text,p_definition jsonb,p_price numeric) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT CASE WHEN p_definition='{}'::jsonb THEN p_legacy ELSE jsonb_build_object(
  'schema',2,'legacy_key',p_legacy,'definition_revision',md5(p_definition::text),
  'definition',jsonb_set(p_definition,'{groups}',(SELECT jsonb_agg(jsonb_set(g,'{values}',
    (SELECT jsonb_agg(v-'recipe_additions' ORDER BY vo) FROM jsonb_array_elements(g->'values') WITH ORDINALITY vals(v,vo))) ORDER BY go)
   FROM jsonb_array_elements(p_definition->'groups') WITH ORDINALITY groups(g,go))),
  'base_price',p_price)::text END;
$$;
ALTER TABLE public.menu_items ALTER COLUMN menu_option_key SET EXPRESSION AS
 (public.menu_choice_catalog_key(public.menu_meal_option_key(id,size_parent_id,size_prices,option_base_names,
  portion_code,spice_level,spice_choice,price,meal_choices,meal_choice),choice_definition,price));

-- Pure per-line normalization; database rows are fetched/locked once per batch.
CREATE FUNCTION public.menu_choice_snapshot(p_menu jsonb,p_key text,p_channel text) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $$
DECLARE definition jsonb:=p_menu->'choice_definition'; chosen jsonb; request jsonb; result jsonb;
BEGIN
 IF coalesce(definition,'{}')='{}'::jsonb THEN RETURN '{}'::jsonb; END IF;
 IF p_channel IS NULL OR p_channel NOT IN('pos','qr','direct') THEN RAISE EXCEPTION 'MENU_SELECTION_CHANNEL_INVALID'; END IF;
 BEGIN request:=p_key::jsonb;
 EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'MENU_SELECTION_REQUIRED'; END;
 IF request->>'schema' IS DISTINCT FROM '2' OR request->>'revision' IS DISTINCT FROM md5(p_menu->>'menu_option_key')
  OR jsonb_typeof(request->'selected') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'MENU_SELECTION_CHANGED'; END IF;
 chosen:=request->'selected';
 IF jsonb_array_length(chosen)>64 OR EXISTS(SELECT 1 FROM jsonb_array_elements(chosen)c
  WHERE jsonb_typeof(c)<>'object' OR coalesce(c->>'quantity','') !~ '^[1-8]$'
   OR coalesce(c->>'value_id','') !~ '^[A-Za-z0-9_-]{1,64}$'
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(c)k WHERE k NOT IN('value_id','quantity')))
 OR (SELECT count(DISTINCT c->>'value_id') FROM jsonb_array_elements(chosen)c)<>jsonb_array_length(chosen)
 THEN RAISE EXCEPTION 'MENU_SELECTION_INVALID'; END IF;
 IF EXISTS(
  WITH available AS (SELECT g,v FROM jsonb_array_elements(definition->'groups')g CROSS JOIN LATERAL jsonb_array_elements(g->'values')v)
  SELECT 1 FROM jsonb_array_elements(chosen)c LEFT JOIN available a ON a.v->>'id'=c->>'value_id'
  WHERE a.v IS NULL OR NOT (a.v->>'available')::boolean OR NOT (a.g->'channels' ? p_channel)
   OR (NOT (a.g->>'repeat')::boolean AND (c->>'quantity')::int>1)
 ) OR EXISTS(
  SELECT 1 FROM jsonb_array_elements(definition->'groups')g
  LEFT JOIN LATERAL (SELECT coalesce(sum((c->>'quantity')::int),0) quantity
   FROM jsonb_array_elements(g->'values')v JOIN jsonb_array_elements(chosen)c ON v->>'id'=c->>'value_id')q ON true
  WHERE g->'channels' ? p_channel AND q.quantity NOT BETWEEN (g->>'min')::int AND (g->>'max')::int
 ) OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(definition->'rules','[]'))r
   WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(chosen)c WHERE c->>'value_id'=r->>'from')
    AND ((r->>'kind'='requires' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(chosen)c WHERE c->>'value_id'=r->>'to'))
      OR (r->>'kind'='excludes' AND EXISTS(SELECT 1 FROM jsonb_array_elements(chosen)c WHERE c->>'value_id'=r->>'to'))))
 THEN RAISE EXCEPTION 'MENU_SELECTION_INVALID'; END IF;
 WITH selected AS MATERIALIZED (
  SELECT g->>'id' group_id,gord,v,vord,(c->>'quantity')::int quantity FROM jsonb_array_elements(definition->'groups') WITH ORDINALITY groups(g,gord)
  CROSS JOIN LATERAL jsonb_array_elements(g->'values') WITH ORDINALITY vals(v,vord)
  JOIN jsonb_array_elements(chosen)c ON c->>'value_id'=v->>'id'
 ), labels AS (
  SELECT coalesce(sum((v->>'price_delta')::numeric*quantity),0) extra,
   string_agg(v->>'name_ko'||CASE WHEN quantity>1 THEN ' ×'||quantity ELSE '' END,' · ' ORDER BY gord,vord) ko,
   string_agg(v->>'name_vi'||CASE WHEN quantity>1 THEN ' ×'||quantity ELSE '' END,' · ' ORDER BY gord,vord) vi,
   string_agg(v->>'name_en'||CASE WHEN quantity>1 THEN ' ×'||quantity ELSE '' END,' · ' ORDER BY gord,vord) en,
   coalesce(jsonb_agg(jsonb_build_object('group_id',group_id,'value_id',v->>'id','quantity',quantity,
    'name_ko',v->>'name_ko','name_vi',v->>'name_vi','name_en',v->>'name_en','price_delta',(v->>'price_delta')::numeric) ORDER BY gord,vord),'[]') choices
  FROM selected
 ), recipes AS (SELECT (r->>'ingredient_id')::uuid ingredient_id,sum((r->>'quantity_g')::numeric*s.quantity) quantity_g
  FROM selected s CROSS JOIN LATERAL jsonb_array_elements(coalesce(v->'recipe_additions','[]'))r GROUP BY (r->>'ingredient_id')::uuid)
 SELECT jsonb_build_object('choice_schema',1,'menu_item_id',p_menu->'id','catalog_revision',md5(p_menu->>'menu_option_key'),
  'selection_key',p_key,'choice_signature',md5(l.choices::text),'choices',l.choices,'unit_price',(p_menu->>'price')::numeric+l.extra,
  'name_ko',coalesce(nullif(p_menu->>'name_ko',''),p_menu->>'name')||coalesce(' ['||l.ko||']',''),
  'name_vi',coalesce(nullif(p_menu->>'name_vi',''),p_menu->>'name')||coalesce(' ['||l.vi||']',''),
  'name_en',coalesce(nullif(p_menu->>'name_en',''),p_menu->>'name')||coalesce(' ['||l.en||']',''),
  'recipe_additions',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY ingredient_id) FROM recipes r),'[]'))
 INTO result FROM labels l;
 RETURN result;
END $$;

CREATE FUNCTION public.admin_apply_menu_choices(p_item_id uuid,p_definition jsonb) RETURNS public.menu_items
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE m public.menu_items;
BEGIN
 SELECT * INTO m FROM public.menu_items WHERE id=p_item_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'MENU_ITEM_NOT_FOUND'; END IF;
 PERFORM public.require_admin_actor_for_restaurant(m.restaurant_id);
 IF m.size_parent_id IS NOT NULL OR NOT public.menu_choice_definition_valid(p_definition) THEN RAISE EXCEPTION 'MENU_SELECTION_DEFINITION_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(p_definition->'groups','[]'))g
  CROSS JOIN LATERAL jsonb_array_elements(g->'values')v CROSS JOIN LATERAL jsonb_array_elements(coalesce(v->'recipe_additions','[]'))r
  LEFT JOIN public.inventory_items i ON i.id=(r->>'ingredient_id')::uuid AND i.restaurant_id=m.restaurant_id
  WHERE i.id IS NULL) THEN RAISE EXCEPTION 'MENU_SELECTION_RECIPE_INVALID'; END IF;
 PERFORM id FROM public.menu_items WHERE id=p_item_id OR size_parent_id=p_item_id ORDER BY id FOR UPDATE;
 UPDATE public.menu_items SET choice_definition=p_definition,updated_at=now()
 WHERE (id=p_item_id OR size_parent_id=p_item_id) AND choice_definition IS DISTINCT FROM p_definition;
 SELECT * INTO m FROM public.menu_items WHERE id=p_item_id;
 INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,details)
 VALUES(auth.uid(),'menu_choices_registered','menu_items',p_item_id,jsonb_build_object('restaurant_id',m.restaurant_id,'revision',md5(m.menu_option_key)));
 RETURN m;
END $$;
REVOKE ALL ON FUNCTION public.menu_choice_snapshot(jsonb,text,text),public.admin_apply_menu_choices(uuid,jsonb)
 FROM PUBLIC,anon,authenticated,service_role;
-- The public registration RPCs below call the private atomic helper.
CREATE OR REPLACE FUNCTION public.admin_create_menu_item_with_options(
 p_store_id uuid,p_category_id uuid,p_name_ko text,p_name_vi text,p_name_en text,p_paperless_name_vi text,p_price numeric,
 p_options jsonb,p_sort_order integer DEFAULT 0,p_is_available boolean DEFAULT true,p_tax jsonb DEFAULT NULL,p_invoice_sale_unit text DEFAULT NULL
) RETURNS public.menu_items LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE m public.menu_items;
BEGIN
 IF p_options ? 'meal_choices' AND jsonb_typeof(p_options->'meal_choices')<>'boolean' THEN RAISE EXCEPTION 'MENU_ITEM_PRICE_INVALID'; END IF;
 m:=public.admin_create_menu_item_pre_meal_choices(p_store_id,p_category_id,p_name_ko,p_name_vi,p_name_en,p_paperless_name_vi,p_price,
  p_options-'meal_choices'-'choice_definition',p_sort_order,p_is_available,p_tax,p_invoice_sale_unit);
 UPDATE public.menu_items SET meal_choices=coalesce((p_options->>'meal_choices')::boolean,false) WHERE id=m.id RETURNING * INTO m;
 IF p_options ? 'choice_definition' THEN m:=public.admin_apply_menu_choices(m.id,p_options->'choice_definition'); END IF;
 RETURN m;
END $$;
CREATE OR REPLACE FUNCTION public.admin_update_menu_item_with_options(
 p_item_id uuid,p_name_ko text,p_name_vi text,p_name_en text,p_paperless_name_vi text,p_price numeric,p_options jsonb,p_tax jsonb DEFAULT NULL
) RETURNS public.menu_items LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE m public.menu_items;
BEGIN
 IF p_options ? 'meal_choices' AND jsonb_typeof(p_options->'meal_choices')<>'boolean' THEN RAISE EXCEPTION 'MENU_ITEM_PRICE_INVALID'; END IF;
 m:=public.admin_update_menu_item_pre_meal_choices(p_item_id,p_name_ko,p_name_vi,p_name_en,p_paperless_name_vi,p_price,p_options-'meal_choices'-'choice_definition',p_tax);
 IF p_options ? 'meal_choices' THEN UPDATE public.menu_items SET meal_choices=(p_options->>'meal_choices')::boolean WHERE id=m.id RETURNING * INTO m; END IF;
 IF p_options ? 'choice_definition' OR m.choice_definition<>'{}'::jsonb THEN
  m:=public.admin_apply_menu_choices(m.id,coalesce(p_options->'choice_definition',m.choice_definition));
 END IF;
 RETURN m;
END $$;
CREATE OR REPLACE FUNCTION "public"."menu_size_price_sync_batch"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF pg_trigger_depth()>1 THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM changed_sizes n JOIN public.menu_items p ON p.id=n.size_parent_id
   WHERE n.restaurant_id<>p.restaurant_id OR (NOT n.is_archived AND
    (n.price<>CASE WHEN p.size_prices='{}'::jsonb THEN p.price ELSE (p.size_prices->>n.portion_code)::numeric END
     OR n.meal_choices<>p.meal_choices OR n.choice_definition<>p.choice_definition))) THEN RAISE EXCEPTION 'MENU_SIZE_PRICE_MANAGED_BY_PARENT'; END IF;
 UPDATE public.menu_items c SET
  price=CASE WHEN p.size_prices='{}'::jsonb THEN p.price ELSE coalesce((p.size_prices->>c.portion_code)::numeric,c.price) END,
  name=p.option_base_names->>'name',name_ko=p.option_base_names->>'name_ko',name_vi=p.option_base_names->>'name_vi',name_en=p.option_base_names->>'name_en',
  paperless_name_vi=p.option_base_names->>'paperless_name_vi',option_base_names=p.option_base_names,
  spice_level=p.spice_level,spice_choice=p.spice_choice,meal_choices=p.meal_choices,choice_definition=p.choice_definition,
  meal_choice=CASE WHEN p.meal_choices AND c.meal_choice='' THEN 'noodles' WHEN NOT p.meal_choices AND c.meal_choice='noodles' THEN '' ELSE c.meal_choice END,
  category_id=p.category_id,description=p.description,image_url=p.image_url,image_storage_path=p.image_storage_path,
  is_available=p.is_available AND
   (CASE WHEN p.size_prices='{}'::jsonb THEN c.portion_code=p.portion_code ELSE p.size_prices ? c.portion_code END) AND
   (CASE WHEN p.meal_choices THEN c.meal_choice IN ('','noodles','rice') ELSE c.meal_choice IN ('','noodles') END),
  is_archived=p.is_archived OR NOT
   ((CASE WHEN p.size_prices='{}'::jsonb THEN c.portion_code=p.portion_code ELSE p.size_prices ? c.portion_code END) AND
    (CASE WHEN p.meal_choices THEN c.meal_choice IN ('','noodles','rice') ELSE c.meal_choice IN ('','noodles') END)),
  is_visible_public=p.is_visible_public,fulfillment_route=p.fulfillment_route,vat_category=p.vat_category,
  beverage_sugar_tax_class=p.beverage_sugar_tax_class,sugar_g_per_100ml=p.sugar_g_per_100ml,tax_basis_note=p.tax_basis_note,
  invoice_sale_unit=p.invoice_sale_unit,updated_at=now()
 FROM changed_sizes p WHERE c.size_parent_id=p.id AND p.size_parent_id IS NULL;
 INSERT INTO public.menu_items(restaurant_id,category_id,name,name_ko,name_vi,name_en,paperless_name_vi,
  price,portion_code,spice_level,spice_choice,option_base_names,size_parent_id,meal_choices,meal_choice,
  sort_order,is_available,is_archived,is_visible_public,description,image_url,image_storage_path,
  fulfillment_route,vat_category,beverage_sugar_tax_class,sugar_g_per_100ml,tax_basis_note,invoice_sale_unit,choice_definition)
 SELECT p.restaurant_id,p.category_id,p.option_base_names->>'name',p.option_base_names->>'name_ko',p.option_base_names->>'name_vi',p.option_base_names->>'name_en',p.option_base_names->>'paperless_name_vi',
  CASE WHEN p.size_prices='{}'::jsonb THEN p.price ELSE (p.size_prices->>sizes.portion)::numeric END,
  sizes.portion,p.spice_level,p.spice_choice,p.option_base_names,p.id,p.meal_choices,meals.choice,
  p.sort_order,p.is_available,p.is_archived,p.is_visible_public,p.description,p.image_url,p.image_storage_path,
  p.fulfillment_route,p.vat_category,p.beverage_sugar_tax_class,p.sugar_g_per_100ml,p.tax_basis_note,p.invoice_sale_unit,p.choice_definition
 FROM changed_sizes p
 CROSS JOIN LATERAL(SELECT key portion FROM jsonb_each(p.size_prices)
   UNION ALL SELECT p.portion_code WHERE p.size_prices='{}'::jsonb) sizes
 CROSS JOIN LATERAL(SELECT choice FROM (VALUES('noodles'),('rice')) m(choice) WHERE p.meal_choices
   UNION ALL SELECT '' WHERE NOT p.meal_choices) meals
 WHERE p.size_parent_id IS NULL AND (p.meal_choices OR p.size_prices<>'{}'::jsonb)
  AND (sizes.portion,meals.choice)<>(p.portion_code,p.meal_choice)
  AND NOT EXISTS(SELECT 1 FROM public.menu_items c WHERE c.size_parent_id=p.id AND c.portion_code=sizes.portion AND c.meal_choice=meals.choice)
 ON CONFLICT(size_parent_id,portion_code,meal_choice) WHERE size_parent_id IS NOT NULL DO NOTHING;
 RETURN NULL;
END $$;


NOTIFY pgrst,'reload schema';
DO $verify$ BEGIN
 IF NOT public.menu_choice_definition_valid('{}') OR public.menu_choice_definition_valid('{"schema_version":1,"groups":[]}')
 OR has_function_privilege('authenticated','public.admin_apply_menu_choices(uuid,jsonb)','EXECUTE')
 OR has_function_privilege('anon','public.admin_update_menu_item_with_options(uuid,text,text,text,text,numeric,jsonb,jsonb)','EXECUTE')
 THEN RAISE EXCEPTION 'MENU_CHOICE_REGISTRATION_CONTRACT_INVALID'; END IF;
END $verify$;

-- COMPONENT 20261021181000_menu_choice_intake.sql
-- General selections through POS, QR, direct request and approval.
-- Full effective function bodies preserve the existing permission and payment contracts.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
ALTER TABLE public.direct_order_requests ADD COLUMN submission_hash text;
ALTER TABLE public.qr_order_batches ADD COLUMN submission_hash text;
ALTER TABLE public.direct_order_request_items DROP CONSTRAINT direct_order_request_items_request_id_menu_item_id_key;
CREATE INDEX direct_order_request_items_request_menu_idx ON public.direct_order_request_items(request_id,menu_item_id);


CREATE OR REPLACE FUNCTION "public"."validate_menu_option_batch"("p_store_id" "uuid", "p_items" "jsonb", "p_channel" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
BEGIN
 IF jsonb_typeof(p_items)='array' AND (jsonb_array_length(p_items)>500 OR octet_length(p_items::text)>1048576) THEN RAISE EXCEPTION 'MENU_SELECTION_BATCH_LIMIT'; END IF;
 IF jsonb_typeof(p_items)='array' THEN
  PERFORM m.id FROM public.menu_items m JOIN (
   SELECT DISTINCT CASE WHEN x->>'menu_item_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (x->>'menu_item_id')::uuid END id
   FROM jsonb_array_elements(p_items)x) ids ON ids.id=m.id
   WHERE m.restaurant_id=p_store_id ORDER BY m.id FOR SHARE OF m;
 END IF;
 IF jsonb_typeof(p_items)='array' AND EXISTS(
  SELECT 1 FROM jsonb_array_elements(p_items)x JOIN public.menu_items m
   ON m.id=CASE WHEN x->>'menu_item_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (x->>'menu_item_id')::uuid END
   AND m.restaurant_id=p_store_id
  WHERE CASE WHEN m.choice_definition='{}'::jsonb THEN x->>'menu_option_key' IS DISTINCT FROM m.menu_option_key ELSE public.menu_choice_snapshot(to_jsonb(m),x->>'menu_option_key',p_channel) IS NULL END
 ) THEN
  IF p_channel='direct' THEN RAISE EXCEPTION 'DIRECT_ORDER_MENU_CHANGED';
  ELSIF p_channel='qr' THEN RAISE EXCEPTION 'QR_MENU_ITEM_UNAVAILABLE';
  ELSE RAISE EXCEPTION 'MENU_ITEM_PRICE_INVALID'; END IF;
 END IF;
EXCEPTION WHEN raise_exception THEN
 IF SQLERRM LIKE 'MENU_SELECTION_%' THEN
  IF p_channel='direct' THEN RAISE EXCEPTION 'DIRECT_ORDER_MENU_CHANGED';
  ELSIF p_channel='qr' THEN RAISE EXCEPTION 'QR_MENU_ITEM_UNAVAILABLE';
  ELSE RAISE EXCEPTION 'MENU_ITEM_PRICE_INVALID'; END IF;
 END IF;
 RAISE;
END $_$;

CREATE OR REPLACE FUNCTION "public"."create_order_pre_takeout_core"("p_store_id" "uuid", "p_table_id" "uuid", "p_items" "jsonb") RETURNS "public"."orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_actor public.users%ROWTYPE;
  v_table public.tables%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_item_count int := 0;
BEGIN
  SELECT *
  INTO v_actor
  FROM public.users
  WHERE auth_id = auth.uid()
    AND is_active = TRUE
  LIMIT 1;

  IF NOT FOUND OR v_actor.role NOT IN ('waiter', 'admin', 'store_admin', 'super_admin') THEN
    RAISE EXCEPTION 'ORDER_CREATE_FORBIDDEN';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT EXISTS (
       SELECT 1
       FROM public.user_accessible_stores(auth.uid()) s(store_id)
       WHERE s.store_id = p_store_id
     ) THEN
    RAISE EXCEPTION 'ORDER_CREATE_FORBIDDEN';
  END IF;

  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'ORDER_ITEMS_REQUIRED';
  END IF;

  SELECT *
  INTO v_table
  FROM public.tables
  WHERE id = p_table_id
    AND restaurant_id = p_store_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND';
  END IF;

  IF v_table.status <> 'available' THEN
    RAISE EXCEPTION 'TABLE_NOT_AVAILABLE';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_items) item
    WHERE NULLIF(item->>'menu_item_id', '') IS NULL
       OR COALESCE((item->>'quantity')::int, 0) <= 0
  ) THEN
    RAISE EXCEPTION 'INVALID_ORDER_ITEM_INPUT';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_items) item
    LEFT JOIN public.menu_items m
      ON m.id = (item->>'menu_item_id')::uuid
     AND m.restaurant_id = p_store_id
     AND m.is_available = TRUE
    WHERE m.id IS NULL
  ) THEN
    RAISE EXCEPTION 'MENU_ITEM_NOT_AVAILABLE';
  END IF;

  INSERT INTO public.orders (restaurant_id, table_id, status, created_by)
  VALUES (p_store_id, p_table_id, 'pending', auth.uid())
  RETURNING * INTO v_order;

  INSERT INTO public.order_items (
    order_id,
    menu_item_id,
    quantity,
    unit_price,
    label,
    display_name,
    restaurant_id,
    item_type, menu_option_snapshot
  )
  SELECT
    v_order.id,
    m.id,
    (item->>'quantity')::int,
    coalesce((choice.snapshot->>'unit_price')::numeric,m.price),
    coalesce(choice.snapshot->>'name_ko',m.name),
    coalesce(choice.snapshot->>'name_ko',m.name),
    p_store_id,
    'menu_item', choice.snapshot
  FROM jsonb_array_elements(p_items) item
  JOIN public.menu_items m
    ON m.id = (item->>'menu_item_id')::uuid
   AND m.restaurant_id = p_store_id
   AND m.is_available = TRUE
  CROSS JOIN LATERAL (SELECT public.menu_choice_snapshot(to_jsonb(m),item->>'menu_option_key','pos') snapshot) choice;

  GET DIAGNOSTICS v_item_count = ROW_COUNT;

  UPDATE public.tables
  SET status = 'occupied',
      updated_at = now()
  WHERE id = p_table_id;

  PERFORM public.enqueue_print_jobs(
    v_order.id,
    ARRAY['kitchen', 'floor'],
    p_items,
    'initial'
  );

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, details)
  VALUES (
    auth.uid(),
    'create_order',
    'orders',
    v_order.id,
    jsonb_build_object(
      'store_id', p_store_id,
      'table_id', p_table_id,
      'item_count', v_item_count,
      'sales_channel', 'dine_in'
    )
  );

  RETURN v_order;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."add_items_to_order_pre_takeout_core"("p_order_id" "uuid", "p_store_id" "uuid", "p_items" "jsonb") RETURNS SETOF "public"."order_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_actor public.users%ROWTYPE;
  v_order public.orders%ROWTYPE;
  v_line record;
  v_item public.order_items%ROWTYPE;
  v_inserted_count int := 0;
  v_result_ids jsonb;
  v_print_items jsonb := '[]'::jsonb;
BEGIN
  SELECT *
  INTO v_actor
  FROM public.users
  WHERE auth_id = auth.uid()
    AND is_active = TRUE
  LIMIT 1;

  IF NOT FOUND OR v_actor.role NOT IN ('waiter', 'admin', 'store_admin', 'super_admin') THEN
    RAISE EXCEPTION 'ORDER_MUTATION_FORBIDDEN';
  END IF;

  IF NOT public.is_super_admin()
     AND NOT EXISTS (
       SELECT 1
       FROM public.user_accessible_stores(auth.uid()) s(store_id)
       WHERE s.store_id = p_store_id
     ) THEN
    RAISE EXCEPTION 'ORDER_MUTATION_FORBIDDEN';
  END IF;

  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'ORDER_ITEMS_REQUIRED';
  END IF;

  SELECT *
  INTO v_order
  FROM public.orders
  WHERE id = p_order_id
    AND restaurant_id = p_store_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND';
  END IF;

  IF v_order.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'ORDER_NOT_MUTABLE';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_items) item
    WHERE NULLIF(item->>'menu_item_id', '') IS NULL
       OR COALESCE((item->>'quantity')::int, 0) <= 0
  ) THEN
    RAISE EXCEPTION 'INVALID_ORDER_ITEM_INPUT';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_items) item
    LEFT JOIN public.menu_items m
      ON m.id = (item->>'menu_item_id')::uuid
     AND m.restaurant_id = p_store_id
     AND m.is_available = TRUE
    WHERE m.id IS NULL
  ) THEN
    RAISE EXCEPTION 'MENU_ITEM_NOT_AVAILABLE';
  END IF;

  WITH input AS MATERIALIZED (
    SELECT gen_random_uuid() id,raw,ord FROM jsonb_array_elements(p_items) WITH ORDINALITY item(raw,ord)
  ), inserted AS (
    INSERT INTO public.order_items(id,order_id,menu_item_id,quantity,unit_price,label,display_name,restaurant_id,item_type,menu_option_snapshot)
    SELECT src.id,p_order_id,m.id,(raw->>'quantity')::int,coalesce((c.snapshot->>'unit_price')::numeric,m.price),coalesce(c.snapshot->>'name_ko',m.name),coalesce(c.snapshot->>'name_ko',m.name),p_store_id,'menu_item',c.snapshot
    FROM input src JOIN public.menu_items m ON m.id=(raw->>'menu_item_id')::uuid
      AND m.restaurant_id=p_store_id AND m.is_available
    CROSS JOIN LATERAL (SELECT public.menu_choice_snapshot(to_jsonb(m),raw->>'menu_option_key','pos') snapshot)c ORDER BY ord RETURNING *
  ) SELECT count(*)::integer,coalesce(jsonb_agg(i.id ORDER BY src.ord),'[]'),
    coalesce(jsonb_agg(jsonb_build_object('item_id',i.id::text,'menu_item_id',i.menu_item_id::text,
      'label',coalesce(nullif(i.label,''),nullif(i.display_name,''),'Item'),'quantity',i.quantity,
      'notes',i.notes,'supplemental',true,'components',coalesce(i.combo_components,'[]')) ORDER BY src.ord),'[]')
    INTO v_inserted_count,v_result_ids,v_print_items FROM inserted i JOIN input src ON src.id=i.id;

  PERFORM public.recalc_order_status(p_order_id);
  PERFORM public.void_active_order_discount_for_item_change(
    p_order_id,
    p_store_id,
    'order_items_changed'
  );
  PERFORM public.enqueue_print_jobs(
    p_order_id,
    ARRAY['kitchen', 'floor'],
    v_print_items,
    'added_items'
  );

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, details)
  VALUES (
    auth.uid(),
    'add_items_to_order',
    'orders',
    p_order_id,
    jsonb_build_object(
      'store_id', p_store_id,
      'added_item_count', v_inserted_count
    )
  );

  RETURN QUERY SELECT item.* FROM jsonb_array_elements_text(v_result_ids) WITH ORDINALITY ids(id,ord)
    JOIN public.order_items item ON item.id=ids.id::uuid ORDER BY ids.ord;
  RETURN;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."qr_place_order_pre_takeout_core"("p_token" "text", "p_items" "jsonb", "p_client_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $_$
DECLARE
  v_token text := NULLIF(btrim(COALESCE(p_token, '')), '');
  v_table record;
  v_existing_batch public.qr_order_batches%ROWTYPE;
  v_items jsonb := COALESCE(p_items, '[]'::jsonb);
  v_item_count int;
  v_line record;
  v_inserted_item public.order_items%ROWTYPE;
  v_live_order public.orders%ROWTYPE;
  v_order_id uuid;
  v_is_new_order boolean := false;
  v_batch_no int;
  v_items_snapshot jsonb := '[]'::jsonb;
  v_print_items jsonb := '[]'::jsonb;
  v_result jsonb;
  v_print_reason text;
BEGIN
  IF p_client_order_id IS NULL THEN
    RAISE EXCEPTION 'QR_CLIENT_ORDER_ID_REQUIRED';
  END IF;

  SELECT
    q.restaurant_id,
    q.table_id,
    t.table_number,
    COALESCE(t.floor_label, '1F') AS floor_label,
    r.name AS store_name
  INTO v_table
  FROM public.table_qr_tokens q
  JOIN public.tables t
    ON t.id = q.table_id
   AND t.restaurant_id = q.restaurant_id
  JOIN public.restaurants r
    ON r.id = q.restaurant_id
   AND r.is_active = true
  WHERE q.token = v_token
    AND q.is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'QR_TOKEN_INVALID';
  END IF;

  SELECT *
  INTO v_existing_batch
  FROM public.qr_order_batches
  WHERE client_order_id = p_client_order_id
    AND restaurant_id = v_table.restaurant_id
    AND table_id = v_table.table_id;

  IF FOUND THEN
    IF v_existing_batch.submission_hash IS NOT NULL AND v_existing_batch.submission_hash IS DISTINCT FROM md5(v_items::text) THEN RAISE EXCEPTION 'QR_ITEMS_INVALID'; END IF;
    RETURN v_existing_batch.result_snapshot;
  END IF;

  IF jsonb_typeof(v_items) <> 'array' THEN
    RAISE EXCEPTION 'QR_ITEMS_INVALID';
  END IF;

  v_item_count := jsonb_array_length(v_items);
  IF v_item_count < 1 OR v_item_count > 20 THEN
    RAISE EXCEPTION 'QR_ITEMS_INVALID';
  END IF;

  FOR v_line IN
    SELECT raw
    FROM jsonb_array_elements(v_items) AS line(raw)
  LOOP
    IF COALESCE(v_line.raw->>'menu_item_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'QR_ITEMS_INVALID';
    END IF;
    IF COALESCE(v_line.raw->>'quantity', '') !~ '^[0-9]+$'
       OR (v_line.raw->>'quantity')::int < 1
       OR (v_line.raw->>'quantity')::int > 20 THEN
      RAISE EXCEPTION 'QR_ITEMS_INVALID';
    END IF;
  END LOOP;

  IF EXISTS (
    SELECT 1
    FROM public.qr_order_batches b
    WHERE b.table_id = v_table.table_id
      AND b.created_at > now() - interval '20 seconds'
  ) THEN
    RAISE EXCEPTION 'QR_TOO_FREQUENT';
  END IF;

  WITH input_items AS (
    SELECT
      (raw->>'menu_item_id')::uuid AS menu_item_id,
      (raw->>'quantity')::int AS quantity,raw->>'menu_option_key' selection_key,
      ord
    FROM jsonb_array_elements(v_items) WITH ORDINALITY AS line(raw, ord)
  ),
  matched_items AS (
    SELECT
      i.menu_item_id,
      i.quantity,
      i.ord,
      coalesce(c.snapshot->>'name_ko',m.name) name,
      coalesce((c.snapshot->>'unit_price')::numeric,m.price) price,c.snapshot
    FROM input_items i
    JOIN public.menu_items m
      ON m.id = i.menu_item_id
     AND m.restaurant_id = v_table.restaurant_id
     AND m.is_available = true
     AND m.is_visible_public = true
    CROSS JOIN LATERAL (SELECT public.menu_choice_snapshot(to_jsonb(m),i.selection_key,'qr') snapshot)c
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'menu_item_id', menu_item_id::text,
        'quantity', quantity,
        'name', name,
        'unit_price', price,'menu_option_snapshot',snapshot
      )
      ORDER BY ord
    ),
    '[]'::jsonb
  )
  INTO v_items_snapshot
  FROM matched_items;

  IF jsonb_array_length(v_items_snapshot) <> v_item_count THEN
    RAISE EXCEPTION 'QR_MENU_ITEM_UNAVAILABLE';
  END IF;

  PERFORM 1
  FROM public.tables
  WHERE id = v_table.table_id
    AND restaurant_id = v_table.restaurant_id
  FOR UPDATE;

  SELECT *
  INTO v_live_order
  FROM public.orders
  WHERE table_id = v_table.table_id
    AND restaurant_id = v_table.restaurant_id
    AND status IN ('pending', 'confirmed', 'serving') AND public.table_order_is_current(orders)
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.orders (
      restaurant_id,
      table_id,
      sales_channel,
      status,
      created_by,
      order_source,
      order_purpose
    )
    VALUES (
      v_table.restaurant_id,
      v_table.table_id,
      'dine_in',
      'pending',
      NULL,
      'qr',
      'customer'
    )
    RETURNING * INTO v_live_order;

    v_is_new_order := true;

    UPDATE public.tables
    SET status = 'occupied',
        updated_at = now()
    WHERE id = v_table.table_id;
  ELSE
    -- Partial payments remain attached to this open order. A fully paid
    -- order is completed by process_payment and is not selected above.
  END IF;

  v_order_id := v_live_order.id;

  WITH input AS MATERIALIZED (
    SELECT gen_random_uuid() id,raw,ord FROM jsonb_array_elements(v_items_snapshot) WITH ORDINALITY item(raw,ord)
  ), inserted AS (
    INSERT INTO public.order_items(id,order_id,menu_item_id,quantity,unit_price,label,display_name,restaurant_id,item_type,menu_option_snapshot)
    SELECT id,v_order_id,(raw->>'menu_item_id')::uuid,(raw->>'quantity')::int,
      (raw->>'unit_price')::numeric,raw->>'name',raw->>'name',v_table.restaurant_id,'menu_item',raw->'menu_option_snapshot'
    FROM input ORDER BY ord RETURNING *
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object('item_id',i.id::text,'menu_item_id',i.menu_item_id::text,
    'label',coalesce(nullif(i.label,''),nullif(i.display_name,''),'Item'),'quantity',i.quantity,
    'notes',i.notes,'supplemental',NOT v_is_new_order) ORDER BY src.ord),'[]')
  INTO v_print_items FROM inserted i JOIN input src ON src.id=i.id;

  IF NOT v_is_new_order THEN
    PERFORM public.void_active_order_discount_for_item_change(
      v_order_id,
      v_table.restaurant_id,
      'order_items_changed'
    );
  END IF;

  PERFORM public.recalc_order_status(v_order_id);

  SELECT COALESCE(MAX(batch_no), 0) + 1
  INTO v_batch_no
  FROM public.print_jobs
  WHERE order_id = v_order_id
    AND copy_type IN ('kitchen', 'floor', 'confirmation');

  v_print_reason := CASE WHEN v_batch_no = 1 THEN 'initial' ELSE 'added_items' END;

  PERFORM public.enqueue_print_jobs(
    v_order_id,
    ARRAY['kitchen', 'floor', 'confirmation'],
    v_print_items,
    v_print_reason
  );

  v_result := jsonb_build_object(
    'order_id', v_order_id::text,
    'order_code', substring(v_order_id::text from 1 for 8),
    'batch_no', v_batch_no,
    'table_number', v_table.table_number,
    'floor_label', v_table.floor_label,
    'items', (
      SELECT COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'name', item->>'name',
            'quantity', (item->>'quantity')::int
          )
        ),
        '[]'::jsonb
      )
      FROM jsonb_array_elements(v_items_snapshot) item
    )
  );

  INSERT INTO public.qr_order_batches (
    restaurant_id,
    table_id,
    order_id,
    batch_no,
    client_order_id,
    items_snapshot,
    result_snapshot,submission_hash
  )
  VALUES (
    v_table.restaurant_id,
    v_table.table_id,
    v_order_id,
    v_batch_no,
    p_client_order_id,
    v_items_snapshot,
    v_result,md5(v_items::text)
  );

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, details)
  VALUES (
    NULL,
    'qr_place_order',
    'orders',
    v_order_id,
    jsonb_build_object(
      'store_id', v_table.restaurant_id,
      'table_id', v_table.table_id,
      'batch_no', v_batch_no,
      'client_order_id', p_client_order_id,
      'item_count', v_item_count
    )
  );

  RETURN v_result;
EXCEPTION
  WHEN unique_violation THEN
    SELECT *
    INTO v_existing_batch
    FROM public.qr_order_batches
    WHERE client_order_id = p_client_order_id
      AND restaurant_id = v_table.restaurant_id
      AND table_id = v_table.table_id;
    IF FOUND THEN
      IF v_existing_batch.submission_hash IS NOT NULL AND v_existing_batch.submission_hash IS DISTINCT FROM md5(v_items::text) THEN RAISE EXCEPTION 'QR_ITEMS_INVALID'; END IF;
    RETURN v_existing_batch.result_snapshot;
    END IF;
    RAISE;
END;
$_$;

CREATE OR REPLACE FUNCTION "public"."qr_place_order"("p_token" "text", "p_items" "jsonb", "p_client_order_id" "uuid", "p_validate_combo_choices" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $_$
DECLARE
  v_token text := NULLIF(btrim(COALESCE(p_token, '')), '');
  v_items jsonb := COALESCE(p_items, '[]'::jsonb);
  v_table record;
  v_existing public.qr_order_batches%ROWTYPE;
  v_line record;
  v_choice_count integer;
  v_expected_count integer;
BEGIN
  IF p_client_order_id IS NULL OR jsonb_typeof(v_items) <> 'array' THEN
    RAISE EXCEPTION 'QR_ITEMS_INVALID';
  END IF;

  IF (
    SELECT count(*)
    FROM (
      SELECT line.raw->>'menu_item_id',line.raw->>'menu_option_key',
             COALESCE((line.raw->>'is_takeout')::boolean, false)
      FROM jsonb_array_elements(v_items) line(raw)
      GROUP BY line.raw->>'menu_item_id',line.raw->>'menu_option_key',
               COALESCE((line.raw->>'is_takeout')::boolean, false)
    ) unique_lines
  ) <> jsonb_array_length(v_items) THEN
    RAISE EXCEPTION 'QR_ITEMS_INVALID';
  END IF;

  SELECT q.restaurant_id, q.table_id
  INTO v_table
  FROM public.table_qr_tokens q
  JOIN public.tables t ON t.id = q.table_id AND t.restaurant_id = q.restaurant_id
  JOIN public.restaurants r ON r.id = q.restaurant_id AND r.is_active = true
  WHERE q.token = v_token AND q.is_active = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'QR_TOKEN_INVALID'; END IF;

  SELECT * INTO v_existing
  FROM public.qr_order_batches
  WHERE client_order_id = p_client_order_id
    AND restaurant_id = v_table.restaurant_id
    AND table_id = v_table.table_id;
  IF FOUND THEN
   IF v_existing.submission_hash IS NOT NULL AND v_existing.submission_hash IS DISTINCT FROM md5(v_items::text) THEN RAISE EXCEPTION 'QR_ITEMS_INVALID'; END IF;
   RETURN v_existing.result_snapshot; END IF;

  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_items) line(raw)
    WHERE coalesce(raw->>'menu_item_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR coalesce(raw->>'quantity','') !~ '^[0-9]+$'
      OR (raw ? 'is_takeout' AND jsonb_typeof(raw->'is_takeout')<>'boolean')) THEN
    RAISE EXCEPTION 'QR_ITEMS_INVALID';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_items) line(raw)
    WHERE jsonb_typeof(coalesce(raw->'combo_drink_choices','[]'))<>'array') THEN
    RAISE EXCEPTION 'QR_COMBO_DRINK_CHOICES_INVALID';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_items) line(raw)
    LEFT JOIN public.menu_items menu ON menu.id=(raw->>'menu_item_id')::uuid
    WHERE jsonb_array_length(coalesce(raw->'combo_drink_choices','[]'))<>
      CASE WHEN menu.is_combo THEN coalesce(menu.combo_drink_choice_count,0) ELSE 0 END*(raw->>'quantity')::integer) THEN
    RAISE EXCEPTION 'QR_COMBO_DRINK_CHOICES_INVALID';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_items) line(raw)
    CROSS JOIN LATERAL jsonb_array_elements_text(coalesce(raw->'combo_drink_choices','[]')) choice(value)
    LEFT JOIN public.menu_items option_item ON option_item.id=CASE
      WHEN choice.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN choice.value::uuid ELSE NULL END
      AND option_item.restaurant_id=v_table.restaurant_id AND NOT option_item.is_archived
      AND option_item.is_available AND option_item.is_visible_public AND NOT option_item.is_combo
    LEFT JOIN public.menu_categories drink_category ON drink_category.id=option_item.category_id
      AND drink_category.restaurant_id=v_table.restaurant_id AND drink_category.system_key='drink' AND drink_category.is_active
    WHERE option_item.id IS NULL OR drink_category.id IS NULL) THEN
    RAISE EXCEPTION 'QR_COMBO_DRINK_CHOICES_INVALID';
  END IF;

  PERFORM public.validate_menu_option_batch(v_table.restaurant_id,v_items,'qr');
  PERFORM set_config('pos.qr_combo_payload', v_items::text, true);
  RETURN public.qr_place_order(p_token, p_items, p_client_order_id);
END;
$_$;

CREATE OR REPLACE FUNCTION "public"."direct_order_prepare_combo_items"("p_store_id" "uuid", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
DECLARE prepared jsonb;
BEGIN
 IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 50 THEN
  RAISE EXCEPTION 'DIRECT_ORDER_ITEM_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_items) e WHERE jsonb_typeof(e) IS DISTINCT FROM 'object'
  OR COALESCE(e->>'menu_item_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  OR COALESCE(e->>'quantity','') !~ '^[1-9][0-9]?$'
  OR jsonb_typeof(COALESCE(e->'combo_drink_choices','[]')) IS DISTINCT FROM 'array'
  OR char_length(COALESCE(e->>'note',''))>300) THEN RAISE EXCEPTION 'DIRECT_ORDER_ITEM_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_items) e WHERE (e->>'quantity')::integer>50
  OR jsonb_array_length(COALESCE(e->'combo_drink_choices','[]'))>500)
 OR (SELECT count(DISTINCT ROW((e->>'menu_item_id')::uuid,e->>'menu_option_key')) FROM jsonb_array_elements(p_items)e)<>jsonb_array_length(p_items)
 THEN RAISE EXCEPTION 'DIRECT_ORDER_ITEM_INVALID'; END IF;
 IF (SELECT sum((e->>'quantity')::integer) FROM jsonb_array_elements(p_items)e)>100 THEN RAISE EXCEPTION 'DIRECT_ORDER_QUANTITY_LIMIT'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_items)e CROSS JOIN LATERAL jsonb_array_elements(COALESCE(e->'combo_drink_choices','[]'))c
  WHERE jsonb_typeof(c) IS DISTINCT FROM 'string' OR (c#>>'{}') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
 THEN RAISE EXCEPTION 'DIRECT_ORDER_COMBO_CHOICES_INVALID'; END IF;
 PERFORM public.validate_menu_option_batch(p_store_id,p_items,'direct');
 -- Stable lock order covers parent menus, fixed components and chosen drinks.
 PERFORM m.id FROM public.menu_items m JOIN (
  SELECT (e->>'menu_item_id')::uuid id FROM jsonb_array_elements(p_items)e
  UNION SELECT co.component_menu_item_id FROM public.menu_combo_components co
   JOIN jsonb_array_elements(p_items)e ON co.combo_menu_item_id=(e->>'menu_item_id')::uuid WHERE co.restaurant_id=p_store_id
  UNION SELECT c::uuid FROM jsonb_array_elements(p_items)e CROSS JOIN LATERAL jsonb_array_elements_text(COALESCE(e->'combo_drink_choices','[]'))c
 ) ids ON ids.id=m.id WHERE m.restaurant_id=p_store_id ORDER BY m.id FOR SHARE OF m;
 WITH lines AS MATERIALIZED(
  SELECT e.raw,e.ord,gen_random_uuid() line_id,m.id,
   coalesce(c.snapshot->>'name_ko',m.name) name,coalesce(c.snapshot->>'name_ko',m.name_ko) name_ko,
   coalesce(c.snapshot->>'name_vi',m.name_vi) name_vi,coalesce(c.snapshot->>'name_en',m.name_en) name_en,
   m.vat_category,coalesce((c.snapshot->>'unit_price')::numeric,m.price) price,m.is_combo,c.snapshot,
   m.combo_drink_choice_count,m.effective_vat_rate,(e.raw->>'quantity')::integer qty,
   m.restaurant_id=p_store_id AND m.is_available AND m.is_visible_public AND NOT m.is_archived
    AND (m.category_id IS NULL OR cat.is_active) valid
  FROM jsonb_array_elements(p_items) WITH ORDINALITY e(raw,ord)
  LEFT JOIN public.menu_items m ON m.id=(e.raw->>'menu_item_id')::uuid AND m.restaurant_id=p_store_id
  LEFT JOIN public.menu_categories cat ON cat.id=m.category_id AND cat.restaurant_id=p_store_id
  CROSS JOIN LATERAL (SELECT public.menu_choice_snapshot(to_jsonb(m),e.raw->>'menu_option_key','direct') snapshot)c
 ), fixed AS MATERIALIZED(
  SELECT l.line_id parent,co.component_menu_item_id id,co.quantity,co.sort_order,
   m.name,m.name_ko,m.name_vi,m.name_en,m.price,m.effective_vat_rate,m.fulfillment_route,
   m.id IS NOT NULL AND m.is_available AND m.is_visible_public AND NOT m.is_archived AND NOT m.is_combo
    AND m.price>0 AND co.quantity>0 AND (m.category_id IS NULL OR cat.is_active) valid
  FROM lines l JOIN public.menu_combo_components co ON co.combo_menu_item_id=l.id AND co.restaurant_id=p_store_id AND l.is_combo
  LEFT JOIN public.menu_items m ON m.id=co.component_menu_item_id AND m.restaurant_id=p_store_id
  LEFT JOIN public.menu_categories cat ON cat.id=m.category_id AND cat.restaurant_id=p_store_id
  WHERE m.id IS NULL OR COALESCE(l.combo_drink_choice_count,0)=0 OR lower(btrim(COALESCE(NULLIF(m.name_ko,''),m.name))) NOT IN('음료','drink','beverage','đồ uống','nước uống')
 ), selected AS MATERIALIZED(
  SELECT l.line_id parent,c.id::uuid id,count(*)::integer quantity,min(c.ord)::integer sort_order
  FROM lines l CROSS JOIN LATERAL jsonb_array_elements_text(COALESCE(l.raw->'combo_drink_choices','[]')) WITH ORDINALITY c(id,ord)
  GROUP BY l.line_id,c.id
 ), drinks AS MATERIALIZED(
  SELECT s.*,m.name,m.name_ko,m.name_vi,m.name_en,m.price,m.effective_vat_rate,m.fulfillment_route,
   m.id IS NOT NULL AND m.is_available AND m.is_visible_public AND NOT m.is_archived AND NOT m.is_combo
    AND m.price>0 AND cat.is_active AND cat.system_key='drink' valid
  FROM selected s LEFT JOIN public.menu_items m ON m.id=s.id AND m.restaurant_id=p_store_id
  LEFT JOIN public.menu_categories cat ON cat.id=m.category_id AND cat.restaurant_id=p_store_id
 ), parts AS MATERIALIZED(
  SELECT *,false is_total FROM fixed UNION ALL SELECT *,true FROM drinks
 ), normalized AS MATERIALIZED(
  SELECT p.parent,p.id,p.name,p.name_ko,p.name_vi,p.name_en,p.price,p.effective_vat_rate,p.fulfillment_route,
   min(p.sort_order) sort_order,bool_and(p.valid) valid,bool_or(p.is_total) is_total,
   COALESCE(sum(p.quantity) FILTER(WHERE NOT p.is_total),0)::integer fixed_quantity,
   CASE WHEN bool_or(p.is_total) AND bool_or(NOT p.is_total)
    THEN sum(p.quantity*CASE WHEN p.is_total THEN 1 ELSE l.qty END) ELSE sum(p.quantity) END quantity
  FROM parts p JOIN lines l ON l.line_id=p.parent
  GROUP BY p.parent,p.id,p.name,p.name_ko,p.name_vi,p.name_en,p.price,p.effective_vat_rate,p.fulfillment_route
 ), snapshots AS(
  SELECT parent,bool_and(valid) valid,count(*) component_count,jsonb_agg(jsonb_build_object(
   'menu_item_id',id,'label',name,'name_ko',COALESCE(NULLIF(name_ko,''),name),
   'name_vi',COALESCE(NULLIF(name_vi,''),name),'name_en',COALESCE(NULLIF(name_en,''),name),
   'quantity',quantity,'fixed_quantity',fixed_quantity,'is_total_quantity',is_total,'fulfillment_route',fulfillment_route,
   'tax_unit_price',price,'tax_vat_rate',effective_vat_rate) ORDER BY is_total,sort_order,id) components
  FROM normalized GROUP BY parent
 ), rates AS(
  SELECT p.parent,p.effective_vat_rate rate,sum(p.price*p.quantity*CASE WHEN p.is_total THEN 1 ELSE l.qty END) weight
  FROM parts p JOIN lines l ON l.line_id=p.parent GROUP BY p.parent,p.effective_vat_rate
 ), profiles AS(SELECT parent,jsonb_agg(jsonb_build_object('rate',rate,'weight',weight) ORDER BY rate) profile FROM rates GROUP BY parent)
 SELECT jsonb_agg(jsonb_build_object('line_id',l.line_id,'menu_option_snapshot',l.snapshot,'menu_item_id',l.id,'display_name',l.name,
  'name_ko',COALESCE(NULLIF(l.name_ko,''),l.name),'name_vi',COALESCE(NULLIF(l.name_vi,''),l.name),'name_en',COALESCE(NULLIF(l.name_en,''),l.name),
  'vat_category',COALESCE(l.vat_category,'food'),'unit_price',l.price,'quantity',l.qty,'item_note',NULLIF(btrim(l.raw->>'note'),''),'sort_order',l.ord-1,
  'combo_drink_choices',COALESCE(l.raw->'combo_drink_choices','[]'),'combo_components',COALESCE(s.components,'[]'),
  'vat_profile_snapshot',CASE WHEN l.is_combo THEN pr.profile ELSE jsonb_build_array(jsonb_build_object('rate',l.effective_vat_rate,'weight',1)) END,
  'valid',COALESCE(l.valid,false) AND (NOT l.is_combo OR (COALESCE(s.valid,false) AND s.component_count>0))
   AND jsonb_array_length(COALESCE(l.raw->'combo_drink_choices','[]'))=COALESCE(l.combo_drink_choice_count,0)*l.qty
  ) ORDER BY l.ord) INTO prepared FROM lines l LEFT JOIN snapshots s ON s.parent=l.line_id LEFT JOIN profiles pr ON pr.parent=l.line_id;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(prepared)e WHERE NOT (e->>'valid')::boolean) THEN
  RAISE EXCEPTION 'DIRECT_ORDER_COMBO_UNAVAILABLE'; END IF;
 RETURN prepared;
END $_$;

CREATE OR REPLACE FUNCTION "public"."direct_order_public_submit"("p_session_id" "uuid", "p_secret_hash" "text", "p_client_request_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_prepared jsonb; v_previous_prepared text;
  v_session public.direct_order_sessions%ROWTYPE;
  v_storefront public.direct_order_storefronts%ROWTYPE;
  v_request public.direct_order_requests%ROWTYPE;
  v_existing public.direct_order_requests%ROWTYPE;
  v_address jsonb;
  v_item jsonb;
  v_menu public.menu_items%ROWTYPE;
  v_item_count integer := 0;
  v_total_quantity integer := 0;
  v_reference text;
  v_local_time time;
BEGIN
  IF p_client_request_id IS NULL
     OR p_payload IS NULL
     OR jsonb_typeof(p_payload) <> 'object'
     OR jsonb_typeof(p_payload->'items') <> 'array'
     OR jsonb_array_length(p_payload->'items') NOT BETWEEN 1 AND 50
     OR jsonb_typeof(p_payload->'address') <> 'object'
     OR COALESCE(p_payload->>'locale', '') NOT IN ('ko', 'vi', 'en') THEN
    RAISE EXCEPTION 'DIRECT_ORDER_REQUEST_INPUT_INVALID';
  END IF;

  v_session := public.direct_order_validate_session(
    p_session_id, p_secret_hash
  );

  PERFORM pg_advisory_xact_lock(hashtextextended(v_session.restaurant_id::text||':direct-submit:'||p_client_request_id::text,0));
  SELECT * INTO v_existing
  FROM public.direct_order_requests request_row
  WHERE request_row.client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_existing.session_id <> v_session.id
       OR v_existing.restaurant_id <> v_session.restaurant_id THEN
      RAISE EXCEPTION 'DIRECT_ORDER_REQUEST_INPUT_INVALID';
    END IF;
    IF v_existing.submission_hash IS NOT NULL AND v_existing.submission_hash IS DISTINCT FROM md5(p_payload::text) THEN RAISE EXCEPTION 'DIRECT_ORDER_REQUEST_INPUT_INVALID'; END IF;
    RETURN jsonb_build_object(
      'request_id', v_existing.id,
      'reference_code', v_existing.reference_code,
      'state', v_existing.state,
      'idempotent', true
    );
  END IF;

  SELECT * INTO v_storefront
  FROM public.direct_order_storefronts storefront
  WHERE storefront.restaurant_id = v_session.restaurant_id
    AND storefront.is_enabled = true
  FOR SHARE;

  IF NOT FOUND OR v_storefront.is_paused THEN
    RAISE EXCEPTION 'DIRECT_ORDER_STOREFRONT_PAUSED';
  END IF;

  v_local_time := (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::time;
  IF v_storefront.ordering_hours_enforced
     AND (v_local_time < v_storefront.ordering_starts_at
          OR v_local_time >= v_storefront.ordering_cutoff_at) THEN
    RAISE EXCEPTION 'DIRECT_ORDER_OUTSIDE_HOURS';
  END IF;


  v_address := p_payload->'address';
  IF char_length(btrim(COALESCE(v_address->>'customer_name', ''))) NOT BETWEEN 1 AND 100
     OR COALESCE(v_address->>'customer_phone', '') !~ '^[+]?[0-9][0-9 -]{7,19}$'
     OR char_length(btrim(COALESCE(v_address->>'formatted_address', ''))) NOT BETWEEN 3 AND 500
     OR char_length(btrim(COALESCE(v_address->>'detail_address', ''))) NOT BETWEEN 0 AND 300 THEN
    RAISE EXCEPTION 'DIRECT_ORDER_ADDRESS_INVALID';
  END IF;

  IF v_address->>'address_source' = 'manual' THEN
    -- A typed address has no verified location. Never manufacture coordinates
    -- or reuse a stale pin when the customer edits a previously saved address.
    IF v_address->>'latitude' IS NOT NULL
       OR v_address->>'longitude' IS NOT NULL
       OR NULLIF(btrim(COALESCE(v_address->>'google_place_id', '')), '') IS NOT NULL
       OR COALESCE(v_address->>'location_verified', 'false') <> 'false' THEN
      RAISE EXCEPTION 'DIRECT_ORDER_ADDRESS_INVALID';
    END IF;
  ELSIF COALESCE(v_address->>'address_source', '') NOT IN ('search', 'map_pin')
     OR COALESCE(v_address->>'location_verified', 'false') <> 'true'
     OR v_address->>'latitude' IS NULL
     OR v_address->>'longitude' IS NULL THEN
    -- Preserve in-flight legacy client compatibility without relaxing its
    -- existing location requirements.
    RAISE EXCEPTION 'DIRECT_ORDER_ADDRESS_INVALID';
  END IF;

  v_reference := 'D' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

  INSERT INTO public.direct_order_requests(
    restaurant_id, session_id, client_request_id, reference_code,
    state, locale, customer_note
  ) VALUES (
    v_session.restaurant_id,
    v_session.id,
    p_client_request_id,
    v_reference,
    'awaiting_quote',
    COALESCE(NULLIF(p_payload->>'locale', ''), v_session.locale),
    NULLIF(btrim(COALESCE(p_payload->>'customer_note', '')), '')
  ) RETURNING * INTO v_request;

  UPDATE public.direct_order_requests SET submission_hash=md5(p_payload::text) WHERE id=v_request.id;
  v_prepared:=public.direct_order_prepare_combo_items(v_session.restaurant_id,p_payload->'items');
  v_previous_prepared:=current_setting('pos.direct_prepared_items',true);
  PERFORM set_config('pos.direct_prepared_items',(SELECT jsonb_object_agg(e->>'line_id',e) FROM jsonb_array_elements(v_prepared)e)::text,true);
  INSERT INTO public.direct_order_request_items(id,request_id,restaurant_id,menu_item_id,display_name,name_ko,name_vi,name_en,vat_category,unit_price,quantity,item_note,sort_order,combo_drink_choices,combo_components,vat_profile_snapshot,menu_option_snapshot)
  SELECT (e->>'line_id')::uuid,v_request.id,v_request.restaurant_id,(e->>'menu_item_id')::uuid,e->>'display_name',e->>'name_ko',e->>'name_vi',e->>'name_en',e->>'vat_category',
   (e->>'unit_price')::numeric,(e->>'quantity')::integer,e->>'item_note',(e->>'sort_order')::integer,e->'combo_drink_choices',e->'combo_components',e->'vat_profile_snapshot',e->'menu_option_snapshot'
  FROM jsonb_array_elements(v_prepared)e;
  PERFORM set_config('pos.direct_prepared_items',COALESCE(v_previous_prepared,''),true);
  SELECT sum((e->>'quantity')::integer) INTO v_total_quantity FROM jsonb_array_elements(v_prepared)e;
  IF v_total_quantity > 100 THEN
    RAISE EXCEPTION 'DIRECT_ORDER_QUANTITY_LIMIT';
  END IF;

  INSERT INTO public.direct_order_request_addresses(
    request_id, restaurant_id, customer_name, customer_phone,
    formatted_address, detail_address, latitude, longitude,
    google_place_id, district, ward, address_source, location_verified
  ) VALUES (
    v_request.id,
    v_request.restaurant_id,
    btrim(v_address->>'customer_name'),
    btrim(v_address->>'customer_phone'),
    btrim(v_address->>'formatted_address'),
    btrim(v_address->>'detail_address'),
    (v_address->>'latitude')::numeric,
    (v_address->>'longitude')::numeric,
    NULLIF(btrim(COALESCE(v_address->>'google_place_id', '')), ''),
    NULLIF(btrim(COALESCE(v_address->>'district', '')), ''),
    NULLIF(btrim(COALESCE(v_address->>'ward', '')), ''),
    v_address->>'address_source',
    v_address->>'address_source' <> 'manual'
  );

  IF v_address->>'address_source' <> 'manual' THEN
    INSERT INTO public.direct_order_location_facts(
      request_id, restaurant_id, district, ward,
      coarse_latitude, coarse_longitude, requested_at
    ) VALUES (
      v_request.id,
      v_request.restaurant_id,
      NULLIF(btrim(COALESCE(v_address->>'district', '')), ''),
      NULLIF(btrim(COALESCE(v_address->>'ward', '')), ''),
      round((v_address->>'latitude')::numeric, 3),
      round((v_address->>'longitude')::numeric, 3),
      v_request.created_at
    );
  END IF;

  INSERT INTO public.direct_order_messages(
    request_id, restaurant_id, sender_type, message_type, body
  ) VALUES (
    v_request.id,
    v_request.restaurant_id,
    'system',
    'system',
    'DIRECT_ORDER_REQUEST_RECEIVED'
  );

  RETURN jsonb_build_object(
    'request_id', v_request.id,
    'reference_code', v_request.reference_code,
    'state', v_request.state,
    'idempotent', false
  );
END;
$_$;

CREATE OR REPLACE FUNCTION "public"."direct_order_public_submit_v2"("p_session_id" "uuid", "p_secret_hash" "text", "p_client_request_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_prepared jsonb; v_previous_prepared text;
  v_session public.direct_order_sessions%ROWTYPE;
  v_storefront public.direct_order_storefronts%ROWTYPE;
  v_request public.direct_order_requests%ROWTYPE;
  v_existing public.direct_order_requests%ROWTYPE;
  v_address jsonb;
  v_type text := p_payload->>'fulfillment_type';
  v_item jsonb;
  v_menu public.menu_items%ROWTYPE;
  v_item_count integer := 0;
  v_total_quantity integer := 0;
  v_reference text;
  v_local_time time;
BEGIN
  IF p_client_request_id IS NULL
     OR p_payload IS NULL
     OR jsonb_typeof(p_payload) <> 'object'
     OR jsonb_typeof(p_payload->'items') <> 'array'
     OR jsonb_array_length(p_payload->'items') NOT BETWEEN 1 AND 50
     OR jsonb_typeof(p_payload->'address') <> 'object'
     OR COALESCE(p_payload->>'locale', '') NOT IN ('ko', 'vi', 'en') THEN
    RAISE EXCEPTION 'DIRECT_ORDER_REQUEST_INPUT_INVALID';
  END IF;

  IF v_type IS NULL OR v_type NOT IN ('delivery','pickup') THEN
    RAISE EXCEPTION 'DIRECT_ORDER_REQUEST_INPUT_INVALID';
  END IF;
  v_session := public.direct_order_validate_session(
    p_session_id, p_secret_hash
  );

  PERFORM pg_advisory_xact_lock(hashtextextended(v_session.restaurant_id::text||':direct-submit:'||p_client_request_id::text,0));
  SELECT * INTO v_existing
  FROM public.direct_order_requests request_row
  WHERE request_row.client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_existing.session_id <> v_session.id
       OR v_existing.restaurant_id <> v_session.restaurant_id THEN
      RAISE EXCEPTION 'DIRECT_ORDER_REQUEST_INPUT_INVALID';
    END IF;
    IF v_existing.fulfillment_type <> v_type THEN
      RAISE EXCEPTION 'DIRECT_ORDER_FULFILLMENT_TYPE_LOCKED';
    END IF;
    IF v_existing.submission_hash IS NOT NULL AND v_existing.submission_hash IS DISTINCT FROM md5(p_payload::text) THEN RAISE EXCEPTION 'DIRECT_ORDER_REQUEST_INPUT_INVALID'; END IF;
    RETURN jsonb_build_object(
      'request_id', v_existing.id,
      'reference_code', v_existing.reference_code,
      'state', v_existing.state,
      'idempotent', true
    );
  END IF;

  SELECT * INTO v_storefront
  FROM public.direct_order_storefronts storefront
  WHERE storefront.restaurant_id = v_session.restaurant_id
    AND storefront.is_enabled = true
  FOR SHARE;

  IF NOT FOUND OR v_storefront.is_paused THEN
    RAISE EXCEPTION 'DIRECT_ORDER_STOREFRONT_PAUSED';
  END IF;

  v_local_time := (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::time;
  IF v_storefront.ordering_hours_enforced
     AND (v_local_time < v_storefront.ordering_starts_at
          OR v_local_time >= v_storefront.ordering_cutoff_at) THEN
    RAISE EXCEPTION 'DIRECT_ORDER_OUTSIDE_HOURS';
  END IF;


  v_address := p_payload->'address';
  IF char_length(btrim(COALESCE(v_address->>'customer_name', ''))) NOT BETWEEN 1 AND 100
     OR COALESCE(v_address->>'customer_phone', '') !~ '^[+]?[0-9][0-9 -]{7,19}$'
     OR (v_type='delivery' AND (char_length(btrim(COALESCE(v_address->>'formatted_address', ''))) NOT BETWEEN 3 AND 500
     OR char_length(btrim(COALESCE(v_address->>'detail_address', ''))) NOT BETWEEN 0 AND 300)) THEN
    RAISE EXCEPTION 'DIRECT_ORDER_ADDRESS_INVALID';
  END IF;

  IF v_type='pickup' THEN
    IF v_address->>'address_source' IS DISTINCT FROM 'pickup'
       OR v_address->>'formatted_address' IS NOT NULL OR v_address->>'detail_address' IS NOT NULL
       OR v_address->>'latitude' IS NOT NULL OR v_address->>'longitude' IS NOT NULL
       OR v_address->>'google_place_id' IS NOT NULL
       OR v_address->>'district' IS NOT NULL OR v_address->>'ward' IS NOT NULL
       OR COALESCE(v_address->>'location_verified','false') <> 'false' THEN
      RAISE EXCEPTION 'DIRECT_ORDER_ADDRESS_INVALID';
    END IF;
  ELSIF v_address->>'address_source' = 'manual' THEN
    -- A typed address has no verified location. Never manufacture coordinates
    -- or reuse a stale pin when the customer edits a previously saved address.
    IF v_address->>'latitude' IS NOT NULL
       OR v_address->>'longitude' IS NOT NULL
       OR NULLIF(btrim(COALESCE(v_address->>'google_place_id', '')), '') IS NOT NULL
       OR COALESCE(v_address->>'location_verified', 'false') <> 'false' THEN
      RAISE EXCEPTION 'DIRECT_ORDER_ADDRESS_INVALID';
    END IF;
  ELSIF COALESCE(v_address->>'address_source', '') NOT IN ('search', 'map_pin')
     OR COALESCE(v_address->>'location_verified', 'false') <> 'true'
     OR v_address->>'latitude' IS NULL
     OR v_address->>'longitude' IS NULL THEN
    -- Preserve in-flight legacy client compatibility without relaxing its
    -- existing location requirements.
    RAISE EXCEPTION 'DIRECT_ORDER_ADDRESS_INVALID';
  END IF;

  v_reference := 'D' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));

  INSERT INTO public.direct_order_requests(
    restaurant_id, session_id, client_request_id, reference_code,
    state, locale, customer_note, fulfillment_type
  ) VALUES (
    v_session.restaurant_id,
    v_session.id,
    p_client_request_id,
    v_reference,
    'awaiting_quote',
    COALESCE(NULLIF(p_payload->>'locale', ''), v_session.locale),
    NULLIF(btrim(COALESCE(p_payload->>'customer_note', '')), ''), v_type
  ) RETURNING * INTO v_request;

  UPDATE public.direct_order_requests SET submission_hash=md5(p_payload::text) WHERE id=v_request.id;
  v_prepared:=public.direct_order_prepare_combo_items(v_session.restaurant_id,p_payload->'items');
  v_previous_prepared:=current_setting('pos.direct_prepared_items',true);
  PERFORM set_config('pos.direct_prepared_items',(SELECT jsonb_object_agg(e->>'line_id',e) FROM jsonb_array_elements(v_prepared)e)::text,true);
  INSERT INTO public.direct_order_request_items(id,request_id,restaurant_id,menu_item_id,display_name,name_ko,name_vi,name_en,vat_category,unit_price,quantity,item_note,sort_order,combo_drink_choices,combo_components,vat_profile_snapshot,menu_option_snapshot)
  SELECT (e->>'line_id')::uuid,v_request.id,v_request.restaurant_id,(e->>'menu_item_id')::uuid,e->>'display_name',e->>'name_ko',e->>'name_vi',e->>'name_en',e->>'vat_category',
   (e->>'unit_price')::numeric,(e->>'quantity')::integer,e->>'item_note',(e->>'sort_order')::integer,e->'combo_drink_choices',e->'combo_components',e->'vat_profile_snapshot',e->'menu_option_snapshot'
  FROM jsonb_array_elements(v_prepared)e;
  PERFORM set_config('pos.direct_prepared_items',COALESCE(v_previous_prepared,''),true);
  SELECT sum((e->>'quantity')::integer) INTO v_total_quantity FROM jsonb_array_elements(v_prepared)e;
  IF v_total_quantity > 100 THEN
    RAISE EXCEPTION 'DIRECT_ORDER_QUANTITY_LIMIT';
  END IF;

  INSERT INTO public.direct_order_request_addresses(
    request_id, restaurant_id, customer_name, customer_phone,
    formatted_address, detail_address, latitude, longitude,
    google_place_id, district, ward, address_source, location_verified
  ) VALUES (
    v_request.id,
    v_request.restaurant_id,
    btrim(v_address->>'customer_name'),
    btrim(v_address->>'customer_phone'),
    btrim(v_address->>'formatted_address'),
    btrim(v_address->>'detail_address'),
    (v_address->>'latitude')::numeric,
    (v_address->>'longitude')::numeric,
    NULLIF(btrim(COALESCE(v_address->>'google_place_id', '')), ''),
    NULLIF(btrim(COALESCE(v_address->>'district', '')), ''),
    NULLIF(btrim(COALESCE(v_address->>'ward', '')), ''),
    v_address->>'address_source',
    v_address->>'address_source' IN ('search','map_pin')
  );

  IF v_address->>'address_source' IN ('search','map_pin') THEN
    INSERT INTO public.direct_order_location_facts(
      request_id, restaurant_id, district, ward,
      coarse_latitude, coarse_longitude, requested_at
    ) VALUES (
      v_request.id,
      v_request.restaurant_id,
      NULLIF(btrim(COALESCE(v_address->>'district', '')), ''),
      NULLIF(btrim(COALESCE(v_address->>'ward', '')), ''),
      round((v_address->>'latitude')::numeric, 3),
      round((v_address->>'longitude')::numeric, 3),
      v_request.created_at
    );
  END IF;

  INSERT INTO public.direct_order_messages(
    request_id, restaurant_id, sender_type, message_type, body
  ) VALUES (
    v_request.id,
    v_request.restaurant_id,
    'system',
    'system',
    'DIRECT_ORDER_REQUEST_RECEIVED'
  );

  RETURN jsonb_build_object(
    'request_id', v_request.id,
    'reference_code', v_request.reference_code,
    'state', v_request.state,
    'idempotent', false
  );
END;
$_$;

CREATE OR REPLACE FUNCTION "public"."direct_order_approve_payment_before_combo"("p_store_id" "uuid", "p_request_id" "uuid", "p_confirmed_amount" numeric, "p_confirmed_bank_reference" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
  v_actor public.users%ROWTYPE;
  v_reviewed_proof_id uuid;
  v_request public.direct_order_requests%ROWTYPE;
  v_quote public.direct_order_quotes%ROWTYPE;
  v_existing public.direct_order_financials%ROWTYPE;
  v_storefront public.direct_order_storefronts%ROWTYPE;
  v_mode text;
  v_order public.orders%ROWTYPE;
  v_previous_direct_pos text := current_setting('app.direct_order_pos_id',true);
  v_previous_direct_request text := current_setting('app.direct_order_request_id',true);
  v_payment public.payments%ROWTYPE;
  v_ticket public.direct_delivery_fulfillment_tickets%ROWTYPE;
  v_order_total numeric(15,2);
  v_local_time time;
BEGIN
  v_actor := public.direct_order_require_actor(
    p_store_id,
    ARRAY['cashier', 'admin', 'store_admin', 'brand_admin', 'super_admin']
  );
  IF p_confirmed_amount IS NULL OR p_confirmed_amount <= 0
     OR char_length(COALESCE(p_confirmed_bank_reference, '')) > 200 THEN
    RAISE EXCEPTION 'DIRECT_ORDER_APPROVAL_INPUT_INVALID';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('direct-order-approval:' || p_request_id::text, 0)
  );

  SELECT * INTO v_existing
  FROM public.direct_order_financials financial
  WHERE financial.request_id = p_request_id
    AND financial.restaurant_id = p_store_id;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'request_id', v_existing.request_id,
      'order_id', v_existing.order_id,
      'payment_id', v_existing.payment_id,
      'ticket_id', (
        SELECT ticket.id
        FROM public.direct_delivery_fulfillment_tickets ticket
        WHERE ticket.request_id = v_existing.request_id
          AND ticket.restaurant_id = p_store_id
      ),
      'final_total', v_existing.final_total,
      'idempotent', true
    );
  END IF;

  SELECT * INTO v_request
  FROM public.direct_order_requests request_row
  WHERE request_row.id = p_request_id
    AND request_row.restaurant_id = p_store_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'DIRECT_ORDER_REQUEST_NOT_FOUND'; END IF;
  IF v_request.state <> 'awaiting_payment_review' THEN
    RAISE EXCEPTION 'DIRECT_ORDER_REQUEST_NOT_APPROVABLE';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.direct_order_proof_review_requests review
    WHERE review.request_id = p_request_id
      AND review.restaurant_id = p_store_id
      AND review.status = 'requested'
  ) THEN
    RAISE EXCEPTION 'DIRECT_ORDER_PROOF_RESUBMISSION_PENDING';
  END IF;

  SELECT * INTO v_storefront
  FROM public.direct_order_storefronts storefront
  WHERE storefront.restaurant_id = p_store_id
    AND storefront.is_enabled = true
  FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'DIRECT_ORDER_STOREFRONT_DISABLED'; END IF;

  v_local_time := (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::time;
  -- The intake window never blocks review of an already submitted payment.

  SELECT COALESCE(settings.fulfillment_mode, 'pos_print') INTO v_mode
  FROM public.restaurant_settings settings
  WHERE settings.restaurant_id = p_store_id;
  v_mode := COALESCE(v_mode, 'pos_print');
  -- Direct delivery is routed through its isolated fulfillment ticket graph.
  -- Keep its financial order snapshots on pos_print so a paperless dine-in
  -- workflow cannot intercept or duplicate the delivery ticket.

  -- Direct delivery uses its own fulfillment ticket graph, so an active
  -- paperless emergency session cannot intercept or duplicate this ticket.

  IF EXISTS (
    SELECT 1 FROM public.store_promotions promotion
    WHERE promotion.restaurant_id = p_store_id
      AND promotion.is_active = true
      AND now() >= promotion.starts_at
      AND now() < promotion.ends_at
  ) THEN
    RAISE EXCEPTION 'DIRECT_ORDER_PROMOTION_ACTIVE';
  END IF;

  SELECT * INTO v_quote
  FROM public.direct_order_quotes quote
  WHERE quote.request_id = v_request.id
    AND quote.restaurant_id = p_store_id
    AND quote.status = 'locked'
  ORDER BY quote.version DESC
  LIMIT 1
  FOR UPDATE;
  -- Uploading payment proof locks the quoted amount. The locked quote remains
  -- approvable after its browsing TTL because amount, proof, and menu integrity
  -- are all revalidated below before the atomic payment is created.
  IF NOT FOUND THEN
    RAISE EXCEPTION 'DIRECT_ORDER_QUOTE_EXPIRED';
  END IF;
  IF round(p_confirmed_amount, 2) IS DISTINCT FROM round(v_quote.final_total, 2) THEN
    RAISE EXCEPTION 'DIRECT_ORDER_PAYMENT_AMOUNT_MISMATCH';
  END IF;
  SELECT message.id INTO v_reviewed_proof_id
  FROM public.direct_order_messages message
  WHERE message.request_id = v_request.id
    AND message.restaurant_id = p_store_id
    AND message.sender_type = 'customer'
    AND message.message_type = 'payment_proof'
    AND message.attachment_storage_path IS NOT NULL
    AND message.metadata->>'quote_id' = v_quote.id::text
    AND message.metadata->>'quote_version' = v_quote.version::text
  ORDER BY message.created_at DESC, message.id DESC
  LIMIT 1;

  -- Preserve the optional legacy verified-transfer caller. Photo review is
  -- sufficient for authenticated staff and never requires that integration.
  IF v_reviewed_proof_id IS NULL AND NOT EXISTS (
    SELECT 1
    FROM public.direct_order_sepay_candidates payment_link
    JOIN public.sepay_transactions payment_transaction
      ON payment_transaction.id = payment_link.sepay_transaction_id
    WHERE payment_link.request_id = v_request.id
      AND payment_link.restaurant_id = p_store_id
      AND payment_transaction.restaurant_id = p_store_id
      AND payment_transaction.transfer_type = 'in'
      AND payment_transaction.resolution_status = 'matched'
      AND payment_transaction.transfer_amount::numeric = v_quote.final_total
  ) THEN
    RAISE EXCEPTION 'DIRECT_ORDER_PAYMENT_PROOF_REQUIRED';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.direct_order_request_items request_item
    LEFT JOIN public.menu_items menu ON menu.id = request_item.menu_item_id
    WHERE request_item.request_id = v_request.id
      AND (
        menu.id IS NULL OR menu.restaurant_id <> p_store_id
        OR menu.is_available = false OR menu.is_visible_public = false
        OR CASE WHEN request_item.menu_option_snapshot->>'choice_schema'='1' THEN
          request_item.menu_option_snapshot->>'catalog_revision' IS DISTINCT FROM md5(menu.menu_option_key)
          OR (request_item.menu_option_snapshot->>'unit_price')::numeric IS DISTINCT FROM request_item.unit_price
        ELSE menu.choice_definition<>'{}'::jsonb OR menu.price IS DISTINCT FROM request_item.unit_price END
      )
  ) THEN
    RAISE EXCEPTION 'DIRECT_ORDER_MENU_CHANGED';
  END IF;

  IF v_quote.delivery_fee_total IS DISTINCT FROM 0::numeric THEN
    RAISE EXCEPTION 'DELIVERY_FEE_DISABLED';
  END IF;

  INSERT INTO public.orders(
    restaurant_id, table_id, sales_channel, status, guest_count,
    created_by, notes, order_source, order_purpose,
    fulfillment_mode_snapshot
  ) VALUES (
    p_store_id, NULL, CASE WHEN v_request.fulfillment_type='pickup' THEN 'takeaway' ELSE 'delivery' END, 'serving', v_request.diner_count,
    (SELECT auth.uid()),
    CASE WHEN v_request.fulfillment_type='pickup' THEN 'Direct pickup ' ELSE 'Direct delivery ' END || v_request.reference_code,
    'staff', 'customer', 'pos_print'
  ) RETURNING * INTO v_order;
  PERFORM set_config('app.direct_order_pos_id',v_order.id::text,true);
  PERFORM set_config('app.direct_order_request_id',v_request.id::text,true);

  PERFORM set_config('pos.direct_vat_request',v_request.id::text,true);
  INSERT INTO public.order_items(
    id, restaurant_id, order_id, menu_item_id, item_type, label,
    display_name, unit_price, quantity, status, notes,
    vat_rate, vat_amount, total_amount_ex_tax, paying_amount_inc_tax,
    is_service_item, fulfillment_mode_snapshot, menu_option_snapshot
  )
  SELECT
    item.id,
    p_store_id,
    v_order.id,
    item.menu_item_id,
    'menu_item',
    item.display_name,
    item.display_name,
    item.unit_price,
    item.quantity,
    'served',
    item.item_note,
    0, 0, 0, 0,
    false,
    'pos_print',item.menu_option_snapshot
  FROM public.direct_order_request_items item
  WHERE item.request_id = v_request.id
  ORDER BY item.sort_order, item.id;

  -- No delivery fee item is created, including a zero-value placeholder.

  INSERT INTO public.direct_delivery_fulfillment_tickets(
    request_id, restaurant_id, pickup_code, updated_by
  ) VALUES (
    v_request.id, p_store_id, v_request.reference_code, (SELECT auth.uid())
  ) RETURNING * INTO v_ticket;

  INSERT INTO public.direct_delivery_fulfillment_ticket_items(
    id, ticket_id, restaurant_id, menu_item_id,
    display_name_ko, display_name_vi, display_name_en,
    quantity, item_note, sort_order
  )
  SELECT
    item.id, v_ticket.id, p_store_id, item.menu_item_id,
    item.name_ko, item.name_vi, item.name_en,
    item.quantity, item.item_note, item.sort_order
  FROM public.direct_order_request_items item
  WHERE item.request_id = v_request.id
  ORDER BY item.sort_order, item.id;

  PERFORM set_config('pos.direct_vat_request','',true);
  -- This is the unchanged, authoritative payment anchor. It also produces
  -- brand service-charge lines, VAT snapshots, inventory deductions, and the
  -- asynchronous MISA queue record. Any mismatch below rolls all of it back.
  v_payment := public.process_payment(
    v_order.id, p_store_id, v_quote.final_total, 'BANKTRANSFER'
  );

  SELECT round(COALESCE(sum(item.paying_amount_inc_tax), 0), 2)
  INTO v_order_total
  FROM public.order_items item
  WHERE item.order_id = v_order.id
    AND item.status <> 'cancelled'
    AND COALESCE(item.is_service_item, false) = false;

  IF v_order_total IS DISTINCT FROM round(v_quote.final_total, 2)
     OR round(v_payment.amount_portion, 2) IS DISTINCT FROM round(v_quote.final_total, 2)
     OR NOT EXISTS (
       SELECT 1 FROM public.orders completed_order
       WHERE completed_order.id = v_order.id
         AND completed_order.status = 'completed'
     ) THEN
    RAISE EXCEPTION 'DIRECT_ORDER_FINANCIAL_RECONCILIATION_FAILED';
  END IF;

  INSERT INTO public.direct_order_financials(
    request_id, restaurant_id, quote_id, order_id, payment_id,
    delivery_fee_item_id, menu_total, service_charge_total,
    delivery_fee_total, final_total, confirmed_bank_reference, delivery_payment_mode,
    approved_by
  ) VALUES (
    v_request.id, p_store_id, v_quote.id, v_order.id, v_payment.id,
    NULL::uuid, v_quote.menu_total, v_quote.service_charge_total,
    v_quote.delivery_fee_total, v_quote.final_total,
    NULLIF(btrim(COALESCE(p_confirmed_bank_reference, '')), ''), v_quote.delivery_payment_mode,
    (SELECT auth.uid())
  );

  UPDATE public.direct_order_requests
  SET state = 'approved', approved_at = now(), updated_at = now()
  WHERE id = v_request.id;

  INSERT INTO public.direct_order_messages(
    request_id, restaurant_id, sender_type, message_type, body,
    metadata
  ) VALUES (
    v_request.id, p_store_id, 'system', 'system',
    'DIRECT_ORDER_PAYMENT_APPROVED',
    jsonb_build_object('order_id', v_order.id, 'ticket_id', v_ticket.id)
  );

  INSERT INTO public.audit_logs(actor_id, action, entity_type, entity_id, details)
  VALUES (
    (SELECT auth.uid()),
    'direct_order_payment_approved',
    'direct_order_requests',
    v_request.id,
    jsonb_build_object(
      'store_id', p_store_id,
      'quote_id', v_quote.id,
      'order_id', v_order.id,
      'payment_id', v_payment.id,
      'ticket_id', v_ticket.id,
      'final_total', v_quote.final_total,
      'review_method', CASE WHEN v_reviewed_proof_id IS NOT NULL
        THEN 'customer_photo' ELSE 'sepay' END,
      'proof_message_id', v_reviewed_proof_id
    )
  );

  PERFORM set_config('app.direct_order_pos_id',COALESCE(v_previous_direct_pos,''),true);
  PERFORM set_config('app.direct_order_request_id',COALESCE(v_previous_direct_request,''),true);
  RETURN jsonb_build_object(
    'request_id', v_request.id,
    'order_id', v_order.id,
    'payment_id', v_payment.id,
    'ticket_id', v_ticket.id,
    'final_total', v_quote.final_total,
    'idempotent', false
  );
END;
$$;

CREATE OR REPLACE FUNCTION "public"."capture_menu_option_batch"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
 IF current_setting('globos.cashier_item_mutation',true) IS DISTINCT FROM 'on' AND EXISTS(
  SELECT 1 FROM new_menu_lines n JOIN public.menu_items m ON m.id=n.menu_item_id
  WHERE m.choice_definition<>'{}'::jsonb AND (n.menu_option_snapshot->>'choice_schema' IS DISTINCT FROM '1'
   OR (n.menu_option_snapshot->>'unit_price')::numeric IS DISTINCT FROM n.unit_price)
 ) THEN RAISE EXCEPTION 'MENU_ITEM_PRICE_INVALID'; END IF;
 IF TG_TABLE_NAME='order_items' THEN
  -- Cashier splits copy the original immutable row; never reprice or replace it.
  IF current_setting('globos.cashier_item_mutation',true)='on' THEN RETURN NULL; END IF;
  IF EXISTS(SELECT 1 FROM new_menu_lines n JOIN public.menu_items m ON m.id=n.menu_item_id
    WHERE n.menu_option_snapshot='{}'::jsonb AND (m.meal_choice<>'' OR m.portion_code<>'' OR m.spice_level<>'unknown' OR m.spice_choice<>'')
     AND (n.restaurant_id<>m.restaurant_id OR NOT m.is_available OR m.is_archived
      OR (NOT n.is_service_item AND n.unit_price<>m.price))) THEN RAISE EXCEPTION 'MENU_ITEM_PRICE_INVALID'; END IF;
  UPDATE public.order_items o SET menu_option_snapshot=jsonb_build_object(
    'menu_item_id',m.id,'meal_choice',m.meal_choice,'portion_code',m.portion_code,'spice_level',m.spice_level,'spice_choice',m.spice_choice,
    'unit_price',n.unit_price,'name_ko',m.name_ko,'name_vi',m.name_vi,'name_en',m.name_en),
    label=m.name,display_name=m.name
  FROM new_menu_lines n JOIN public.menu_items m ON m.id=n.menu_item_id
  WHERE o.id=n.id AND n.menu_option_snapshot='{}'::jsonb AND (m.meal_choice<>'' OR m.portion_code<>'' OR m.spice_level<>'unknown' OR m.spice_choice<>'');
  IF nullif(current_setting('app.direct_order_request_id',true),'') IS NOT NULL THEN
   UPDATE public.order_items o SET menu_option_snapshot=r.menu_option_snapshot,
    label=r.display_name,display_name=r.display_name
   FROM new_menu_lines n JOIN public.direct_order_request_items r
    ON r.request_id=nullif(current_setting('app.direct_order_request_id',true),'')::uuid
    AND r.id=n.id AND r.restaurant_id=n.restaurant_id
   WHERE o.id=n.id AND r.menu_option_snapshot<>'{}'::jsonb;
  END IF;
 ELSE
  UPDATE public.direct_order_request_items o SET menu_option_snapshot=jsonb_build_object(
    'menu_item_id',m.id,'meal_choice',m.meal_choice,'portion_code',m.portion_code,'spice_level',m.spice_level,'spice_choice',m.spice_choice,
    'unit_price',n.unit_price,'name_ko',n.name_ko,'name_vi',n.name_vi,'name_en',n.name_en)
  FROM new_menu_lines n JOIN public.menu_items m ON m.id=n.menu_item_id AND m.restaurant_id=n.restaurant_id
  WHERE o.id=n.id AND n.menu_option_snapshot='{}'::jsonb AND (m.meal_choice<>'' OR m.portion_code<>'' OR m.spice_level<>'unknown' OR m.spice_choice<>'');
 END IF;

 -- Component choices are keyed by their stable sellable ID in the order-time
 -- snapshot. One aggregate JOIN covers the complete inserted batch.
 IF TG_TABLE_NAME='order_items' AND nullif(current_setting('app.direct_order_request_id',true),'') IS NULL THEN
  WITH parts AS (
   SELECT n.id,jsonb_object_agg(m.id::text,jsonb_build_object('menu_item_id',m.id,
    'meal_choice',m.meal_choice,'portion_code',m.portion_code,'spice_level',m.spice_level,'spice_choice',m.spice_choice,
    'name_ko',coalesce(c->>'name_ko',m.name_ko),'name_vi',coalesce(c->>'name_vi',m.name_vi),
    'name_en',coalesce(c->>'name_en',m.name_en),'unit_price',coalesce(c->'tax_unit_price',to_jsonb(m.price)))) data
   FROM new_menu_lines n CROSS JOIN LATERAL jsonb_array_elements(coalesce(n.combo_components,'[]'))c
   JOIN public.menu_items m ON m.id=(c->>'menu_item_id')::uuid AND m.restaurant_id=n.restaurant_id
   WHERE m.menu_option_key IS NOT NULL GROUP BY n.id
  ) UPDATE public.order_items o SET menu_option_snapshot=
   CASE WHEN o.menu_option_snapshot='{}'::jsonb THEN jsonb_build_object('menu_item_id',m.id,
    'meal_choice',m.meal_choice,'portion_code',m.portion_code,'spice_level',m.spice_level,'spice_choice',m.spice_choice,
    'name_ko',m.name_ko,'name_vi',m.name_vi,'name_en',m.name_en,'unit_price',o.unit_price)
    ELSE o.menu_option_snapshot END || jsonb_build_object('components',p.data)
   FROM parts p,new_menu_lines n,public.menu_items m WHERE o.id=p.id AND n.id=o.id AND m.id=n.menu_item_id;
 ELSIF TG_TABLE_NAME='direct_order_request_items' THEN
  WITH parts AS (
   SELECT n.id,jsonb_object_agg(m.id::text,jsonb_build_object('menu_item_id',m.id,
    'meal_choice',m.meal_choice,'portion_code',m.portion_code,'spice_level',m.spice_level,'spice_choice',m.spice_choice,
    'name_ko',coalesce(c->>'name_ko',m.name_ko),'name_vi',coalesce(c->>'name_vi',m.name_vi),
    'name_en',coalesce(c->>'name_en',m.name_en),'unit_price',coalesce(c->'tax_unit_price',to_jsonb(m.price)))) data
   FROM new_menu_lines n CROSS JOIN LATERAL jsonb_array_elements(coalesce(n.combo_components,'[]'))c
   JOIN public.menu_items m ON m.id=(c->>'menu_item_id')::uuid AND m.restaurant_id=n.restaurant_id
   WHERE m.menu_option_key IS NOT NULL GROUP BY n.id
  ) UPDATE public.direct_order_request_items o SET menu_option_snapshot=
   CASE WHEN o.menu_option_snapshot='{}'::jsonb THEN jsonb_build_object('menu_item_id',m.id,
    'meal_choice',m.meal_choice,'portion_code',m.portion_code,'spice_level',m.spice_level,'spice_choice',m.spice_choice,
    'name_ko',m.name_ko,'name_vi',m.name_vi,'name_en',m.name_en,'unit_price',o.unit_price)
    ELSE o.menu_option_snapshot END || jsonb_build_object('components',p.data)
   FROM parts p,new_menu_lines n,public.menu_items m WHERE o.id=p.id AND n.id=o.id AND m.id=n.menu_item_id;
 END IF;
 -- Freeze the registered recipe basis for configured choices in one aggregate
 -- per inserted batch. A later menu recipe edit cannot reprice stock history.
 EXECUTE format($basis$
  WITH lines AS MATERIALIZED(SELECT * FROM new_menu_lines WHERE menu_option_snapshot->>'choice_schema'='1' AND NOT menu_option_snapshot ? 'recipe_basis'),
  base AS(SELECT n.id,jsonb_agg(jsonb_build_object('ingredient_id',r.ingredient_id,'quantity_g',r.quantity_g*n.quantity) ORDER BY r.ingredient_id) items
   FROM lines n JOIN public.menu_recipes r ON r.menu_item_id=n.menu_item_id AND r.restaurant_id=n.restaurant_id GROUP BY n.id),
  combo_totals AS(SELECT n.id,r.ingredient_id,sum(r.quantity_g*(c->>'quantity')::numeric*CASE WHEN coalesce((c->>'is_total_quantity')::boolean,false) THEN 1 ELSE n.quantity END) quantity_g
   FROM lines n CROSS JOIN LATERAL jsonb_array_elements(coalesce(n.combo_components,'[]'))c JOIN public.menu_recipes r ON r.menu_item_id=(c->>'menu_item_id')::uuid AND r.restaurant_id=n.restaurant_id GROUP BY n.id,r.ingredient_id),
  combo AS(SELECT id,jsonb_agg(jsonb_build_object('ingredient_id',ingredient_id,'quantity_g',quantity_g) ORDER BY ingredient_id) items FROM combo_totals GROUP BY id),
  snapshots AS(SELECT n.id,jsonb_build_object('recipe_basis',jsonb_build_object('quantity',n.quantity,'items',coalesce(b.items,'[]')),'combo_recipe_basis',jsonb_build_object('quantity',n.quantity,'items',coalesce(c.items,'[]'))) data
   FROM lines n LEFT JOIN base b ON b.id=n.id LEFT JOIN combo c ON c.id=n.id)
  UPDATE public.%I o SET menu_option_snapshot=o.menu_option_snapshot||s.data||jsonb_build_object('choice_signature',md5((o.menu_option_snapshot->>'choice_signature')||s.data::text)) FROM snapshots s WHERE o.id=s.id
 $basis$,TG_TABLE_NAME);
 RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION "public"."snapshot_order_item_takeout"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_payload_text text;
  v_payload jsonb;
  v_selected jsonb;
  v_selected_ordinal bigint;
  v_remaining jsonb;
BEGIN
  v_payload_text := current_setting('pos.order_takeout_payload', true);
  IF NULLIF(v_payload_text, '') IS NULL THEN
    RETURN NEW;
  END IF;

  v_payload := v_payload_text::jsonb;
  SELECT line.raw, line.ord
  INTO v_selected, v_selected_ordinal
  FROM jsonb_array_elements(v_payload)
    WITH ORDINALITY AS line(raw, ord)
  WHERE line.raw->>'menu_item_id' = NEW.menu_item_id::text
    AND (NOT (NEW.menu_option_snapshot ? 'selection_key') OR line.raw->>'menu_option_key'=NEW.menu_option_snapshot->>'selection_key')
    AND COALESCE((line.raw->>'quantity')::integer, 0) = NEW.quantity
  ORDER BY line.ord
  LIMIT 1;

  IF v_selected IS NULL THEN
    SELECT line.raw, line.ord
    INTO v_selected, v_selected_ordinal
    FROM jsonb_array_elements(v_payload)
      WITH ORDINALITY AS line(raw, ord)
    WHERE line.raw->>'menu_item_id' = NEW.menu_item_id::text
    AND (NOT (NEW.menu_option_snapshot ? 'selection_key') OR line.raw->>'menu_option_key'=NEW.menu_option_snapshot->>'selection_key')
    ORDER BY line.ord
    LIMIT 1;
  END IF;

  IF v_selected IS NOT NULL THEN
    NEW.is_takeout := COALESCE((v_selected->>'is_takeout')::boolean, false);
    SELECT COALESCE(jsonb_agg(line.raw ORDER BY line.ord), '[]'::jsonb)
    INTO v_remaining
    FROM jsonb_array_elements(v_payload)
      WITH ORDINALITY AS line(raw, ord)
    WHERE line.ord <> v_selected_ordinal;
    PERFORM set_config('pos.order_takeout_payload', v_remaining::text, true);
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."snapshot_order_item_combo_components"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_payload_text text;
  v_selected jsonb := '[]'::jsonb;
  v_fixed jsonb := '[]'::jsonb;
  v_drinks jsonb := '[]'::jsonb;
  v_direct_enabled boolean := false;
BEGIN
 IF TG_OP='INSERT' AND NULLIF(current_setting('pos.direct_line_snapshots',true),'') IS NOT NULL
  AND current_setting('pos.direct_line_snapshots',true)::jsonb ? NEW.id::text THEN
  NEW.combo_components:=current_setting('pos.direct_line_snapshots',true)::jsonb->NEW.id::text->'combo_components';
  RETURN NEW;
 END IF;
 IF current_setting('globos.cashier_item_mutation',true)='on' THEN RETURN NEW; END IF;
  IF NEW.menu_item_id IS NULL THEN
    NEW.combo_components := '[]'::jsonb;
    RETURN NEW;
  END IF;

  SELECT COALESCE(settings.floor_direct_beverages_enabled, false)
  INTO v_direct_enabled
  FROM public.restaurant_settings settings
  WHERE settings.restaurant_id = NEW.restaurant_id;

  IF EXISTS (
    SELECT 1 FROM public.orders order_row
    WHERE order_row.id = NEW.order_id
      AND order_row.sales_channel = 'delivery'
  ) THEN
    v_direct_enabled := false;
  END IF;

  v_payload_text := current_setting('pos.qr_combo_payload', true);
  IF NULLIF(v_payload_text, '') IS NOT NULL THEN
    SELECT COALESCE(line.raw->'combo_drink_choices', '[]'::jsonb)
    INTO v_selected
    FROM jsonb_array_elements(v_payload_text::jsonb) line(raw)
    WHERE line.raw->>'menu_item_id' = NEW.menu_item_id::text
      AND (NOT (NEW.menu_option_snapshot ? 'selection_key') OR line.raw->>'menu_option_key'=NEW.menu_option_snapshot->>'selection_key')
      AND COALESCE((line.raw->>'is_takeout')::boolean, false) = NEW.is_takeout
    LIMIT 1;
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'menu_item_id', component_item.id::text,
      'label', component_item.name,
      'name_ko', COALESCE(NULLIF(component_item.name_ko, ''), component_item.name),
      'name_vi', COALESCE(NULLIF(component_item.name_vi, ''), component_item.name),
      'name_en', COALESCE(NULLIF(component_item.name_en, ''), component_item.name),
      'quantity', component.quantity,
      'fulfillment_route', CASE
        WHEN NEW.fulfillment_mode_snapshot = 'paperless'
          AND v_direct_enabled
          THEN component_item.fulfillment_route
        ELSE 'kitchen_tray_floor'
      END
    ) ORDER BY component.sort_order, component.created_at, component.id
  ), '[]'::jsonb)
  INTO v_fixed
  FROM public.menu_combo_components component
  JOIN public.menu_items component_item
    ON component_item.id = component.component_menu_item_id
   AND component_item.restaurant_id = component.restaurant_id
  WHERE component.combo_menu_item_id = NEW.menu_item_id
    AND component.restaurant_id = NEW.restaurant_id
    AND (
      jsonb_array_length(v_selected) = 0
      OR lower(btrim(COALESCE(NULLIF(component_item.name_ko, ''), component_item.name)))
        NOT IN ('음료', 'drink', 'beverage', 'đồ uống', 'nước uống')
    );

  IF jsonb_array_length(v_selected) > 0 THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'menu_item_id', selected_item.id::text,
      'label', selected_item.name,
      'name_ko', COALESCE(NULLIF(selected_item.name_ko, ''), selected_item.name),
      'name_vi', COALESCE(NULLIF(selected_item.name_vi, ''), selected_item.name),
      'name_en', COALESCE(NULLIF(selected_item.name_en, ''), selected_item.name),
      'quantity', selected.quantity,
      'is_total_quantity', true,
      'fulfillment_route', CASE
        WHEN NEW.fulfillment_mode_snapshot = 'paperless'
          AND v_direct_enabled
          THEN selected_item.fulfillment_route
        ELSE 'kitchen_tray_floor'
      END
    ) ORDER BY selected.first_ordinal), '[]'::jsonb)
    INTO v_drinks
    FROM (
      SELECT choice.value::uuid AS item_id,
             count(*)::integer AS quantity,
             min(choice.ordinality) AS first_ordinal
      FROM jsonb_array_elements_text(v_selected)
        WITH ORDINALITY choice(value, ordinality)
      GROUP BY choice.value
    ) selected
    JOIN public.menu_items selected_item
      ON selected_item.id = selected.item_id
     AND selected_item.restaurant_id = NEW.restaurant_id;
  END IF;

  NEW.combo_components := v_fixed || v_drinks;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."direct_order_enrich_translations"("p_base" "jsonb", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
 WITH notes AS (
 SELECT source_kind,source_id,source_text,jsonb_object_agg(target_locale,translated_text) FILTER(WHERE status='translated') translations,
 CASE WHEN bool_and(status='translated') THEN 'translated' WHEN bool_or(status='failed') THEN 'failed' ELSE 'pending' END status
 FROM public.direct_order_translation_jobs WHERE request_id=$2 GROUP BY source_kind,source_id,source_text
 ), messages AS (
 SELECT COALESCE(jsonb_agg(e.value||jsonb_build_object('metadata',m.metadata||jsonb_build_object('translation_status',COALESCE(n.status,'original'))) ORDER BY e.ordinality),'[]'::jsonb) value
 FROM jsonb_array_elements(COALESCE($1->'messages','[]'::jsonb)) WITH ORDINALITY e LEFT JOIN public.direct_order_messages m ON m.id=(e.value->>'id')::uuid
 LEFT JOIN notes n ON n.source_kind='message' AND n.source_id=m.id AND n.source_text=m.body
 ), items AS (
 SELECT COALESCE(jsonb_agg(e.value||jsonb_build_object('note_translations',COALESCE(n.translations,'{}'::jsonb),'translation_status',COALESCE(n.status,'original')) ORDER BY e.ordinality),'[]'::jsonb) value
 FROM jsonb_array_elements(COALESCE($1->'items','[]'::jsonb)) WITH ORDINALITY e
 LEFT JOIN (SELECT i.*,row_number() OVER(ORDER BY sort_order,id) ord FROM public.direct_order_request_items i WHERE request_id=$2)i ON i.ord=e.ordinality
 LEFT JOIN notes n ON n.source_kind='item_note' AND n.source_id=i.id AND n.source_text=i.item_note
 ), quotes AS (
 SELECT COALESCE(jsonb_agg(e.value||jsonb_build_object('note_translations',COALESCE(n.translations,'{}'::jsonb),'translation_status',COALESCE(n.status,'original')) ORDER BY e.ordinality),'[]'::jsonb) value
 FROM jsonb_array_elements(COALESCE($1->'quotes','[]'::jsonb)) WITH ORDINALITY e LEFT JOIN notes n ON n.source_kind='cashier_note' AND n.source_id::text=e.value->>'id' AND n.source_text=e.value->>'cashier_note'
 )
 SELECT $1||jsonb_build_object('messages',messages.value,'items',items.value)||CASE WHEN $1?'quotes' THEN jsonb_build_object('quotes',quotes.value) ELSE '{}'::jsonb END
 ||CASE WHEN jsonb_typeof($1->'quote')='object' THEN jsonb_build_object('quote',($1->'quote')||(SELECT jsonb_build_object('cashier_note',q.cashier_note,'note_translations',COALESCE(n.translations,'{}'::jsonb),'translation_status',COALESCE(n.status,'original')) FROM public.direct_order_quotes q LEFT JOIN notes n ON n.source_kind='cashier_note' AND n.source_id=q.id AND n.source_text=q.cashier_note WHERE q.id::text=$1->'quote'->>'id')) ELSE '{}'::jsonb END
 ||CASE WHEN $1?'request' THEN jsonb_build_object('request',($1->'request')||jsonb_build_object('note_translations',COALESCE((SELECT translations FROM notes WHERE source_kind='customer_note' AND source_text=$1->'request'->>'customer_note'),'{}'::jsonb),'translation_status',COALESCE((SELECT status FROM notes WHERE source_kind='customer_note' AND source_text=$1->'request'->>'customer_note'),'original'))) ELSE '{}'::jsonb END
 FROM messages CROSS JOIN items CROSS JOIN quotes;
$_$;

CREATE OR REPLACE FUNCTION "public"."direct_order_public_status_v11"("p_session_id" "uuid", "p_secret_hash" "text", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
DECLARE payload jsonb; items jsonb;
BEGIN
 payload:=public.direct_order_public_status_v10($1,$2,$3);
 SELECT COALESCE(jsonb_agg(e.raw||CASE WHEN jsonb_array_length(i.combo_components)>0 THEN jsonb_build_object('combo_components',i.combo_components) ELSE '{}'::jsonb END ORDER BY e.ord),'[]')
 INTO items FROM jsonb_array_elements(payload->'items') WITH ORDINALITY e(raw,ord)
 LEFT JOIN (SELECT i.*,row_number() OVER(ORDER BY sort_order,id) ord FROM public.direct_order_request_items i WHERE request_id=$3)i ON i.ord=e.ord;
 RETURN jsonb_set(payload,'{items}',items);
END $_$;

CREATE OR REPLACE FUNCTION "public"."direct_order_staff_detail_v8"("p_store_id" "uuid", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $_$
DECLARE payload jsonb; items jsonb;
BEGIN
 payload:=public.direct_order_staff_detail_v7($1,$2);
 SELECT COALESCE(jsonb_agg(e.raw||CASE WHEN jsonb_array_length(i.combo_components)>0 THEN jsonb_build_object('combo_components',i.combo_components) ELSE '{}'::jsonb END ORDER BY e.ord),'[]')
 INTO items FROM jsonb_array_elements(payload->'items') WITH ORDINALITY e(raw,ord)
 LEFT JOIN public.direct_order_request_items i ON i.request_id=$2 AND i.restaurant_id=$1 AND i.id::text=e.raw->>'id';
 RETURN jsonb_set(payload,'{items}',items);
END $_$;

CREATE OR REPLACE FUNCTION "public"."direct_order_quote_preview_core"("p_store_id" "uuid", "p_request_id" "uuid", "p_validate_menu" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE v_combo boolean; mode text; enabled boolean; rate numeric; minimum numeric; result jsonb; n integer;
BEGIN
 SELECT COALESCE(s.vat_pricing_mode,'exclusive'),COALESCE(b.service_charge_enabled,false),COALESCE(b.service_charge_rate,0),sf.minimum_order_amount
 INTO mode,enabled,rate,minimum FROM public.restaurants s LEFT JOIN public.brands b ON b.id=s.brand_id
 JOIN public.direct_order_storefronts sf ON sf.restaurant_id=s.id WHERE s.id=p_store_id AND sf.is_enabled
 AND sf.accounting_approved_at IS NOT NULL AND sf.accounting_approved_by IS NOT NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'DIRECT_ORDER_ACCOUNTING_APPROVAL_REQUIRED'; END IF;
 SELECT count(*) INTO n FROM public.direct_order_request_items WHERE request_id=p_request_id AND restaurant_id=p_store_id;
 IF n NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'DIRECT_ORDER_QUOTE_INPUT_INVALID'; END IF;
 IF p_validate_menu AND EXISTS(SELECT 1 FROM public.direct_order_request_items i LEFT JOIN public.menu_items m ON m.id=i.menu_item_id
 WHERE i.request_id=p_request_id AND (m.id IS NULL OR m.restaurant_id<>p_store_id OR NOT m.is_available OR NOT m.is_visible_public OR CASE WHEN i.menu_option_snapshot->>'choice_schema'='1' THEN i.menu_option_snapshot->>'catalog_revision' IS DISTINCT FROM md5(m.menu_option_key) OR (i.menu_option_snapshot->>'unit_price')::numeric IS DISTINCT FROM i.unit_price ELSE m.choice_definition<>'{}'::jsonb OR m.price IS DISTINCT FROM i.unit_price END))
 THEN RAISE EXCEPTION 'DIRECT_ORDER_MENU_CHANGED'; END IF;
 IF p_validate_menu THEN PERFORM public.direct_order_validate_combo_request(p_store_id,p_request_id); END IF;
 SELECT EXISTS(SELECT 1 FROM public.direct_order_request_items WHERE request_id=p_request_id AND restaurant_id=p_store_id AND jsonb_array_length(combo_components)>0) INTO v_combo;
 WITH priced AS MATERIALIZED(
  SELECT i.*,CASE WHEN v_combo THEN public.direct_order_combo_vnd_vat(COALESCE(NULLIF(to_jsonb(i)->'vat_profile_snapshot','null'::jsonb),
   jsonb_build_array(jsonb_build_object('rate',CASE WHEN i.vat_category='alcohol' THEN 10 ELSE 8 END,'weight',1))),round(i.unit_price*i.quantity,2),mode) ELSE public.calculate_item_vat(COALESCE(NULLIF(to_jsonb(i)->'vat_profile_snapshot','null'::jsonb),jsonb_build_array(jsonb_build_object('rate',CASE WHEN i.vat_category='alcohol' THEN 10 ELSE 8 END,'weight',1))),round(i.unit_price*i.quantity,2),mode) END tax
  FROM public.direct_order_request_items i WHERE i.request_id=p_request_id AND i.restaurant_id=p_store_id
 ), totals AS(SELECT sum((tax->>'supply')::numeric) supply,sum((tax->>'vat')::numeric) vat,sum((tax->>'total')::numeric) total FROM priced),
 parts AS(SELECT (e->>'vat_rate')::numeric vat_rate,sum((e->>'total_amount_ex_tax')::numeric) supply FROM priced CROSS JOIN LATERAL jsonb_array_elements(tax->'parts') e GROUP BY 1),
 service AS(SELECT COALESCE(sum(round(supply*rate/100,CASE WHEN v_combo THEN 0 ELSE 2 END)),0) supply,COALESCE(sum(round(round(supply*rate/100,CASE WHEN v_combo THEN 0 ELSE 2 END)*vat_rate/100,CASE WHEN v_combo THEN 0 ELSE 2 END)),0) vat FROM parts WHERE enabled AND rate>0 AND vat_rate IN(8,10))
 SELECT jsonb_build_object('menu_pretax',t.supply,'menu_vat',t.vat,'menu_total',t.total,
  'service_charge_pretax',s.supply,'service_charge_vat',s.vat,'service_charge_total',s.supply+s.vat,
  'delivery_fee_total',0,'delivery_fee_pretax',0,'delivery_fee_vat',0,'final_total',t.total+s.supply+s.vat,
  'vat_pricing_mode',mode) INTO result FROM totals t CROSS JOIN service s;
 IF (result->>'menu_total')::numeric<minimum THEN RAISE EXCEPTION 'DIRECT_ORDER_BELOW_MINIMUM'; END IF;
 RETURN result;
END $$;


CREATE OR REPLACE FUNCTION "public"."direct_order_staff_quote_before_final_amount"("p_store_id" "uuid", "p_request_id" "uuid", "p_delivery_fee_total" numeric, "p_cashier_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
  v_tax jsonb;
  v_request public.direct_order_requests%ROWTYPE;
  v_storefront public.direct_order_storefronts%ROWTYPE;
  v_brand public.brands%ROWTYPE;
  v_vat_pricing_mode text;
  v_line record;
  v_line_gross numeric(15,2);
  v_line_pretax numeric(15,2);
  v_line_vat numeric(15,2);
  v_line_total numeric(15,2);
  v_vat_rate numeric(5,2);
  v_food_pretax numeric(15,2) := 0;
  v_alcohol_pretax numeric(15,2) := 0;
  v_menu_pretax numeric(15,2) := 0;
  v_menu_vat numeric(15,2) := 0;
  v_menu_total numeric(15,2) := 0;
  v_sc_pretax numeric(15,2) := 0;
  v_sc_vat numeric(15,2) := 0;
  v_sc_total numeric(15,2) := 0;
  v_fee_pretax numeric(15,2);
  v_fee_vat numeric(15,2);
  v_final_total numeric(15,2);
  v_version integer;
  v_quote public.direct_order_quotes%ROWTYPE;
BEGIN
  PERFORM public.direct_order_require_actor(
    p_store_id,
    ARRAY['cashier', 'admin', 'store_admin', 'brand_admin', 'super_admin']
  );
  IF p_delivery_fee_total IS NULL OR p_delivery_fee_total < 0
     OR char_length(COALESCE(p_cashier_note, '')) > 500 THEN
    RAISE EXCEPTION 'DIRECT_ORDER_QUOTE_INPUT_INVALID';
  END IF;

  SELECT * INTO v_request
  FROM public.direct_order_requests request_row
  WHERE request_row.id = p_request_id
    AND request_row.restaurant_id = p_store_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'DIRECT_ORDER_REQUEST_NOT_FOUND'; END IF;
  IF v_request.state NOT IN ('awaiting_quote', 'quoted') THEN
    RAISE EXCEPTION 'DIRECT_ORDER_REQUEST_NOT_QUOTABLE';
  END IF;

  IF v_request.fulfillment_type='pickup' AND p_delivery_fee_total <> 0 THEN
    RAISE EXCEPTION 'DIRECT_ORDER_PICKUP_FEE_INVALID';
  END IF;

  IF v_request.fulfillment_method = 'pickup' AND p_delivery_fee_total <> 0 THEN
    RAISE EXCEPTION 'DIRECT_ORDER_PICKUP_FEE_INVALID';
  END IF;
  IF v_request.fulfillment_method = 'pickup' AND v_request.state = 'quoted' AND EXISTS (SELECT 1 FROM public.direct_order_quotes WHERE request_id=p_request_id AND status IN ('active','locked') AND delivery_fee_total>0) THEN
    RAISE EXCEPTION 'DIRECT_ORDER_PAYMENT_PROOF_REQUIRED';
  END IF;

  SELECT * INTO v_storefront
  FROM public.direct_order_storefronts storefront
  WHERE storefront.restaurant_id = p_store_id
    AND storefront.is_enabled = true
  FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'DIRECT_ORDER_STOREFRONT_DISABLED'; END IF;
  IF v_storefront.accounting_approved_at IS NULL
     OR v_storefront.accounting_approved_by IS NULL THEN
    RAISE EXCEPTION 'DIRECT_ORDER_ACCOUNTING_APPROVAL_REQUIRED';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.direct_order_request_items request_item
    LEFT JOIN public.menu_items menu ON menu.id = request_item.menu_item_id
    WHERE request_item.request_id = v_request.id
      AND (
        menu.id IS NULL
        OR menu.restaurant_id <> p_store_id
        OR menu.is_available = false
        OR menu.is_visible_public = false
        OR CASE WHEN request_item.menu_option_snapshot->>'choice_schema'='1' THEN request_item.menu_option_snapshot->>'catalog_revision' IS DISTINCT FROM md5(menu.menu_option_key) OR (request_item.menu_option_snapshot->>'unit_price')::numeric IS DISTINCT FROM request_item.unit_price ELSE menu.choice_definition<>'{}'::jsonb OR menu.price IS DISTINCT FROM request_item.unit_price END
      )
  ) THEN
    RAISE EXCEPTION 'DIRECT_ORDER_MENU_CHANGED';
  END IF;

  v_tax:=public.direct_order_quote_preview_core(p_store_id,v_request.id);
  v_menu_pretax:=(v_tax->>'menu_pretax')::numeric;
  v_menu_vat:=(v_tax->>'menu_vat')::numeric;
  v_menu_total:=(v_tax->>'menu_total')::numeric;
  v_sc_pretax:=(v_tax->>'service_charge_pretax')::numeric;
  v_sc_vat:=(v_tax->>'service_charge_vat')::numeric;
  v_sc_total:=(v_tax->>'service_charge_total')::numeric;
  IF v_storefront.delivery_fee_vat_rate = 0 THEN
    v_fee_pretax := round(p_delivery_fee_total, 2);
    v_fee_vat := 0;
  ELSE
    v_fee_pretax := round(
      p_delivery_fee_total / (1 + v_storefront.delivery_fee_vat_rate / 100),
      2
    );
    v_fee_vat := round(p_delivery_fee_total, 2) - v_fee_pretax;
  END IF;

  v_menu_pretax := round(v_menu_pretax, 2);
  v_menu_vat := round(v_menu_vat, 2);
  v_menu_total := round(v_menu_total, 2);
  v_sc_pretax := round(v_sc_pretax, 2);
  v_sc_vat := round(v_sc_vat, 2);
  v_sc_total := round(v_sc_total, 2);
  v_final_total := round(v_menu_total + v_sc_total + p_delivery_fee_total, 2);

  IF v_menu_total < v_storefront.minimum_order_amount THEN
    RAISE EXCEPTION 'DIRECT_ORDER_BELOW_MINIMUM';
  END IF;

  UPDATE public.direct_order_quotes
  SET status = 'superseded'
  WHERE request_id = v_request.id
    AND status = 'active';

  SELECT COALESCE(max(version), 0) + 1 INTO v_version
  FROM public.direct_order_quotes
  WHERE request_id = v_request.id;

  INSERT INTO public.direct_order_quotes(
    request_id, restaurant_id, version,
    menu_pretax, menu_vat, menu_total,
    service_charge_pretax, service_charge_vat, service_charge_total,
    delivery_fee_pretax, delivery_fee_vat, delivery_fee_total,
    final_total, delivery_fee_vat_rate, status, cashier_note,
    created_by, expires_at, delivery_payment_mode
  ) VALUES (
    v_request.id, p_store_id, v_version,
    v_menu_pretax, v_menu_vat, v_menu_total,
    v_sc_pretax, v_sc_vat, v_sc_total,
    v_fee_pretax, v_fee_vat, round(p_delivery_fee_total, 2),
    v_final_total, v_storefront.delivery_fee_vat_rate, 'active',
    NULLIF(btrim(COALESCE(p_cashier_note, '')), ''),
    (SELECT auth.uid()),
    now() + make_interval(mins => v_storefront.quote_ttl_minutes), CASE WHEN to_jsonb(v_request)->>'fulfillment_type'='pickup' THEN 'not_applicable' WHEN to_jsonb(v_request)->>'fulfillment_type' IS NULL AND v_request.fulfillment_method='pickup' THEN 'customer_direct' WHEN v_request.delivery_policy_version=2 THEN 'customer_direct' ELSE 'store_prepaid' END
  ) RETURNING * INTO v_quote;

  UPDATE public.direct_order_requests
  SET state = 'quoted', updated_at = now()
  WHERE id = v_request.id;

  INSERT INTO public.direct_order_messages(
    request_id, restaurant_id, sender_type, sender_auth_id,
    message_type, body, metadata
  ) VALUES (
    v_request.id,
    p_store_id,
    'cashier',
    (SELECT auth.uid()),
    'quote',
    'DIRECT_ORDER_QUOTE_SENT',
    jsonb_build_object(
      'quote_id', v_quote.id,
      'version', v_quote.version,
      'delivery_fee_total', v_quote.delivery_fee_total,
      'final_total', v_quote.final_total,
      'expires_at', v_quote.expires_at
    )
  );

  RETURN to_jsonb(v_quote) - ARRAY['restaurant_id', 'created_by'];
END;
$$;


CREATE OR REPLACE FUNCTION "public"."qr_place_order_before_daily_reset"("p_token" "text", "p_items" "jsonb", "p_client_order_id" "uuid", "p_validate_combo_choices" boolean, "p_expected_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
  v_token text := NULLIF(btrim(COALESCE(p_token, '')), '');
  v_table record;
  v_existing public.qr_order_batches%ROWTYPE;
  v_current_order_id uuid;
BEGIN
  SELECT qr.restaurant_id, qr.table_id
  INTO v_table
  FROM public.table_qr_tokens qr
  JOIN public.tables table_row
    ON table_row.id = qr.table_id
   AND table_row.restaurant_id = qr.restaurant_id
  JOIN public.restaurants restaurant
    ON restaurant.id = qr.restaurant_id
   AND restaurant.is_active = true
  WHERE qr.token = v_token
    AND qr.is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'QR_TOKEN_INVALID';
  END IF;

  SELECT *
  INTO v_existing
  FROM public.qr_order_batches batch
  WHERE batch.client_order_id = p_client_order_id
    AND batch.restaurant_id = v_table.restaurant_id
    AND batch.table_id = v_table.table_id;

  IF FOUND THEN
    IF v_existing.submission_hash IS NOT NULL AND v_existing.submission_hash IS DISTINCT FROM md5(p_items::text) THEN RAISE EXCEPTION 'QR_ITEMS_INVALID'; END IF;
    RETURN v_existing.result_snapshot;
  END IF;

  SELECT order_row.id
  INTO v_current_order_id
  FROM public.orders order_row
  WHERE order_row.table_id = v_table.table_id
    AND order_row.restaurant_id = v_table.restaurant_id
    AND order_row.status IN ('pending', 'confirmed', 'serving') AND public.table_order_is_current(order_row)
  ORDER BY order_row.created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF v_current_order_id IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM public.payments payment
       WHERE payment.order_id = v_current_order_id
         AND payment.is_revenue IS DISTINCT FROM true
     ) THEN
    RAISE EXCEPTION 'QR_ORDER_PAYMENT_IN_PROGRESS';
  END IF;

  RETURN public.qr_place_order_before_non_revenue_guard(
    p_token,
    p_items,
    p_client_order_id,
    p_validate_combo_choices,
    p_expected_order_id
  );
END;
$$;


CREATE OR REPLACE FUNCTION "public"."qr_place_order_pre_takeout_availability"("p_token" "text", "p_items" "jsonb", "p_client_order_id" "uuid", "p_validate_combo_choices" boolean, "p_expected_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
  v_token text := NULLIF(btrim(COALESCE(p_token, '')), '');
  v_table record;
  v_current_order_id uuid;
  v_existing public.qr_order_batches%ROWTYPE;
  v_result jsonb;
BEGIN
  SELECT qr.restaurant_id, qr.table_id INTO v_table
  FROM public.table_qr_tokens qr
  JOIN public.tables table_row
    ON table_row.id = qr.table_id
   AND table_row.restaurant_id = qr.restaurant_id
  JOIN public.restaurants restaurant
    ON restaurant.id = qr.restaurant_id AND restaurant.is_active = true
  WHERE qr.token = v_token AND qr.is_active = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'QR_TOKEN_INVALID'; END IF;

  SELECT * INTO v_existing
  FROM public.qr_order_batches batch
  WHERE batch.client_order_id = p_client_order_id
    AND batch.restaurant_id = v_table.restaurant_id
    AND batch.table_id = v_table.table_id;
  IF FOUND THEN IF v_existing.submission_hash IS NOT NULL AND v_existing.submission_hash IS DISTINCT FROM md5(p_items::text) THEN RAISE EXCEPTION 'QR_ITEMS_INVALID'; END IF;
    RETURN v_existing.result_snapshot; END IF;

  -- Payment locks the order before releasing its table. Match that order for
  -- an existing check so a payment completion and a QR addition cannot form
  -- an order/table lock cycle. If no active order exists, lock the table and
  -- recheck before allowing the delegated function to create one.
  SELECT order_row.id INTO v_current_order_id
  FROM public.orders order_row
  WHERE order_row.table_id = v_table.table_id
    AND order_row.restaurant_id = v_table.restaurant_id
    AND order_row.status IN ('pending', 'confirmed', 'serving') AND public.table_order_is_current(order_row)
  ORDER BY order_row.created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF v_current_order_id IS NULL THEN
    PERFORM 1
    FROM public.tables table_row
    WHERE table_row.id = v_table.table_id
      AND table_row.restaurant_id = v_table.restaurant_id
    FOR UPDATE;

    SELECT order_row.id INTO v_current_order_id
    FROM public.orders order_row
    WHERE order_row.table_id = v_table.table_id
      AND order_row.restaurant_id = v_table.restaurant_id
      AND order_row.status IN ('pending', 'confirmed', 'serving') AND public.table_order_is_current(order_row)
    ORDER BY order_row.created_at DESC
    LIMIT 1
    FOR UPDATE;
  ELSE
    PERFORM 1
    FROM public.tables table_row
    WHERE table_row.id = v_table.table_id
      AND table_row.restaurant_id = v_table.restaurant_id
    FOR UPDATE;
  END IF;

  IF v_current_order_id IS DISTINCT FROM p_expected_order_id THEN
    RAISE EXCEPTION 'QR_ORDER_CONTEXT_CHANGED';
  END IF;

  IF v_current_order_id IS NOT NULL THEN
    PERFORM public.qr_apply_due_order_display_reset(v_current_order_id);
  END IF;

  v_result := public.qr_place_order(
    p_token,
    p_items,
    p_client_order_id,
    p_validate_combo_choices
  );

  PERFORM public.qr_refresh_order_display_state((v_result->>'order_id')::uuid);
  RETURN v_result;
END;
$$;


NOTIFY pgrst,'reload schema';
DO $verify$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.direct_order_request_items'::regclass AND conname='direct_order_request_items_request_id_menu_item_id_key')
 OR to_regclass('public.direct_order_request_items_request_menu_idx') IS NULL
 OR strpos(pg_get_functiondef('public.capture_menu_option_batch()'::regprocedure),'recipe_basis')=0
 THEN RAISE EXCEPTION 'MENU_CHOICE_INTAKE_CONTRACT_INVALID'; END IF;
END $verify$;

-- COMPONENT 20261021182000_menu_choice_stock.sql
-- Extra recipe usage is frozen with the customer selection; consuming once uses
-- the same cancellation/partial-payment rules as the base recipe.
-- production-gate: self-verifying

CREATE FUNCTION public.order_choice_consumption(p_order_id uuid,p_store_id uuid)
RETURNS TABLE(order_item_id uuid,ingredient_id uuid,quantity numeric)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
 WITH lines AS MATERIALIZED (
  SELECT oi.id,oi.menu_item_id,oi.menu_option_snapshot,
   CASE WHEN oi.status='cancelled' THEN oi.cancelled_consumed_quantity
    ELSE oi.quantity+oi.cancelled_consumed_quantity END qty
  FROM public.order_items oi WHERE oi.order_id=p_order_id AND oi.restaurant_id=p_store_id
   AND oi.item_type='menu_item' AND (oi.status<>'cancelled' OR oi.cancelled_consumed_quantity>0)
   AND NOT (coalesce(nullif(current_setting('pos.direct_combo_snapshot',true),''),'{}')::jsonb ? oi.id::text)
 ), usage AS (
  SELECT l.id,mr.ingredient_id,l.qty*mr.quantity_g quantity FROM lines l JOIN public.menu_recipes mr
   ON mr.menu_item_id=l.menu_item_id AND mr.restaurant_id=p_store_id WHERE NOT l.menu_option_snapshot ? 'recipe_basis'
  UNION ALL
  SELECT l.id,(r->>'ingredient_id')::uuid,(l.qty*(r->>'quantity_g')::numeric)/(l.menu_option_snapshot->'recipe_basis'->>'quantity')::numeric
   FROM lines l CROSS JOIN LATERAL jsonb_array_elements(coalesce(l.menu_option_snapshot->'recipe_basis'->'items','[]'))r
  UNION ALL
  SELECT l.id,(r->>'ingredient_id')::uuid,l.qty*(r->>'quantity_g')::numeric
   FROM lines l CROSS JOIN LATERAL jsonb_array_elements(coalesce(l.menu_option_snapshot->'recipe_additions','[]'))r
 ) SELECT u.id,u.ingredient_id,sum(u.quantity) FROM usage u GROUP BY u.id,u.ingredient_id;
$$;
REVOKE ALL ON FUNCTION public.order_choice_consumption(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION "public"."process_payment_without_scoped_promotions"("p_order_id" "uuid", "p_store_id" "uuid", "p_amount" numeric, "p_method" "text") RETURNS "public"."payments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_actor                  users%ROWTYPE;
  v_order                  orders%ROWTYPE;
  v_payment                payments%ROWTYPE;
  v_brand                  brands%ROWTYPE;
  v_discount               order_discounts%ROWTYPE;
  v_has_discount           boolean := false;
  v_table_id               uuid;
  v_food_subtotal          decimal(15,2) := 0;
  v_alcohol_subtotal       decimal(15,2) := 0;
  v_menu_inc_total         decimal(15,2) := 0;
  v_menu_inc_cents         bigint := 0;
  v_sc_rate                decimal(5,2)  := 0;
  v_sc_pretax              decimal(15,2);
  v_sc_vat                 decimal(15,2);
  v_sc_total               decimal(15,2);
  v_is_revenue             boolean := true;
  v_payment_method_storage text := p_method;
  v_order_total            decimal(15,2) := 0;
  v_total_paid_before      decimal(15,2) := 0;
  v_total_paid_after       decimal(15,2) := 0;
  v_remaining_due          decimal(15,2) := 0;
  v_should_complete        boolean := false;
  v_vat_pricing_mode       text := 'exclusive';
  v_discount_total         decimal(15,2) := 0;
  v_discount_cents         bigint := 0;
  v_remainder_cents        bigint := 0;
BEGIN
  SELECT * INTO v_actor
  FROM users
  WHERE auth_id = auth.uid()
    AND is_active = TRUE
  LIMIT 1;

  IF NOT FOUND OR v_actor.role NOT IN ('cashier','admin','store_admin','brand_admin','super_admin') THEN
    RAISE EXCEPTION 'PAYMENT_FORBIDDEN';
  END IF;

  IF p_store_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_STORE_REQUIRED';
  END IF;

  IF NOT is_super_admin()
     AND NOT EXISTS (
       SELECT 1
       FROM public.user_accessible_stores(auth.uid()) s(store_id)
       WHERE s.store_id = p_store_id
     ) THEN
    RAISE EXCEPTION 'PAYMENT_FORBIDDEN';
  END IF;

  IF p_method = 'SERVICE' THEN
    v_is_revenue := FALSE;
    v_payment_method_storage := 'OTHER';
  ELSIF p_method NOT IN (
    'CASH','CREDITCARD','ATM','MOMO','ZALOPAY',
    'VNPAY','SHOPEEPAY','BANKTRANSFER','VOUCHER','CREDITSALE','OTHER'
  ) THEN
    RAISE EXCEPTION 'INVALID_PAYMENT_METHOD';
  END IF;

  SELECT * INTO v_order
  FROM orders
  WHERE id = p_order_id
    AND restaurant_id = p_store_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND';
  END IF;

  IF v_order.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'ORDER_NOT_PAYABLE';
  END IF;

  IF COALESCE(v_order.order_purpose, 'customer') = 'staff_meal'
     AND p_method <> 'SERVICE' THEN
    RAISE EXCEPTION 'STAFF_MEAL_SERVICE_REQUIRED';
  END IF;

  -- Contract invariant I3 (ORDER_LIFECYCLE_STATE_CONTRACT_2026_07_03):
  -- an order is payable only when every active item is ready or served.
  IF EXISTS (
    SELECT 1
    FROM order_items oi
    WHERE oi.order_id = p_order_id
      AND oi.status NOT IN ('ready', 'served', 'cancelled')
  ) THEN
    RAISE EXCEPTION 'ORDER_NOT_PAYABLE';
  END IF;

  IF p_amount < 0 THEN
    RAISE EXCEPTION 'PAYMENT_AMOUNT_INVALID';
  END IF;

  SELECT b.* INTO v_brand
  FROM restaurants r
  JOIN brands b ON b.id = r.brand_id
  WHERE r.id = p_store_id;

  SELECT COALESCE(r.vat_pricing_mode, 'exclusive')
  INTO v_vat_pricing_mode
  FROM restaurants r
  WHERE r.id = p_store_id;

  IF FOUND AND v_brand.service_charge_enabled THEN
    v_sc_rate := COALESCE(v_brand.service_charge_rate, 0);
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS payment_discount_lines (
    line_id uuid PRIMARY KEY,
    menu_item_id uuid,
    unit_price numeric(12,2) NOT NULL,
    quantity integer NOT NULL,
    display_name text,
    label text,
    vat_category text NOT NULL,
    vat_rate numeric(5,2) NOT NULL,
    tax_profile jsonb NOT NULL,
    undiscounted_pretax numeric(15,2) NOT NULL,
    undiscounted_vat numeric(15,2) NOT NULL,
    undiscounted_inc numeric(15,2) NOT NULL,
    line_inc_cents bigint NOT NULL,
    base_discount_cents bigint NOT NULL DEFAULT 0,
    discount_fraction numeric NOT NULL DEFAULT 0,
    allocated_discount_cents bigint NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL
  ) ON COMMIT DROP;

  TRUNCATE TABLE payment_discount_lines;

  UPDATE public.order_items SET vat_rate=0,vat_amount=0,total_amount_ex_tax=0,paying_amount_inc_tax=0
  WHERE order_id=p_order_id AND restaurant_id=p_store_id AND status<>'cancelled'
    AND item_type='menu_item' AND is_service_item=true;

  WITH lines AS MATERIALIZED (
    SELECT oi.id,oi.menu_item_id,oi.unit_price,oi.quantity,oi.display_name,oi.label,oi.created_at,
      coalesce(mi.vat_category,'food') vat_category,
      coalesce(oi.vat_profile_snapshot,jsonb_build_array(jsonb_build_object('rate',
        CASE WHEN oi.vat_rate IN (8,10) THEN oi.vat_rate ELSE mi.effective_vat_rate END,'weight',1))) tax_profile
    FROM public.order_items oi LEFT JOIN public.menu_items mi ON mi.id=oi.menu_item_id
    WHERE oi.order_id=p_order_id AND oi.restaurant_id=p_store_id AND oi.status<>'cancelled'
      AND oi.item_type='menu_item' AND coalesce(oi.is_service_item,false)=false
  ), priced AS MATERIALIZED (
    SELECT l.*,public.direct_order_payment_vat(l.tax_profile,round(l.unit_price*l.quantity,2),v_vat_pricing_mode) tax
    FROM lines l
  ), inserted AS (
    INSERT INTO payment_discount_lines(line_id,menu_item_id,unit_price,quantity,display_name,label,
      vat_category,vat_rate,tax_profile,undiscounted_pretax,undiscounted_vat,undiscounted_inc,line_inc_cents,created_at)
    SELECT id,menu_item_id,unit_price,quantity,display_name,label,vat_category,(tax->>'vat_rate')::numeric,
      tax_profile,(tax->>'supply')::numeric,(tax->>'vat')::numeric,(tax->>'total')::numeric,
      round((tax->>'total')::numeric*100)::bigint,created_at FROM priced RETURNING line_id
  ) SELECT
    (SELECT coalesce(sum((tax->>'total')::numeric),0) FROM priced),
    (SELECT coalesce(sum(round((tax->>'total')::numeric*100)::bigint),0) FROM priced),
    coalesce(sum((part->>'total_amount_ex_tax')::numeric) FILTER(WHERE (part->>'vat_rate')::numeric=10),0),
    coalesce(sum((part->>'total_amount_ex_tax')::numeric) FILTER(WHERE (part->>'vat_rate')::numeric=8),0)
  INTO v_menu_inc_total,v_menu_inc_cents,v_alcohol_subtotal,v_food_subtotal
  FROM priced p CROSS JOIN LATERAL jsonb_array_elements(p.tax->'parts') part;


  SELECT *
  INTO v_discount
  FROM order_discounts
  WHERE order_id = p_order_id
    AND restaurant_id = p_store_id
    AND status = 'active'
  FOR UPDATE;

  IF FOUND THEN
    v_has_discount := true;
    IF v_menu_inc_total <= 0 THEN
      RAISE EXCEPTION 'ORDER_TOTAL_INVALID';
    END IF;

    IF v_discount.discount_mode = 'percent' THEN
      v_discount_total := ROUND(v_menu_inc_total * v_discount.discount_value / 100, 2);
    ELSE
      v_discount_total := LEAST(ROUND(v_discount.discount_value, 2), v_menu_inc_total);
    END IF;

    IF v_discount_total < 0 THEN
      RAISE EXCEPTION 'DISCOUNT_AMOUNT_INVALID';
    END IF;

    v_discount_cents := LEAST(ROUND(v_discount_total * 100)::bigint, v_menu_inc_cents);

    IF v_discount_cents > 0 AND v_menu_inc_cents > 0 THEN
      UPDATE payment_discount_lines
      SET base_discount_cents = FLOOR((v_discount_cents::numeric * line_inc_cents::numeric) / v_menu_inc_cents::numeric)::bigint,
          discount_fraction = ((v_discount_cents::numeric * line_inc_cents::numeric) / v_menu_inc_cents::numeric)
            - FLOOR((v_discount_cents::numeric * line_inc_cents::numeric) / v_menu_inc_cents::numeric)
      WHERE line_inc_cents > 0;

      SELECT v_discount_cents - COALESCE(SUM(base_discount_cents), 0)
      INTO v_remainder_cents
      FROM payment_discount_lines;

      WITH ranked AS (
        SELECT
          line_id,
          row_number() OVER (ORDER BY discount_fraction DESC, line_id) AS rn
        FROM payment_discount_lines
      )
      UPDATE payment_discount_lines l
      SET allocated_discount_cents =
        l.base_discount_cents + CASE WHEN ranked.rn <= v_remainder_cents THEN 1 ELSE 0 END
      FROM ranked
      WHERE ranked.line_id = l.line_id;
    END IF;
  END IF;

  -- Final targeted allocation before invoice snapshots.
  IF v_has_discount AND v_discount.approved_via = 'scheduled_promotion'
     AND EXISTS (SELECT 1 FROM public.order_discount_lines
                 WHERE order_discount_id = v_discount.id) THEN
    IF EXISTS (
      SELECT 1 FROM public.order_discount_lines allocation
      LEFT JOIN payment_discount_lines line ON line.line_id = allocation.order_item_id
      WHERE allocation.order_discount_id = v_discount.id
        AND (line.line_id IS NULL OR allocation.discount_amount < 0
          OR round(allocation.discount_amount * 100) > line.line_inc_cents)
    ) OR (SELECT round(sum(discount_amount) * 100)
          FROM public.order_discount_lines WHERE order_discount_id = v_discount.id)
         IS DISTINCT FROM v_discount_cents THEN
      RAISE EXCEPTION 'PROMOTION_ALLOCATION_MISMATCH';
    END IF;
    WITH allocations AS (
      SELECT line.line_id,coalesce(round(a.discount_amount*100)::bigint,0) cents
      FROM payment_discount_lines line LEFT JOIN public.order_discount_lines a
        ON a.order_discount_id=v_discount.id AND a.order_item_id=line.line_id
    ) UPDATE payment_discount_lines line SET allocated_discount_cents=a.cents
    FROM allocations a WHERE a.line_id=line.line_id;
  END IF;

  WITH priced AS MATERIALIZED (
    SELECT line_id,public.direct_order_payment_vat(tax_profile,round(unit_price*quantity,2),
      v_vat_pricing_mode,allocated_discount_cents::numeric/100) tax FROM payment_discount_lines
  ) UPDATE public.order_items oi SET vat_rate=(p.tax->>'vat_rate')::numeric,
    vat_amount=(p.tax->>'vat')::numeric,total_amount_ex_tax=(p.tax->>'supply')::numeric,
    paying_amount_inc_tax=(p.tax->>'total')::numeric,vat_breakdown=p.tax->'parts'
  FROM priced p WHERE oi.id=p.line_id;


  IF v_sc_rate > 0 AND v_food_subtotal > 0 THEN
    v_sc_pretax := ROUND(v_food_subtotal * v_sc_rate / 100, CASE WHEN COALESCE(NULLIF(current_setting('pos.direct_combo_snapshot',true),''),'{}')<>'{}' THEN 0 ELSE 2 END);
    v_sc_vat := ROUND(v_sc_pretax * 8 / 100, CASE WHEN COALESCE(NULLIF(current_setting('pos.direct_combo_snapshot',true),''),'{}')<>'{}' THEN 0 ELSE 2 END);
    v_sc_total := v_sc_pretax + v_sc_vat;

    IF NOT EXISTS (
      SELECT 1 FROM order_items
      WHERE order_id = p_order_id
        AND item_type = 'service_charge'
        AND display_name IN ('Service Charge (Food)','Service Charge (VAT 8%)')
    ) THEN
      INSERT INTO order_items (
        order_id, restaurant_id, item_type, display_name, menu_item_id,
        unit_price, quantity, label, status, vat_rate, vat_amount,
        total_amount_ex_tax, paying_amount_inc_tax
      )
      VALUES (
        p_order_id, p_store_id, 'service_charge', 'Service Charge (VAT 8%)', NULL,
        v_sc_pretax, 1, 'Service Charge (VAT 8%)', 'served', 8, v_sc_vat,
        v_sc_pretax, v_sc_total
      );
    ELSE
      UPDATE order_items
      SET unit_price = v_sc_pretax,
          quantity = 1,
          vat_rate = 8,
          vat_amount = v_sc_vat,
          total_amount_ex_tax = v_sc_pretax,
          paying_amount_inc_tax = v_sc_total,
          status = 'served'
      WHERE order_id = p_order_id
        AND item_type = 'service_charge'
        AND display_name IN ('Service Charge (Food)','Service Charge (VAT 8%)');
    END IF;

  END IF;

  IF v_sc_rate > 0 AND v_alcohol_subtotal > 0 THEN
    v_sc_pretax := ROUND(v_alcohol_subtotal * v_sc_rate / 100, CASE WHEN COALESCE(NULLIF(current_setting('pos.direct_combo_snapshot',true),''),'{}')<>'{}' THEN 0 ELSE 2 END);
    v_sc_vat := ROUND(v_sc_pretax * 10 / 100, CASE WHEN COALESCE(NULLIF(current_setting('pos.direct_combo_snapshot',true),''),'{}')<>'{}' THEN 0 ELSE 2 END);
    v_sc_total := v_sc_pretax + v_sc_vat;

    IF NOT EXISTS (
      SELECT 1 FROM order_items
      WHERE order_id = p_order_id
        AND item_type = 'service_charge'
        AND display_name IN ('Service Charge (Alcohol)','Service Charge (VAT 10%)')
    ) THEN
      INSERT INTO order_items (
        order_id, restaurant_id, item_type, display_name, menu_item_id,
        unit_price, quantity, label, status, vat_rate, vat_amount,
        total_amount_ex_tax, paying_amount_inc_tax
      )
      VALUES (
        p_order_id, p_store_id, 'service_charge', 'Service Charge (VAT 10%)', NULL,
        v_sc_pretax, 1, 'Service Charge (VAT 10%)', 'served', 10, v_sc_vat,
        v_sc_pretax, v_sc_total
      );
    ELSE
      UPDATE order_items
      SET unit_price = v_sc_pretax,
          quantity = 1,
          vat_rate = 10,
          vat_amount = v_sc_vat,
          total_amount_ex_tax = v_sc_pretax,
          paying_amount_inc_tax = v_sc_total,
          status = 'served'
      WHERE order_id = p_order_id
        AND item_type = 'service_charge'
        AND display_name IN ('Service Charge (Alcohol)','Service Charge (VAT 10%)');
    END IF;

  END IF;

  -- Never silently reprice a partly paid legacy zero-VAT charge.
  IF EXISTS (SELECT 1 FROM order_items WHERE order_id = p_order_id
             AND item_type = 'wet_tissue_charge' AND status <> 'cancelled'
             AND vat_rate IS DISTINCT FROM 8)
     AND EXISTS (SELECT 1 FROM payments WHERE order_id = p_order_id) THEN
    RAISE EXCEPTION 'WET_TISSUE_LEGACY_PAYMENT_REVIEW_REQUIRED';
  END IF;
  UPDATE order_items item
  SET vat_rate = 8,
      total_amount_ex_tax = CASE WHEN v_vat_pricing_mode = 'inclusive'
        THEN round(item.unit_price * item.quantity / 1.08, 2)
        ELSE item.unit_price * item.quantity END,
      vat_amount = CASE WHEN v_vat_pricing_mode = 'inclusive'
        THEN item.unit_price * item.quantity - round(item.unit_price * item.quantity / 1.08, 2)
        ELSE round(item.unit_price * item.quantity * .08, 2) END,
      paying_amount_inc_tax = CASE WHEN v_vat_pricing_mode = 'inclusive'
        THEN item.unit_price * item.quantity ELSE round(item.unit_price * item.quantity * 1.08, 2) END
  WHERE item.order_id = p_order_id AND item.restaurant_id = p_store_id
    AND item.item_type = 'wet_tissue_charge' AND item.status <> 'cancelled'
    AND NOT EXISTS (SELECT 1 FROM payments WHERE order_id = p_order_id);

  SELECT ROUND(COALESCE(SUM(COALESCE(paying_amount_inc_tax, unit_price * quantity)), 0), 2)
  INTO v_order_total
  FROM order_items
  WHERE order_id = p_order_id
    AND status <> 'cancelled'
    AND COALESCE(is_service_item, false) = false;

  IF v_order_total < 0 OR (v_order_total <= 0 AND NOT v_has_discount) THEN
    RAISE EXCEPTION 'ORDER_TOTAL_INVALID';
  END IF;

  SELECT COALESCE(SUM(amount_portion), 0)
  INTO v_total_paid_before
  FROM payments
  WHERE order_id = p_order_id;

  v_remaining_due := ROUND(v_order_total - v_total_paid_before, 2);

  IF v_remaining_due < -0.01 THEN
    RAISE EXCEPTION 'PAYMENT_AMOUNT_EXCEEDS_REMAINING';
  END IF;

  IF GREATEST(v_remaining_due, 0) <= 0.01 THEN
    IF ABS(ROUND(COALESCE(p_amount, -1), 2)) > 0.01 THEN
      RAISE EXCEPTION 'PAYMENT_AMOUNT_EXCEEDS_REMAINING';
    END IF;
  ELSE
    IF ROUND(COALESCE(p_amount, -1), 2) <= 0 THEN
      RAISE EXCEPTION 'PAYMENT_AMOUNT_INVALID';
    END IF;

    IF ROUND(COALESCE(p_amount, -1), 2) - v_remaining_due > 0.01 THEN
      RAISE EXCEPTION 'PAYMENT_AMOUNT_EXCEEDS_REMAINING';
    END IF;
  END IF;

  v_total_paid_after := ROUND(v_total_paid_before + p_amount, 2);
  v_should_complete := v_total_paid_after >= v_order_total - 0.01;

  INSERT INTO payments (
    order_id,
    restaurant_id,
    amount,
    method,
    processed_by,
    is_revenue,
    amount_portion
  )
  VALUES (
    p_order_id,
    p_store_id,
    p_amount,
    v_payment_method_storage,
    auth.uid(),
    v_is_revenue,
    p_amount
  )
  RETURNING * INTO v_payment;

  IF v_has_discount AND v_should_complete THEN
    UPDATE order_discounts
    SET status = 'consumed',
        discount_amount = v_discount_cents::numeric / 100,
        updated_at = now()
    WHERE id = v_discount.id;
  END IF;

  IF v_should_complete THEN
    UPDATE orders
    SET status = 'completed', updated_at = now()
    WHERE id = p_order_id
    RETURNING table_id INTO v_table_id;

    IF v_table_id IS NOT NULL THEN
      UPDATE tables
      SET status = 'available', updated_at = now()
      WHERE id = v_table_id;
    END IF;

    -- Lock the complete ingredient set in stable order, then consume and post
    -- one ledger row per order line / ingredient. No item -> recipe SQL loop.
    PERFORM stock.id FROM public.inventory_items stock
    JOIN (SELECT DISTINCT ingredient_id FROM public.order_choice_consumption(p_order_id,p_store_id)) ingredients ON ingredients.ingredient_id=stock.id
    WHERE stock.restaurant_id=p_store_id ORDER BY stock.id FOR UPDATE OF stock;
    WITH consumption AS MATERIALIZED (
      SELECT * FROM public.order_choice_consumption(p_order_id,p_store_id)
    ), totals AS (SELECT ingredient_id,sum(quantity) quantity FROM consumption GROUP BY ingredient_id),
    changed AS (UPDATE public.inventory_items stock SET current_stock=stock.current_stock-t.quantity,updated_at=now()
      FROM totals t WHERE stock.id=t.ingredient_id AND stock.restaurant_id=p_store_id RETURNING stock.id)
    INSERT INTO public.inventory_transactions(restaurant_id,ingredient_id,transaction_type,quantity_g,reference_type,reference_id,created_by)
    SELECT p_store_id,c.ingredient_id,'deduct',-c.quantity,'order_item',c.order_item_id,auth.uid()
    FROM consumption c;


  END IF;

  INSERT INTO audit_logs (actor_id, action, entity_type, entity_id, details)
  VALUES (
    auth.uid(),
    'process_payment',
    'payments',
    v_payment.id,
    jsonb_build_object(
      'store_id', p_store_id,
      'order_id', p_order_id,
      'amount', p_amount,
      'input_method', p_method,
      'stored_method', v_payment_method_storage,
      'is_revenue', v_is_revenue,
      'order_total', v_order_total,
      'discount_id', CASE WHEN v_has_discount THEN v_discount.id ELSE NULL END,
      'discount_amount', v_discount_cents::numeric / 100,
      'total_paid_before', v_total_paid_before,
      'total_paid_after', v_total_paid_after,
      'payment_completes_order', v_should_complete
    )
  );

  RETURN v_payment;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."direct_order_deduct_combo_stock"("p_store_id" "uuid", "p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE expected integer; applied integer;
BEGIN
 WITH lines AS MATERIALIZED(SELECT oi.id,oi.quantity,oi.combo_components,oi.menu_option_snapshot FROM public.direct_order_financials f
  JOIN public.order_items oi ON oi.order_id=f.order_id AND oi.restaurant_id=f.restaurant_id
  JOIN public.direct_order_request_items i ON i.request_id=f.request_id AND i.id=oi.id
  WHERE f.request_id=p_request_id AND f.restaurant_id=p_store_id AND jsonb_array_length(i.combo_components)>0),
 base_usage AS (SELECT l.id order_item_id,mr.ingredient_id,
  sum(mr.quantity_g*(c.value->>'quantity')::numeric*CASE WHEN COALESCE((c.value->>'is_total_quantity')::boolean,false) THEN 1 ELSE l.quantity END) quantity
  FROM lines l CROSS JOIN LATERAL jsonb_array_elements(l.combo_components)c
  JOIN public.menu_recipes mr ON mr.menu_item_id=(c.value->>'menu_item_id')::uuid AND mr.restaurant_id=p_store_id
  WHERE NOT l.menu_option_snapshot ? 'combo_recipe_basis'
  GROUP BY l.id,mr.ingredient_id
  UNION ALL SELECT l.id,(r->>'ingredient_id')::uuid,(l.quantity*(r->>'quantity_g')::numeric)/(l.menu_option_snapshot->'combo_recipe_basis'->>'quantity')::numeric
   FROM lines l CROSS JOIN LATERAL jsonb_array_elements(coalesce(l.menu_option_snapshot->'combo_recipe_basis'->'items','[]'))r
  UNION ALL SELECT l.id,(r->>'ingredient_id')::uuid,l.quantity*(r->>'quantity_g')::numeric
   FROM lines l CROSS JOIN LATERAL jsonb_array_elements(coalesce(l.menu_option_snapshot->'recipe_additions','[]'))r),
 consumption AS MATERIALIZED(SELECT order_item_id,ingredient_id,sum(quantity) quantity FROM base_usage GROUP BY order_item_id,ingredient_id),
 totals AS(SELECT ingredient_id,sum(quantity) quantity FROM consumption GROUP BY ingredient_id),
 changed AS(UPDATE public.inventory_items stock SET current_stock=stock.current_stock-t.quantity,updated_at=now()
  FROM totals t WHERE stock.id=t.ingredient_id AND stock.restaurant_id=p_store_id RETURNING stock.id),
 journal AS(INSERT INTO public.inventory_transactions(restaurant_id,ingredient_id,transaction_type,quantity_g,reference_type,reference_id,created_by)
  SELECT p_store_id,ingredient_id,'deduct',-quantity,'order_item',order_item_id,auth.uid() FROM consumption RETURNING ingredient_id)
 SELECT (SELECT count(*) FROM totals),(SELECT count(*) FROM changed) INTO expected,applied;
 IF expected<>applied THEN RAISE EXCEPTION 'DIRECT_ORDER_COMBO_STOCK_UNAVAILABLE'; END IF;
END $$;
CREATE OR REPLACE FUNCTION "public"."direct_order_lock_combo_stock"("p_store_id" "uuid", "p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
 PERFORM stock.id FROM public.inventory_items stock JOIN(
  SELECT DISTINCT mr.ingredient_id FROM public.menu_recipes mr JOIN(
   SELECT i.menu_item_id FROM public.direct_order_request_items i WHERE i.request_id=p_request_id AND i.restaurant_id=p_store_id
   UNION SELECT (c.value->>'menu_item_id')::uuid FROM public.direct_order_request_items i
    CROSS JOIN LATERAL jsonb_array_elements(i.combo_components)c WHERE i.request_id=p_request_id AND i.restaurant_id=p_store_id
  ) menus ON menus.menu_item_id=mr.menu_item_id WHERE mr.restaurant_id=p_store_id
 UNION SELECT (r->>'ingredient_id')::uuid FROM public.direct_order_request_items i
  CROSS JOIN LATERAL jsonb_array_elements(coalesce(i.menu_option_snapshot->'recipe_additions','[]')||coalesce(i.menu_option_snapshot->'combo_recipe_basis'->'items','[]'))r
  WHERE i.request_id=p_request_id AND i.restaurant_id=p_store_id
 ) used ON used.ingredient_id=stock.id WHERE stock.restaurant_id=p_store_id ORDER BY stock.id FOR UPDATE OF stock;
END $$;


DO $verify$ BEGIN
 IF has_function_privilege('authenticated','public.order_choice_consumption(uuid,uuid)','EXECUTE')
 OR strpos(pg_get_functiondef('public.process_payment_without_scoped_promotions(uuid,uuid,numeric,text)'::regprocedure),'order_choice_consumption')=0
 THEN RAISE EXCEPTION 'MENU_CHOICE_STOCK_CONTRACT_INVALID'; END IF;
END $verify$;

-- COMPONENT 20261021190000_store_workflow_publication.sql
-- Versioned kitchen routing. Existing stores stay on their current workflow until
-- an administrator explicitly publishes, devices acknowledge, and a super admin activates.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE TABLE public.store_workflow_releases (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 definition jsonb NOT NULL, source_hash text NOT NULL, created_by uuid NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(restaurant_id,id)
);
CREATE TABLE public.store_workflow_configs (
 restaurant_id uuid PRIMARY KEY REFERENCES public.restaurants(id) ON DELETE CASCADE,
 revision bigint NOT NULL DEFAULT 0, draft jsonb, candidate_id uuid, active_id uuid,
 validated_hash text, validated_at timestamptz,
 FOREIGN KEY(restaurant_id,candidate_id) REFERENCES public.store_workflow_releases(restaurant_id,id),
 FOREIGN KEY(restaurant_id,active_id) REFERENCES public.store_workflow_releases(restaurant_id,id)
);
CREATE TABLE public.store_workflow_devices (
 restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 user_id uuid NOT NULL, device_id uuid NOT NULL, release_id uuid NOT NULL,
 quiesced boolean NOT NULL DEFAULT false, pending_count integer NOT NULL CHECK(pending_count>=0), seen_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(restaurant_id,user_id,device_id),
 FOREIGN KEY(restaurant_id,release_id) REFERENCES public.store_workflow_releases(restaurant_id,id)
);
ALTER TABLE public.orders ADD COLUMN operating_release_id uuid REFERENCES public.store_workflow_releases(id);
ALTER TABLE public.direct_order_requests ADD COLUMN operating_release_id uuid REFERENCES public.store_workflow_releases(id);
CREATE INDEX orders_operating_release ON public.orders(operating_release_id) WHERE operating_release_id IS NOT NULL;
CREATE INDEX direct_requests_operating_release ON public.direct_order_requests(operating_release_id) WHERE operating_release_id IS NOT NULL;

CREATE FUNCTION public.store_workflow_source(p_store_id uuid) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
 SELECT md5(jsonb_build_object('opening',public.store_operating_source_v1(p_store_id),'menus',
  (SELECT jsonb_agg(jsonb_build_array(id,size_parent_id,m.menu_option_key,price,is_available,is_archived,is_visible_public,fulfillment_route,name_ko,name_vi,name_en) ORDER BY id)
   FROM public.menu_items m WHERE restaurant_id=p_store_id))::text);
$$;
CREATE FUNCTION public.store_workflow_path(p_definition jsonb,p_menu_id uuid,p_channel text,p_parent_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT coalesce((SELECT r->'path' FROM jsonb_array_elements(p_definition->'routes')r
  WHERE (r->'menu_ids' ? p_menu_id::text OR r->'menu_ids' ? p_parent_id::text) AND r->'channels' ? CASE p_channel WHEN 'takeaway' THEN 'pickup' ELSE p_channel END ORDER BY CASE WHEN r->'menu_ids' ? p_menu_id::text THEN 0 ELSE 1 END LIMIT 1),p_definition->'default_path');
$$;
CREATE FUNCTION public.store_workflow_validate(p_store_id uuid,p_definition jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE source jsonb:=public.store_operating_source_v1(p_store_id); total integer;
BEGIN
 IF source IS NULL OR NOT (source->>'within_bounds')::boolean THEN RAISE EXCEPTION 'WORKFLOW_STORE_INVALID'; END IF;
 IF p_definition IS NULL OR octet_length(p_definition::text)>65536 OR p_definition->>'schema' IS DISTINCT FROM '1'
  OR jsonb_typeof(p_definition->'stations') IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_definition->'stations') NOT BETWEEN 1 AND 8
  OR jsonb_typeof(p_definition->'routes') IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_definition->'routes')>100
  OR jsonb_typeof(p_definition->'default_path') IS DISTINCT FROM 'array'
  OR p_definition->>'workflow' IS DISTINCT FROM source->>'workflow'
  OR p_definition->>'fulfillment_mode' IS DISTINCT FROM source->>'fulfillment_mode'
 THEN RAISE EXCEPTION 'WORKFLOW_DEFINITION_INVALID'; END IF;
 -- Physical printing still serves its existing single kitchen. Multi-station routing
 -- requires the paperless station protocol; no claim that a print job is a device test.
 IF source->>'fulfillment_mode'<>'paperless' THEN RAISE EXCEPTION 'WORKFLOW_PAPERLESS_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'stations')s
  WHERE nullif(btrim(s->>'name'),'') IS NULL OR length(s->>'name')>80
   OR (s->>'id')::uuid IS NULL OR jsonb_typeof(s->'user_ids') IS DISTINCT FROM 'array' OR jsonb_array_length(s->'user_ids')=0)
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'stations')s WHERE s->>'id'=coalesce(p_definition->>'packaging_station_id',p_definition->'default_path'->>0))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'stations')s GROUP BY s->>'id' HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'stations')s,jsonb_array_elements_text(s->'user_ids')u GROUP BY u HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'stations')s JOIN public.store_service_stations st ON st.id=(s->>'id')::uuid WHERE st.restaurant_id<>p_store_id OR st.kind<>'kitchen')
 THEN RAISE EXCEPTION 'WORKFLOW_STATION_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'stations')s,jsonb_array_elements_text(s->'user_ids')u
  LEFT JOIN public.users usr ON usr.id=u::uuid AND usr.restaurant_id=p_store_id AND usr.is_active
  LEFT JOIN public.emergency_station_assignments a ON a.user_id=usr.id AND a.restaurant_id=p_store_id AND a.is_active AND a.station_type='kitchen'
  WHERE usr.id IS NULL OR a.id IS NULL)
 THEN RAISE EXCEPTION 'WORKFLOW_ASSIGNMENT_INVALID'; END IF;
 -- Every current kitchen account is bound exactly once; tray/floor retain explicit legacy assignments.
 IF EXISTS(SELECT 1 FROM public.emergency_station_assignments a WHERE a.restaurant_id=p_store_id AND a.is_active AND a.station_type='kitchen'
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'stations')s WHERE s->'user_ids' ? a.user_id::text))
 THEN RAISE EXCEPTION 'WORKFLOW_ASSIGNMENT_MISSING'; END IF;
 IF EXISTS(WITH paths AS (SELECT p_definition->'default_path' path UNION ALL SELECT r->'path' FROM jsonb_array_elements(p_definition->'routes')r)
  SELECT 1 FROM paths WHERE jsonb_typeof(path) IS DISTINCT FROM 'array' OR jsonb_array_length(path) NOT BETWEEN 1 AND 8
   OR (SELECT count(DISTINCT v) FROM jsonb_array_elements_text(path)v)<>jsonb_array_length(path)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(path)v WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'stations')s WHERE s->>'id'=v)))
 THEN RAISE EXCEPTION 'WORKFLOW_PATH_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'routes')r WHERE jsonb_typeof(r->'menu_ids') IS DISTINCT FROM 'array'
  OR jsonb_array_length(r->'menu_ids') NOT BETWEEN 1 AND 500 OR jsonb_typeof(r->'channels') IS DISTINCT FROM 'array'
  OR jsonb_array_length(r->'channels') NOT BETWEEN 1 AND 3)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'routes')r,jsonb_array_elements_text(r->'channels')c WHERE c NOT IN ('dine_in','pickup','delivery'))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'routes')r,jsonb_array_elements_text(r->'menu_ids')m
  LEFT JOIN public.menu_items mi ON mi.id=m::uuid AND mi.restaurant_id=p_store_id WHERE mi.id IS NULL)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_definition->'routes')r,jsonb_array_elements_text(r->'menu_ids')m,jsonb_array_elements_text(r->'channels')c GROUP BY m,c HAVING count(*)>1)
 THEN RAISE EXCEPTION 'WORKFLOW_ROUTE_INVALID'; END IF;
 SELECT count(*) INTO total FROM public.menu_items WHERE restaurant_id=p_store_id;
 IF total>4000 THEN RAISE EXCEPTION 'WORKFLOW_MENU_LIMIT'; END IF;
 RETURN jsonb_build_object('menu_count',total,'channel_cases',total*3,'station_count',jsonb_array_length(p_definition->'stations'),
  'source_hash',public.store_workflow_source(p_store_id),'definition_hash',md5(p_definition::text),
  'paths', (SELECT jsonb_agg(jsonb_build_object('channel',c,'menu_count',n,'path',path)) FROM (
   SELECT c,public.store_workflow_path(p_definition,m.id,c,m.size_parent_id) path,count(*) n FROM public.menu_items m CROSS JOIN unnest(ARRAY['dine_in','pickup','delivery'])c
   WHERE m.restaurant_id=p_store_id GROUP BY c,path)x));
END;
$$;

CREATE FUNCTION public.admin_store_workflow_v1(p_store_id uuid,p_action text DEFAULT 'load',p_expected_revision bigint DEFAULT NULL,p_definition jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE cfg public.store_workflow_configs%ROWTYPE; proof jsonb; candidate uuid; result jsonb;
BEGIN
 PERFORM public.require_admin_actor_for_restaurant(p_store_id);
 PERFORM pg_advisory_xact_lock(hashtextextended('store-opening:'||p_store_id::text,0));
 INSERT INTO public.store_workflow_configs(restaurant_id) VALUES(p_store_id) ON CONFLICT DO NOTHING;
 SELECT * INTO cfg FROM public.store_workflow_configs WHERE restaurant_id=p_store_id FOR UPDATE;
 IF p_action IS NULL OR p_action NOT IN ('load','save','validate','publish','activate','deactivate','retire_device') THEN RAISE EXCEPTION 'WORKFLOW_ACTION_INVALID'; END IF;
 IF p_action<>'load' AND cfg.revision IS DISTINCT FROM p_expected_revision THEN RAISE EXCEPTION 'WORKFLOW_CHANGED'; END IF;
 IF p_action='save' THEN
  proof:=public.store_workflow_validate(p_store_id,p_definition);
  UPDATE public.store_workflow_configs SET draft=p_definition,revision=revision+1,validated_hash=NULL,validated_at=NULL,candidate_id=NULL WHERE restaurant_id=p_store_id;
 ELSIF p_action='validate' THEN
  proof:=public.store_workflow_validate(p_store_id,cfg.draft);
  UPDATE public.store_workflow_configs SET validated_hash=md5(cfg.draft::text||public.store_workflow_source(p_store_id)),validated_at=now(),revision=revision+1 WHERE restaurant_id=p_store_id;
 ELSIF p_action='publish' THEN
  proof:=public.store_workflow_validate(p_store_id,cfg.draft);
  IF cfg.validated_at<now()-interval '30 minutes' OR cfg.validated_hash IS DISTINCT FROM md5(cfg.draft::text||public.store_workflow_source(p_store_id)) THEN RAISE EXCEPTION 'WORKFLOW_REVALIDATE'; END IF;
  INSERT INTO public.store_service_stations(id,restaurant_id,code,kind)
  SELECT (s->>'id')::uuid,p_store_id,'kitchen:'||(s->>'id'),'kitchen' FROM jsonb_array_elements(cfg.draft->'stations')s ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.store_workflow_releases(restaurant_id,definition,source_hash,created_by)
   VALUES(p_store_id,cfg.draft,public.store_workflow_source(p_store_id),auth.uid()) RETURNING id INTO candidate;
  UPDATE public.store_workflow_configs SET candidate_id=candidate,revision=revision+1 WHERE restaurant_id=p_store_id;
 ELSIF p_action='retire_device' THEN
  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'WORKFLOW_SUPER_ADMIN_REQUIRED'; END IF;
  DELETE FROM public.store_workflow_devices WHERE restaurant_id=p_store_id
   AND user_id=(p_definition->>'user_id')::uuid AND device_id=(p_definition->>'device_id')::uuid
   AND pending_count=0 AND seen_at<now()-interval '5 minutes' RETURNING to_jsonb(store_workflow_devices) INTO proof;
  IF NOT FOUND THEN RAISE EXCEPTION 'WORKFLOW_DEVICE_NOT_RETIRABLE'; END IF;
  UPDATE public.store_workflow_configs SET revision=revision+1 WHERE restaurant_id=p_store_id;
 ELSIF p_action IN ('activate','deactivate') THEN
  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'WORKFLOW_SUPER_ADMIN_REQUIRED'; END IF;
  IF p_action='activate' THEN
   IF to_regprocedure('public.store_workflow_notify(uuid)') IS NULL THEN RAISE EXCEPTION 'WORKFLOW_SERVER_UPDATE_REQUIRED'; END IF;
   SELECT definition INTO result FROM public.store_workflow_releases WHERE id=cfg.candidate_id AND source_hash=public.store_workflow_source(p_store_id) AND created_at>now()-interval '30 minutes';
   IF NOT FOUND THEN RAISE EXCEPTION 'WORKFLOW_REVALIDATE'; END IF;
   proof:=public.store_workflow_validate(p_store_id,result);
   IF EXISTS(SELECT 1 FROM public.emergency_station_assignments a WHERE a.restaurant_id=p_store_id AND a.is_active
    AND NOT EXISTS(SELECT 1 FROM public.store_workflow_devices d WHERE d.restaurant_id=p_store_id AND d.user_id=a.user_id
     AND d.release_id=cfg.candidate_id AND d.quiesced AND d.pending_count=0 AND d.seen_at>now()-interval '5 minutes'))
    OR EXISTS(SELECT 1 FROM public.store_workflow_devices d WHERE d.restaurant_id=p_store_id AND (d.pending_count>0 OR d.seen_at<now()-interval '5 minutes' OR d.release_id<>cfg.candidate_id))
   THEN RAISE EXCEPTION 'WORKFLOW_DEVICES_NOT_READY'; END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM public.orders WHERE restaurant_id=p_store_id AND status NOT IN ('completed','cancelled'))
   OR EXISTS(SELECT 1 FROM public.direct_order_requests r WHERE restaurant_id=p_store_id AND (state IN ('awaiting_quote','quoted','awaiting_payment_review') OR state='approved' AND NOT EXISTS(SELECT 1 FROM public.direct_delivery_fulfillment_tickets t WHERE t.request_id=r.id AND t.status IN ('completed','cancelled'))))
   OR EXISTS(SELECT 1 FROM public.leftover_packaging_requests WHERE restaurant_id=p_store_id AND status NOT IN ('completed','cancelled'))
   OR EXISTS(SELECT 1 FROM public.direct_delivery_fulfillment_tickets WHERE restaurant_id=p_store_id AND status NOT IN ('completed','cancelled'))
   OR EXISTS(SELECT 1 FROM public.emergency_fulfillment_items i WHERE restaurant_id=p_store_id AND NOT is_cancelled AND floor_served_quantity+excused_quantity<ordered_quantity AND NOT EXISTS(SELECT 1 FROM public.direct_order_financials f JOIN public.direct_delivery_fulfillment_tickets t ON t.request_id=f.request_id WHERE f.order_id=i.order_id AND t.status IN ('completed','cancelled')))
   OR EXISTS(SELECT 1 FROM public.emergency_combo_component_items i WHERE restaurant_id=p_store_id AND NOT is_cancelled AND floor_served_quantity+excused_quantity<ordered_quantity AND NOT EXISTS(SELECT 1 FROM public.direct_order_financials f JOIN public.direct_delivery_fulfillment_tickets t ON t.request_id=f.request_id WHERE f.order_id=i.order_id AND t.status IN ('completed','cancelled')))
   OR EXISTS(SELECT 1 FROM public.emergency_floor_direct_items i WHERE restaurant_id=p_store_id AND NOT is_cancelled AND floor_served_quantity+excused_quantity<ordered_quantity AND NOT EXISTS(SELECT 1 FROM public.direct_order_financials f JOIN public.direct_delivery_fulfillment_tickets t ON t.request_id=f.request_id WHERE f.order_id=i.order_id AND t.status IN ('completed','cancelled')))
  THEN RAISE EXCEPTION 'WORKFLOW_DRAIN_REQUIRED'; END IF;
  IF p_action='deactivate' AND EXISTS(SELECT 1 FROM public.store_workflow_devices WHERE restaurant_id=p_store_id AND (pending_count>0 OR seen_at<now()-interval '5 minutes')) THEN RAISE EXCEPTION 'WORKFLOW_DEVICES_NOT_READY'; END IF;
  UPDATE public.store_workflow_configs SET active_id=CASE WHEN p_action='activate' THEN candidate_id END,revision=revision+1 WHERE restaurant_id=p_store_id;
  UPDATE public.store_workflow_devices SET quiesced=false WHERE restaurant_id=p_store_id;
 END IF;
 IF p_action<>'load' THEN
  INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(auth.uid(),'store_workflow_'||p_action,'restaurants',p_store_id,jsonb_build_object('previous_revision',cfg.revision,'candidate_id',coalesce(candidate,cfg.candidate_id),'active_id',cfg.active_id,'proof',proof));
 END IF;
 SELECT to_jsonb(c)||jsonb_build_object('proof',proof,'current_workflow',(public.store_operating_source_v1(p_store_id))->>'workflow','fulfillment_mode',(public.store_operating_source_v1(p_store_id))->>'fulfillment_mode',
  'accounts',(SELECT jsonb_agg(jsonb_build_object('id',u.id,'name',u.full_name,'kind',a.station_type,'floor',a.floor_label) ORDER BY a.station_type,u.full_name)
    FROM public.emergency_station_assignments a JOIN public.users u ON u.id=a.user_id AND u.is_active WHERE a.restaurant_id=p_store_id AND a.is_active),
  'devices',(SELECT jsonb_agg(to_jsonb(d)-'restaurant_id') FROM public.store_workflow_devices d WHERE d.restaurant_id=p_store_id),
  'releases',(SELECT jsonb_agg(to_jsonb(v) ORDER BY v.created_at DESC) FROM (SELECT id,definition,created_at FROM public.store_workflow_releases WHERE restaurant_id=p_store_id ORDER BY created_at DESC LIMIT 20)v)) INTO result
 FROM public.store_workflow_configs c WHERE c.restaurant_id=p_store_id;
 RETURN result;
END;
$$;

CREATE FUNCTION public.store_workflow_capture_order() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('store-opening:'||NEW.restaurant_id::text,0));
 SELECT active_id INTO NEW.operating_release_id FROM public.store_workflow_configs WHERE restaurant_id=NEW.restaurant_id;
 RETURN NEW;
END;
$$;
CREATE TRIGGER aa_workflow_capture BEFORE INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.store_workflow_capture_order();
CREATE TRIGGER aa_workflow_capture BEFORE INSERT ON public.direct_order_requests FOR EACH ROW EXECUTE FUNCTION public.store_workflow_capture_order();
CREATE FUNCTION public.store_workflow_guard_version() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN IF NEW.operating_release_id IS DISTINCT FROM OLD.operating_release_id THEN RAISE EXCEPTION 'WORKFLOW_VERSION_IMMUTABLE'; END IF; RETURN NEW; END;
$$;
CREATE TRIGGER aa_workflow_immutable BEFORE UPDATE OF operating_release_id ON public.orders FOR EACH ROW EXECUTE FUNCTION public.store_workflow_guard_version();
CREATE TRIGGER aa_workflow_immutable BEFORE UPDATE OF operating_release_id ON public.direct_order_requests FOR EACH ROW EXECUTE FUNCTION public.store_workflow_guard_version();
CREATE TRIGGER workflow_release_delete_guard AFTER DELETE ON public.store_workflow_releases REFERENCING OLD TABLE AS deleted_operating_rows FOR EACH STATEMENT EXECUTE FUNCTION public.store_operating_guard_delete_v1();
CREATE TRIGGER workflow_release_immutable BEFORE UPDATE ON public.store_workflow_releases FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();

ALTER TABLE public.store_workflow_releases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.store_workflow_configs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.store_workflow_devices ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_workflow_releases,public.store_workflow_configs,public.store_workflow_devices FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.store_workflow_source(uuid),public.store_workflow_path(jsonb,uuid,text,uuid),public.store_workflow_validate(uuid,jsonb),public.store_workflow_capture_order(),public.store_workflow_guard_version() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.admin_store_workflow_v1(uuid,text,bigint,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_store_workflow_v1(uuid,text,bigint,jsonb) TO authenticated,service_role;
DO $verify$ BEGIN
 IF has_function_privilege('anon','public.admin_store_workflow_v1(uuid,text,bigint,jsonb)','EXECUTE')
 OR has_function_privilege('authenticated','public.store_workflow_validate(uuid,jsonb)','EXECUTE')
 OR has_table_privilege('authenticated','public.store_workflow_configs','UPDATE')
 OR NOT has_function_privilege('authenticated','public.admin_store_workflow_v1(uuid,text,bigint,jsonb)','EXECUTE')
 THEN RAISE EXCEPTION 'WORKFLOW_PUBLICATION_CONTRACT_INVALID'; END IF;
END $verify$;

-- COMPONENT 20261021191000_multi_kitchen_progress.sql
-- Additional kitchen stages project only their final handoff into the existing
-- tray/floor FIFO ledger. No stock or payment is posted by preparation stages.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE TABLE public.store_preparation_tasks (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 release_id uuid NOT NULL, order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE, order_item_id uuid NOT NULL REFERENCES public.order_items(id) ON DELETE CASCADE,
 source_kind text NOT NULL CHECK(source_kind IN ('base','combo_component','direct_ticket')), source_id uuid NOT NULL,
 menu_item_id uuid NOT NULL, ticket_id uuid, created_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(restaurant_id,release_id) REFERENCES public.store_workflow_releases(restaurant_id,id) ON DELETE CASCADE,
 UNIQUE(source_kind,source_id), UNIQUE(restaurant_id,id)
);
CREATE INDEX store_preparation_tasks_order ON public.store_preparation_tasks(order_id,order_item_id);
CREATE INDEX store_preparation_tasks_item ON public.store_preparation_tasks(order_item_id);
CREATE TABLE public.store_preparation_steps (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL,
 task_id uuid NOT NULL, station_id uuid NOT NULL, position integer NOT NULL CHECK(position BETWEEN 1 AND 8),
 started integer NOT NULL DEFAULT 0, done integer NOT NULL DEFAULT 0, revision bigint NOT NULL DEFAULT 0,
 started_at timestamptz, done_at timestamptz, updated_by uuid,
 FOREIGN KEY(restaurant_id,task_id) REFERENCES public.store_preparation_tasks(restaurant_id,id) ON DELETE CASCADE,
 FOREIGN KEY(restaurant_id,station_id) REFERENCES public.store_service_stations(restaurant_id,id) ON DELETE CASCADE,
 UNIQUE(task_id,position), CHECK(done>=0 AND started>=done)
);
CREATE INDEX store_preparation_steps_station ON public.store_preparation_steps(restaurant_id,station_id,task_id);
CREATE TABLE public.store_preparation_events (
 id uuid PRIMARY KEY, restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE, actor_id uuid NOT NULL,
 payload jsonb NOT NULL, response jsonb NOT NULL, before_steps jsonb NOT NULL DEFAULT '[]', after_steps jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now()
);
CREATE VIEW public.store_preparation_sources WITH (security_invoker=true) AS
 SELECT i.restaurant_id,i.order_id,i.order_item_id,'base'::text source_kind,i.id source_id,oi.menu_item_id,
  i.queue_id,ticket.id ticket_id,i.ordered_quantity-i.excused_quantity quantity,i.is_cancelled OR i.needs_review OR coalesce(ticket.status IN ('completed','cancelled'),false) blocked,
  coalesce(nullif(oi.menu_option_snapshot->>'name_ko',''),nullif(menu.name_ko,''),oi.display_name) name_ko,
  coalesce(nullif(oi.menu_option_snapshot->>'name_vi',''),nullif(menu.name_vi,''),oi.display_name) name_vi,
  coalesce(nullif(oi.menu_option_snapshot->>'name_en',''),nullif(menu.name_en,''),oi.display_name) name_en,oi.notes,q.table_number,q.floor_label,i.created_at
 FROM public.emergency_fulfillment_items i JOIN public.order_items oi ON oi.id=i.order_item_id LEFT JOIN public.menu_items menu ON menu.id=oi.menu_item_id JOIN public.emergency_order_queue q ON q.id=i.queue_id
 LEFT JOIN public.direct_order_financials financials ON financials.order_id=i.order_id
 LEFT JOIN public.direct_delivery_fulfillment_tickets ticket ON ticket.request_id=financials.request_id
 WHERE NOT EXISTS(SELECT 1 FROM public.emergency_combo_component_items c WHERE c.order_item_id=i.order_item_id AND NOT c.is_cancelled)
 AND coalesce(oi.fulfillment_route_snapshot,'kitchen_tray_floor')<>'floor_direct'
 UNION ALL
 SELECT i.restaurant_id,i.order_id,i.order_item_id,'combo_component',i.id,i.component_menu_item_id,
  i.queue_id,ticket.id,i.ordered_quantity-i.excused_quantity,i.is_cancelled OR i.needs_review OR coalesce(ticket.status IN ('completed','cancelled'),false),
  i.name_ko,i.name_vi,i.name_en,oi.notes,q.table_number,q.floor_label,i.created_at
 FROM public.emergency_combo_component_items i JOIN public.order_items oi ON oi.id=i.order_item_id JOIN public.emergency_order_queue q ON q.id=i.queue_id
 LEFT JOIN public.direct_order_financials financials ON financials.order_id=i.order_id
 LEFT JOIN public.direct_delivery_fulfillment_tickets ticket ON ticket.request_id=financials.request_id
 UNION ALL
 SELECT i.restaurant_id,o.id,oi.id,'direct_ticket',i.id,oi.menu_item_id,NULL::uuid,t.id,i.quantity,t.status IN ('cancelled','completed') OR oi.status='cancelled',
  i.display_name_ko,i.display_name_vi,i.display_name_en,oi.notes,t.pickup_code,NULL::text,t.created_at
 FROM public.direct_delivery_fulfillment_ticket_items i JOIN public.direct_delivery_fulfillment_tickets t ON t.id=i.ticket_id
 JOIN public.direct_order_financials f ON f.request_id=t.request_id JOIN public.orders o ON o.id=f.order_id
 JOIN public.order_items oi ON oi.id=i.id
 WHERE NOT EXISTS(SELECT 1 FROM public.emergency_fulfillment_items b WHERE b.order_id=o.id AND NOT b.is_cancelled)
 AND NOT EXISTS(SELECT 1 FROM public.emergency_combo_component_items c WHERE c.order_id=o.id AND NOT c.is_cancelled);

CREATE FUNCTION public.store_preparation_seed(p_order_ids uuid[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF current_setting('globos.cashier_item_mutation',true)='on' OR nullif(current_setting('app.direct_order_request_id',true),'') IS NOT NULL THEN RETURN; END IF;
 WITH added AS (
  INSERT INTO public.store_preparation_tasks(restaurant_id,release_id,order_id,order_item_id,source_kind,source_id,menu_item_id,ticket_id,created_at)
  SELECT s.restaurant_id,o.operating_release_id,s.order_id,s.order_item_id,s.source_kind,s.source_id,s.menu_item_id,s.ticket_id,s.created_at
  FROM public.store_preparation_sources s JOIN public.orders o ON o.id=s.order_id
  WHERE s.order_id=ANY(p_order_ids) AND o.operating_release_id IS NOT NULL AND NOT s.blocked
  ON CONFLICT(source_kind,source_id) DO NOTHING RETURNING *
 ) INSERT INTO public.store_preparation_steps(restaurant_id,task_id,station_id,position)
 SELECT t.restaurant_id,t.id,p.station::uuid,p.n FROM added t JOIN public.orders o ON o.id=t.order_id
 JOIN public.store_workflow_releases r ON r.id=t.release_id JOIN public.menu_items m ON m.id=t.menu_item_id JOIN public.order_items oi ON oi.id=t.order_item_id
 CROSS JOIN LATERAL jsonb_array_elements_text(public.store_workflow_path(r.definition,t.menu_item_id,CASE WHEN oi.is_takeout THEN 'pickup' ELSE o.sales_channel END,m.size_parent_id)) WITH ORDINALITY p(station,n);
 IF FOUND THEN PERFORM public.store_preparation_ready_notify(p_order_ids); END IF;
END;
$$;
CREATE FUNCTION public.store_preparation_seed_items() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE ids uuid[];
BEGIN
 SELECT array_agg(DISTINCT order_id) INTO ids FROM new_workflow_items;
 PERFORM public.store_preparation_seed(ids); RETURN NULL;
END;
$$;
CREATE TRIGGER zzzz_workflow_seed AFTER INSERT ON public.order_items REFERENCING NEW TABLE AS new_workflow_items FOR EACH STATEMENT EXECUTE FUNCTION public.store_preparation_seed_items();
CREATE TRIGGER zzzz_workflow_seed AFTER INSERT ON public.direct_order_financials REFERENCING NEW TABLE AS new_workflow_items FOR EACH STATEMENT EXECUTE FUNCTION public.store_preparation_seed_items();
CREATE FUNCTION public.store_preparation_seed_tickets() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE ids uuid[];
BEGIN
 SELECT array_agg(DISTINCT f.order_id) INTO ids FROM new_workflow_tickets i JOIN public.direct_delivery_fulfillment_tickets t ON t.id=i.ticket_id JOIN public.direct_order_financials f ON f.request_id=t.request_id;
 PERFORM public.store_preparation_seed(ids); RETURN NULL;
END;
$$;
CREATE TRIGGER zzzz_workflow_seed AFTER INSERT ON public.direct_delivery_fulfillment_ticket_items REFERENCING NEW TABLE AS new_workflow_tickets FOR EACH STATEMENT EXECUTE FUNCTION public.store_preparation_seed_tickets();

-- Enforce the protocol at the data boundary, including older callable RPC aliases.
CREATE FUNCTION public.store_preparation_guard_legacy() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF current_setting('globos.workflow_projection',true)='on' OR current_setting('globos.cashier_item_mutation',true) IN ('on','repair') THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM public.store_workflow_devices d JOIN public.users u ON u.id=d.user_id WHERE u.auth_id=auth.uid() AND d.quiesced) AND EXISTS(SELECT 1 FROM new_workflow_progress n JOIN old_workflow_progress o USING(id) WHERE n.kitchen_started_quantity>o.kitchen_started_quantity OR n.kitchen_done_quantity>o.kitchen_done_quantity OR n.tray_dispatched_quantity>o.tray_dispatched_quantity OR n.floor_served_quantity>o.floor_served_quantity) THEN RAISE EXCEPTION 'WORKFLOW_DEVICE_QUIESCED'; END IF;
 IF EXISTS(SELECT 1 FROM new_workflow_progress n JOIN old_workflow_progress o USING(id)
  JOIN public.store_preparation_tasks t ON t.source_id=n.id
  WHERE n.kitchen_started_quantity IS DISTINCT FROM o.kitchen_started_quantity OR n.kitchen_done_quantity IS DISTINCT FROM o.kitchen_done_quantity)
 THEN RAISE EXCEPTION 'WORKFLOW_CLIENT_UPDATE_REQUIRED'; END IF;
 RETURN NULL;
END;
$$;
CREATE TRIGGER workflow_legacy_guard AFTER UPDATE ON public.emergency_fulfillment_items REFERENCING OLD TABLE AS old_workflow_progress NEW TABLE AS new_workflow_progress FOR EACH STATEMENT EXECUTE FUNCTION public.store_preparation_guard_legacy();
CREATE TRIGGER workflow_legacy_guard AFTER UPDATE ON public.emergency_combo_component_items REFERENCING OLD TABLE AS old_workflow_progress NEW TABLE AS new_workflow_progress FOR EACH STATEMENT EXECUTE FUNCTION public.store_preparation_guard_legacy();
CREATE FUNCTION public.store_preparation_guard_ticket() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM public.store_preparation_tasks t JOIN public.store_preparation_steps s ON s.task_id=t.id
  JOIN public.store_preparation_sources src ON src.source_id=t.source_id AND src.source_kind=t.source_kind
  WHERE t.ticket_id=NEW.id AND NOT src.blocked AND s.done<src.quantity)
  AND (NEW.cooking_completed_at IS NOT NULL AND NEW.cooking_completed_at IS DISTINCT FROM OLD.cooking_completed_at OR NEW.status IN ('ready','dispatched','completed') AND NEW.status<>OLD.status)
 THEN RAISE EXCEPTION 'WORKFLOW_PREPARATION_INCOMPLETE'; END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER workflow_ticket_guard BEFORE UPDATE ON public.direct_delivery_fulfillment_tickets FOR EACH ROW EXECUTE FUNCTION public.store_preparation_guard_ticket();

CREATE FUNCTION public.store_workflow_device_v1(p_store_id uuid,p_device_id uuid DEFAULT NULL,p_release_id uuid DEFAULT NULL,p_pending_count integer DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE usr public.users%ROWTYPE; cfg public.store_workflow_configs%ROWTYPE; station jsonb; definition jsonb;
BEGIN
 SELECT * INTO usr FROM public.users WHERE auth_id=auth.uid() AND restaurant_id=p_store_id AND is_active;
 IF NOT FOUND THEN RAISE EXCEPTION 'WORKFLOW_ACTOR_REQUIRED'; END IF;
 SELECT * INTO cfg FROM public.store_workflow_configs WHERE restaurant_id=p_store_id;
 IF p_release_id IS NOT NULL THEN
  IF p_device_id IS NULL OR p_pending_count IS NULL OR p_pending_count NOT BETWEEN -1 AND 10000 OR (p_release_id IS DISTINCT FROM cfg.candidate_id AND p_release_id IS DISTINCT FROM cfg.active_id)
   OR NOT EXISTS(SELECT 1 FROM public.emergency_station_assignments WHERE restaurant_id=p_store_id AND user_id=usr.id AND is_active)
  THEN RAISE EXCEPTION 'WORKFLOW_DEVICE_INVALID'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.store_workflow_devices WHERE restaurant_id=p_store_id AND user_id=usr.id AND device_id=p_device_id)
   AND (SELECT count(*) FROM public.store_workflow_devices WHERE restaurant_id=p_store_id AND user_id=usr.id)>=10 THEN RAISE EXCEPTION 'WORKFLOW_DEVICE_LIMIT'; END IF;
  INSERT INTO public.store_workflow_devices(restaurant_id,user_id,device_id,release_id,pending_count,quiesced) VALUES(p_store_id,usr.id,p_device_id,p_release_id,greatest(0,p_pending_count),p_pending_count=0 AND p_release_id IS DISTINCT FROM cfg.active_id)
   ON CONFLICT(restaurant_id,user_id,device_id) DO UPDATE SET release_id=excluded.release_id,pending_count=excluded.pending_count,quiesced=excluded.quiesced,seen_at=now();
 END IF;
 SELECT r.definition INTO definition FROM public.store_workflow_releases r WHERE r.id=cfg.active_id;
 SELECT s INTO station FROM jsonb_array_elements(definition->'stations')s WHERE s->'user_ids' ? usr.id::text;
 RETURN jsonb_build_object('quiesced',EXISTS(SELECT 1 FROM public.store_workflow_devices d WHERE d.restaurant_id=p_store_id AND d.user_id=usr.id AND d.quiesced),'active_id',cfg.active_id,'candidate_id',cfg.candidate_id,'revision',coalesce(cfg.revision,0),'station',station,
 'candidate_station',(SELECT s FROM public.store_workflow_releases r,jsonb_array_elements(r.definition->'stations')s WHERE r.id=cfg.candidate_id AND s->'user_ids' ? usr.id::text),
 'candidate_definition_hash',(SELECT md5(v.definition::text) FROM public.store_workflow_releases v WHERE v.id=cfg.candidate_id));
END;
$$;
CREATE FUNCTION public.store_preparation_snapshot_v1(p_store_id uuid,p_after timestamptz DEFAULT NULL,p_after_id uuid DEFAULT NULL,p_completed boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE usr public.users%ROWTYPE; release uuid; station jsonb; result jsonb;
BEGIN
 SELECT * INTO usr FROM public.users WHERE auth_id=auth.uid() AND restaurant_id=p_store_id AND is_active;
 IF NOT FOUND THEN RAISE EXCEPTION 'WORKFLOW_ACTOR_REQUIRED'; END IF;
 SELECT c.active_id,s INTO release,station FROM public.store_workflow_configs c JOIN public.store_workflow_releases r ON r.id=c.active_id,
 jsonb_array_elements(r.definition->'stations')s WHERE c.restaurant_id=p_store_id AND s->'user_ids' ? usr.id::text;
 IF station IS NULL OR NOT EXISTS(SELECT 1 FROM public.emergency_station_assignments WHERE restaurant_id=p_store_id AND user_id=usr.id AND is_active AND station_type='kitchen') THEN RAISE EXCEPTION 'WORKFLOW_STATION_FORBIDDEN'; END IF;
 WITH rows AS MATERIALIZED (
  SELECT s.id,s.task_id,s.position,s.started,s.done,s.revision,s.started_at,s.done_at,t.created_at,
   src.quantity,src.name_ko,src.name_vi,src.name_en,src.notes,src.table_number,src.floor_label,
   coalesce(prev.done,src.quantity) available,coalesce(prev.done_at,t.created_at) ready_at,
   greatest(0,s.started-s.done) undo_start_available,
   greatest(0,s.done-CASE WHEN next_step.id IS NOT NULL THEN next_step.started WHEN ticket.id IS NOT NULL AND ticket.status NOT IN ('pending','preparing') THEN s.done WHEN t.source_kind='direct_ticket' THEN 0 WHEN queue.kitchen_direct_to_floor THEN coalesce(base.floor_served_quantity,component.floor_served_quantity) ELSE coalesce(base.tray_received_quantity,component.tray_received_quantity) END) undo_done_available,
   NOT EXISTS(SELECT 1 FROM public.store_preparation_steps n WHERE n.task_id=t.id AND n.position>s.position) final_step
  FROM public.store_preparation_steps s JOIN public.store_preparation_tasks t ON t.id=s.task_id
  JOIN public.store_preparation_sources src ON src.source_id=t.source_id AND src.source_kind=t.source_kind
  LEFT JOIN public.store_preparation_steps prev ON prev.task_id=t.id AND prev.position=s.position-1
  LEFT JOIN public.store_preparation_steps next_step ON next_step.task_id=t.id AND next_step.position=s.position+1
  LEFT JOIN public.emergency_fulfillment_items base ON t.source_kind='base' AND base.id=t.source_id
  LEFT JOIN public.emergency_combo_component_items component ON t.source_kind='combo_component' AND component.id=t.source_id
  LEFT JOIN public.emergency_order_queue queue ON queue.id=coalesce(base.queue_id,component.queue_id)
  LEFT JOIN public.direct_delivery_fulfillment_tickets ticket ON ticket.id=t.ticket_id
  WHERE s.restaurant_id=p_store_id AND s.station_id=(station->>'id')::uuid AND t.release_id=release
   AND NOT src.blocked AND CASE WHEN p_completed THEN s.done>=src.quantity AND s.done_at>now()-interval '24 hours' ELSE s.done<src.quantity END AND (p_after IS NULL OR (t.created_at,s.id)>(p_after,p_after_id))
  ORDER BY t.created_at,s.id LIMIT 101
 ) SELECT jsonb_build_object('release_id',release,'station',station,'has_more',(SELECT count(*)>100 FROM rows),
   'items',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY created_at,id) FROM (SELECT * FROM rows ORDER BY created_at,id LIMIT 100)x),'[]'::jsonb)) INTO result;
 RETURN result;
END;
$$;
CREATE FUNCTION public.store_preparation_trim_lots(p_source_ids uuid[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE lot_table text; used text; allowed text;
BEGIN
 FOREACH lot_table IN ARRAY ARRAY['emergency_floor_ready_lots','emergency_tray_ready_lots'] LOOP
  used:=CASE lot_table WHEN 'emergency_floor_ready_lots' THEN 'served_quantity' ELSE 'handed_quantity' END;
  allowed:=CASE lot_table WHEN 'emergency_floor_ready_lots' THEN 'tray_dispatched_quantity-floor_served_quantity' ELSE 'kitchen_done_quantity-tray_dispatched_quantity' END;
  EXECUTE format($trim$
   WITH sources AS(SELECT id,%s allowed FROM public.emergency_fulfillment_items WHERE id=ANY($1) UNION ALL SELECT id,%s FROM public.emergency_combo_component_items WHERE id=ANY($1)),
   lots AS MATERIALIZED(SELECT l.id,l.source_id,l.ready_sequence,l.ready_quantity-l.%I-l.voided_quantity remaining,s.allowed FROM public.%I l JOIN sources s ON s.id=l.source_id FOR UPDATE OF l),
   allocations AS(SELECT id,remaining,greatest(0,sum(remaining)OVER(PARTITION BY source_id)-allowed) excess,coalesce(sum(remaining)OVER(PARTITION BY source_id ORDER BY ready_sequence DESC,id DESC ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) prior FROM lots)
   UPDATE public.%I l SET voided_quantity=l.voided_quantity+greatest(0,least(a.remaining,a.excess-a.prior))::integer,updated_at=now() FROM allocations a WHERE l.id=a.id AND a.excess>a.prior AND a.remaining>0
  $trim$,allowed,allowed,used,lot_table,lot_table) USING p_source_ids;
 END LOOP;
END;
$$;
REVOKE ALL ON FUNCTION public.store_preparation_trim_lots(uuid[]) FROM PUBLIC,anon,authenticated,service_role;

-- Multi-kitchen start is already counted before final handoff. Keep the legacy
-- Bunsik implicit-start behavior for legacy callers, but never count it twice
-- when the versioned preparation protocol projects its explicit final handoff.
CREATE OR REPLACE FUNCTION "public"."kds_apply_station_progress_batch_v1"("p_request_id" "uuid", "p_restaurant_id" "uuid", "p_actor_user_id" "uuid", "p_action" "text", "p_floor_label" "text", "p_allocations" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_direct boolean := public.kds_uses_direct_floor_workflow(p_restaurant_id);
  v_allocation_count integer;
  v_changed_quantity integer;
  v_matched_count integer;
  v_workflow_two_quantity integer := 0;
  v_tray_sequence_end bigint;
  v_floor_sequence_end bigint;
  v_event_ids jsonb := '[]'::jsonb;
BEGIN
  IF p_request_id IS NULL OR p_restaurant_id IS NULL
     OR p_actor_user_id IS NULL
     OR p_action NOT IN ('kitchen_done', 'tray_dispatched', 'floor_served')
     OR jsonb_typeof(p_allocations) <> 'array'
     OR jsonb_array_length(p_allocations) = 0 THEN
    RAISE EXCEPTION 'KDS_BATCH_INPUT_INVALID';
  END IF;

  SELECT count(*)::integer, COALESCE(sum(a.quantity), 0)::integer
  INTO v_allocation_count, v_changed_quantity
  FROM jsonb_to_recordset(p_allocations) AS a(
    item_id uuid, queue_id uuid, source_kind text, quantity integer
  );
  IF v_allocation_count > 1000 OR v_changed_quantity <= 0
     OR v_changed_quantity > 1000 OR EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_allocations) AS a(
      item_id uuid, queue_id uuid, source_kind text, quantity integer
    )
    WHERE a.item_id IS NULL
      OR a.source_kind NOT IN ('base', 'combo_component')
      OR a.quantity IS NULL OR a.quantity <= 0
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_allocations) AS a(
      item_id uuid, queue_id uuid, source_kind text, quantity integer
    )
    GROUP BY a.item_id, a.source_kind
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'KDS_BATCH_INPUT_INVALID';
  END IF;

  -- A single global lock order prevents two mixed base/combo batches from
  -- deadlocking while still allowing different stores to progress in parallel.
  BEGIN
    PERFORM item.id
    FROM public.emergency_fulfillment_items item
    JOIN jsonb_to_recordset(p_allocations) AS allocation(
      item_id uuid, queue_id uuid, source_kind text, quantity integer
    ) ON allocation.item_id = item.id
      AND allocation.source_kind = 'base'
    ORDER BY item.id
    FOR UPDATE OF item NOWAIT;

    PERFORM component.id
    FROM public.emergency_combo_component_items component
    JOIN jsonb_to_recordset(p_allocations) AS allocation(
      item_id uuid, queue_id uuid, source_kind text, quantity integer
    ) ON allocation.item_id = component.id
      AND allocation.source_kind = 'combo_component'
    ORDER BY component.id
    FOR UPDATE OF component NOWAIT;

    PERFORM parent.id
    FROM public.emergency_fulfillment_items parent
    JOIN (
      SELECT DISTINCT component.session_id, component.order_item_id
      FROM public.emergency_combo_component_items component
      JOIN jsonb_to_recordset(p_allocations) AS allocation(
        item_id uuid, queue_id uuid, source_kind text, quantity integer
      ) ON allocation.item_id = component.id
        AND allocation.source_kind = 'combo_component'
    ) affected ON affected.session_id = parent.session_id
      AND affected.order_item_id = parent.order_item_id
    ORDER BY parent.id
    FOR UPDATE OF parent NOWAIT;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'KDS_BATCH_STALE';
  END;

  WITH allocations AS (
    SELECT * FROM jsonb_to_recordset(p_allocations) AS a(
      item_id uuid, queue_id uuid, source_kind text, quantity integer
    )
  ), lines AS (
    SELECT item.id AS item_id, item.queue_id, 'base'::text AS source_kind,
      item.session_id, item.order_id, item.order_item_id,
      item.ordered_quantity, item.excused_quantity,
      item.kitchen_done_quantity, item.tray_dispatched_quantity,
      item.floor_served_quantity, queue.workflow_version,
      queue.floor_label, COALESCE(order_row.sales_channel, 'dine_in') AS channel,
      allocation.quantity
    FROM allocations allocation
    JOIN public.emergency_fulfillment_items item
      ON item.id = allocation.item_id
     AND allocation.source_kind = 'base'
    JOIN public.emergency_order_queue queue ON queue.id = item.queue_id
    JOIN public.emergency_fulfillment_sessions session
      ON session.id = item.session_id AND session.status = 'active'
    JOIN public.orders order_row ON order_row.id = item.order_id
    WHERE item.restaurant_id = p_restaurant_id
      AND item.is_cancelled = false AND item.needs_review = false
      AND (allocation.queue_id IS NULL OR allocation.queue_id = item.queue_id)
      AND NOT EXISTS (
        SELECT 1 FROM public.emergency_combo_component_items component
        WHERE component.session_id = item.session_id
          AND component.order_item_id = item.order_item_id
          AND component.is_cancelled = false
      )
    UNION ALL
    SELECT component.id, component.queue_id, 'combo_component',
      component.session_id, component.order_id, component.order_item_id,
      component.ordered_quantity, component.excused_quantity,
      component.kitchen_done_quantity, component.tray_dispatched_quantity,
      component.floor_served_quantity, queue.workflow_version,
      queue.floor_label, COALESCE(order_row.sales_channel, 'dine_in'),
      allocation.quantity
    FROM allocations allocation
    JOIN public.emergency_combo_component_items component
      ON component.id = allocation.item_id
     AND allocation.source_kind = 'combo_component'
    JOIN public.emergency_order_queue queue ON queue.id = component.queue_id
    JOIN public.emergency_fulfillment_sessions session
      ON session.id = component.session_id AND session.status = 'active'
    JOIN public.orders order_row ON order_row.id = component.order_id
    WHERE component.restaurant_id = p_restaurant_id
      AND component.is_cancelled = false AND component.needs_review = false
      AND (allocation.queue_id IS NULL OR allocation.queue_id = component.queue_id)
  )
  SELECT count(*)::integer,
    COALESCE(sum(quantity) FILTER (WHERE workflow_version = 2), 0)::integer
  INTO v_matched_count, v_workflow_two_quantity
  FROM lines
  WHERE CASE p_action
    WHEN 'kitchen_done' THEN
      kitchen_done_quantity + quantity <= ordered_quantity - excused_quantity
    WHEN 'tray_dispatched' THEN
      workflow_version = 2 AND channel <> 'delivery'
      AND upper(btrim(floor_label)) = upper(btrim(p_floor_label))
      AND tray_dispatched_quantity + quantity <= kitchen_done_quantity
    WHEN 'floor_served' THEN
      workflow_version = 2 AND channel <> 'delivery'
      AND upper(btrim(floor_label)) = upper(btrim(p_floor_label))
      AND floor_served_quantity + quantity <= tray_dispatched_quantity
    ELSE false END;

  IF v_matched_count <> v_allocation_count THEN
    RAISE EXCEPTION 'KDS_BATCH_STALE';
  END IF;

  IF p_action = 'tray_dispatched' AND EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_allocations) AS allocation(
      item_id uuid, queue_id uuid, source_kind text, quantity integer
    )
    LEFT JOIN LATERAL (
      SELECT COALESCE(sum(
        lot.ready_quantity - lot.handed_quantity - lot.voided_quantity
      ), 0)::integer AS available
      FROM public.emergency_tray_ready_lots lot
      WHERE lot.source_kind = allocation.source_kind
        AND lot.source_id = allocation.item_id
    ) ready ON true
    WHERE ready.available < allocation.quantity
  ) THEN
    RAISE EXCEPTION 'KDS_BATCH_STALE';
  END IF;

  IF p_action = 'floor_served' AND EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_allocations) AS allocation(
      item_id uuid, queue_id uuid, source_kind text, quantity integer
    )
    LEFT JOIN LATERAL (
      SELECT COALESCE(sum(
        lot.ready_quantity - lot.served_quantity - lot.voided_quantity
      ), 0)::integer AS available
      FROM public.emergency_floor_ready_lots lot
      WHERE lot.source_kind = allocation.source_kind
        AND lot.source_id = allocation.item_id
    ) ready ON true
    WHERE ready.available < allocation.quantity
  ) THEN
    RAISE EXCEPTION 'KDS_BATCH_STALE';
  END IF;

  IF p_action = 'kitchen_done' AND NOT v_direct AND v_workflow_two_quantity > 0 THEN
    INSERT INTO public.emergency_tray_ready_sequences AS sequence(
      restaurant_id, current_sequence, updated_at
    ) VALUES (p_restaurant_id, v_workflow_two_quantity, now())
    ON CONFLICT (restaurant_id) DO UPDATE
    SET current_sequence = sequence.current_sequence
          + EXCLUDED.current_sequence,
        updated_at = now()
    RETURNING current_sequence INTO v_tray_sequence_end;

    WITH allocations AS (
      SELECT * FROM jsonb_to_recordset(p_allocations) AS a(
        item_id uuid, queue_id uuid, source_kind text, quantity integer
      )
    ), lines AS (
      SELECT item.id AS item_id, item.session_id, item.queue_id, item.order_id,
        item.order_item_id, 'base'::text AS source_kind, allocation.quantity,
        queue.created_at, queue.queue_no
      FROM allocations allocation
      JOIN public.emergency_fulfillment_items item
        ON item.id = allocation.item_id AND allocation.source_kind = 'base'
      JOIN public.emergency_order_queue queue
        ON queue.id = item.queue_id AND queue.workflow_version = 2
      UNION ALL
      SELECT component.id, component.session_id, component.queue_id,
        component.order_id, component.order_item_id, 'combo_component',
        allocation.quantity, queue.created_at, queue.queue_no
      FROM allocations allocation
      JOIN public.emergency_combo_component_items component
        ON component.id = allocation.item_id
       AND allocation.source_kind = 'combo_component'
      JOIN public.emergency_order_queue queue
        ON queue.id = component.queue_id AND queue.workflow_version = 2
    ), ranked AS (
      SELECT lines.*,
        COALESCE(sum(quantity) OVER (
          ORDER BY created_at, queue_no, queue_id, source_kind, item_id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 0)::bigint AS sequence_offset
      FROM lines
    )
    INSERT INTO public.emergency_tray_ready_lots(
      restaurant_id, session_id, queue_id, order_id, order_item_id,
      source_kind, source_id, kitchen_event_id, ready_sequence, ready_quantity
    )
    SELECT p_restaurant_id, ranked.session_id, ranked.queue_id,
      ranked.order_id, ranked.order_item_id, ranked.source_kind, ranked.item_id,
      md5(p_request_id::text || ':kitchen_done:' || ranked.source_kind || ':'
        || ranked.item_id::text)::uuid,
      v_tray_sequence_end - v_workflow_two_quantity
        + ranked.sequence_offset + 1,
      ranked.quantity
    FROM ranked;
  END IF;

  IF p_action = 'tray_dispatched' OR (v_direct AND p_action = 'kitchen_done') THEN
    WITH allocations AS (
      SELECT * FROM jsonb_to_recordset(p_allocations) AS a(
        item_id uuid, queue_id uuid, source_kind text, quantity integer
      )
    ), candidates AS (
      SELECT lot.id, allocation.item_id, allocation.source_kind,
        allocation.quantity,
        lot.ready_quantity - lot.handed_quantity - lot.voided_quantity
          AS available,
        COALESCE(sum(
          lot.ready_quantity - lot.handed_quantity - lot.voided_quantity
        ) OVER (
          PARTITION BY allocation.item_id, allocation.source_kind
          ORDER BY lot.ready_sequence, lot.id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 0)::integer AS consumed_before
      FROM allocations allocation
      JOIN public.emergency_tray_ready_lots lot
        ON lot.source_kind = allocation.source_kind
       AND lot.source_id = allocation.item_id
       AND lot.handed_quantity + lot.voided_quantity < lot.ready_quantity
    ), consumed AS (
      SELECT id, LEAST(
        available, GREATEST(quantity - consumed_before, 0)
      )::integer AS take_quantity
      FROM candidates
    )
    UPDATE public.emergency_tray_ready_lots lot
    SET handed_quantity = lot.handed_quantity + consumed.take_quantity,
        updated_at = now()
    FROM consumed
    WHERE lot.id = consumed.id AND consumed.take_quantity > 0;

    INSERT INTO public.emergency_floor_ready_sequences AS sequence(
      restaurant_id, current_sequence, updated_at
    ) VALUES (p_restaurant_id, v_changed_quantity, now())
    ON CONFLICT (restaurant_id) DO UPDATE
    SET current_sequence = sequence.current_sequence
          + EXCLUDED.current_sequence,
        updated_at = now()
    RETURNING current_sequence INTO v_floor_sequence_end;

    WITH allocations AS (
      SELECT * FROM jsonb_to_recordset(p_allocations) AS a(
        item_id uuid, queue_id uuid, source_kind text, quantity integer
      )
    ), lines AS (
      SELECT item.id AS item_id, item.session_id, item.queue_id, item.order_id,
        item.order_item_id, 'base'::text AS source_kind, allocation.quantity,
        queue.created_at, queue.queue_no
      FROM allocations allocation
      JOIN public.emergency_fulfillment_items item
        ON item.id = allocation.item_id AND allocation.source_kind = 'base'
      JOIN public.emergency_order_queue queue ON queue.id = item.queue_id
      UNION ALL
      SELECT component.id, component.session_id, component.queue_id,
        component.order_id, component.order_item_id, 'combo_component',
        allocation.quantity, queue.created_at, queue.queue_no
      FROM allocations allocation
      JOIN public.emergency_combo_component_items component
        ON component.id = allocation.item_id
       AND allocation.source_kind = 'combo_component'
      JOIN public.emergency_order_queue queue ON queue.id = component.queue_id
    ), ranked AS (
      SELECT lines.*,
        COALESCE(sum(quantity) OVER (
          ORDER BY created_at, queue_no, queue_id, source_kind, item_id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 0)::bigint AS sequence_offset
      FROM lines
    )
    INSERT INTO public.emergency_floor_ready_lots(
      restaurant_id, session_id, queue_id, order_id, order_item_id,
      source_kind, source_id, ready_action_id, ready_sequence, ready_quantity
    )
    SELECT p_restaurant_id, ranked.session_id, ranked.queue_id,
      ranked.order_id, ranked.order_item_id, ranked.source_kind, ranked.item_id,
      md5(p_request_id::text || ':' || p_action || ':' || ranked.source_kind || ':'
        || ranked.item_id::text)::uuid,
      v_floor_sequence_end - v_changed_quantity
        + ranked.sequence_offset + 1,
      ranked.quantity
    FROM ranked
    WHERE NOT v_direct OR (NOT EXISTS (
      SELECT 1 FROM public.orders o WHERE o.id = ranked.order_id AND o.sales_channel = 'delivery'
    ) AND NOT EXISTS (SELECT 1 FROM public.direct_order_financials f
      JOIN public.direct_order_requests r ON r.id = f.request_id AND r.fulfillment_type = 'pickup'
      WHERE f.order_id = ranked.order_id AND f.restaurant_id = p_restaurant_id));
  ELSIF p_action = 'floor_served' THEN
    WITH allocations AS (
      SELECT * FROM jsonb_to_recordset(p_allocations) AS a(
        item_id uuid, queue_id uuid, source_kind text, quantity integer
      )
    ), candidates AS (
      SELECT lot.id, allocation.item_id, allocation.source_kind,
        allocation.quantity,
        lot.ready_quantity - lot.served_quantity - lot.voided_quantity
          AS available,
        COALESCE(sum(
          lot.ready_quantity - lot.served_quantity - lot.voided_quantity
        ) OVER (
          PARTITION BY allocation.item_id, allocation.source_kind
          ORDER BY lot.ready_sequence, lot.id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 0)::integer AS consumed_before
      FROM allocations allocation
      JOIN public.emergency_floor_ready_lots lot
        ON lot.source_kind = allocation.source_kind
       AND lot.source_id = allocation.item_id
       AND lot.served_quantity + lot.voided_quantity < lot.ready_quantity
    ), consumed AS (
      SELECT id, LEAST(
        available, GREATEST(quantity - consumed_before, 0)
      )::integer AS take_quantity
      FROM candidates
    )
    UPDATE public.emergency_floor_ready_lots lot
    SET served_quantity = lot.served_quantity + consumed.take_quantity,
        updated_at = now()
    FROM consumed
    WHERE lot.id = consumed.id AND consumed.take_quantity > 0;
  END IF;

  WITH allocations AS (
    SELECT * FROM jsonb_to_recordset(p_allocations) AS a(
      item_id uuid, queue_id uuid, source_kind text, quantity integer
    )
  )
  UPDATE public.emergency_fulfillment_items item
  SET kitchen_started_quantity = CASE WHEN p_action = 'kitchen_done'
        THEN CASE WHEN v_direct OR current_setting('globos.workflow_projection',true)='on' THEN greatest(item.kitchen_started_quantity,
        item.kitchen_done_quantity + allocation.quantity)
        ELSE item.kitchen_started_quantity + allocation.quantity END
        ELSE item.kitchen_started_quantity END,
      kitchen_done_quantity = CASE WHEN p_action = 'kitchen_done'
        THEN item.kitchen_done_quantity + allocation.quantity
        ELSE item.kitchen_done_quantity END,
      tray_received_quantity = CASE WHEN p_action = 'tray_dispatched' OR (v_direct AND p_action = 'kitchen_done')
        THEN item.tray_received_quantity + allocation.quantity
        ELSE item.tray_received_quantity END,
      tray_dispatched_quantity = CASE WHEN p_action = 'tray_dispatched' OR (v_direct AND p_action = 'kitchen_done')
        THEN item.tray_dispatched_quantity + allocation.quantity
        ELSE item.tray_dispatched_quantity END,
      floor_served_quantity = CASE WHEN p_action = 'floor_served'
        THEN item.floor_served_quantity + allocation.quantity
        ELSE item.floor_served_quantity END,
      updated_at = now()
  FROM allocations allocation
  WHERE allocation.source_kind = 'base' AND item.id = allocation.item_id;

  WITH allocations AS (
    SELECT * FROM jsonb_to_recordset(p_allocations) AS a(
      item_id uuid, queue_id uuid, source_kind text, quantity integer
    )
  )
  UPDATE public.emergency_combo_component_items component
  SET kitchen_started_quantity = CASE WHEN p_action = 'kitchen_done'
        THEN CASE WHEN v_direct OR current_setting('globos.workflow_projection',true)='on' THEN greatest(component.kitchen_started_quantity,
        component.kitchen_done_quantity + allocation.quantity)
        ELSE component.kitchen_started_quantity + allocation.quantity END
        ELSE component.kitchen_started_quantity END,
      kitchen_done_quantity = CASE WHEN p_action = 'kitchen_done'
        THEN component.kitchen_done_quantity + allocation.quantity
        ELSE component.kitchen_done_quantity END,
      tray_received_quantity = CASE WHEN p_action = 'tray_dispatched' OR (v_direct AND p_action = 'kitchen_done')
        THEN component.tray_received_quantity + allocation.quantity
        ELSE component.tray_received_quantity END,
      tray_dispatched_quantity = CASE WHEN p_action = 'tray_dispatched' OR (v_direct AND p_action = 'kitchen_done')
        THEN component.tray_dispatched_quantity + allocation.quantity
        ELSE component.tray_dispatched_quantity END,
      floor_served_quantity = CASE WHEN p_action = 'floor_served'
        THEN component.floor_served_quantity + allocation.quantity
        ELSE component.floor_served_quantity END,
      updated_at = now()
  FROM allocations allocation
  WHERE allocation.source_kind = 'combo_component'
    AND component.id = allocation.item_id;

  -- Recompute every affected combo parent once, after all component rows have
  -- advanced. This preserves the commercial-line projection without N+1 RPCs.
  WITH allocations AS (
    SELECT * FROM jsonb_to_recordset(p_allocations) AS a(
      item_id uuid, queue_id uuid, source_kind text, quantity integer
    )
  ), affected AS (
    SELECT DISTINCT component.session_id, component.order_item_id
    FROM allocations allocation
    JOIN public.emergency_combo_component_items component
      ON component.id = allocation.item_id
     AND allocation.source_kind = 'combo_component'
  ), parent_values AS (
    SELECT parent.id,
      COALESCE(min(
        CASE p_action
          WHEN 'kitchen_done' THEN component.kitchen_done_quantity
          WHEN 'tray_dispatched' THEN component.tray_dispatched_quantity
          ELSE component.floor_served_quantity
        END * parent.ordered_quantity / component.ordered_quantity
      ), 0)::integer AS stage_quantity
    FROM affected
    JOIN public.emergency_fulfillment_items parent
      ON parent.session_id = affected.session_id
     AND parent.order_item_id = affected.order_item_id
    JOIN public.emergency_combo_component_items component
      ON component.session_id = affected.session_id
     AND component.order_item_id = affected.order_item_id
     AND component.is_cancelled = false
    GROUP BY parent.id
  )
  UPDATE public.emergency_fulfillment_items parent
  SET kitchen_started_quantity = CASE WHEN p_action = 'kitchen_done'
        THEN CASE WHEN v_direct OR current_setting('globos.workflow_projection',true)='on' THEN greatest(parent.kitchen_started_quantity,
        parent_values.stage_quantity) ELSE parent_values.stage_quantity END
        ELSE parent.kitchen_started_quantity END,
      kitchen_done_quantity = CASE WHEN p_action = 'kitchen_done'
        THEN parent_values.stage_quantity ELSE parent.kitchen_done_quantity END,
      tray_received_quantity = CASE WHEN p_action = 'tray_dispatched' OR (v_direct AND p_action = 'kitchen_done')
        THEN parent_values.stage_quantity ELSE parent.tray_received_quantity END,
      tray_dispatched_quantity = CASE WHEN p_action = 'tray_dispatched' OR (v_direct AND p_action = 'kitchen_done')
        THEN parent_values.stage_quantity ELSE parent.tray_dispatched_quantity END,
      floor_served_quantity = CASE WHEN p_action = 'floor_served'
        THEN parent_values.stage_quantity ELSE parent.floor_served_quantity END,
      updated_at = now()
  FROM parent_values
  WHERE parent.id = parent_values.id;

  WITH allocations AS (
    SELECT * FROM jsonb_to_recordset(p_allocations) AS a(
      item_id uuid, queue_id uuid, source_kind text, quantity integer
    )
  ), lines AS (
    SELECT item.id AS item_id, item.session_id, item.order_id,
      item.order_item_id, NULL::uuid AS combo_component_item_id,
      'base'::text AS source_kind, allocation.quantity,
      item.kitchen_started_quantity, item.kitchen_done_quantity,
      item.tray_received_quantity, item.tray_dispatched_quantity,
      item.floor_served_quantity
    FROM allocations allocation
    JOIN public.emergency_fulfillment_items item
      ON item.id = allocation.item_id AND allocation.source_kind = 'base'
    UNION ALL
    SELECT component.id, component.session_id, component.order_id,
      component.order_item_id, component.id, 'combo_component',
      allocation.quantity, component.kitchen_started_quantity,
      component.kitchen_done_quantity, component.tray_received_quantity,
      component.tray_dispatched_quantity, component.floor_served_quantity
    FROM allocations allocation
    JOIN public.emergency_combo_component_items component
      ON component.id = allocation.item_id
     AND allocation.source_kind = 'combo_component'
  ), inserted AS (
    INSERT INTO public.emergency_fulfillment_events(
      event_id, session_id, restaurant_id, order_id, order_item_id,
      combo_component_item_id, stage, delta, actor_user_id, details
    )
    SELECT md5(p_request_id::text || ':' || p_action || ':'
        || lines.source_kind || ':' || lines.item_id::text)::uuid,
      lines.session_id, p_restaurant_id, lines.order_id, lines.order_item_id,
      lines.combo_component_item_id, p_action, lines.quantity, p_actor_user_id,
      jsonb_build_object(
        'kitchen_direct_to_floor', v_direct, 'workflow_action', p_action,
        'source_kind', lines.source_kind,
        'effective_action', p_action,
        'source_id', lines.item_id,
        'batch_request_id', p_request_id,
        'response', jsonb_build_object(
          'kitchen_started_quantity', lines.kitchen_started_quantity,
          'kitchen_done_quantity', lines.kitchen_done_quantity,
          'tray_received_quantity', lines.tray_received_quantity,
          'tray_dispatched_quantity', lines.tray_dispatched_quantity,
          'floor_served_quantity', lines.floor_served_quantity
        )
      )
    FROM lines
    RETURNING event_id
  )
  SELECT COALESCE(jsonb_agg(event_id ORDER BY event_id), '[]'::jsonb)
  INTO v_event_ids
  FROM inserted;

  IF v_direct AND p_action = 'kitchen_done' THEN
    WITH allocations AS (
      SELECT * FROM jsonb_to_recordset(p_allocations) AS a(item_id uuid, queue_id uuid, source_kind text, quantity integer)
    ), affected AS MATERIALIZED (
      SELECT i.order_id FROM allocations a JOIN public.emergency_fulfillment_items i
        ON i.id = a.item_id AND a.source_kind = 'base'
      UNION
      SELECT i.order_id FROM allocations a JOIN public.emergency_combo_component_items i
        ON i.id = a.item_id AND a.source_kind = 'combo_component'
    ), readiness AS (
      SELECT t.id, bool_and(i.is_cancelled OR i.kitchen_done_quantity >= i.ordered_quantity - i.excused_quantity) AS ready
      FROM affected a JOIN public.direct_order_financials f ON f.order_id = a.order_id AND f.restaurant_id = p_restaurant_id
      JOIN public.direct_delivery_fulfillment_tickets t ON t.request_id = f.request_id
      JOIN public.emergency_fulfillment_items i ON i.order_id = a.order_id
      WHERE t.status IN ('pending', 'preparing', 'ready')
      GROUP BY t.id
    )
    UPDATE public.direct_delivery_fulfillment_tickets t
    SET status = CASE WHEN r.ready THEN 'ready' ELSE 'preparing' END,
      version = t.version + 1, accepted_at = COALESCE(t.accepted_at, now()),
      ready_at = CASE WHEN r.ready THEN COALESCE(t.ready_at, now()) ELSE NULL END, updated_at = now()
    FROM readiness r WHERE t.id = r.id
      AND t.status IS DISTINCT FROM CASE WHEN r.ready THEN 'ready' ELSE 'preparing' END;
  END IF;

  -- Push fan-out is also one set operation. A slow or unavailable push worker
  -- therefore never holds the operator request open.
  IF p_action IN ('kitchen_done', 'tray_dispatched') THEN
    WITH allocations AS (
      SELECT * FROM jsonb_to_recordset(p_allocations) AS a(
        item_id uuid, queue_id uuid, source_kind text, quantity integer
      )
    ), event_rows AS (
      SELECT md5(p_request_id::text || ':' || p_action || ':base:'
          || item.id::text)::uuid AS event_id,
        item.order_id, queue.floor_label,
        COALESCE(order_row.sales_channel, 'dine_in') AS channel
      FROM allocations allocation
      JOIN public.emergency_fulfillment_items item
        ON item.id = allocation.item_id AND allocation.source_kind = 'base'
      JOIN public.emergency_order_queue queue ON queue.id = item.queue_id
      JOIN public.orders order_row ON order_row.id = item.order_id
      UNION ALL
      SELECT md5(p_request_id::text || ':' || p_action || ':combo_component:'
          || component.id::text)::uuid,
        component.order_id, queue.floor_label,
        COALESCE(order_row.sales_channel, 'dine_in')
      FROM allocations allocation
      JOIN public.emergency_combo_component_items component
        ON component.id = allocation.item_id
       AND allocation.source_kind = 'combo_component'
      JOIN public.emergency_order_queue queue ON queue.id = component.queue_id
      JOIN public.orders order_row ON order_row.id = component.order_id
    )
    INSERT INTO public.emergency_push_deliveries(
      event_id, restaurant_id, device_id, push_token, station_type,
      floor_label, order_id, stage
    )
    SELECT event_rows.event_id, p_restaurant_id, device.id, device.token,
      assignment.station_type, assignment.floor_label,
      event_rows.order_id, p_action
    FROM event_rows
    JOIN public.emergency_station_assignments assignment
      ON assignment.restaurant_id = p_restaurant_id
     AND assignment.is_active = true
     AND assignment.station_type = CASE p_action
       WHEN 'kitchen_done' THEN CASE WHEN v_direct THEN 'floor' ELSE 'tray' END ELSE 'floor' END
    JOIN public.emergency_web_push_devices device
      ON device.station_assignment_id = assignment.id
     AND device.restaurant_id = p_restaurant_id
     AND device.is_enabled = true
    WHERE (assignment.station_type <> 'floor'
      OR assignment.floor_label = event_rows.floor_label)
      AND NOT (assignment.station_type = 'floor'
        AND (event_rows.channel = 'delivery' OR (v_direct AND EXISTS (
    SELECT 1 FROM public.direct_order_financials f JOIN public.direct_order_requests r
      ON r.id = f.request_id AND r.fulfillment_type = 'pickup'
    WHERE f.order_id = event_rows.order_id AND f.restaurant_id = p_restaurant_id))))
    ON CONFLICT (event_id, device_id) DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'changed_quantity', v_changed_quantity,
    'event_ids', v_event_ids
  );
EXCEPTION WHEN lock_not_available THEN
  RAISE EXCEPTION 'KDS_BATCH_STALE';
END;
$$;

CREATE FUNCTION public.store_preparation_progress_v1(p_store_id uuid,p_event_id uuid,p_action text,p_allocations jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE before_steps jsonb; usr public.users%ROWTYPE; release uuid; station jsonb; previous public.store_preparation_events%ROWTYPE;
 payload jsonb:=jsonb_build_object('action',p_action,'allocations',p_allocations); finals jsonb; result jsonb; requests uuid[];
BEGIN
 SELECT * INTO usr FROM public.users WHERE auth_id=auth.uid() AND restaurant_id=p_store_id AND is_active;
 IF NOT FOUND THEN RAISE EXCEPTION 'WORKFLOW_ACTOR_REQUIRED'; END IF;
 IF p_event_id IS NULL OR p_action IS NULL OR p_action NOT IN ('start','done','undo_start','undo_done') OR jsonb_typeof(p_allocations) IS DISTINCT FROM 'array' OR jsonb_array_length(p_allocations) NOT BETWEEN 1 AND 1000
  OR EXISTS(SELECT 1 FROM jsonb_to_recordset(p_allocations)a(step_id uuid,revision bigint,quantity integer) WHERE step_id IS NULL OR revision IS NULL OR quantity IS NULL OR quantity NOT BETWEEN 1 AND 1000)
  OR EXISTS(SELECT 1 FROM jsonb_to_recordset(p_allocations)a(step_id uuid) GROUP BY step_id HAVING count(*)>1)
  OR (SELECT sum(quantity) FROM jsonb_to_recordset(p_allocations)a(quantity integer))>1000 THEN RAISE EXCEPTION 'WORKFLOW_INPUT_INVALID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('prep-event:'||p_event_id::text,0));
 SELECT * INTO previous FROM public.store_preparation_events WHERE id=p_event_id;
 IF FOUND THEN
  IF previous.restaurant_id<>p_store_id OR previous.actor_id<>usr.id OR previous.payload<>payload THEN RAISE EXCEPTION 'WORKFLOW_EVENT_CONFLICT'; END IF;
  RETURN previous.response;
 END IF;
 IF EXISTS(SELECT 1 FROM public.store_workflow_devices WHERE restaurant_id=p_store_id AND user_id=usr.id AND quiesced) THEN RAISE EXCEPTION 'WORKFLOW_DEVICE_QUIESCED'; END IF;
 SELECT c.active_id,s INTO release,station FROM public.store_workflow_configs c JOIN public.store_workflow_releases r ON r.id=c.active_id,
 jsonb_array_elements(r.definition->'stations')s WHERE c.restaurant_id=p_store_id AND s->'user_ids' ? usr.id::text;
 IF station IS NULL OR NOT EXISTS(SELECT 1 FROM public.emergency_station_assignments WHERE restaurant_id=p_store_id AND user_id=usr.id AND is_active AND station_type='kitchen') THEN RAISE EXCEPTION 'WORKFLOW_STATION_FORBIDDEN'; END IF;
 -- Direct fulfillment uses request -> ticket -> order; ordinary cashier mutations
 -- cannot move a direct-order line. NOWAIT safely rejects overlapping changes.
 PERFORM r.id FROM public.direct_order_requests r WHERE r.id IN(SELECT f.request_id FROM public.direct_order_financials f JOIN public.store_preparation_tasks t ON t.order_id=f.order_id JOIN public.store_preparation_steps s ON s.task_id=t.id JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id) ORDER BY r.id FOR UPDATE NOWAIT;
 PERFORM ticket.id FROM public.direct_delivery_fulfillment_tickets ticket WHERE ticket.request_id IN(SELECT f.request_id FROM public.direct_order_financials f JOIN public.store_preparation_tasks t ON t.order_id=f.order_id JOIN public.store_preparation_steps s ON s.task_id=t.id JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id) ORDER BY ticket.id FOR UPDATE NOWAIT;
 -- Match cash-register mutation lock order. NOWAIT turns an overlapping operation
 -- into a retryable conflict rather than taking locks in the reverse direction.
 PERFORM o.id FROM public.orders o WHERE o.id IN (SELECT t.order_id FROM public.store_preparation_tasks t JOIN public.store_preparation_steps s ON s.task_id=t.id JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id) ORDER BY o.id FOR UPDATE NOWAIT;
 PERFORM i.id FROM public.order_items i WHERE i.id IN (SELECT t.order_item_id FROM public.store_preparation_tasks t JOIN public.store_preparation_steps s ON s.task_id=t.id JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id) ORDER BY i.id FOR UPDATE NOWAIT;
 PERFORM s.id FROM public.store_preparation_steps s WHERE s.task_id IN (SELECT x.task_id FROM public.store_preparation_steps x JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=x.id) ORDER BY s.id FOR UPDATE NOWAIT;
 IF (SELECT count(*) FROM jsonb_to_recordset(p_allocations)a(step_id uuid,revision bigint,quantity integer)
  JOIN public.store_preparation_steps s ON s.id=a.step_id AND s.revision=a.revision
  JOIN public.store_preparation_tasks t ON t.id=s.task_id AND t.release_id=release
  JOIN public.store_preparation_sources src ON src.source_id=t.source_id AND src.source_kind=t.source_kind
  LEFT JOIN public.store_preparation_steps prev ON prev.task_id=t.id AND prev.position=s.position-1
  LEFT JOIN public.store_preparation_steps next_step ON next_step.task_id=t.id AND next_step.position=s.position+1
  LEFT JOIN public.emergency_fulfillment_items base ON t.source_kind='base' AND base.id=t.source_id
  LEFT JOIN public.emergency_combo_component_items component ON t.source_kind='combo_component' AND component.id=t.source_id
  LEFT JOIN public.emergency_order_queue queue ON queue.id=coalesce(base.queue_id,component.queue_id)
  LEFT JOIN public.direct_delivery_fulfillment_tickets ticket ON ticket.id=t.ticket_id
  WHERE s.restaurant_id=p_store_id AND s.station_id=(station->>'id')::uuid AND NOT src.blocked
   AND CASE p_action WHEN 'start' THEN s.started+a.quantity<=least(src.quantity,coalesce(prev.done,src.quantity)) WHEN 'done' THEN s.done+a.quantity<=least(s.started,src.quantity,coalesce(prev.done,src.quantity))
    WHEN 'undo_start' THEN s.started-a.quantity>=s.done
    WHEN 'undo_done' THEN s.done-a.quantity>=CASE WHEN next_step.id IS NOT NULL THEN next_step.started
     WHEN ticket.id IS NOT NULL AND ticket.status NOT IN ('pending','preparing') THEN s.done WHEN t.source_kind='direct_ticket' THEN 0
     WHEN queue.kitchen_direct_to_floor THEN coalesce(base.floor_served_quantity,component.floor_served_quantity)
     ELSE coalesce(base.tray_received_quantity,component.tray_received_quantity) END ELSE false END)<>jsonb_array_length(p_allocations)
 THEN RAISE EXCEPTION 'WORKFLOW_PROGRESS_CHANGED'; END IF;
 SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) INTO before_steps FROM public.store_preparation_steps s JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id;
 UPDATE public.store_preparation_steps s SET started=started+CASE p_action WHEN 'start' THEN a.quantity WHEN 'undo_start' THEN -a.quantity ELSE 0 END,
  done=done+CASE p_action WHEN 'done' THEN a.quantity WHEN 'undo_done' THEN -a.quantity ELSE 0 END,revision=s.revision+1,updated_by=usr.id,
  started_at=CASE WHEN p_action='undo_start' AND started=a.quantity THEN NULL WHEN p_action='start' THEN coalesce(started_at,now()) ELSE started_at END,
  done_at=CASE WHEN p_action='undo_done' AND done=a.quantity THEN NULL WHEN p_action='done' THEN now() ELSE done_at END
 FROM jsonb_to_recordset(p_allocations)a(step_id uuid,quantity integer) WHERE s.id=a.step_id;
 PERFORM set_config('globos.workflow_projection','on',true);
 IF p_action='start' THEN
  UPDATE public.direct_delivery_fulfillment_tickets ticket SET status='preparing',accepted_at=coalesce(accepted_at,now()),version=version+1,updated_at=now(),updated_by=auth.uid()
   WHERE ticket.status='pending' AND ticket.request_id IN(SELECT f.request_id FROM public.direct_order_financials f JOIN public.store_preparation_tasks t ON t.order_id=f.order_id JOIN public.store_preparation_steps s ON s.task_id=t.id JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id);
  UPDATE public.emergency_fulfillment_items i SET kitchen_started_quantity=greatest(i.kitchen_started_quantity,s.started),updated_at=now()
   FROM public.store_preparation_tasks t JOIN public.store_preparation_steps s ON s.task_id=t.id AND s.position=1
   JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id WHERE t.source_kind='base' AND i.id=t.source_id;
  UPDATE public.emergency_combo_component_items i SET kitchen_started_quantity=greatest(i.kitchen_started_quantity,s.started),updated_at=now()
   FROM public.store_preparation_tasks t JOIN public.store_preparation_steps s ON s.task_id=t.id AND s.position=1
   JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id WHERE t.source_kind='combo_component' AND i.id=t.source_id;
 ELSIF p_action IN ('undo_start','undo_done') THEN
  -- The next stage and the existing tray/floor counters have already fenced
  -- consumed quantities above. Reverse only the unconsumed preparation units.
  UPDATE public.emergency_fulfillment_items i SET
   kitchen_started_quantity=CASE WHEN p_action='undo_start' AND s.position=1 THEN s.started ELSE i.kitchen_started_quantity END,
   kitchen_done_quantity=CASE WHEN p_action='undo_done' AND n.id IS NULL THEN s.done ELSE i.kitchen_done_quantity END,
   tray_received_quantity=CASE WHEN p_action='undo_done' AND n.id IS NULL AND q.kitchen_direct_to_floor THEN least(i.tray_received_quantity,s.done) ELSE i.tray_received_quantity END,
   tray_dispatched_quantity=CASE WHEN p_action='undo_done' AND n.id IS NULL AND q.kitchen_direct_to_floor THEN least(i.tray_dispatched_quantity,s.done) ELSE i.tray_dispatched_quantity END,updated_at=now()
  FROM jsonb_to_recordset(p_allocations)a(step_id uuid) JOIN public.store_preparation_steps s ON s.id=a.step_id
  JOIN public.store_preparation_tasks t ON t.id=s.task_id JOIN public.emergency_order_queue q ON q.order_id=t.order_id
  LEFT JOIN public.store_preparation_steps n ON n.task_id=t.id AND n.position=s.position+1
  WHERE t.source_kind='base' AND i.id=t.source_id AND i.queue_id=q.id;
  UPDATE public.emergency_combo_component_items i SET
   kitchen_started_quantity=CASE WHEN p_action='undo_start' AND s.position=1 THEN s.started ELSE i.kitchen_started_quantity END,
   kitchen_done_quantity=CASE WHEN p_action='undo_done' AND n.id IS NULL THEN s.done ELSE i.kitchen_done_quantity END,
   tray_received_quantity=CASE WHEN p_action='undo_done' AND n.id IS NULL AND q.kitchen_direct_to_floor THEN least(i.tray_received_quantity,s.done) ELSE i.tray_received_quantity END,
   tray_dispatched_quantity=CASE WHEN p_action='undo_done' AND n.id IS NULL AND q.kitchen_direct_to_floor THEN least(i.tray_dispatched_quantity,s.done) ELSE i.tray_dispatched_quantity END,updated_at=now()
  FROM jsonb_to_recordset(p_allocations)a(step_id uuid) JOIN public.store_preparation_steps s ON s.id=a.step_id
  JOIN public.store_preparation_tasks t ON t.id=s.task_id JOIN public.emergency_order_queue q ON q.order_id=t.order_id
  LEFT JOIN public.store_preparation_steps n ON n.task_id=t.id AND n.position=s.position+1
  WHERE t.source_kind='combo_component' AND i.id=t.source_id AND i.queue_id=q.id;
  IF p_action='undo_done' THEN
   PERFORM public.store_preparation_trim_lots(ARRAY(SELECT t.source_id FROM public.store_preparation_tasks t JOIN public.store_preparation_steps s ON s.task_id=t.id JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id));
   UPDATE public.direct_delivery_fulfillment_tickets ticket SET cooking_completed_at=NULL,version=version+1,updated_at=now(),updated_by=auth.uid()
    WHERE ticket.cooking_completed_at IS NOT NULL AND ticket.request_id IN(SELECT f.request_id FROM public.direct_order_financials f JOIN public.store_preparation_tasks t ON t.order_id=f.order_id JOIN public.store_preparation_steps s ON s.task_id=t.id JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id);
  END IF;
 ELSE
  SELECT jsonb_agg(jsonb_build_object('item_id',t.source_id,'source_kind',t.source_kind,'queue_id',src.queue_id,'quantity',a.quantity)) INTO finals
   FROM jsonb_to_recordset(p_allocations)a(step_id uuid,quantity integer) JOIN public.store_preparation_steps s ON s.id=a.step_id
   JOIN public.store_preparation_tasks t ON t.id=s.task_id JOIN public.store_preparation_sources src ON src.source_id=t.source_id AND src.source_kind=t.source_kind
   WHERE t.source_kind<>'direct_ticket' AND NOT EXISTS(SELECT 1 FROM public.store_preparation_steps n WHERE n.task_id=t.id AND n.position>s.position);
  IF finals IS NOT NULL THEN PERFORM public.kds_apply_station_progress_batch_v1(p_event_id,p_store_id,usr.id,'kitchen_done',NULL,finals); END IF;
  WITH changed AS (
   UPDATE public.direct_delivery_fulfillment_tickets ticket SET cooking_completed_at=now(),version=version+1,updated_at=now(),updated_by=auth.uid()
   WHERE ticket.id IN (SELECT t.ticket_id FROM public.store_preparation_tasks t JOIN public.store_preparation_steps s ON s.task_id=t.id JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id)
    AND ticket.cooking_completed_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.store_preparation_tasks t JOIN public.store_preparation_steps s ON s.task_id=t.id
     JOIN public.store_preparation_sources src ON src.source_id=t.source_id AND src.source_kind=t.source_kind WHERE t.ticket_id=ticket.id AND NOT src.blocked AND s.done<src.quantity)
   RETURNING ticket.request_id
  ) SELECT array_agg(request_id) INTO requests FROM changed;
  SELECT ARRAY(SELECT DISTINCT id FROM (SELECT unnest(requests) id UNION ALL SELECT f.request_id FROM public.direct_order_financials f
   JOIN public.store_preparation_tasks t ON t.order_id=f.order_id JOIN public.store_preparation_steps s ON s.task_id=t.id JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id)x) INTO requests;
  PERFORM public.direct_order_progress_notice_batch(requests,'cooking_complete');
 END IF;
 PERFORM set_config('globos.workflow_projection','off',true);
 result:=jsonb_build_object('event_id',p_event_id,'release_id',release,'changed_quantity',(SELECT sum(quantity) FROM jsonb_to_recordset(p_allocations)a(quantity integer)));
 INSERT INTO public.store_preparation_events(id,restaurant_id,actor_id,payload,response,before_steps,after_steps) VALUES(p_event_id,p_store_id,usr.id,payload,result,before_steps,(SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM public.store_preparation_steps s JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id));
 INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(auth.uid(),'store_preparation_'||p_action,'restaurants',p_store_id,result);
 IF p_action='done' THEN
  PERFORM public.store_preparation_ready_notify(ARRAY(SELECT DISTINCT t.order_id FROM public.store_preparation_tasks t JOIN public.store_preparation_steps s ON s.task_id=t.id JOIN jsonb_to_recordset(p_allocations)a(step_id uuid) ON a.step_id=s.id));
 ELSE PERFORM public.store_workflow_notify(p_store_id); END IF;
 RETURN result;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'WORKFLOW_PROGRESS_CHANGED';
END;
$$;
ALTER TABLE public.store_preparation_tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.store_preparation_steps ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.store_preparation_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_preparation_tasks,public.store_preparation_steps,public.store_preparation_events,public.store_preparation_sources FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.store_preparation_seed(uuid[]),public.store_preparation_seed_items(),public.store_preparation_seed_tickets(),public.store_preparation_guard_legacy(),public.store_preparation_guard_ticket() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.store_workflow_device_v1(uuid,uuid,uuid,integer),public.store_preparation_snapshot_v1(uuid,timestamptz,uuid,boolean),public.store_preparation_progress_v1(uuid,uuid,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.store_workflow_device_v1(uuid,uuid,uuid,integer),public.store_preparation_snapshot_v1(uuid,timestamptz,uuid,boolean),public.store_preparation_progress_v1(uuid,uuid,text,jsonb) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION "public"."direct_order_approve_payment"("p_store_id" "uuid", "p_request_id" "uuid", "p_confirmed_amount" numeric, "p_confirmed_bank_reference" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE previous_snapshot text; previous_lines text; line_snapshots jsonb; result jsonb; snapshot jsonb; already_approved boolean;
BEGIN
 previous_snapshot:=current_setting('pos.direct_combo_snapshot',true);
 previous_lines:=current_setting('pos.direct_line_snapshots',true);
 PERFORM public.direct_order_require_actor(p_store_id,ARRAY['cashier','admin','store_admin','brand_admin','super_admin']);
 PERFORM pg_advisory_xact_lock(hashtextextended('direct-order-approval:'||p_request_id::text,0));
 PERFORM 1 FROM public.direct_order_requests WHERE id=p_request_id AND restaurant_id=p_store_id FOR UPDATE;
 already_approved:=EXISTS(SELECT 1 FROM public.direct_order_financials WHERE request_id=p_request_id);
 IF NOT already_approved THEN
  PERFORM public.direct_order_validate_combo_request(p_store_id,p_request_id);
 END IF;
 -- Hydrate every approved line in one query. Individual snapshot triggers
 -- read the transaction map instead of re-querying each request/menu/recipe.
 WITH lines AS MATERIALIZED (
  SELECT i.id,jsonb_array_length(i.combo_components)>0 is_combo,
   jsonb_build_object('vat_profile_snapshot',i.vat_profile_snapshot,'combo_components',
    coalesce((SELECT jsonb_agg(c||jsonb_build_object('fulfillment_route','kitchen_tray_floor'))
     FROM jsonb_array_elements(i.combo_components)c),'[]'::jsonb)) payload
  FROM public.direct_order_request_items i WHERE i.request_id=p_request_id AND i.restaurant_id=p_store_id
 ) SELECT jsonb_object_agg(id::text,payload),jsonb_object_agg(id::text,payload) FILTER(WHERE is_combo)
 INTO line_snapshots,snapshot FROM lines;
 IF NOT already_approved AND snapshot IS NOT NULL THEN PERFORM public.direct_order_lock_combo_stock(p_store_id,p_request_id); END IF;
 PERFORM set_config('pos.direct_combo_snapshot',COALESCE(snapshot,'{}')::text,true);
 PERFORM set_config('pos.direct_line_snapshots',COALESCE(line_snapshots,'{}')::text,true);
 result:=public.direct_order_approve_payment_before_combo(p_store_id,p_request_id,p_confirmed_amount,p_confirmed_bank_reference);
 IF NOT already_approved THEN PERFORM public.direct_order_deduct_combo_stock(p_store_id,p_request_id); END IF;
 PERFORM set_config('pos.direct_line_snapshots',COALESCE(previous_lines,''),true);
 PERFORM set_config('pos.direct_combo_snapshot',COALESCE(previous_snapshot,''),true);
 PERFORM public.store_preparation_seed(ARRAY(SELECT order_id FROM public.direct_order_financials WHERE request_id=p_request_id));
 RETURN result;
EXCEPTION WHEN OTHERS THEN
 PERFORM set_config('pos.direct_line_snapshots',COALESCE(previous_lines,''),true);
 PERFORM set_config('pos.direct_combo_snapshot',COALESCE(previous_snapshot,''),true); RAISE;
END $$;


DO $verify$ BEGIN
 IF has_table_privilege('authenticated','public.store_preparation_steps','SELECT')
 OR has_function_privilege('anon','public.store_preparation_progress_v1(uuid,uuid,text,jsonb)','EXECUTE')
 OR has_function_privilege('authenticated','public.store_preparation_seed(uuid[])','EXECUTE')
 OR NOT has_function_privilege('authenticated','public.store_preparation_snapshot_v1(uuid,timestamptz,uuid,boolean)','EXECUTE')
 THEN RAISE EXCEPTION 'WORKFLOW_PREPARATION_CONTRACT_INVALID'; END IF;
END $verify$;

-- COMPONENT 20261021192000_workflow_order_mutations.sql
-- Set-based movement preserves immutable choices and every kitchen stage.
-- production-gate: self-verifying

CREATE OR REPLACE FUNCTION "public"."cashier_item_progress"("p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
 SELECT jsonb_build_object('base',COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.id) FROM public.emergency_fulfillment_items t WHERE order_item_id=$1),'[]'::jsonb),
 'combo',COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.id) FROM public.emergency_combo_component_items t WHERE order_item_id=$1),'[]'::jsonb),
 'direct',COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.id) FROM public.emergency_floor_direct_items t WHERE order_item_id=$1),'[]'::jsonb),
 'floor_lots',COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.id) FROM public.emergency_floor_ready_lots t WHERE order_item_id=$1),'[]'::jsonb),
 'preparation',COALESCE((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM public.store_preparation_steps s JOIN public.store_preparation_tasks t ON t.id=s.task_id WHERE t.order_item_id=$1),'[]'::jsonb),
 'tray_lots',COALESCE((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.id) FROM public.emergency_tray_ready_lots t WHERE order_item_id=$1),'[]'::jsonb));
$_$;


CREATE OR REPLACE FUNCTION "public"."cashier_restore_item_quantity"("p_store_id" "uuid", "p_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $_$
DECLARE operation public.cashier_item_operations%ROWTYPE; item public.order_items%ROWTYPE; kind text; table_name text; row jsonb; assignments text;
BEGIN
 PERFORM public.cashier_require_item_actor(p_store_id);
 SELECT op.* INTO operation FROM public.cashier_item_operations op WHERE op.id=p_operation_id AND op.restaurant_id=p_store_id AND op.kind='partial_cancel';
 IF NOT FOUND THEN RAISE EXCEPTION 'CANCELLATION_NOT_FOUND'; END IF;
 PERFORM 1 FROM public.orders WHERE id=operation.order_id FOR UPDATE; PERFORM public.cashier_assert_unpaid(operation.order_id,p_store_id);
 IF EXISTS(SELECT 1 FROM public.order_cancellation_reversals WHERE cancellation_ledger_id=operation.ledger_id) THEN RETURN operation.response||jsonb_build_object('restored',true); END IF;
 SELECT * INTO item FROM public.order_items WHERE id=(operation.payload->>'item_id')::uuid FOR UPDATE;
 PERFORM 1 FROM public.emergency_fulfillment_items WHERE order_item_id=item.id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.emergency_combo_component_items WHERE order_item_id=item.id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.emergency_floor_direct_items WHERE order_item_id=item.id ORDER BY id FOR UPDATE;
 IF item.order_id<>operation.order_id OR item.quantity<>(operation.payload->>'new_quantity')::integer OR item.status='cancelled' OR public.cashier_item_progress(item.id)<>operation.after_progress THEN RAISE EXCEPTION 'CASHIER_ITEM_CHANGED'; END IF;
 PERFORM set_config('globos.cashier_item_mutation','on',true);
 PERFORM 1 FROM public.store_preparation_steps s JOIN public.store_preparation_tasks t ON t.id=s.task_id WHERE t.order_item_id=item.id ORDER BY s.id FOR UPDATE;
 UPDATE public.order_items SET quantity=(operation.payload->>'expected_quantity')::integer,billing_cancelled_quantity=billing_cancelled_quantity-((operation.payload->>'expected_quantity')::integer-item.quantity),
  cancelled_consumed_quantity=(SELECT (item_snapshot->0->>'cancelled_consumed_quantity')::integer FROM public.order_cancellation_ledger WHERE id=operation.ledger_id),
  paying_amount_inc_tax=(SELECT (item_snapshot->0->>'before_paying_amount_inc_tax')::numeric FROM public.order_cancellation_ledger WHERE id=operation.ledger_id),vat_amount=(SELECT (item_snapshot->0->>'vat_amount')::numeric FROM public.order_cancellation_ledger WHERE id=operation.ledger_id),total_amount_ex_tax=(SELECT (item_snapshot->0->>'total_amount_ex_tax')::numeric FROM public.order_cancellation_ledger WHERE id=operation.ledger_id),combo_components=(SELECT item_snapshot->0->'combo_components' FROM public.order_cancellation_ledger WHERE id=operation.ledger_id) WHERE id=item.id;
 FOREACH kind IN ARRAY ARRAY['base','combo','direct','floor_lots','tray_lots'] LOOP
  table_name:=CASE kind WHEN 'base' THEN 'emergency_fulfillment_items' WHEN 'combo' THEN 'emergency_combo_component_items' WHEN 'direct' THEN 'emergency_floor_direct_items' WHEN 'floor_lots' THEN 'emergency_floor_ready_lots' ELSE 'emergency_tray_ready_lots' END;
  SELECT string_agg(format('%I=x.%I',a.attname,a.attname),',') INTO assignments FROM pg_attribute a WHERE a.attrelid=('public.'||table_name)::regclass AND a.attnum>0 AND NOT a.attisdropped AND a.attname<>'id';
  EXECUTE format('UPDATE public.%I t SET %s FROM jsonb_populate_recordset(NULL::public.%I,$1) x WHERE t.id=x.id',table_name,assignments,table_name) USING operation.before_progress->kind;

 END LOOP;
 UPDATE public.store_preparation_steps s SET started=x.started,done=x.done,revision=greatest(s.revision,x.revision)+1,started_at=x.started_at,done_at=x.done_at,updated_by=x.updated_by
 FROM jsonb_populate_recordset(NULL::public.store_preparation_steps,coalesce(operation.before_progress->'preparation','[]'))x WHERE s.id=x.id;
 PERFORM set_config('globos.cashier_item_mutation','off',true);
 INSERT INTO public.order_cancellation_reversals(cancellation_ledger_id,restaurant_id,order_id,order_item_id,restored_by) VALUES(operation.ledger_id,p_store_id,operation.order_id,item.id,auth.uid());
 PERFORM public.void_active_order_discount_for_item_change(item.order_id,p_store_id,'order_items_changed'); PERFORM public.recalc_order_status(item.order_id);
 PERFORM public.cashier_invalidate_changed_display(p_store_id,ARRAY[item.order_id]);
 PERFORM public.store_workflow_notify(p_store_id);
 RETURN operation.response||jsonb_build_object('restored',true);
END;
$_$;


CREATE OR REPLACE FUNCTION "public"."cashier_move_order_items"("p_store_id" "uuid", "p_source_order_id" "uuid", "p_target_table_id" "uuid", "p_items" "jsonb", "p_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $_$
DECLARE old public.cashier_item_operations%ROWTYPE; source public.orders%ROWTYPE; target public.orders%ROWTYPE; target_table public.tables%ROWTYPE;
 payload jsonb; response jsonb; table_name text; assignments text; kind text; key text; lot_table text; moved_ids jsonb:='[]'::jsonb;
BEGIN
 PERFORM public.cashier_require_item_actor(p_store_id);
 IF p_operation_id IS NULL OR p_target_table_id IS NULL OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'CASHIER_MOVE_INPUT_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_to_recordset(p_items) x(item_id uuid,quantity integer,expected_quantity integer) WHERE item_id IS NULL OR quantity IS NULL OR quantity<1 OR expected_quantity IS NULL OR expected_quantity<quantity) OR EXISTS(SELECT 1 FROM jsonb_to_recordset(p_items) x(item_id uuid) GROUP BY item_id HAVING count(*)>1) THEN RAISE EXCEPTION 'CASHIER_MOVE_INPUT_INVALID'; END IF;
 payload:=jsonb_build_object('source_order_id',p_source_order_id,'target_table_id',p_target_table_id,'items',p_items);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_operation_id::text,0));
 SELECT * INTO old FROM public.cashier_item_operations WHERE id=p_operation_id;
 IF FOUND THEN IF old.restaurant_id<>p_store_id OR old.kind<>'move' OR old.payload<>payload THEN RAISE EXCEPTION 'CASHIER_OPERATION_CHANGED'; END IF; RETURN old.response; END IF;
 SELECT * INTO source FROM public.orders WHERE id=p_source_order_id AND restaurant_id=p_store_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND'; END IF;
 IF source.table_id IS NULL OR source.table_id=p_target_table_id OR source.order_purpose<>'customer' OR source.sales_channel<>'dine_in' THEN RAISE EXCEPTION 'CASHIER_MOVE_INPUT_INVALID'; END IF;
 PERFORM 1 FROM public.tables WHERE id IN (source.table_id,p_target_table_id) AND restaurant_id=p_store_id ORDER BY id FOR UPDATE;
 SELECT * INTO target_table FROM public.tables WHERE id=p_target_table_id AND restaurant_id=p_store_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'TABLE_NOT_FOUND'; END IF;
 IF (SELECT count(*) FROM public.orders WHERE table_id=p_target_table_id AND restaurant_id=p_store_id AND status NOT IN ('completed','cancelled'))>1 THEN RAISE EXCEPTION 'CASHIER_TARGET_ORDER_AMBIGUOUS'; END IF;
 SELECT * INTO target FROM public.orders WHERE table_id=p_target_table_id AND restaurant_id=p_store_id AND status NOT IN ('completed','cancelled');
 PERFORM 1 FROM public.orders WHERE id IN (source.id,target.id) ORDER BY id FOR UPDATE NOWAIT;
 IF source.table_id IS DISTINCT FROM (SELECT table_id FROM public.orders WHERE id=source.id) THEN RAISE EXCEPTION 'CASHIER_ITEM_CHANGED'; END IF;
 PERFORM public.cashier_assert_unpaid(source.id,p_store_id);
 IF target.id IS NOT NULL THEN
  PERFORM public.cashier_assert_unpaid(target.id,p_store_id);
  IF target.order_purpose<>source.order_purpose OR target.fulfillment_mode_snapshot<>source.fulfillment_mode_snapshot OR target.sales_channel<>source.sales_channel OR target.operating_release_id IS DISTINCT FROM source.operating_release_id THEN RAISE EXCEPTION 'CASHIER_TARGET_INCOMPATIBLE'; END IF;
 ELSE
  INSERT INTO public.orders(restaurant_id,table_id,sales_channel,status,guest_count,created_by,notes,order_source,order_purpose,fulfillment_mode_snapshot)
  VALUES(p_store_id,p_target_table_id,source.sales_channel,'confirmed',source.guest_count,auth.uid(),source.notes,source.order_source,source.order_purpose,source.fulfillment_mode_snapshot) RETURNING * INTO target;
 END IF;
 PERFORM 1 FROM public.order_items i JOIN jsonb_to_recordset(p_items) x(item_id uuid) ON x.item_id=i.id WHERE i.order_id=source.id ORDER BY i.id FOR UPDATE OF i;
 PERFORM s.id FROM public.store_preparation_steps s JOIN public.store_preparation_tasks t ON t.id=s.task_id WHERE t.order_id IN (source.id,target.id) ORDER BY s.id FOR UPDATE;
 PERFORM 1 FROM public.emergency_fulfillment_items WHERE order_id IN (source.id,target.id) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.emergency_combo_component_items WHERE order_id IN (source.id,target.id) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.emergency_floor_direct_items WHERE order_id IN (source.id,target.id) ORDER BY id FOR UPDATE;
 PERFORM set_config('globos.cashier_item_mutation','on',true);

 DROP TABLE IF EXISTS pg_temp.workflow_move_map;
 CREATE TEMP TABLE workflow_move_map ON COMMIT DROP AS
 SELECT i.id source_item_id,CASE WHEN x.quantity=i.quantity THEN i.id ELSE gen_random_uuid() END target_item_id,
  x.quantity move_count,i.quantity original_count,to_jsonb(i) original
 FROM public.order_items i JOIN jsonb_to_recordset(p_items)x(item_id uuid,quantity integer,expected_quantity integer) ON x.item_id=i.id
 WHERE i.order_id=source.id AND i.restaurant_id=p_store_id AND i.quantity=x.expected_quantity AND i.item_type='menu_item' AND i.status<>'cancelled' AND x.quantity<=i.quantity;
 IF (SELECT count(*) FROM pg_temp.workflow_move_map)<>jsonb_array_length(p_items) THEN RAISE EXCEPTION 'CASHIER_ITEM_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM pg_temp.workflow_move_map WHERE move_count<original_count AND (original->>'billing_cancelled_quantity')::integer>0) THEN RAISE EXCEPTION 'CASHIER_MOVE_CANCELLED_SPLIT'; END IF;
 ALTER TABLE pg_temp.workflow_move_map ADD COLUMN copied jsonb;
 UPDATE pg_temp.workflow_move_map m SET copied=original||jsonb_build_object('id',target_item_id,'order_id',target.id,'quantity',move_count,
  'paying_amount_inc_tax',round((original->>'paying_amount_inc_tax')::numeric*move_count/original_count,2),
  'vat_amount',round((original->>'vat_amount')::numeric*move_count/original_count,2),
  'total_amount_ex_tax',round((original->>'total_amount_ex_tax')::numeric*move_count/original_count,2),
  'combo_components',coalesce((SELECT jsonb_agg(CASE WHEN coalesce((c->>'is_total_quantity')::boolean,false) THEN jsonb_set(c,'{quantity}',to_jsonb((c->>'quantity')::integer*move_count/original_count)) ELSE c END) FROM jsonb_array_elements(coalesce(original->'combo_components','[]'))c),'[]'::jsonb));
 INSERT INTO public.order_items SELECT (jsonb_populate_record(NULL::public.order_items,copied)).* FROM pg_temp.workflow_move_map WHERE move_count<original_count;
 UPDATE public.order_items i SET order_id=CASE WHEN m.move_count=m.original_count THEN target.id ELSE source.id END,
  quantity=CASE WHEN m.move_count=m.original_count THEN i.quantity ELSE i.quantity-m.move_count END,
  paying_amount_inc_tax=CASE WHEN m.move_count=m.original_count THEN i.paying_amount_inc_tax ELSE i.paying_amount_inc_tax-(m.copied->>'paying_amount_inc_tax')::numeric END,
  vat_amount=CASE WHEN m.move_count=m.original_count THEN i.vat_amount ELSE i.vat_amount-(m.copied->>'vat_amount')::numeric END,
  total_amount_ex_tax=CASE WHEN m.move_count=m.original_count THEN i.total_amount_ex_tax ELSE i.total_amount_ex_tax-(m.copied->>'total_amount_ex_tax')::numeric END,
  combo_components=CASE WHEN m.move_count=m.original_count THEN i.combo_components ELSE coalesce((SELECT jsonb_agg(CASE WHEN coalesce((c->>'is_total_quantity')::boolean,false) THEN jsonb_set(c,'{quantity}',to_jsonb((c->>'quantity')::integer*(m.original_count-m.move_count)/m.original_count)) ELSE c END) FROM jsonb_array_elements(coalesce(m.original->'combo_components','[]'))c),'[]'::jsonb) END
 FROM pg_temp.workflow_move_map m WHERE i.id=m.source_item_id;
 -- Queue allocation is serialized per session, independent of item count.
 PERFORM sess.id FROM public.emergency_fulfillment_sessions sess WHERE sess.id IN(SELECT session_id FROM public.emergency_order_queue WHERE order_id=source.id) ORDER BY sess.id FOR UPDATE;
 INSERT INTO public.emergency_order_queue(session_id,restaurant_id,order_id,queue_no,table_number,floor_label,workflow_version,created_at)
 SELECT q.session_id,p_store_id,target.id,coalesce((SELECT max(queue_no)+1 FROM public.emergency_order_queue WHERE session_id=q.session_id),1),target_table.table_number,
  public.emergency_floor_label(p_store_id,target_table.floor_label,target_table.table_number),q.workflow_version,q.created_at
 FROM public.emergency_order_queue q WHERE q.order_id=source.id AND NOT EXISTS(SELECT 1 FROM public.emergency_order_queue x WHERE x.session_id=q.session_id AND x.order_id=target.id);
 FOREACH table_name IN ARRAY ARRAY['emergency_fulfillment_items','emergency_combo_component_items','emergency_floor_direct_items'] LOOP
  kind:=CASE table_name WHEN 'emergency_fulfillment_items' THEN 'base' WHEN 'emergency_combo_component_items' THEN 'combo_component' ELSE 'floor_direct' END;
  DROP TABLE IF EXISTS pg_temp.workflow_progress_map;
  EXECUTE format('CREATE TEMP TABLE workflow_progress_map ON COMMIT DROP AS SELECT to_jsonb(p) original,m.target_item_id,m.move_count,m.original_count,CASE WHEN m.move_count=m.original_count THEN p.id ELSE gen_random_uuid() END new_id,q.id target_queue,(p.source_quantity*m.move_count/m.original_count)::integer units FROM public.%I p JOIN pg_temp.workflow_move_map m ON m.source_item_id=p.order_item_id JOIN public.emergency_order_queue q ON q.session_id=p.session_id AND q.order_id=$1',table_name) USING target.id;
  IF EXISTS(SELECT 1 FROM pg_temp.workflow_progress_map WHERE move_count<original_count AND ((original->>'source_quantity')::integer%original_count<>0 OR (original->>'excused_quantity')::integer>0 OR (original->>'is_cancelled')::boolean OR (original->>'needs_review')::boolean)) THEN RAISE EXCEPTION 'CASHIER_COMBO_QUANTITY_CHANGED'; END IF;
  ALTER TABLE pg_temp.workflow_progress_map ADD COLUMN copied jsonb;
  UPDATE pg_temp.workflow_progress_map m SET copied=original||jsonb_build_object('id',new_id,'order_item_id',target_item_id,'order_id',target.id,'queue_id',target_queue,'source_quantity',units,'ordered_quantity',CASE WHEN move_count=original_count THEN (original->>'ordered_quantity')::integer ELSE units END)||
   coalesce((SELECT jsonb_object_agg(k,least(units,(original->>k)::integer)) FROM unnest(ARRAY['kitchen_started_quantity','kitchen_done_quantity','tray_received_quantity','tray_dispatched_quantity','floor_served_quantity','excused_quantity'])k WHERE original ? k AND move_count<original_count),'{}');
  UPDATE pg_temp.workflow_progress_map m SET original=CASE WHEN move_count=original_count THEN copied ELSE original||jsonb_build_object('source_quantity',(original->>'source_quantity')::integer-units,'ordered_quantity',(original->>'ordered_quantity')::integer-units)||
   coalesce((SELECT jsonb_object_agg(k,(original->>k)::integer-(copied->>k)::integer) FROM unnest(ARRAY['kitchen_started_quantity','kitchen_done_quantity','tray_received_quantity','tray_dispatched_quantity','floor_served_quantity','excused_quantity'])k WHERE original ? k),'{}') END;
  SELECT string_agg(format('%I=x.%I',a.attname,a.attname),',') INTO assignments FROM pg_attribute a WHERE a.attrelid=('public.'||table_name)::regclass AND a.attnum>0 AND NOT a.attisdropped AND a.attname<>'id';
  EXECUTE format('UPDATE public.%I t SET %s FROM (SELECT (jsonb_populate_record(NULL::public.%I,original)).* FROM pg_temp.workflow_progress_map)x WHERE t.id=x.id',table_name,assignments,table_name);
  EXECUTE format('INSERT INTO public.%I SELECT (jsonb_populate_record(NULL::public.%I,copied)).* FROM pg_temp.workflow_progress_map WHERE move_count<original_count',table_name,table_name);
  -- Each split retains per-stage counters, timers and actor, with an auditable task lineage.
  DROP TABLE IF EXISTS pg_temp.workflow_task_map;
  CREATE TEMP TABLE workflow_task_map ON COMMIT DROP AS SELECT t.id old_id,gen_random_uuid() new_id,m.new_id source_id,m.target_item_id,m.units,t.restaurant_id,t.release_id,t.source_kind,t.menu_item_id,t.ticket_id,t.created_at FROM public.store_preparation_tasks t JOIN pg_temp.workflow_progress_map m ON t.source_id=(m.original->>'id')::uuid AND t.source_kind=kind WHERE m.move_count<m.original_count;
  INSERT INTO public.store_preparation_tasks(id,restaurant_id,release_id,order_id,order_item_id,source_kind,source_id,menu_item_id,ticket_id,created_at)
   SELECT new_id,restaurant_id,release_id,target.id,target_item_id,source_kind,source_id,menu_item_id,ticket_id,created_at FROM pg_temp.workflow_task_map;
  INSERT INTO public.store_preparation_steps(restaurant_id,task_id,station_id,position,started,done,revision,started_at,done_at,updated_by)
   SELECT s.restaurant_id,m.new_id,s.station_id,s.position,least(m.units,s.started),least(m.units,s.done),s.revision,s.started_at,s.done_at,s.updated_by FROM pg_temp.workflow_task_map m JOIN public.store_preparation_steps s ON s.task_id=m.old_id;
  UPDATE public.store_preparation_steps s SET started=s.started-least(m.units,s.started),done=s.done-least(m.units,s.done),revision=s.revision+1 FROM pg_temp.workflow_task_map m WHERE s.task_id=m.old_id;
  UPDATE public.store_preparation_tasks t SET order_id=target.id FROM pg_temp.workflow_progress_map m WHERE m.move_count=m.original_count AND t.source_id=(m.original->>'id')::uuid AND t.source_kind=kind;
  FOREACH lot_table IN ARRAY ARRAY['emergency_floor_ready_lots','emergency_tray_ready_lots'] LOOP
   key:=CASE lot_table WHEN 'emergency_floor_ready_lots' THEN 'served_quantity' ELSE 'handed_quantity' END;
   DROP TABLE IF EXISTS pg_temp.workflow_lot_map;
   EXECUTE format('CREATE TEMP TABLE workflow_lot_map ON COMMIT DROP AS WITH fifo AS (SELECT l.*,m.new_id,m.target_item_id,m.target_queue,m.move_count=m.original_count whole,coalesce((m.copied->>$1)::integer,0) capacity,coalesce(sum(l.ready_quantity-l.voided_quantity) OVER(PARTITION BY l.source_id ORDER BY l.ready_sequence,l.id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) prior FROM public.%I l JOIN pg_temp.workflow_progress_map m ON l.source_id=(m.original->>''id'')::uuid) SELECT id,to_jsonb(fifo)-ARRAY[''new_id'',''target_item_id'',''target_queue'',''whole'',''capacity'',''prior''] original,new_id,target_item_id,target_queue,CASE WHEN whole THEN ready_quantity ELSE greatest(0,least(ready_quantity-voided_quantity,capacity-prior))::integer END take FROM fifo',lot_table) USING CASE lot_table WHEN 'emergency_floor_ready_lots' THEN 'tray_dispatched_quantity' ELSE 'kitchen_done_quantity' END;
   ALTER TABLE pg_temp.workflow_lot_map ADD COLUMN copied jsonb;
   UPDATE pg_temp.workflow_lot_map m SET copied=original||jsonb_build_object('id',CASE WHEN take=(original->>'ready_quantity')::integer THEN m.id ELSE gen_random_uuid() END,'order_id',target.id,'order_item_id',target_item_id,'queue_id',target_queue,'source_id',new_id,'ready_quantity',take,'voided_quantity',CASE WHEN take=(original->>'ready_quantity')::integer THEN (original->>'voided_quantity')::integer ELSE 0 END,key,least(take,(original->>key)::integer)) WHERE take>0;
   SELECT string_agg(format('%I=x.%I',a.attname,a.attname),',') INTO assignments FROM pg_attribute a WHERE a.attrelid=('public.'||lot_table)::regclass AND a.attnum>0 AND NOT a.attisdropped AND a.attname<>'id';
   EXECUTE format('UPDATE public.%I t SET %s FROM (SELECT (jsonb_populate_record(NULL::public.%I,copied)).* FROM pg_temp.workflow_lot_map WHERE take=(original->>''ready_quantity'')::integer)x WHERE t.id=x.id',lot_table,assignments,lot_table);
   EXECUTE format('UPDATE public.%I t SET ready_quantity=t.ready_quantity-m.take,%I=t.%I-least(m.take,(m.original->>$1)::integer) FROM pg_temp.workflow_lot_map m WHERE t.id=m.id AND m.take>0 AND m.take<(m.original->>''ready_quantity'')::integer',lot_table,key,key) USING key;
   EXECUTE format('INSERT INTO public.%I SELECT (jsonb_populate_record(NULL::public.%I,copied)).* FROM pg_temp.workflow_lot_map WHERE take>0 AND take<(original->>''ready_quantity'')::integer',lot_table,lot_table);
  END LOOP;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_object('source_item_id',source_item_id,'target_item_id',target_item_id,'quantity',move_count) ORDER BY source_item_id) INTO moved_ids FROM pg_temp.workflow_move_map;
 PERFORM set_config('globos.cashier_item_mutation','off',true);
 PERFORM public.void_active_order_discount_for_item_change(source.id,p_store_id,'order_items_changed'); PERFORM public.void_active_order_discount_for_item_change(target.id,p_store_id,'order_items_changed');
 PERFORM public.recalc_order_status(source.id); PERFORM public.recalc_order_status(target.id);
 IF NOT EXISTS(SELECT 1 FROM public.order_items WHERE order_id=source.id AND status<>'cancelled' AND item_type='menu_item') THEN UPDATE public.orders SET status='cancelled',updated_at=now() WHERE id=source.id; END IF;
 UPDATE public.tables SET status='occupied',updated_at=now() WHERE id=p_target_table_id;
 UPDATE public.tables SET status='available',updated_at=now() WHERE id=source.table_id AND NOT EXISTS(SELECT 1 FROM public.orders WHERE table_id=source.table_id AND status NOT IN ('completed','cancelled'));
 PERFORM public.cashier_invalidate_changed_display(p_store_id,ARRAY[source.id,target.id]);
 PERFORM public.store_workflow_notify(p_store_id);
 response:=jsonb_build_object('source_order_id',source.id,'target_order_id',target.id,'target_table_id',p_target_table_id,'moved',moved_ids,'operation_id',p_operation_id,'discount_review_required',true);
 INSERT INTO public.cashier_item_operations(id,restaurant_id,order_id,kind,payload,response,created_by) VALUES(p_operation_id,p_store_id,source.id,'move',payload,response,auth.uid());
 INSERT INTO public.audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(auth.uid(),'cashier_move_order_items','orders',source.id,response);
 RETURN response;
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'CASHIER_ITEM_CHANGED';
END;
$_$;


CREATE FUNCTION public.store_preparation_reconcile_items() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF current_setting('globos.cashier_item_mutation',true)='on' THEN RETURN NULL; END IF;
 UPDATE public.store_preparation_steps s SET started=least(s.started,src.quantity),done=least(s.done,src.quantity),revision=s.revision+1
 FROM public.store_preparation_tasks t JOIN public.store_preparation_sources src ON src.source_id=t.source_id AND src.source_kind=t.source_kind
 JOIN changed_workflow_items i ON i.id=t.order_item_id
 WHERE s.task_id=t.id AND NOT src.blocked AND (s.started>src.quantity OR s.done>src.quantity);
 RETURN NULL;
END;
$$;
CREATE TRIGGER zzzz_workflow_reconcile AFTER UPDATE ON public.order_items REFERENCING NEW TABLE AS changed_workflow_items FOR EACH STATEMENT EXECUTE FUNCTION public.store_preparation_reconcile_items();
REVOKE ALL ON FUNCTION public.store_preparation_reconcile_items() FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.cashier_partial_progress_sync() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE table_name text; lot_table text; used text; quantities jsonb; changes text;
BEGIN
 IF NEW.billing_cancelled_quantity=0 OR NEW.status='cancelled' OR current_setting('globos.cashier_item_mutation',true)='on' THEN RETURN NEW; END IF;
 IF NEW.menu_option_snapshot IS DISTINCT FROM OLD.menu_option_snapshot AND (to_jsonb(NEW)-'menu_option_snapshot')=(to_jsonb(OLD)-'menu_option_snapshot') THEN RETURN NEW; END IF;
 FOREACH table_name IN ARRAY ARRAY['emergency_fulfillment_items','emergency_combo_component_items','emergency_floor_direct_items'] LOOP
  changes:=CASE WHEN table_name='emergency_floor_direct_items' THEN '' ELSE ',kitchen_started_quantity=least(t.kitchen_started_quantity,x.required),kitchen_done_quantity=least(t.kitchen_done_quantity,x.required),tray_received_quantity=least(t.tray_received_quantity,x.required),tray_dispatched_quantity=least(t.tray_dispatched_quantity,x.required)' END;
  EXECUTE format($q$
   WITH lines AS MATERIALIZED(SELECT t.*,to_jsonb(t) data,CASE WHEN $2='emergency_fulfillment_items' OR to_jsonb(t)->>'line_key'='base' THEN 1 ELSE greatest(1,t.ordered_quantity::numeric/($3+$4)) END ratio
    FROM public.%I t WHERE order_item_id=$1 FOR UPDATE),
   counted AS (SELECT l.*,CASE WHEN $2='emergency_combo_component_items' OR $2='emergency_floor_direct_items' AND data->>'line_key'<>'base'
    THEN coalesce((SELECT CASE WHEN coalesce((c->>'is_total_quantity')::boolean,false) THEN (c->>'quantity')::integer ELSE (c->>'quantity')::integer*$3 END FROM jsonb_array_elements(coalesce($5,'[]'))c WHERE c->>'menu_item_id'=data->>'component_menu_item_id'),0)
    ELSE ceil($3*ratio)::integer END needed FROM lines l),
   computed AS(SELECT id,greatest(1,needed) source,greatest(ordered_quantity,ceil(($3+$4)*ratio)::integer) ordered,greatest(needed,floor_served_quantity) required,needed>0 active FROM counted),
   updated AS(UPDATE public.%I t SET source_quantity=x.source,ordered_quantity=x.ordered,excused_quantity=x.ordered-x.required,needs_review=false,is_cancelled=NOT x.active,updated_at=now()%s FROM computed x WHERE t.id=x.id RETURNING t.*)
   SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'floor',greatest(0,coalesce((to_jsonb(updated)->>'tray_dispatched_quantity')::integer,0)-floor_served_quantity),'tray',greatest(0,coalesce((to_jsonb(updated)->>'kitchen_done_quantity')::integer,0)-coalesce((to_jsonb(updated)->>'tray_dispatched_quantity')::integer,0)))),'[]') FROM updated
  $q$,table_name,table_name,changes) INTO quantities USING NEW.id,table_name,NEW.quantity,NEW.billing_cancelled_quantity,NEW.combo_components;
  IF table_name='emergency_floor_direct_items' THEN CONTINUE; END IF;
  FOREACH lot_table IN ARRAY ARRAY['emergency_floor_ready_lots','emergency_tray_ready_lots'] LOOP
   used:=CASE lot_table WHEN 'emergency_floor_ready_lots' THEN 'served_quantity' ELSE 'handed_quantity' END;
   EXECUTE format($q$
    WITH lots AS MATERIALIZED(SELECT l.id,l.source_id,l.ready_sequence,l.ready_quantity-l.%I-l.voided_quantity remaining,coalesce((q->>$2)::integer,0) allowed
     FROM public.%I l JOIN jsonb_array_elements($1)q ON (q->>'id')::uuid=l.source_id FOR UPDATE OF l),
    allocations AS(SELECT id,remaining,greatest(0,sum(remaining)OVER(PARTITION BY source_id)-allowed) excess,
     coalesce(sum(remaining)OVER(PARTITION BY source_id ORDER BY ready_sequence DESC,id DESC ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) prior FROM lots)
    UPDATE public.%I l SET voided_quantity=l.voided_quantity+greatest(0,least(a.remaining,a.excess-a.prior))::integer,updated_at=now() FROM allocations a WHERE l.id=a.id AND a.excess>a.prior AND a.remaining>0
   $q$,used,lot_table,lot_table) USING quantities,CASE lot_table WHEN 'emergency_floor_ready_lots' THEN 'floor' ELSE 'tray' END;
  END LOOP;
 END LOOP;
 RETURN NEW;
END;
$$;

DO $verify$ BEGIN
 IF strpos(pg_get_functiondef('public.cashier_move_order_items(uuid,uuid,uuid,jsonb,uuid)'::regprocedure),'store_preparation_steps')=0
 OR strpos(pg_get_functiondef('public.cashier_restore_item_quantity(uuid,uuid)'::regprocedure),'store_preparation_steps')=0
 OR has_function_privilege('authenticated','public.store_preparation_reconcile_items()','EXECUTE')
 THEN RAISE EXCEPTION 'WORKFLOW_MUTATION_CONTRACT_INVALID'; END IF;
END $verify$;

-- COMPONENT 20261021193000_workflow_client_scope.sql
-- Scoped discovery retains legacy snapshots only for stores that have not switched.
-- production-gate: self-verifying

CREATE OR REPLACE FUNCTION public.get_emergency_station_snapshot() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE payload jsonb; workflow jsonb;
BEGIN
 payload:=public.get_emergency_station_snapshot_pre_direct();
 IF payload->>'restaurant_id' IS NOT NULL THEN
  workflow:=public.store_workflow_device_v1((payload->>'restaurant_id')::uuid);
  payload:=payload||jsonb_build_object('operating_workflow',workflow);
  IF workflow->>'active_id' IS NOT NULL AND payload->>'station_type'='kitchen' THEN
   payload:=payload||jsonb_build_object('orders','[]'::jsonb,'completed_orders','[]'::jsonb);
   IF workflow->'station'->>'id' IS DISTINCT FROM (SELECT coalesce(r.definition->>'packaging_station_id',r.definition->'default_path'->>0) FROM public.store_workflow_releases r WHERE r.id=(workflow->>'active_id')::uuid) THEN payload:=payload||jsonb_build_object('leftover_packaging_tasks','[]'::jsonb); END IF;
  END IF;
 END IF;
 RETURN payload||jsonb_build_object('kitchen_direct_to_floor',public.kds_uses_direct_floor_workflow((payload->>'restaurant_id')::uuid));
END;
$$;
CREATE FUNCTION public.store_workflow_notify(p_store_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE station record;
BEGIN
 -- At most eight station invalidations, independent of the number of order lines.
 FOR station IN SELECT c.active_id,s->>'id' id FROM public.store_workflow_configs c JOIN public.store_workflow_releases r ON r.id=c.active_id,jsonb_array_elements(r.definition->'stations')s WHERE c.restaurant_id=p_store_id LOOP
  PERFORM realtime.send(jsonb_build_object('release_id',station.active_id),'changed','workflow:'||p_store_id||':'||station.id||':'||station.active_id,true);
 END LOOP;
END;
$$;
-- Coalesce preparation readiness into at most one event per affected station and
-- session, then reuse the existing push delivery/lease/dispatch infrastructure.
CREATE FUNCTION public.store_preparation_ready_notify(p_order_ids uuid[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 WITH ready AS MATERIALIZED (
  SELECT t.restaurant_id,t.release_id,t.order_id,s.station_id,q.session_id,s.id,coalesce(prev.done,src.quantity)-s.started quantity
  FROM public.store_preparation_tasks t JOIN public.store_preparation_steps s ON s.task_id=t.id
  JOIN public.store_preparation_sources src ON src.source_id=t.source_id AND src.source_kind=t.source_kind
  JOIN public.emergency_order_queue q ON q.id=src.queue_id
  LEFT JOIN public.store_preparation_steps prev ON prev.task_id=t.id AND prev.position=s.position-1
  WHERE t.order_id=ANY(p_order_ids) AND NOT src.blocked AND coalesce(prev.done,src.quantity)>s.started
 ), grouped AS (
  SELECT restaurant_id,release_id,station_id,session_id,(array_agg(order_id ORDER BY order_id))[1] order_id,
   sum(quantity)::integer quantity,md5(station_id::text||jsonb_agg(jsonb_build_array(id,quantity) ORDER BY id)::text)::uuid event_id
  FROM ready GROUP BY restaurant_id,release_id,station_id,session_id
 ), added AS (
  INSERT INTO public.emergency_fulfillment_events(event_id,session_id,restaurant_id,order_id,stage,delta,details)
  SELECT event_id,session_id,restaurant_id,order_id,'order_received',quantity,
   jsonb_build_object('workflow_station_id',station_id,'workflow_release_id',release_id) FROM grouped
  ON CONFLICT(event_id) DO NOTHING RETURNING *
 ) INSERT INTO public.emergency_push_deliveries(event_id,restaurant_id,device_id,push_token,station_type,floor_label,order_id,stage)
 SELECT e.event_id,e.restaurant_id,d.id,d.token,'kitchen',NULL,e.order_id,e.stage
 FROM added e JOIN public.store_workflow_releases r ON r.id=(e.details->>'workflow_release_id')::uuid,
 jsonb_array_elements(r.definition->'stations')station
 JOIN public.emergency_station_assignments a ON a.is_active AND a.station_type='kitchen' AND station->'user_ids' ? a.user_id::text
 JOIN public.emergency_web_push_devices d ON d.station_assignment_id=a.id AND d.is_enabled
 WHERE station->>'id'=e.details->>'workflow_station_id' AND a.restaurant_id=e.restaurant_id AND d.restaurant_id=e.restaurant_id
 ON CONFLICT(event_id,device_id) DO NOTHING;
 PERFORM public.store_workflow_notify(restaurant_id) FROM (SELECT DISTINCT restaurant_id FROM public.orders WHERE id=ANY(p_order_ids)) stores;
END;
$$;
REVOKE ALL ON FUNCTION public.store_preparation_ready_notify(uuid[]) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.store_workflow_settings_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF (NEW.fulfillment_mode IS DISTINCT FROM OLD.fulfillment_mode OR NEW.kds_workflow IS DISTINCT FROM OLD.kds_workflow)
 AND EXISTS(SELECT 1 FROM public.store_workflow_configs WHERE restaurant_id=NEW.restaurant_id AND active_id IS NOT NULL)
 THEN RAISE EXCEPTION 'WORKFLOW_DEACTIVATE_FIRST'; END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER workflow_settings_guard BEFORE UPDATE ON public.restaurant_settings FOR EACH ROW EXECUTE FUNCTION public.store_workflow_settings_guard();
CREATE FUNCTION public.store_workflow_assignment_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM public.store_workflow_configs c WHERE c.restaurant_id=coalesce(NEW.restaurant_id,OLD.restaurant_id) AND c.active_id IS NOT NULL)
 AND (TG_OP<>'UPDATE' OR (NEW.user_id,NEW.station_type,NEW.floor_label,NEW.is_active) IS DISTINCT FROM (OLD.user_id,OLD.station_type,OLD.floor_label,OLD.is_active))
 THEN RAISE EXCEPTION 'WORKFLOW_DEACTIVATE_FIRST'; END IF;
 RETURN coalesce(NEW,OLD);
END;
$$;
CREATE TRIGGER workflow_assignment_guard BEFORE INSERT OR UPDATE OR DELETE ON public.emergency_station_assignments FOR EACH ROW EXECUTE FUNCTION public.store_workflow_assignment_guard();
REVOKE ALL ON FUNCTION public.store_workflow_notify(uuid),public.store_workflow_settings_guard(),public.store_workflow_assignment_guard() FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION "public"."kds_can_access_topic"("p_topic" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
  v_parts text[] := string_to_array(COALESCE(p_topic, ''), ':');
  v_store_id uuid;
  v_station text;
  v_floor text;
  v_assignment public.emergency_station_assignments%ROWTYPE;
BEGIN
  IF cardinality(v_parts)=4 AND v_parts[1]='workflow' THEN
   RETURN EXISTS(SELECT 1 FROM public.users u JOIN public.emergency_station_assignments a ON a.user_id=u.id AND a.is_active AND a.station_type='kitchen'
    JOIN public.store_workflow_configs c ON c.restaurant_id=a.restaurant_id AND c.active_id::text=v_parts[4]
    JOIN public.store_workflow_releases r ON r.id=c.active_id,jsonb_array_elements(r.definition->'stations')s
    WHERE u.auth_id=auth.uid() AND u.is_active AND c.restaurant_id::text=v_parts[2] AND s->>'id'=v_parts[3] AND s->'user_ids' ? u.id::text);
  END IF;
  IF cardinality(v_parts) NOT IN (3, 4) OR v_parts[1] <> 'kds' THEN
    RETURN false;
  END IF;
  BEGIN
    v_store_id := v_parts[2]::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN false;
  END;
  v_station := v_parts[3];
  v_floor := CASE WHEN cardinality(v_parts) = 4 THEN v_parts[4] END;
  IF v_station NOT IN ('kitchen', 'tray', 'floor', 'control') THEN
    RETURN false;
  END IF;

  SELECT assignment.* INTO v_assignment
  FROM public.users user_row
  JOIN public.emergency_station_assignments assignment
    ON assignment.user_id = user_row.id
   AND assignment.restaurant_id = v_store_id
   AND assignment.is_active = true
  WHERE user_row.auth_id = auth.uid()
    AND user_row.is_active = true
  LIMIT 1;
  IF NOT FOUND THEN RETURN false; END IF;

  IF v_station='kitchen' AND EXISTS(SELECT 1 FROM public.store_workflow_configs WHERE restaurant_id=v_store_id AND active_id IS NOT NULL) THEN RETURN false; END IF;
  IF v_station = 'control' THEN
    RETURN cardinality(v_parts) = 3;
  END IF;
  IF v_assignment.station_type <> v_station THEN RETURN false; END IF;
  IF v_station = 'floor' THEN
    RETURN cardinality(v_parts) = 4
      AND v_assignment.floor_label = v_floor;
  END IF;
  RETURN cardinality(v_parts) = 3;
END;
$$;

CREATE OR REPLACE FUNCTION "public"."get_kds_bootstrap_v2"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
  v_config jsonb;
  v_snapshot jsonb;
  v_completed jsonb;
  v_timings jsonb;
  v_store_id uuid;
  v_mode text;
BEGIN
  v_config := public.get_kds_sync_config();
  v_snapshot := public.get_emergency_station_snapshot();
  v_completed := public.get_emergency_station_today_completed();
  v_timings := public.get_emergency_station_timings();
  v_store_id := NULLIF(v_config->>'restaurant_id', '')::uuid;
  IF v_store_id IS NOT NULL THEN
    v_mode := public.get_store_fulfillment_mode(v_store_id);
  END IF;
  IF v_snapshot->'operating_workflow'->>'active_id' IS NOT NULL AND v_snapshot->>'station_type'='kitchen' THEN v_completed:='[]';v_timings:='[]'; END IF;
  RETURN jsonb_build_object(
    'sync', v_config,
    'snapshot', v_snapshot,
    'completed_orders', COALESCE(v_completed, '[]'::jsonb),
    'timings', COALESCE(v_timings, '[]'::jsonb),
    'fulfillment_mode', COALESCE(v_mode, 'paperless')
  );
END;
$$;

CREATE OR REPLACE FUNCTION "public"."get_kds_changes_v2"("p_after_revision" bigint, "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
  v_config jsonb;
  v_store_id uuid;
  v_station text;
  v_floor text;
  v_after bigint := GREATEST(COALESCE(p_after_revision, 0), 0);
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 200);
  v_current bigint := 0;
  v_earliest bigint;
  v_scanned bigint;
  v_changes jsonb := '[]'::jsonb;
BEGIN
  v_config := public.get_kds_sync_config();
  IF COALESCE((v_config->>'assigned')::boolean, false) = false THEN
    RAISE EXCEPTION 'EMERGENCY_STATION_REQUIRED';
  END IF;
  v_store_id := (v_config->>'restaurant_id')::uuid;
  IF v_config->>'station_type'='kitchen' AND EXISTS(SELECT 1 FROM public.store_workflow_configs WHERE restaurant_id=v_store_id AND active_id IS NOT NULL) THEN RETURN jsonb_build_object('bootstrap_required',true,'has_more',false,'changes','[]'::jsonb); END IF;
  v_station := v_config->>'station_type';
  v_floor := v_config->>'floor_label';
  v_current := COALESCE((v_config->>'revision')::bigint, 0);
  SELECT min(revision) INTO v_earliest
  FROM public.kds_change_log
  WHERE restaurant_id = v_store_id;
  IF v_earliest IS NOT NULL AND v_after < v_earliest - 1 THEN
    RETURN jsonb_build_object(
      'bootstrap_required', true,
      'scanned_through_revision', v_after,
      'current_revision', v_current,
      'has_more', false,
      'changes', '[]'::jsonb
    );
  END IF;

  WITH revision_window AS (
    SELECT change.*
    FROM public.kds_change_log change
    WHERE change.restaurant_id = v_store_id
      AND change.revision > v_after
    ORDER BY change.revision
    LIMIT v_limit
  )
  SELECT
    COALESCE(max(change_row.revision), v_after),
    COALESCE(jsonb_agg(jsonb_build_object(
      'schema_version', 1,
      'restaurant_id', change_row.restaurant_id,
      'session_id', change_row.session_id,
      'revision', change_row.revision,
      'event_id', change_row.event_id,
      'event_type', change_row.event_type,
      'target_stations', change_row.target_stations,
      'target_floor_label', change_row.target_floor_label,
      'queue_id', change_row.queue_id,
      'order_id', change_row.order_id,
      'order_item_id', change_row.order_item_id,
      'payload', change_row.payload,
      'occurred_at', change_row.created_at
    ) ORDER BY change_row.revision) FILTER (
        WHERE 'control' = ANY(change_row.target_stations)
           OR (
             v_station = ANY(change_row.target_stations)
             AND (
               v_station <> 'floor'
               OR change_row.target_floor_label IS NULL
               OR change_row.target_floor_label = v_floor
             )
           )
      ), '[]'::jsonb)
  INTO v_scanned, v_changes
  FROM revision_window change_row;

  RETURN jsonb_build_object(
    'bootstrap_required', false,
    'scanned_through_revision', v_scanned,
    'current_revision', v_current,
    'has_more', v_scanned < v_current,
    'changes', v_changes
  );
END;
$$;


CREATE FUNCTION public.store_workflow_packaging_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE usr public.users%ROWTYPE; definition jsonb;
BEGIN
 SELECT * INTO usr FROM public.users WHERE auth_id=auth.uid() AND is_active;
 IF EXISTS(SELECT 1 FROM public.store_workflow_devices WHERE user_id=usr.id AND restaurant_id=NEW.restaurant_id AND quiesced) THEN RAISE EXCEPTION 'WORKFLOW_DEVICE_QUIESCED'; END IF;
 IF EXISTS(SELECT 1 FROM public.emergency_station_assignments WHERE user_id=usr.id AND restaurant_id=NEW.restaurant_id AND station_type='kitchen' AND is_active) THEN
  SELECT r.definition INTO definition FROM public.store_workflow_configs c JOIN public.store_workflow_releases r ON r.id=c.active_id WHERE c.restaurant_id=NEW.restaurant_id;
  IF definition IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(definition->'stations')s WHERE s->>'id'=coalesce(definition->>'packaging_station_id',definition->'default_path'->>0) AND s->'user_ids' ? usr.id::text) THEN RAISE EXCEPTION 'WORKFLOW_STATION_FORBIDDEN'; END IF;
 END IF;
 RETURN NEW;
END;
$$;
CREATE TRIGGER workflow_packaging_guard BEFORE UPDATE ON public.leftover_packaging_requests FOR EACH ROW EXECUTE FUNCTION public.store_workflow_packaging_guard();
CREATE FUNCTION public.store_workflow_floor_device_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
BEGIN
 IF current_setting('globos.cashier_item_mutation',true) IN ('on','repair') THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM public.store_workflow_devices d JOIN public.users u ON u.id=d.user_id WHERE u.auth_id=auth.uid() AND d.quiesced) AND EXISTS(SELECT 1 FROM new_workflow_progress n JOIN old_workflow_progress o USING(id) WHERE n.floor_served_quantity>o.floor_served_quantity) THEN RAISE EXCEPTION 'WORKFLOW_DEVICE_QUIESCED'; END IF;
 RETURN NULL;
END;
$$;
CREATE TRIGGER workflow_floor_device_guard AFTER UPDATE ON public.emergency_floor_direct_items REFERENCING OLD TABLE AS old_workflow_progress NEW TABLE AS new_workflow_progress FOR EACH STATEMENT EXECUTE FUNCTION public.store_workflow_floor_device_guard();
REVOKE ALL ON FUNCTION public.store_workflow_packaging_guard(),public.store_workflow_floor_device_guard() FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.emergency_enqueue_push(p_event_id uuid, p_store_id uuid, p_order_id uuid, p_target_station text, p_floor_label text, p_stage text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_catalog'
AS $function$
  INSERT INTO public.emergency_push_deliveries (
    event_id, restaurant_id, device_id, push_token, station_type,
    floor_label, order_id, stage
  )
  SELECT
    p_event_id, p_store_id, device.id, device.token,
    assignment.station_type, assignment.floor_label, p_order_id, p_stage
  FROM public.emergency_web_push_devices device
  JOIN public.emergency_station_assignments assignment
    ON assignment.id = device.station_assignment_id
   AND assignment.restaurant_id = p_store_id
   AND assignment.is_active = true
  WHERE device.restaurant_id = p_store_id
    AND device.is_enabled = true
    AND assignment.station_type = p_target_station
    AND NOT (p_target_station='kitchen' AND p_stage='order_received' AND EXISTS(SELECT 1 FROM public.orders o WHERE o.id=p_order_id AND o.operating_release_id IS NOT NULL))
    AND (p_target_station <> 'floor' OR assignment.floor_label = p_floor_label)
    AND NOT (
      p_target_station = 'floor'
      AND EXISTS (
        SELECT 1 FROM public.orders order_row
        WHERE order_row.id = p_order_id
          AND (order_row.sales_channel = 'delivery'
            OR public.direct_order_is_pickup_pos_order(order_row.id, order_row.restaurant_id))
      )
    )
  ON CONFLICT (event_id, device_id) DO NOTHING;
$function$;


NOTIFY pgrst,'reload schema';
DO $verify$ BEGIN
 IF has_function_privilege('authenticated','public.store_workflow_notify(uuid)','EXECUTE')
 OR has_function_privilege('authenticated','public.store_preparation_ready_notify(uuid[])','EXECUTE')
 OR strpos(pg_get_functiondef('public.kds_can_access_topic(text)'::regprocedure),'workflow')=0
 OR strpos(pg_get_functiondef('public.get_emergency_station_snapshot()'::regprocedure),'operating_workflow')=0
 THEN RAISE EXCEPTION 'WORKFLOW_CLIENT_CONTRACT_INVALID'; END IF;
END $verify$;

-- COMPONENT 20261022090000_store_registration_areas.sql
-- Configuration-driven, restartable registration. Existing identities are immutable.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
ALTER TABLE public.store_service_areas ADD COLUMN display_name text,
 ADD COLUMN physical_floor text;
-- A NULL legacy display name reads as its existing code. Do not rewrite immutable areas.
ALTER TABLE public.store_service_areas ADD CONSTRAINT store_area_name_length CHECK(length(display_name) BETWEEN 1 AND 80),
 ADD CONSTRAINT store_area_physical_floor_length CHECK(physical_floor IS NULL OR length(physical_floor) BETWEEN 1 AND 40);

CREATE TABLE public.store_registration_requests (
 id uuid PRIMARY KEY,
 actor_id uuid NOT NULL REFERENCES public.users(id),
 code text NOT NULL UNIQUE CHECK(code ~ '^[A-Z][A-Z0-9]{1,5}$'),
 store_id uuid UNIQUE REFERENCES public.restaurants(id) ON DELETE CASCADE,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX store_registration_actor ON public.store_registration_requests(actor_id,created_at DESC);
ALTER TABLE public.store_registration_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_registration_requests FROM PUBLIC,anon,authenticated;
CREATE SEQUENCE public.store_registration_code_seq MAXVALUE 9999 NO CYCLE;
REVOKE ALL ON SEQUENCE public.store_registration_code_seq FROM PUBLIC,anon,authenticated;

CREATE TABLE public.store_registration_station_bindings (
 restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 account_code text NOT NULL,
 station_id uuid NOT NULL,
 PRIMARY KEY(restaurant_id,account_code),
 FOREIGN KEY(restaurant_id,station_id) REFERENCES public.store_service_stations(restaurant_id,id) ON DELETE CASCADE
);
ALTER TABLE public.store_registration_station_bindings ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_registration_station_bindings FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public.admin_reserve_store_code_v1(p_request_id uuid,p_code text DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE actor uuid; result text; candidate text; serial_number bigint;
BEGIN
 PERFORM public.require_brand_admin_v1();
 SELECT id INTO actor FROM users WHERE auth_id=auth.uid() AND is_active;
 IF p_request_id IS NULL THEN RAISE EXCEPTION 'REQUEST_ID_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('store-registration-code',0));
 SELECT code INTO result FROM store_registration_requests WHERE id=p_request_id AND actor_id=actor;
 IF FOUND THEN
  IF nullif(upper(btrim(p_code)),'') IS NOT NULL AND result<>upper(btrim(p_code)) THEN RAISE EXCEPTION 'REQUEST_CODE_FROZEN'; END IF;
  RETURN result;
 END IF;
 IF EXISTS(SELECT 1 FROM store_registration_requests WHERE id=p_request_id) THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
 candidate:=nullif(upper(btrim(p_code)),'');
 IF candidate IS NULL THEN
  -- One aggregate over the occupied namespace; no lookup loop per collision.
  SELECT greatest(nextval('public.store_registration_code_seq'),coalesce(max(substring(occupied.code FROM 3)::bigint),0)+1)
  INTO serial_number FROM (
   SELECT upper(short_code) code FROM restaurants WHERE upper(short_code) ~ '^ST[0-9]{4}$'
   UNION ALL SELECT r.code FROM store_registration_requests r WHERE r.code ~ '^ST[0-9]{4}$'
  ) occupied;
  IF serial_number>9999 THEN RAISE EXCEPTION 'CODE_NAMESPACE_EXHAUSTED'; END IF;
  PERFORM setval('public.store_registration_code_seq',serial_number);
  candidate:='ST'||lpad(serial_number::text,4,'0');
 END IF;
 IF candidate IS NULL THEN RAISE EXCEPTION 'CODE_ALLOCATION_RETRY'; END IF;
 IF candidate !~ '^[A-Z][A-Z0-9]{1,5}$' THEN RAISE EXCEPTION 'ABBREVIATION_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM restaurants WHERE upper(short_code)=candidate)
 OR EXISTS(SELECT 1 FROM store_registration_requests WHERE code=candidate) THEN RAISE EXCEPTION 'ABBREVIATION_EXISTS'; END IF;
 INSERT INTO store_registration_requests(id,actor_id,code) VALUES(p_request_id,actor,candidate);
 RETURN candidate;
END $$;

CREATE FUNCTION public.store_registration_config_v1(p_config jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE cfg jsonb; areas jsonb; n integer;
BEGIN
 cfg:=coalesce(p_config,'{}'::jsonb);
 IF jsonb_typeof(cfg)<>'object' OR octet_length(cfg::text)>16384 THEN RAISE EXCEPTION 'REGISTRATION_CONFIG_INVALID'; END IF;
 cfg:=jsonb_build_object('dine_in',true,'kitchens',1,'tray',false,'tablet',false,
  'customer_display',false,'fulfillment_mode','paperless')||cfg;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(cfg) k WHERE k NOT IN('dine_in','kitchens','tray','tablet','customer_display','fulfillment_mode','areas'))
 OR jsonb_typeof(cfg->'dine_in')<>'boolean' OR jsonb_typeof(cfg->'tray')<>'boolean'
 OR jsonb_typeof(cfg->'tablet')<>'boolean' OR jsonb_typeof(cfg->'customer_display')<>'boolean'
 OR coalesce(cfg->>'kitchens','') !~ '^[1-8]$'
 OR coalesce(cfg->>'fulfillment_mode','') NOT IN('paperless','pos_print') THEN RAISE EXCEPTION 'REGISTRATION_CONFIG_INVALID'; END IF;
 areas:=coalesce(cfg->'areas',CASE WHEN (cfg->>'dine_in')::boolean THEN '[{"code":"HALL","name":"Hall","physical_floor":null}]'::jsonb ELSE '[]'::jsonb END);
 IF jsonb_typeof(areas)<>'array' OR jsonb_array_length(areas)>16 THEN RAISE EXCEPTION 'SERVICE_AREAS_INVALID'; END IF;
 n:=jsonb_array_length(areas);
 IF ((cfg->>'dine_in')::boolean AND n=0) OR (NOT (cfg->>'dine_in')::boolean AND n<>0) THEN RAISE EXCEPTION 'SERVICE_AREAS_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(areas) a WHERE jsonb_typeof(a)<>'object'
  OR coalesce(a->>'code','') !~ '^[A-Z0-9][A-Z0-9_-]{0,15}$'
  OR length(btrim(coalesce(a->>'name',''))) NOT BETWEEN 1 AND 80
  OR (a->>'physical_floor' IS NOT NULL AND length(btrim(a->>'physical_floor')) NOT BETWEEN 1 AND 40))
 OR (SELECT count(DISTINCT a->>'code') FROM jsonb_array_elements(areas) a)<>n THEN RAISE EXCEPTION 'SERVICE_AREAS_INVALID'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('code',a->>'code','name',btrim(a->>'name'),
  'physical_floor',nullif(btrim(a->>'physical_floor'),'')) ORDER BY a->>'code'),'[]') INTO areas FROM jsonb_array_elements(areas) a;
 RETURN cfg||jsonb_build_object('areas',areas);
END $$;
REVOKE ALL ON FUNCTION public.store_registration_config_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.admin_preview_store_registration_v1(p_request_id uuid,p_brand_id uuid,p_config jsonb DEFAULT '{}',p_code text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE v_code text; cfg jsonb; accounts jsonb; brand_code text;
BEGIN
 PERFORM public.require_brand_admin_v1();
 cfg:=public.store_registration_config_v1(p_config);
 SELECT short_code INTO brand_code FROM brands WHERE id=p_brand_id;
 IF brand_code IS NULL THEN RAISE EXCEPTION 'BRAND_ABBREVIATION_REQUIRED'; END IF;
 v_code:=public.admin_reserve_store_code_v1(p_request_id,p_code);
 WITH managers AS MATERIALIZED(
  SELECT DISTINCT ON(q.account_code) q.account_code,q.account_type,q.role,q.display_name,q.scope
  FROM store_fixed_account_requirements q JOIN restaurants r ON r.id=q.store_id
  WHERE r.brand_id=p_brand_id AND q.scope='brand' AND q.is_active ORDER BY q.account_code,q.created_at
 ), templates AS (
  SELECT * FROM managers UNION ALL SELECT lower(brand_code)||'_bm1','brand_manager','brand_admin','Brand Manager','brand' WHERE NOT EXISTS(SELECT 1 FROM managers)
  UNION ALL SELECT lower(v_code)||'_'||suffix,account_type,role,label,'store' FROM (VALUES
   ('sm1','store_manager','store_admin','Store Manager'),('pos1','device_pos','cashier','Cashier'),
   ('pr1','inventory_orderer','inventory_orderer','Requester / Receiver')) t(suffix,account_type,role,label)
  UNION ALL SELECT lower(v_code)||'_kit'||n,'device_kitchen','kitchen','Kitchen '||n,'store' FROM generate_series(1,(cfg->>'kitchens')::integer)n
  UNION ALL SELECT lower(v_code)||'_area_'||lower(a->>'code'),'device_emergency_station','emergency_station',a->>'name','store' FROM jsonb_array_elements(cfg->'areas')a
  UNION ALL SELECT lower(v_code)||'_tray1','device_emergency_station','emergency_station','Tray','store' WHERE (cfg->>'tray')::boolean
  UNION ALL SELECT lower(v_code)||'_tab1','device_tablet','cashier','Tablet','store' WHERE (cfg->>'tablet')::boolean
  UNION ALL SELECT lower(v_code)||'_print','device_print_station','print_station','Print Station','store' WHERE cfg->>'fulfillment_mode'='pos_print'
  UNION ALL SELECT lower(v_code)||'_customer','device_customer_display','customer_display','Customer Display','store' WHERE (cfg->>'customer_display')::boolean
  UNION ALL SELECT lower(v_code)||'_ops1','store_operator','photo_objet_store_operator','Store Operator','store' WHERE EXISTS(SELECT 1 FROM brands WHERE id=p_brand_id AND code='photo_objet')
 ) SELECT jsonb_agg(to_jsonb(t) ORDER BY account_code) INTO accounts FROM templates t;
 IF jsonb_array_length(accounts)>50 THEN RAISE EXCEPTION 'ACCOUNT_LIMIT'; END IF;
 RETURN jsonb_build_object('code',v_code,'config',cfg,'accounts',accounts);
END $$;

ALTER FUNCTION public.admin_create_restaurant_v2(text,text,text,uuid,uuid,text,numeric,uuid) RENAME TO store_create_record_before_registration;
REVOKE ALL ON FUNCTION public.store_create_record_before_registration(text,text,text,uuid,uuid,text,numeric,uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.admin_register_store_v1(p_request_id uuid,p_input jsonb) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE input jsonb; preview jsonb; job store_account_onboarding_jobs; store restaurants; actor uuid; v_code text; cfg jsonb;
BEGIN
 PERFORM public.require_brand_admin_v1();
 IF p_request_id IS NULL OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>24576 THEN RAISE EXCEPTION 'STORE_INPUT_INVALID'; END IF;
 SELECT id INTO actor FROM users WHERE auth_id=auth.uid() AND is_active;
 PERFORM pg_advisory_xact_lock(hashtextextended('store-onboarding:'||p_request_id,0));
 v_code:=public.admin_reserve_store_code_v1(p_request_id,p_input->>'code');
 cfg:=public.store_registration_config_v1(p_input->'config');
 input:=jsonb_build_object('name',btrim(p_input->>'name'),'address',coalesce(btrim(p_input->>'address'),''),
  'code',v_code,'brand',(p_input->>'brand')::uuid,'entity',(p_input->>'entity')::uuid,
  'mode',coalesce(p_input->>'mode','standard'),'charge',p_input->'charge','config',cfg,
  'account_naming',coalesce(p_input->>'account_naming','configured'),
  'slug',coalesce(nullif(btrim(p_input->>'slug'),''),'store-'||p_request_id), 'office_store_id',p_input->'office_store_id');
 IF length(coalesce(input->>'name','')) NOT BETWEEN 1 AND 120 OR length(input->>'address')>500
 OR input->>'mode' NOT IN('standard','buffet','hybrid')
 OR (input->>'mode'<>'standard' AND coalesce((input->>'charge')::numeric,0)<=0) THEN RAISE EXCEPTION 'STORE_INPUT_INVALID'; END IF;
 SELECT * INTO job FROM store_account_onboarding_jobs WHERE id=p_request_id;
 IF FOUND THEN
  IF job.input<>input OR job.actor_id<>actor THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
  RETURN job.store_id;
 END IF;
 PERFORM 1 FROM brands WHERE id=(input->>'brand')::uuid FOR UPDATE;
 preview:=public.admin_preview_store_registration_v1(p_request_id,(input->>'brand')::uuid,cfg,v_code);
 IF input->>'account_naming'='legacy' THEN
  IF (cfg->>'kitchens')::int<>1 OR EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'areas')a WHERE a->>'code' NOT IN('1F','2F','3F')) THEN RAISE EXCEPTION 'LEGACY_ACCOUNT_CONFIG_INVALID'; END IF;
  preview:=preview||jsonb_build_object('accounts',public.admin_preview_store_accounts_v1((input->>'brand')::uuid,v_code,ARRAY(SELECT a->>'code' FROM jsonb_array_elements(cfg->'areas')a)));
 ELSIF input->>'account_naming'<>'configured' THEN RAISE EXCEPTION 'ACCOUNT_NAMING_INVALID'; END IF;
 store:=public.store_create_record_before_registration(input->>'name',input->>'slug',input->>'mode',
  (input->>'entity')::uuid,(input->>'brand')::uuid,input->>'address',(input->>'charge')::numeric,(input->>'office_store_id')::uuid);
 UPDATE restaurants SET short_code=v_code WHERE id=store.id;
 INSERT INTO restaurant_settings(restaurant_id,fulfillment_mode,kds_workflow)
 VALUES(store.id,cfg->>'fulfillment_mode',CASE WHEN (cfg->>'tray')::boolean THEN 'kitchen_tray_floor' ELSE 'kitchen_floor' END)
 ON CONFLICT(restaurant_id) DO UPDATE SET fulfillment_mode=EXCLUDED.fulfillment_mode,kds_workflow=EXCLUDED.kds_workflow;
 INSERT INTO store_service_areas(restaurant_id,stored_code,display_name,physical_floor)
 SELECT store.id,a->>'code',a->>'name',a->>'physical_floor' FROM jsonb_array_elements(cfg->'areas')a;
 INSERT INTO store_service_stations(restaurant_id,code,kind,area_id)
 SELECT store.id,'area:'||stored_code,'floor',id FROM store_service_areas WHERE restaurant_id=store.id
 UNION ALL SELECT store.id,'kitchen:'||n,'kitchen',NULL::uuid FROM generate_series(1,(cfg->>'kitchens')::integer)n
 UNION ALL SELECT store.id,'tray','tray',NULL::uuid WHERE (cfg->>'tray')::boolean;
 INSERT INTO store_registration_station_bindings(restaurant_id,account_code,station_id)
 SELECT store.id,lower(v_code)||CASE s.kind WHEN 'kitchen' THEN '_kit'||CASE WHEN input->>'account_naming'='legacy' THEN '' ELSE split_part(s.code,':',2) END
  WHEN 'tray' THEN '_tray1' ELSE CASE WHEN input->>'account_naming'='legacy' THEN '_floor_' ELSE '_area_' END||lower(a.stored_code) END,s.id
 FROM store_service_stations s LEFT JOIN store_service_areas a ON a.id=s.area_id WHERE s.restaurant_id=store.id;
 INSERT INTO store_account_onboarding_jobs(id,store_id,actor_id,input,accounts) VALUES(p_request_id,store.id,actor,input,preview->'accounts');
 INSERT INTO store_fixed_account_requirements(store_id,account_code,account_type,role,display_name,scope)
 SELECT store.id,t.account_code,t.account_type,t.role,(input->>'name')||' '||t.display_name,t.scope
 FROM jsonb_to_recordset(preview->'accounts')t(account_code text,account_type text,role text,display_name text,scope text);
 UPDATE store_registration_requests SET store_id=store.id WHERE id=p_request_id;
 INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details)
 VALUES(auth.uid(),'admin_register_store_v1','restaurants',store.id,jsonb_build_object('request_id',p_request_id,'code',v_code,'config',cfg));
 RETURN store.id;
END $$;

-- Old service entry points also produce durable jobs and configuration-driven IDs.
CREATE FUNCTION public.admin_create_restaurant_v2(p_name text,p_slug text,p_operation_mode text,p_tax_entity_id uuid,p_brand_id uuid,
 p_address text DEFAULT NULL,p_per_person_charge numeric DEFAULT NULL,p_office_store_id uuid DEFAULT NULL)
RETURNS public.restaurants LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE store_id uuid; result restaurants; request_id uuid;
BEGIN
 IF nullif(btrim(p_slug),'') IS NULL THEN RAISE EXCEPTION 'REGISTRATION_SLUG_REQUIRED'; END IF;
 request_id:=md5('legacy-registration:'||auth.uid()||':'||btrim(p_slug))::uuid;
 store_id:=public.admin_register_store_v1(request_id,jsonb_build_object('name',p_name,'slug',p_slug,'mode',p_operation_mode,
  'entity',p_tax_entity_id,'brand',p_brand_id,'address',p_address,'charge',p_per_person_charge,'office_store_id',p_office_store_id));
 SELECT * INTO result FROM restaurants WHERE id=store_id; RETURN result;
END $$;

ALTER FUNCTION public.admin_create_store_onboarding_v1(uuid,text,text,text,uuid,uuid,text[],text,numeric) RENAME TO store_create_legacy_onboarding;
REVOKE ALL ON FUNCTION public.store_create_legacy_onboarding(uuid,text,text,text,uuid,uuid,text[],text,numeric) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.admin_create_store_onboarding_v1(p_request_id uuid,p_name text,p_address text,p_code text,p_brand_id uuid,p_tax_entity_id uuid,p_floors text[],p_operation_mode text DEFAULT 'standard',p_per_person_charge numeric DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE areas jsonb;
BEGIN
 PERFORM public.require_brand_admin_v1();
 IF EXISTS(SELECT 1 FROM store_account_onboarding_jobs WHERE id=p_request_id AND NOT input ? 'config') THEN
  RETURN public.store_create_legacy_onboarding(p_request_id,p_name,p_address,p_code,p_brand_id,p_tax_entity_id,p_floors,p_operation_mode,p_per_person_charge);
 END IF;
 IF p_floors IS NULL OR cardinality(p_floors) NOT BETWEEN 1 AND 3 OR array_position(p_floors,NULL) IS NOT NULL OR NOT p_floors <@ ARRAY['1F','2F','3F'] THEN RAISE EXCEPTION 'FLOORS_INVALID'; END IF;
 SELECT jsonb_agg(jsonb_build_object('code',f,'name',f,'physical_floor',f) ORDER BY f) INTO areas FROM (SELECT DISTINCT unnest(p_floors) f)t;
 RETURN public.admin_register_store_v1(p_request_id,jsonb_build_object('name',p_name,'address',p_address,'code',p_code,'brand',p_brand_id,'entity',p_tax_entity_id,'mode',p_operation_mode,'charge',p_per_person_charge,
  'account_naming','legacy','config',jsonb_build_object('areas',areas,'tray',true,'tablet',true,'customer_display',true,'fulfillment_mode','pos_print')));
END $$;
REVOKE ALL ON FUNCTION public.admin_create_store_onboarding_v1(uuid,text,text,text,uuid,uuid,text[],text,numeric) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_create_store_onboarding_v1(uuid,text,text,text,uuid,uuid,text[],text,numeric) TO authenticated;

-- Explicit bindings override name inference only for new stores. Preserve the
-- historical JeonGabok floor mapping and retired checker in the legacy branch.
DO $$ DECLARE definition text; BEGIN
 definition:=pg_get_functiondef('public.sync_emergency_station_assignment_for_user()'::regprocedure);
 IF position('store_registration_station_bindings' IN definition)>0 THEN RAISE EXCEPTION 'REGISTRATION_ALREADY_PATCHED'; END IF;
 definition:=replace(definition,'  IF NEW.fixed_account_code IS NULL OR NEW.restaurant_id IS NULL THEN',
 '  SELECT s.kind,a.stored_code INTO v_station,v_floor FROM public.store_registration_station_bindings b JOIN public.store_service_stations s ON s.id=b.station_id LEFT JOIN public.store_service_areas a ON a.id=s.area_id WHERE b.restaurant_id=NEW.restaurant_id AND b.account_code=NEW.fixed_account_code;
  IF FOUND THEN
    INSERT INTO public.emergency_station_assignments(restaurant_id,user_id,station_type,floor_label,is_active) VALUES(NEW.restaurant_id,NEW.id,v_station,v_floor,NEW.is_active)
    ON CONFLICT(restaurant_id,user_id) DO UPDATE SET station_type=EXCLUDED.station_type,floor_label=EXCLUDED.floor_label,is_active=EXCLUDED.is_active,updated_at=now();
    RETURN NEW;
  END IF;
  IF NEW.fixed_account_code IS NULL OR NEW.restaurant_id IS NULL THEN');
 IF position('store_registration_station_bindings' IN definition)=0 THEN RAISE EXCEPTION 'REGISTRATION_TRIGGER_PATCH_MISMATCH'; END IF;
 EXECUTE definition;
END $$;

REVOKE ALL ON FUNCTION public.admin_reserve_store_code_v1(uuid,text),public.admin_preview_store_registration_v1(uuid,uuid,jsonb,text),
 public.admin_register_store_v1(uuid,jsonb),public.admin_create_restaurant_v2(text,text,text,uuid,uuid,text,numeric,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_reserve_store_code_v1(uuid,text),public.admin_preview_store_registration_v1(uuid,uuid,jsonb,text),
 public.admin_register_store_v1(uuid,jsonb),public.admin_create_restaurant_v2(text,text,text,uuid,uuid,text,numeric,uuid) TO authenticated;

-- COMPONENT 20261022091000_service_area_kds_compat.sql
-- Service-area codes are independent of physical floors. Legacy store mapping
-- remains unchanged; newly registered areas are routed by their stable code.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
ALTER TABLE public.emergency_order_queue DROP CONSTRAINT emergency_order_queue_floor_label_check;
ALTER TABLE public.emergency_order_queue ADD CONSTRAINT emergency_order_queue_floor_label_check CHECK(floor_label ~ '^[A-Z0-9][A-Z0-9_-]{0,15}$');
ALTER TABLE public.emergency_station_assignments DROP CONSTRAINT emergency_station_floor_contract;
ALTER TABLE public.emergency_station_assignments ADD CONSTRAINT emergency_station_floor_contract CHECK(
 (station_type='floor' AND floor_label IS NOT NULL AND floor_label ~ '^[A-Z0-9][A-Z0-9_-]{0,15}$') OR (station_type<>'floor' AND floor_label IS NULL));
ALTER TABLE public.emergency_tray_floor_batch_actions DROP CONSTRAINT emergency_tray_floor_batch_actions_floor_label_check;
ALTER TABLE public.emergency_tray_floor_batch_actions ADD CONSTRAINT emergency_tray_floor_batch_actions_floor_label_check CHECK(floor_label ~ '^[A-Z0-9][A-Z0-9_-]{0,15}$');
ALTER TABLE public.kds_change_log DROP CONSTRAINT kds_change_log_floor_target;
ALTER TABLE public.kds_change_log ADD CONSTRAINT kds_change_log_floor_target CHECK(target_floor_label IS NULL OR target_floor_label ~ '^[A-Z0-9][A-Z0-9_-]{0,15}$');
ALTER TABLE public.kds_shadow_health DROP CONSTRAINT kds_shadow_health_floor_key_check;
ALTER TABLE public.kds_shadow_health ADD CONSTRAINT kds_shadow_health_floor_key_check CHECK(floor_key='' OR floor_key ~ '^[A-Z0-9][A-Z0-9_-]{0,15}$');
ALTER FUNCTION public.emergency_floor_label(uuid,text,text) RENAME TO emergency_floor_label_legacy;
CREATE FUNCTION public.emergency_floor_label(p_store_id uuid,p_floor_label text,p_table_number text) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
 SELECT coalesce((SELECT a.stored_code FROM public.store_service_areas a
 JOIN public.store_registration_requests r ON r.store_id=a.restaurant_id
 WHERE a.restaurant_id=p_store_id AND a.stored_code=upper(btrim(p_floor_label))),
 public.emergency_floor_label_legacy(p_store_id,p_floor_label,p_table_number));
$$;
REVOKE ALL ON FUNCTION public.emergency_floor_label(uuid,text,text),public.emergency_floor_label_legacy(uuid,text,text) FROM PUBLIC,anon,authenticated,service_role;

DO $$ DECLARE definition text; BEGIN
 definition:=pg_get_functiondef('public.kds_dispatch_tray_floor_batch_v1(uuid,text,jsonb)'::regprocedure);
 IF position('v_floor_label NOT IN (''1F'', ''2F'', ''3F'')' IN definition)=0 THEN RAISE EXCEPTION 'AREA_DISPATCH_PATCH_MISMATCH'; END IF;
 definition:=replace(definition,'v_floor_label NOT IN (''1F'', ''2F'', ''3F'')',
  'v_floor_label IS NULL OR v_floor_label !~ ''^[A-Z0-9][A-Z0-9_-]{0,15}$''');
 EXECUTE definition;
 -- Broadcast reset events to actual assigned areas with a single bounded query.
 definition:=pg_get_functiondef('public.kds_broadcast_change()'::regprocedure);
 IF position('FROM unnest(ARRAY[''1F'',''2F'',''3F'']) f' IN definition)=0 THEN RAISE EXCEPTION 'AREA_BROADCAST_PATCH_MISMATCH'; END IF;
 definition:=replace(definition,'FROM unnest(ARRAY[''1F'',''2F'',''3F'']) f',
 'FROM (SELECT DISTINCT floor_label AS f FROM public.emergency_station_assignments WHERE restaurant_id=v_change.restaurant_id AND station_type=''floor'' AND is_active) areas');
 EXECUTE definition;
END $$;

CREATE FUNCTION public.admin_get_store_service_areas_v1(p_store_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 PERFORM public.require_admin_actor_for_restaurant(p_store_id);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'code',stored_code,'name',coalesce(display_name,stored_code),'physical_floor',physical_floor) ORDER BY stored_code),'[]')
 INTO result FROM (SELECT * FROM store_service_areas WHERE restaurant_id=p_store_id ORDER BY stored_code LIMIT 100) a;
 RETURN jsonb_build_object('registered',EXISTS(SELECT 1 FROM store_registration_requests WHERE store_id=p_store_id),'areas',result);
END $$;
REVOKE ALL ON FUNCTION public.admin_get_store_service_areas_v1(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_get_store_service_areas_v1(uuid) TO authenticated;

CREATE FUNCTION public.store_registration_table_area_guard_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM registered_table_rows t
 JOIN public.store_registration_requests r ON r.store_id=t.restaurant_id
 LEFT JOIN public.store_service_areas a ON a.restaurant_id=t.restaurant_id AND a.stored_code=t.floor_label
 WHERE a.id IS NULL) THEN RAISE EXCEPTION 'REGISTERED_SERVICE_AREA_REQUIRED'; END IF;
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION public.store_registration_table_area_guard_v1() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER store_registration_table_area_insert AFTER INSERT ON public.tables
 REFERENCING NEW TABLE AS registered_table_rows FOR EACH STATEMENT EXECUTE FUNCTION public.store_registration_table_area_guard_v1();
CREATE TRIGGER store_registration_table_area_update AFTER UPDATE ON public.tables
 REFERENCING NEW TABLE AS registered_table_rows FOR EACH STATEMENT EXECUTE FUNCTION public.store_registration_table_area_guard_v1();
CREATE FUNCTION public.store_registered_pickup_only_v1(p_store_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM store_account_onboarding_jobs j JOIN store_registration_requests r ON r.store_id=j.store_id
 WHERE j.store_id=p_store_id AND j.input->'config'->>'dine_in'='false');
$$;
REVOKE ALL ON FUNCTION public.store_registered_pickup_only_v1(uuid) FROM PUBLIC,anon,authenticated,service_role;
DO $$ DECLARE definition text; BEGIN
 definition:=pg_get_functiondef('public.admin_validate_store_opening_config_v2(uuid,jsonb,jsonb,text)'::regprocedure);
 IF position('IF v_table_count = 0 THEN' IN definition)=0 THEN RAISE EXCEPTION 'PICKUP_VALIDATION_PATCH_MISMATCH'; END IF;
 definition:=replace(definition,'IF v_table_count = 0 THEN','IF v_table_count = 0 AND NOT public.store_registered_pickup_only_v1(p_store_id) THEN');
 EXECUTE definition;
 definition:=pg_get_functiondef('public.admin_get_store_opening_readiness(uuid)'::regprocedure);
 IF position('v_table_count > 0' IN definition)=0 THEN RAISE EXCEPTION 'PICKUP_READINESS_PATCH_MISMATCH'; END IF;
 EXECUTE replace(definition,'v_table_count > 0','(v_table_count > 0 OR public.store_registered_pickup_only_v1(p_store_id))');
END $$;

-- COMPONENT 20261022100000_store_lifecycle_readiness.sql
-- Opening is an explicit transition, independent of account provisioning and buying.
-- Existing stores are grandfathered; new intake gates do not interrupt old orders.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE TABLE public.store_lifecycle (
 restaurant_id uuid PRIMARY KEY REFERENCES public.restaurants(id) ON DELETE CASCADE,
 state text NOT NULL CHECK(state IN('preparing','active','suspended','closed')),
 legacy_operational boolean NOT NULL DEFAULT false,
 revision bigint NOT NULL DEFAULT 0,
 activated_source_hash text,
 changed_by uuid, changed_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO public.store_lifecycle(restaurant_id,state,legacy_operational)
SELECT r.id,CASE WHEN NOT r.is_active THEN 'closed' WHEN q.id IS NOT NULL THEN 'preparing' ELSE 'active' END,q.id IS NULL
FROM public.restaurants r LEFT JOIN public.store_registration_requests q ON q.store_id=r.id;
ALTER TABLE public.store_lifecycle ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_lifecycle FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.store_initialize_lifecycle_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 INSERT INTO public.store_lifecycle(restaurant_id,state) SELECT id,'preparing' FROM new_stores;
 RETURN NULL;
END $$;
CREATE TRIGGER store_initialize_lifecycle AFTER INSERT ON public.restaurants
 REFERENCING NEW TABLE AS new_stores FOR EACH STATEMENT EXECUTE FUNCTION public.store_initialize_lifecycle_v1();

CREATE TABLE public.store_credential_handovers (
 id uuid PRIMARY KEY,
 restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 employee_id uuid NOT NULL REFERENCES public.store_employees(id) DEFERRABLE INITIALLY DEFERRED,
 account_snapshot jsonb NOT NULL,
 evidence text NOT NULL CHECK(length(btrim(evidence)) BETWEEN 1 AND 500),
 actor_id uuid NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX store_credential_handovers_store ON public.store_credential_handovers(restaurant_id,created_at DESC);
ALTER TABLE public.store_credential_handovers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_credential_handovers FROM PUBLIC,anon,authenticated;

CREATE TABLE public.store_opening_verifications (
 id uuid PRIMARY KEY,
 restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 source_hash text NOT NULL,
 evidence text NOT NULL CHECK(length(btrim(evidence)) BETWEEN 1 AND 500),
 actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX store_opening_verifications_source ON public.store_opening_verifications(restaurant_id,source_hash);
ALTER TABLE public.store_opening_verifications ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_opening_verifications FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public.store_credential_snapshot_v1(p_store_id uuid) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('requirement_id',q.id,'account_code',q.account_code,'user_id',u.id,
  'generation',u.password_change_generation,'ready',coalesce(u.is_active AND NOT u.must_change_password AND au.id IS NOT NULL
   AND EXISTS(SELECT 1 FROM user_store_access sa WHERE sa.user_id=u.id AND sa.store_id=p_store_id AND sa.is_active),false)) ORDER BY q.account_code),'[]')
 FROM store_fixed_account_requirements q LEFT JOIN users u ON u.id=q.provisioned_user_id AND u.fixed_account_code=q.account_code AND u.role=q.role AND u.account_type=q.account_type
 LEFT JOIN auth.users au ON au.id=u.auth_id
 WHERE q.store_id=p_store_id AND q.scope='store' AND q.is_active;
$$;

CREATE FUNCTION public.admin_record_store_handover_v1(p_request_id uuid,p_store_id uuid,p_employee_id uuid,p_evidence text) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE snapshot jsonb; previous store_credential_handovers;
BEGIN
 PERFORM public.require_brand_admin_v1();
 IF p_request_id IS NULL OR length(btrim(coalesce(p_evidence,''))) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'HANDOVER_EVIDENCE_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('store-opening:'||p_store_id,0));
 IF NOT EXISTS(SELECT 1 FROM store_employees WHERE id=p_employee_id AND store_id=p_store_id AND is_active) THEN RAISE EXCEPTION 'HANDOVER_EMPLOYEE_REQUIRED'; END IF;
 snapshot:=public.store_credential_snapshot_v1(p_store_id);
 IF jsonb_array_length(snapshot)=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot)a WHERE a->>'ready'<>'true') THEN RAISE EXCEPTION 'HANDOVER_ACCOUNTS_NOT_READY'; END IF;
 SELECT * INTO previous FROM store_credential_handovers WHERE id=p_request_id;
 IF FOUND THEN
  IF previous.restaurant_id<>p_store_id OR previous.employee_id<>p_employee_id OR previous.evidence<>btrim(p_evidence) OR previous.account_snapshot<>snapshot THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
  RETURN previous.id;
 END IF;
 INSERT INTO store_credential_handovers(id,restaurant_id,employee_id,account_snapshot,evidence,actor_id)
 VALUES(p_request_id,p_store_id,p_employee_id,snapshot,btrim(p_evidence),auth.uid());
 RETURN p_request_id;
END $$;

CREATE FUNCTION public.admin_get_store_lifecycle_v1(p_store_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE state_row store_lifecycle; shop restaurants; cfg jsonb; accounts jsonb; opening jsonb; checks jsonb; v_source_hash text; registered boolean; result jsonb; v_at timestamptz:=clock_timestamp();
BEGIN
 PERFORM public.require_admin_actor_for_restaurant(p_store_id);
 SELECT * INTO shop FROM restaurants WHERE id=p_store_id;
 SELECT * INTO state_row FROM store_lifecycle WHERE restaurant_id=p_store_id;
 IF shop.id IS NULL OR state_row.restaurant_id IS NULL THEN RAISE EXCEPTION 'STORE_NOT_FOUND'; END IF;
 SELECT input->'config' INTO cfg FROM store_account_onboarding_jobs WHERE store_id=p_store_id;
 registered:=cfg IS NOT NULL;
 accounts:=public.store_credential_snapshot_v1(p_store_id);
 opening:=public.admin_get_store_opening_readiness(p_store_id);
 checks:=jsonb_build_object(
  'identity',shop.short_code IS NOT NULL AND shop.brand_id IS NOT NULL AND shop.tax_entity_id IS NOT NULL AND EXISTS(SELECT 1 FROM tax_entity_brands WHERE tax_entity_id=shop.tax_entity_id AND brand_id=shop.brand_id),
  'accounts',jsonb_array_length(accounts)>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(accounts)a WHERE a->>'ready'<>'true'),
  'credential_handover',EXISTS(SELECT 1 FROM store_credential_handovers h JOIN store_employees e ON e.id=h.employee_id AND e.store_id=p_store_id AND e.is_active WHERE h.restaurant_id=p_store_id AND h.account_snapshot=accounts),
  'employees',EXISTS(SELECT 1 FROM store_employees WHERE store_id=p_store_id AND is_active),
  'opening_tests',coalesce((opening->>'ready')::boolean,false),
  'service_areas',NOT registered OR ((cfg->>'dine_in')::boolean=(EXISTS(SELECT 1 FROM tables WHERE restaurant_id=p_store_id))) AND NOT EXISTS(
    SELECT 1 FROM store_service_areas area WHERE area.restaurant_id=p_store_id AND NOT EXISTS(SELECT 1 FROM emergency_station_assignments a JOIN users u ON u.id=a.user_id AND u.is_active WHERE a.restaurant_id=p_store_id AND a.is_active AND a.station_type='floor' AND a.floor_label=area.stored_code)),
  'kitchens',EXISTS(SELECT 1 FROM emergency_station_assignments a JOIN users u ON u.id=a.user_id AND u.is_active WHERE a.restaurant_id=p_store_id AND a.is_active AND a.station_type='kitchen'),
  'workflow',coalesce((cfg->>'kitchens')::int,1)<=1 OR EXISTS(SELECT 1 FROM store_workflow_configs WHERE restaurant_id=p_store_id AND active_id IS NOT NULL),
  'menus',EXISTS(SELECT 1 FROM menu_items WHERE restaurant_id=p_store_id AND is_available AND NOT is_archived),
  'invoice_mapping',EXISTS(SELECT 1 FROM invoice_mapping_policies WHERE store_id=p_store_id AND tax_entity_id=shop.tax_entity_id AND effective_from<=v_at AND (effective_to IS NULL OR effective_to>v_at))
    AND NOT EXISTS(SELECT 1 FROM menu_items m WHERE m.restaurant_id=p_store_id AND m.is_available AND NOT m.is_archived AND NOT EXISTS(SELECT 1 FROM menu_invoice_profiles p WHERE p.menu_item_id=m.id AND p.tax_entity_id=shop.tax_entity_id AND p.effective_from<=v_at AND (p.effective_to IS NULL OR p.effective_to>v_at)))
 );
 -- Capture only bounded configuration data; sales and financial histories are not loaded.
 IF (SELECT count(*) FROM menu_items WHERE restaurant_id=p_store_id)>4000 THEN RAISE EXCEPTION 'WORKFLOW_MENU_LIMIT'; END IF;
 v_source_hash:=md5(jsonb_build_object('workflow',public.store_workflow_source(p_store_id),'accounts',accounts,'checks',checks,
  'printers',(SELECT jsonb_agg(jsonb_build_array(id,ip,port,purpose,floor_label,is_active,updated_at) ORDER BY id) FROM (SELECT * FROM printer_destinations WHERE restaurant_id=p_store_id ORDER BY id LIMIT 21)p),
  'printer_endpoints',(SELECT jsonb_agg(to_jsonb(ep) ORDER BY ep.id) FROM (SELECT e.* FROM printer_endpoints e WHERE e.physical_printer_id IN (SELECT physical_printer_id FROM printer_destinations WHERE restaurant_id=p_store_id) ORDER BY e.id LIMIT 101)ep))::text);
 checks:=checks||jsonb_build_object('field_verification',EXISTS(SELECT 1 FROM store_opening_verifications v WHERE v.restaurant_id=p_store_id AND v.source_hash=v_source_hash));
 result:=jsonb_build_object('can_manage',public.is_super_admin(),'lifecycle',to_jsonb(state_row),'checks',checks,'source_hash',v_source_hash,
  'business_ready',NOT EXISTS(SELECT 1 FROM jsonb_each(checks)c WHERE c.value<>'true'::jsonb),
  'procurement',coalesce((SELECT readiness||jsonb_build_object('office_connected',office_connected) FROM procurement_store_onboarding WHERE restaurant_id=p_store_id),'{}'),
  'accounts',accounts,'opening',opening,
  'employees',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',full_name) ORDER BY employee_number),'[]') FROM (SELECT id,full_name,employee_number FROM store_employees WHERE store_id=p_store_id AND is_active ORDER BY employee_number LIMIT 200)e));
 RETURN result;
END $$;

CREATE FUNCTION public.admin_record_store_verification_v1(p_request_id uuid,p_store_id uuid,p_source_hash text,p_evidence text) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE readiness jsonb; previous store_opening_verifications;
BEGIN
 PERFORM public.require_brand_admin_v1();
 IF p_request_id IS NULL OR length(btrim(coalesce(p_evidence,''))) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'FIELD_VERIFICATION_EVIDENCE_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('store-opening:'||p_store_id,0));
 readiness:=public.admin_get_store_lifecycle_v1(p_store_id);
 IF p_source_hash IS DISTINCT FROM readiness->>'source_hash' OR EXISTS(SELECT 1 FROM jsonb_each(readiness->'checks') c WHERE c.key<>'field_verification' AND c.value<>'true'::jsonb) THEN RAISE EXCEPTION 'STORE_OPENING_NOT_READY'; END IF;
 SELECT * INTO previous FROM store_opening_verifications WHERE id=p_request_id;
 IF FOUND THEN
  IF previous.restaurant_id<>p_store_id OR previous.source_hash<>p_source_hash OR previous.evidence<>btrim(p_evidence) THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
  RETURN previous.id;
 END IF;
 INSERT INTO store_opening_verifications VALUES(p_request_id,p_store_id,p_source_hash,btrim(p_evidence),auth.uid(),now());
 RETURN p_request_id;
END $$;
REVOKE ALL ON FUNCTION public.admin_record_store_verification_v1(uuid,uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_record_store_verification_v1(uuid,uuid,text,text) TO authenticated;

CREATE FUNCTION public.admin_transition_store_lifecycle_v1(p_store_id uuid,p_expected_revision bigint,p_state text,p_source_hash text,p_reason text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE previous store_lifecycle; readiness jsonb;
BEGIN
 PERFORM public.require_brand_admin_v1();
 IF p_state NOT IN('active','suspended') OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'LIFECYCLE_TRANSITION_INVALID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('store-opening:'||p_store_id,0));
 SELECT * INTO previous FROM store_lifecycle WHERE restaurant_id=p_store_id FOR UPDATE;
 IF NOT FOUND OR previous.revision<>p_expected_revision THEN RAISE EXCEPTION 'LIFECYCLE_CHANGED'; END IF;
 IF previous.state='closed' OR NOT EXISTS(SELECT 1 FROM restaurants WHERE id=p_store_id AND is_active) THEN RAISE EXCEPTION 'STORE_CLOSED'; END IF;
 IF p_state='suspended' AND EXISTS(SELECT 1 FROM direct_order_requests WHERE restaurant_id=p_store_id AND state IN('awaiting_quote','quoted','awaiting_payment_review')) THEN RAISE EXCEPTION 'STORE_PENDING_DIRECT_ORDERS'; END IF;
 readiness:=public.admin_get_store_lifecycle_v1(p_store_id);
 IF p_state='active' AND (p_source_hash IS DISTINCT FROM readiness->>'source_hash' OR NOT (readiness->>'business_ready')::boolean) THEN RAISE EXCEPTION 'STORE_OPENING_NOT_READY'; END IF;
 UPDATE store_lifecycle SET state=p_state,revision=revision+1,activated_source_hash=CASE WHEN p_state='active' THEN p_source_hash ELSE activated_source_hash END,changed_by=auth.uid(),changed_at=now() WHERE restaurant_id=p_store_id;
 INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(auth.uid(),'store_lifecycle_transition','restaurants',p_store_id,jsonb_build_object('before',previous.state,'after',p_state,'reason',btrim(p_reason),'source_hash',p_source_hash));
 RETURN public.admin_get_store_lifecycle_v1(p_store_id);
END $$;

CREATE FUNCTION public.store_guard_new_intake_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 -- Same boundary as workflow activation. One check per affected store batch.
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('store-opening:'||restaurant_id,0)) FROM (SELECT DISTINCT restaurant_id FROM new_intake ORDER BY restaurant_id)s;
 IF EXISTS(SELECT 1 FROM new_intake n JOIN store_lifecycle l ON l.restaurant_id=n.restaurant_id JOIN restaurants r ON r.id=n.restaurant_id WHERE l.state<>'active' OR NOT r.is_active) THEN RAISE EXCEPTION 'STORE_NOT_OPEN_FOR_NEW_ORDERS'; END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER store_lifecycle_orders AFTER INSERT ON public.orders REFERENCING NEW TABLE AS new_intake FOR EACH STATEMENT EXECUTE FUNCTION public.store_guard_new_intake_v1();
-- QR checkout creates orders through the same guarded order boundary.
CREATE TRIGGER store_lifecycle_direct AFTER INSERT ON public.direct_order_requests REFERENCING NEW TABLE AS new_intake FOR EACH STATEMENT EXECUTE FUNCTION public.store_guard_new_intake_v1();

CREATE FUNCTION public.store_guard_registered_identity_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF (NEW.brand_id,NEW.tax_entity_id,NEW.short_code) IS DISTINCT FROM (OLD.brand_id,OLD.tax_entity_id,OLD.short_code)
 AND EXISTS(SELECT 1 FROM store_account_onboarding_jobs WHERE store_id=OLD.id) THEN RAISE EXCEPTION 'STORE_REGISTERED_IDENTITY_FROZEN'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER store_registered_identity_guard BEFORE UPDATE OF brand_id,tax_entity_id,short_code ON public.restaurants FOR EACH ROW EXECUTE FUNCTION public.store_guard_registered_identity_v1();
REVOKE ALL ON FUNCTION public.store_initialize_lifecycle_v1(),public.store_credential_snapshot_v1(uuid),public.store_guard_new_intake_v1(),public.store_guard_registered_identity_v1() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.admin_record_store_handover_v1(uuid,uuid,uuid,text),public.admin_get_store_lifecycle_v1(uuid),public.admin_transition_store_lifecycle_v1(uuid,bigint,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_record_store_handover_v1(uuid,uuid,uuid,text),public.admin_get_store_lifecycle_v1(uuid),public.admin_transition_store_lifecycle_v1(uuid,bigint,text,text,text) TO authenticated;

-- COMPONENT 20261022110000_sales_store_identity.sql
-- Capture future sale identities without inventing names for historical sales.
-- Physical restaurants / restaurant_id and MISA financial snapshots stay intact.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE TABLE public.store_sale_identities (
 order_id uuid PRIMARY KEY REFERENCES public.orders(id) ON DELETE CASCADE,
 restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 store_code text,store_name text NOT NULL,
 brand_id uuid,tax_entity_id uuid,
 captured_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX store_sale_identities_store ON public.store_sale_identities(restaurant_id,order_id);
ALTER TABLE public.store_sale_identities ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_sale_identities FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.store_capture_sale_identity_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 INSERT INTO store_sale_identities(order_id,restaurant_id,store_code,store_name,brand_id,tax_entity_id)
 SELECT n.id,r.id,r.short_code,r.name,r.brand_id,r.tax_entity_id FROM new_sale_orders n JOIN restaurants r ON r.id=n.restaurant_id;
 RETURN NULL;
END $$;
CREATE TRIGGER store_capture_sale_identity AFTER INSERT ON public.orders REFERENCING NEW TABLE AS new_sale_orders
 FOR EACH STATEMENT EXECUTE FUNCTION public.store_capture_sale_identity_v1();
CREATE TRIGGER store_sale_identity_immutable BEFORE UPDATE ON public.store_sale_identities FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
REVOKE ALL ON FUNCTION public.store_capture_sale_identity_v1() FROM PUBLIC,anon,authenticated,service_role;

DO $$ DECLARE definition text; BEGIN
 definition:=pg_get_functiondef('public.pos_restaurant_receipt_rows_v2(date,uuid[])'::regprocedure);
 IF position('restaurant.name AS store_name' IN definition)=0 OR position('JOIN public.restaurants restaurant ON restaurant.id = paid.store_id' IN definition)=0 THEN RAISE EXCEPTION 'SALE_IDENTITY_SOURCE_PATCH_MISMATCH'; END IF;
 definition:=replace(definition,'restaurant.name AS store_name','coalesce(sale_identity.store_name,restaurant.name) AS store_name');
 definition:=replace(definition,'JOIN public.restaurants restaurant ON restaurant.id = paid.store_id',
 'JOIN public.restaurants restaurant ON restaurant.id = paid.store_id LEFT JOIN public.store_sale_identities sale_identity ON sale_identity.order_id=paid.order_id');
 EXECUTE definition;
 definition:=pg_get_functiondef('public.get_pos_daily_sales_export_page(date,uuid,text,timestamptz,text,integer)'::regprocedure);
 IF position('jsonb_agg(to_jsonb(r) ORDER BY r.sold_at,r.receipt_id)' IN definition)=0 THEN RAISE EXCEPTION 'SALE_IDENTITY_PAGE_PATCH_MISMATCH'; END IF;
 definition:=replace(definition,'jsonb_agg(to_jsonb(r) ORDER BY r.sold_at,r.receipt_id)',
 'jsonb_agg(to_jsonb(r)||jsonb_build_object(''store_code'',CASE WHEN si.order_id IS NULL THEN shop.short_code ELSE si.store_code END,''store_name_origin'',CASE WHEN si.order_id IS NULL THEN ''current_registry'' ELSE ''order_snapshot'' END) ORDER BY r.sold_at,r.receipt_id)');
 definition:=replace(definition,')) r WHERE r.tax_entity_id=p_tax_entity_id;',
 ')) r LEFT JOIN public.store_sale_identities si ON si.order_id=r.receipt_id::uuid LEFT JOIN public.restaurants shop ON shop.id=r.store_id WHERE r.tax_entity_id=p_tax_entity_id;');
 IF position('si.order_id=r.receipt_id::uuid' IN definition)=0 THEN RAISE EXCEPTION 'SALE_IDENTITY_PAGE_JOIN_MISMATCH'; END IF;
 EXECUTE definition;
END $$;

-- COMPONENT 20261022112000_sales_reporting_batches.sql
-- Frozen reporting membership; owner confirmation and external evidence are separate.
-- No tax submission or invoice dispatch occurs in these functions.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE TABLE public.sales_reporting_batches (
 id uuid PRIMARY KEY, business_date date NOT NULL, tax_entity_id uuid NOT NULL REFERENCES public.tax_entity(id),
 source_revision text NOT NULL, mapping_revision bigint NOT NULL,
 status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','generated','confirmed','reported','void')),
 members jsonb NOT NULL CHECK(jsonb_array_length(members) BETWEEN 1 AND 10000),
 receipt_count integer NOT NULL, gross numeric NOT NULL, membership_hash text NOT NULL,
 file_sha256 text, file_size bigint, created_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),
 confirmed_by uuid REFERENCES auth.users(id),confirmed_at timestamptz,
 external_evidence jsonb, reported_by uuid REFERENCES auth.users(id),reported_at timestamptz,
 void_reason text, voided_by uuid REFERENCES auth.users(id),voided_at timestamptz
);
CREATE INDEX sales_reporting_batches_scope ON public.sales_reporting_batches(tax_entity_id,business_date,created_at DESC,id);
CREATE TABLE public.sales_reporting_claims (
 source_system text NOT NULL,receipt_id text NOT NULL,batch_id uuid NOT NULL REFERENCES public.sales_reporting_batches(id),
 business_date date NOT NULL,tax_entity_id uuid NOT NULL,store_id uuid NOT NULL,source_hash text NOT NULL,gross numeric NOT NULL,
 PRIMARY KEY(source_system,receipt_id)
);
CREATE INDEX sales_reporting_claims_scope ON public.sales_reporting_claims(tax_entity_id,business_date);
ALTER TABLE public.sales_reporting_batches ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sales_reporting_claims ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sales_reporting_batches,public.sales_reporting_claims FROM PUBLIC,anon,authenticated;

-- A single bounded set query per source, never an RPC/SELECT per receipt.
CREATE FUNCTION public.sales_reporting_members_v1(p_date date,p_entity uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE ids uuid[]; photos jsonb; result jsonb;
BEGIN
 SELECT array_agg(order_id) INTO ids FROM pos_daily_receipt_scope_page(p_date,p_entity,NULL,NULL,10001);
 SELECT coalesce(jsonb_agg(jsonb_build_object('source','photo_objet_moers','id',source_hash,'store_id',store_id,'store_name',store_name,
  'store_code',NULL,'name_origin','current_registry','source_hash',md5(jsonb_build_array(source_hash,store_id,sold_at,amount)::text),'gross',amount) ORDER BY sold_at,source_hash),'[]') INTO photos
 FROM pos_photo_receipt_rows_page(p_date,p_entity,NULL,NULL,10001);
 IF coalesce(cardinality(ids),0)+jsonb_array_length(photos)>10000 THEN RAISE EXCEPTION 'SALES_BATCH_LIMIT_10000'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('source','restaurant_pos','id',r.receipt_id,'store_id',r.store_id,'store_name',r.store_name,
  'store_code',CASE WHEN si.order_id IS NULL THEN shop.short_code ELSE si.store_code END,'name_origin',CASE WHEN si.order_id IS NULL THEN 'current_registry' ELSE 'order_snapshot' END,
  'source_hash',r.source_hash,'gross',r.gross_sales) ORDER BY r.sold_at,r.receipt_id),'[]')||photos INTO result
 FROM pos_restaurant_receipt_rows_v2(p_date,coalesce(ids,'{}')) r
 LEFT JOIN store_sale_identities si ON si.order_id=r.receipt_id::uuid LEFT JOIN restaurants shop ON shop.id=r.store_id WHERE r.tax_entity_id=p_entity;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.sales_reporting_members_v1(date,uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.admin_prepare_sales_batch_v1(p_id uuid,p_date date,p_entity uuid,p_source_revision text,p_mapping_revision bigint) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE b sales_reporting_batches; all_members jsonb; selected jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT is_super_admin() THEN RAISE EXCEPTION 'SUPER_ADMIN_ONLY'; END IF;
 IF p_id IS NULL OR p_date IS NULL OR p_date<DATE '2020-01-01' OR p_date>(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date OR p_entity IS NULL THEN RAISE EXCEPTION 'SALES_BATCH_SCOPE_INVALID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sales-reporting:'||p_entity::text||':'||p_date::text,0));
 SELECT * INTO b FROM sales_reporting_batches WHERE id=p_id;
 IF FOUND THEN
  IF (b.business_date,b.tax_entity_id,b.source_revision,b.mapping_revision,b.created_by) IS DISTINCT FROM (p_date,p_entity,p_source_revision,p_mapping_revision,auth.uid()) THEN RAISE EXCEPTION 'SALES_BATCH_REQUEST_CONFLICT'; END IF;
  RETURN to_jsonb(b);
 END IF;
 IF p_source_revision IS DISTINCT FROM pos_sales_export_source_revision(p_date,p_entity)
 OR p_mapping_revision IS DISTINCT FROM coalesce((SELECT revision FROM sales_invoice_mapping_revisions WHERE tax_entity_id=p_entity),0) THEN RAISE EXCEPTION 'SALES_BATCH_SOURCE_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM sales_external_reporting_protections WHERE business_date=p_date AND tax_entity_id=p_entity) THEN RAISE EXCEPTION 'SALES_EXPORT_EXTERNALLY_REPORTED'; END IF;
 all_members:=sales_reporting_members_v1(p_date,p_entity);
 -- A previously confirmed receipt may not disappear or change silently. Corrections
 -- remain in the invoice owner's workflow; an unreported batch can be voided.
 IF EXISTS(WITH current_members AS MATERIALIZED(SELECT * FROM jsonb_array_elements(all_members))
 SELECT 1 FROM sales_reporting_claims c LEFT JOIN current_members m ON m.value->>'source'=c.source_system AND m.value->>'id'=c.receipt_id
 WHERE c.tax_entity_id=p_entity AND c.business_date=p_date
 AND (m.value IS NULL OR (m.value->>'source_hash',(m.value->>'store_id')::uuid,(m.value->>'gross')::numeric) IS DISTINCT FROM (c.source_hash,c.store_id,c.gross))) THEN RAISE EXCEPTION 'SALES_BATCH_RECONCILIATION_REQUIRED'; END IF;
 SELECT coalesce(jsonb_agg(m ORDER BY m->>'source',m->>'id'),'[]') INTO selected FROM jsonb_array_elements(all_members)m
 LEFT JOIN sales_reporting_claims c ON c.source_system=m->>'source' AND c.receipt_id=m->>'id' WHERE c.batch_id IS NULL;
 IF jsonb_array_length(selected)=0 THEN RAISE EXCEPTION 'SALES_BATCH_NO_NEW_RECEIPTS'; END IF;
 INSERT INTO sales_reporting_batches(id,business_date,tax_entity_id,source_revision,mapping_revision,members,receipt_count,gross,membership_hash,created_by)
 SELECT p_id,p_date,p_entity,p_source_revision,p_mapping_revision,selected,jsonb_array_length(selected),sum((m->>'gross')::numeric),md5(selected::text),auth.uid() FROM jsonb_array_elements(selected)m RETURNING * INTO b;
 RETURN to_jsonb(b);
END $$;

CREATE FUNCTION public.admin_update_sales_batch_v1(p_id uuid,p_action text,p_payload jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE b sales_reporting_batches; current_members jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT is_super_admin() THEN RAISE EXCEPTION 'SUPER_ADMIN_ONLY'; END IF;
 SELECT * INTO b FROM sales_reporting_batches WHERE id=p_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'SALES_BATCH_NOT_FOUND'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sales-reporting:'||b.tax_entity_id::text||':'||b.business_date::text,0));
 SELECT * INTO b FROM sales_reporting_batches WHERE id=p_id FOR UPDATE;
 IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>4096 THEN RAISE EXCEPTION 'SALES_BATCH_PAYLOAD_INVALID'; END IF;
 IF p_action='generated' THEN
  IF coalesce(p_payload->>'sha256','')!~'^[a-f0-9]{64}$' OR coalesce((p_payload->>'size')::bigint,0) NOT BETWEEN 1 AND 104857600 THEN RAISE EXCEPTION 'SALES_BATCH_FILE_INVALID'; END IF;
  IF b.status<>'draft' THEN
   IF b.status IN('generated','confirmed','reported') AND b.file_sha256=p_payload->>'sha256' AND b.file_size=(p_payload->>'size')::bigint THEN RETURN to_jsonb(b); END IF;
   RAISE EXCEPTION 'SALES_BATCH_FILE_CONFLICT';
  END IF;
  -- Hash is a client-declared artifact digest, not evidence of transmission.
  UPDATE sales_reporting_batches SET status='generated',file_sha256=p_payload->>'sha256',file_size=(p_payload->>'size')::bigint WHERE id=p_id;
 ELSIF p_action='confirm' THEN
  IF p_payload->>'sha256' IS DISTINCT FROM b.file_sha256 THEN RAISE EXCEPTION 'SALES_BATCH_FILE_CONFLICT'; END IF;
  IF b.status IN('confirmed','reported') THEN RETURN to_jsonb(b); END IF;
  IF b.status<>'generated' THEN RAISE EXCEPTION 'SALES_BATCH_NOT_GENERATED'; END IF;
  IF b.source_revision IS DISTINCT FROM pos_sales_export_source_revision(b.business_date,b.tax_entity_id)
   OR b.mapping_revision IS DISTINCT FROM coalesce((SELECT revision FROM sales_invoice_mapping_revisions WHERE tax_entity_id=b.tax_entity_id),0) THEN RAISE EXCEPTION 'SALES_BATCH_SOURCE_CHANGED'; END IF;
  IF EXISTS(SELECT 1 FROM sales_external_reporting_protections WHERE business_date=b.business_date AND tax_entity_id=b.tax_entity_id) THEN RAISE EXCEPTION 'SALES_EXPORT_EXTERNALLY_REPORTED'; END IF;
  current_members:=sales_reporting_members_v1(b.business_date,b.tax_entity_id);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(b.members)m LEFT JOIN jsonb_array_elements(current_members)c ON c->>'source'=m->>'source' AND c->>'id'=m->>'id'
    WHERE c IS NULL OR (c->>'source_hash',c->>'store_id',c->>'gross') IS DISTINCT FROM (m->>'source_hash',m->>'store_id',m->>'gross')) THEN RAISE EXCEPTION 'SALES_BATCH_SOURCE_CHANGED'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(b.members)m JOIN sales_reporting_claims c ON c.source_system=m->>'source' AND c.receipt_id=m->>'id') THEN RAISE EXCEPTION 'SALES_BATCH_RECEIPT_ALREADY_CONFIRMED'; END IF;
  INSERT INTO sales_reporting_claims SELECT m->>'source',m->>'id',p_id,b.business_date,b.tax_entity_id,(m->>'store_id')::uuid,m->>'source_hash',(m->>'gross')::numeric FROM jsonb_array_elements(b.members)m;
  UPDATE sales_reporting_batches SET status='confirmed',confirmed_by=auth.uid(),confirmed_at=now() WHERE id=p_id;
 ELSIF p_action='reported' THEN
  IF p_payload->>'sha256' IS DISTINCT FROM b.file_sha256 OR length(btrim(coalesce(p_payload->>'channel',''))) NOT BETWEEN 1 AND 80
   OR length(btrim(coalesce(p_payload->>'recipient',''))) NOT BETWEEN 1 AND 200 OR length(btrim(coalesce(p_payload->>'reference',''))) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'SALES_BATCH_EXTERNAL_EVIDENCE_REQUIRED'; END IF;
  IF b.status='reported' AND b.external_evidence=p_payload THEN RETURN to_jsonb(b); END IF;
  IF b.status<>'confirmed' THEN RAISE EXCEPTION 'SALES_BATCH_NOT_CONFIRMED'; END IF;
  UPDATE sales_reporting_batches SET status='reported',external_evidence=p_payload,reported_by=auth.uid(),reported_at=now() WHERE id=p_id;
 ELSIF p_action='void' THEN
  IF length(btrim(coalesce(p_payload->>'reason',''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'SALES_BATCH_REASON_REQUIRED'; END IF;
  IF b.status='reported' THEN RAISE EXCEPTION 'SALES_BATCH_REPORTED_IMMUTABLE'; END IF;
  IF b.status='void' THEN RETURN to_jsonb(b); END IF;
  DELETE FROM sales_reporting_claims WHERE batch_id=p_id;
  UPDATE sales_reporting_batches SET status='void',void_reason=p_payload->>'reason',voided_by=auth.uid(),voided_at=now() WHERE id=p_id;
 ELSE RAISE EXCEPTION 'SALES_BATCH_ACTION_INVALID'; END IF;
 SELECT * INTO b FROM sales_reporting_batches WHERE id=p_id;
 RETURN to_jsonb(b);
END $$;
CREATE FUNCTION public.admin_list_sales_batches_v1(p_date date,p_entity uuid,p_before timestamptz DEFAULT NULL,p_before_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
BEGIN
 IF auth.uid() IS NULL OR NOT is_super_admin() THEN RAISE EXCEPTION 'SUPER_ADMIN_ONLY'; END IF;
 RETURN coalesce((SELECT jsonb_agg(to_jsonb(b) ORDER BY created_at DESC,id) FROM (
 SELECT id,business_date,tax_entity_id,status,receipt_count,gross,file_sha256,file_size,created_at,confirmed_by,confirmed_at,reported_at,external_evidence,void_reason FROM sales_reporting_batches WHERE business_date=p_date AND tax_entity_id=p_entity AND (p_before IS NULL OR created_at<p_before OR (created_at=p_before AND id>p_before_id)) ORDER BY created_at DESC,id LIMIT 20)b),'[]');
END $$;
REVOKE ALL ON FUNCTION public.admin_prepare_sales_batch_v1(uuid,date,uuid,text,bigint),public.admin_update_sales_batch_v1(uuid,text,jsonb),public.admin_list_sales_batches_v1(date,uuid,timestamptz,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_prepare_sales_batch_v1(uuid,date,uuid,text,bigint),public.admin_update_sales_batch_v1(uuid,text,jsonb),public.admin_list_sales_batches_v1(date,uuid,timestamptz,uuid) TO authenticated;

-- COMPONENT 20261022120000_procurement_readiness_profiles.sql
-- New-store procurement setup is explicit and versioned. Existing policies and
-- issued policy-1/2/3 documents retain their current contracts.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE TABLE public.procurement_policy_templates (
 id uuid PRIMARY KEY, name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 100),
 revision integer NOT NULL CHECK(revision>0),family_id uuid NOT NULL,
 policy jsonb NOT NULL,approved_by uuid NOT NULL,approved_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(family_id,revision)
);
CREATE TABLE public.procurement_material_specs (
 id uuid PRIMARY KEY,code text NOT NULL CHECK(code~'^[A-Z0-9][A-Z0-9_-]{1,39}$'),revision integer NOT NULL CHECK(revision>0),
 name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 160),base_unit text NOT NULL CHECK(base_unit IN('g','ml','ea')),
 specification text NOT NULL CHECK(length(btrim(specification)) BETWEEN 1 AND 2000),approved_by uuid NOT NULL,approved_at timestamptz NOT NULL DEFAULT now(),UNIQUE(code,revision)
);
CREATE TABLE public.store_procurement_profiles (
 restaurant_id uuid PRIMARY KEY REFERENCES public.restaurants(id) ON DELETE CASCADE,
 template_id uuid NOT NULL REFERENCES public.procurement_policy_templates(id),revision bigint NOT NULL,enforced boolean NOT NULL DEFAULT false,
 applied_by uuid NOT NULL,applied_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.procurement_catalog_approvals (
 id uuid PRIMARY KEY,restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 product_id uuid NOT NULL REFERENCES public.inventory_products(id) ON DELETE CASCADE,
 supplier_item_id uuid NOT NULL REFERENCES public.inventory_supplier_items(id),spec_id uuid NOT NULL REFERENCES public.procurement_material_specs(id),
 valid_from timestamptz NOT NULL,valid_until timestamptz,source_reference text NOT NULL,
 catalog_snapshot jsonb NOT NULL,approved_by uuid NOT NULL,approved_at timestamptz NOT NULL DEFAULT now(),
 CHECK(valid_until IS NULL OR valid_until>valid_from),CHECK(length(btrim(source_reference)) BETWEEN 1 AND 500)
);
CREATE INDEX procurement_catalog_approvals_product ON public.procurement_catalog_approvals(restaurant_id,product_id,approved_at DESC);
ALTER TABLE public.procurement_policy_templates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.procurement_material_specs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.store_procurement_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.procurement_catalog_approvals ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.procurement_policy_templates,public.procurement_material_specs,public.store_procurement_profiles,public.procurement_catalog_approvals FROM PUBLIC,anon,authenticated;
CREATE TRIGGER procurement_policy_templates_immutable BEFORE UPDATE ON public.procurement_policy_templates FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TRIGGER procurement_material_specs_immutable BEFORE UPDATE ON public.procurement_material_specs FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TRIGGER procurement_catalog_approvals_immutable BEFORE UPDATE ON public.procurement_catalog_approvals FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();

CREATE FUNCTION public.procurement_catalog_snapshot_v1(p public.inventory_products,s public.inventory_supplier_items) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('product_code',p.product_code,'name',p.name,'specification',p.specification,'inventory_item_id',p.inventory_item_id,
  'base_unit',p.base_unit,'stock_unit',p.stock_unit,'base_unit_factor',p.base_unit_factor,'receipt_classification',p.receipt_classification,
  'storage_type',p.storage_type,'shelf_life_days',p.shelf_life_days,'supplier_id',s.supplier_id,'supplier_sku',s.supplier_sku,
  'order_unit',s.order_unit,'order_unit_quantity_base',s.order_unit_quantity_base,'min_order_quantity',s.min_order_quantity,
  'unit_price',s.unit_price,'tax_rate',s.tax_rate,'lead_time_days',s.lead_time_days);
$$;
REVOKE ALL ON FUNCTION public.procurement_catalog_snapshot_v1(public.inventory_products,public.inventory_supplier_items) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.admin_publish_procurement_template_v1(p_id uuid,p_family uuid,p_expected_revision integer,p_name text,p_policy jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE prior procurement_policy_templates; expected jsonb;
BEGIN
 PERFORM require_brand_admin_v1();
 IF p_id IS NULL OR p_family IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR length(btrim(coalesce(p_name,''))) NOT BETWEEN 1 AND 100
 OR jsonb_typeof(p_policy) IS DISTINCT FROM 'object' OR octet_length(p_policy::text)>2048
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_policy)k WHERE k NOT IN('stock_freshness_hours','high_value_amount','max_price_increase_percent','quantity_review_multiplier')) THEN RAISE EXCEPTION 'PROCUREMENT_TEMPLATE_INVALID'; END IF;
 IF coalesce((p_policy->>'stock_freshness_hours')::integer,0) NOT BETWEEN 1 AND 720
 OR (p_policy->>'high_value_amount')::numeric<=0 OR (p_policy->>'max_price_increase_percent')::numeric<0 OR (p_policy->>'quantity_review_multiplier')::numeric<1
 OR EXISTS(SELECT 1 FROM jsonb_each_text(p_policy)v WHERE v.value IN('NaN','Infinity','-Infinity')) THEN RAISE EXCEPTION 'PROCUREMENT_TEMPLATE_INVALID'; END IF;
 expected:=jsonb_build_object('approval_policy_version',3,'two_stage_required',true,'three_stage_required',false,'stock_freshness_hours',(p_policy->>'stock_freshness_hours')::integer,
  'high_value_amount',(p_policy->>'high_value_amount')::numeric,'max_price_increase_percent',(p_policy->>'max_price_increase_percent')::numeric,'quantity_review_multiplier',(p_policy->>'quantity_review_multiplier')::numeric);
 PERFORM pg_advisory_xact_lock(hashtextextended('procurement-template:'||p_family,0));
 SELECT * INTO prior FROM procurement_policy_templates WHERE id=p_id;
 IF FOUND THEN
  IF prior.family_id<>p_family OR prior.revision<>p_expected_revision+1 OR prior.name<>btrim(p_name) OR prior.policy<>expected OR prior.approved_by<>auth.uid() THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
  RETURN to_jsonb(prior);
 END IF;
 IF coalesce((SELECT max(revision) FROM procurement_policy_templates WHERE family_id=p_family),0)<>p_expected_revision THEN RAISE EXCEPTION 'PROCUREMENT_TEMPLATE_STALE'; END IF;
 INSERT INTO procurement_policy_templates VALUES(p_id,btrim(p_name),p_expected_revision+1,p_family,expected,auth.uid(),now()) RETURNING * INTO prior;
 RETURN to_jsonb(prior);
END $$;

CREATE FUNCTION public.admin_publish_material_spec_v1(p_id uuid,p_code text,p_expected_revision integer,p_name text,p_base_unit text,p_specification text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE prior procurement_material_specs;
BEGIN
 PERFORM require_brand_admin_v1();
 IF p_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_code IS NULL THEN RAISE EXCEPTION 'MATERIAL_SPEC_INVALID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('material-spec:'||p_code,0));
 SELECT * INTO prior FROM procurement_material_specs WHERE id=p_id;
 IF FOUND THEN
  IF (prior.code,prior.revision,prior.name,prior.base_unit,prior.specification,prior.approved_by) IS DISTINCT FROM (p_code,p_expected_revision+1,btrim(p_name),p_base_unit,btrim(p_specification),auth.uid()) THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
  RETURN to_jsonb(prior);
 END IF;
 IF coalesce((SELECT max(revision) FROM procurement_material_specs WHERE code=p_code),0)<>p_expected_revision THEN RAISE EXCEPTION 'MATERIAL_SPEC_STALE'; END IF;
 INSERT INTO procurement_material_specs VALUES(p_id,p_code,p_expected_revision+1,btrim(p_name),p_base_unit,btrim(p_specification),auth.uid(),now()) RETURNING * INTO prior;
 RETURN to_jsonb(prior);
END $$;

CREATE FUNCTION public.admin_apply_procurement_template_v1(p_store uuid,p_template uuid,p_expected_revision bigint) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE t procurement_policy_templates; profile store_procurement_profiles;
BEGIN
 PERFORM require_brand_admin_v1();
 PERFORM pg_advisory_xact_lock(hashtextextended('store-procurement:'||p_store,0));
 SELECT * INTO t FROM procurement_policy_templates WHERE id=p_template;
 IF NOT FOUND THEN RAISE EXCEPTION 'PROCUREMENT_TEMPLATE_REQUIRED'; END IF;
 SELECT * INTO profile FROM store_procurement_profiles WHERE restaurant_id=p_store;
 IF profile.template_id=p_template AND profile.revision=p_expected_revision+1 THEN RETURN to_jsonb(profile); END IF;
 IF coalesce(profile.revision,0) IS DISTINCT FROM p_expected_revision THEN RAISE EXCEPTION 'PROCUREMENT_PROFILE_STALE'; END IF;
 IF EXISTS(SELECT 1 FROM store_lifecycle WHERE restaurant_id=p_store AND state='closed') THEN RAISE EXCEPTION 'STORE_CLOSED'; END IF;
 INSERT INTO procurement_store_policies(restaurant_id,enabled,two_stage_required,three_stage_required,new_requests_enabled,stock_freshness_hours,high_value_amount,max_price_increase_percent,quantity_review_multiplier)
 VALUES(p_store,true,true,false,true,(t.policy->>'stock_freshness_hours')::int,(t.policy->>'high_value_amount')::numeric,(t.policy->>'max_price_increase_percent')::numeric,(t.policy->>'quantity_review_multiplier')::numeric)
 ON CONFLICT(restaurant_id) DO UPDATE SET enabled=true,two_stage_required=true,three_stage_required=false,new_requests_enabled=true,stock_freshness_hours=EXCLUDED.stock_freshness_hours,
 high_value_amount=EXCLUDED.high_value_amount,max_price_increase_percent=EXCLUDED.max_price_increase_percent,quantity_review_multiplier=EXCLUDED.quantity_review_multiplier,row_version=procurement_store_policies.row_version+1,updated_at=now();
 INSERT INTO store_procurement_profiles(restaurant_id,template_id,revision,applied_by,applied_at) VALUES(p_store,p_template,p_expected_revision+1,auth.uid(),now())
 ON CONFLICT(restaurant_id) DO UPDATE SET template_id=EXCLUDED.template_id,revision=EXCLUDED.revision,applied_by=EXCLUDED.applied_by,applied_at=EXCLUDED.applied_at RETURNING * INTO profile;
 RETURN to_jsonb(profile);
END $$;

CREATE FUNCTION public.admin_approve_procurement_catalog_v1(p_store uuid,p_rows jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 PERFORM require_brand_admin_v1();
 IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 100 OR octet_length(p_rows::text)>131072 THEN RAISE EXCEPTION 'PROCUREMENT_CATALOG_BATCH_LIMIT'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('store-procurement:'||p_store,0));
 IF EXISTS(SELECT 1 FROM jsonb_to_recordset(p_rows)x(id uuid,product_id uuid,supplier_item_id uuid,spec_id uuid,valid_from timestamptz,valid_until timestamptz,source_reference text)
 LEFT JOIN inventory_products p ON p.id=x.product_id AND p.restaurant_id=p_store AND p.is_active AND p.is_orderable
 LEFT JOIN restaurants catalog_store ON catalog_store.id=p.restaurant_id
 LEFT JOIN inventory_supplier_items s ON s.id=x.supplier_item_id AND s.product_id=p.id AND s.is_active
 LEFT JOIN inventory_suppliers supplier ON supplier.id=s.supplier_id AND supplier.status='active' AND (supplier.brand_id IS NULL OR supplier.brand_id=catalog_store.brand_id)
 LEFT JOIN procurement_material_specs spec ON spec.id=x.spec_id AND spec.base_unit=p.base_unit
 LEFT JOIN inventory_items item ON item.id=p.inventory_item_id AND item.restaurant_id=p_store
 WHERE x.id IS NULL OR p.id IS NULL OR s.id IS NULL OR supplier.id IS NULL OR spec.id IS NULL OR x.valid_from IS NULL
 OR (x.valid_until IS NOT NULL AND x.valid_until<=x.valid_from) OR length(btrim(coalesce(x.source_reference,''))) NOT BETWEEN 1 AND 500
 OR nullif(btrim(p.product_code),'') IS NULL OR nullif(btrim(p.specification),'') IS NULL OR nullif(btrim(s.order_unit),'') IS NULL
 OR (p.receipt_classification='stock' AND item.id IS NULL)) THEN RAISE EXCEPTION 'PROCUREMENT_CATALOG_INCOMPLETE'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_to_recordset(p_rows)x(id uuid,product_id uuid,supplier_item_id uuid,spec_id uuid,valid_from timestamptz,valid_until timestamptz,source_reference text)
 JOIN inventory_products p ON p.id=x.product_id JOIN inventory_supplier_items s ON s.id=x.supplier_item_id JOIN procurement_catalog_approvals a ON a.id=x.id
 WHERE (a.restaurant_id,a.product_id,a.supplier_item_id,a.spec_id,a.valid_from,a.valid_until,a.source_reference,a.catalog_snapshot,a.approved_by)
 IS DISTINCT FROM (p_store,x.product_id,x.supplier_item_id,x.spec_id,x.valid_from,x.valid_until,btrim(x.source_reference),procurement_catalog_snapshot_v1(p,s),auth.uid())) THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
 INSERT INTO procurement_catalog_approvals(id,restaurant_id,product_id,supplier_item_id,spec_id,valid_from,valid_until,source_reference,catalog_snapshot,approved_by)
 SELECT x.id,p_store,x.product_id,x.supplier_item_id,x.spec_id,x.valid_from,x.valid_until,btrim(x.source_reference),procurement_catalog_snapshot_v1(p,s),auth.uid()
 FROM jsonb_to_recordset(p_rows)x(id uuid,product_id uuid,supplier_item_id uuid,spec_id uuid,valid_from timestamptz,valid_until timestamptz,source_reference text)
 JOIN inventory_products p ON p.id=x.product_id JOIN inventory_supplier_items s ON s.id=x.supplier_item_id ON CONFLICT(id) DO NOTHING;
 SELECT jsonb_agg(to_jsonb(a) ORDER BY a.product_id) INTO result FROM procurement_catalog_approvals a JOIN jsonb_to_recordset(p_rows)x(id uuid) ON x.id=a.id;
 RETURN result;
END $$;

CREATE FUNCTION public.store_procurement_readiness_v1(p_stores uuid[]) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 IF p_stores IS NULL OR cardinality(p_stores) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'PROCUREMENT_BATCH_LIMIT'; END IF;
 IF EXISTS(SELECT restaurant_id FROM inventory_products WHERE restaurant_id=ANY(p_stores) GROUP BY restaurant_id HAVING count(*)>2000) THEN RAISE EXCEPTION 'PROCUREMENT_CATALOG_LIMIT_2000'; END IF;
 WITH shops AS MATERIALIZED(SELECT r.id,r.is_active,coalesce(l.state,'closed') lifecycle FROM restaurants r LEFT JOIN store_lifecycle l ON l.restaurant_id=r.id WHERE r.id=ANY(p_stores)),
 valid_pos AS MATERIALIZED(SELECT DISTINCT rr.restaurant_id,rr.stage FROM procurement_role_roster rr JOIN users u ON u.auth_id=rr.subject_id AND u.is_active JOIN auth.users au ON au.id=u.auth_id
 JOIN user_store_access access ON access.user_id=u.id AND access.store_id=rr.restaurant_id AND access.is_active
 WHERE rr.restaurant_id=ANY(p_stores) AND rr.system='pos' AND rr.valid_from<=now() AND rr.valid_until>now()
 AND ((rr.stage IN('requester','receiver','verifier') AND u.role='inventory_orderer') OR (rr.stage='store' AND u.role='store_admin') OR (rr.stage='finance' AND u.role='inventory_accounting'))
 UNION SELECT DISTINCT a.store_id,'finance' FROM user_store_access a JOIN users u ON u.id=a.user_id AND u.is_active AND u.role='inventory_accounting' JOIN auth.users au ON au.id=u.auth_id
 WHERE a.store_id=ANY(p_stores) AND a.is_active),
 valid_office AS MATERIALIZED(SELECT restaurant_id,stage FROM procurement_role_roster WHERE restaurant_id=ANY(p_stores) AND system='office' AND stage IN('purchase','finance') AND valid_from<=now() AND valid_until>now()),
 stages AS(SELECT restaurant_id,stage FROM valid_pos UNION SELECT restaurant_id,stage FROM valid_office),
 valid_catalog AS MATERIALIZED(SELECT DISTINCT p.id FROM inventory_products p JOIN restaurants catalog_store ON catalog_store.id=p.restaurant_id JOIN procurement_catalog_approvals a ON a.product_id=p.id AND a.restaurant_id=p.restaurant_id
 JOIN inventory_supplier_items s ON s.id=a.supplier_item_id AND s.product_id=p.id AND s.is_active JOIN inventory_suppliers supplier ON supplier.id=s.supplier_id AND supplier.status='active' AND (supplier.brand_id IS NULL OR supplier.brand_id=catalog_store.brand_id)
 JOIN procurement_material_specs spec ON spec.id=a.spec_id AND spec.base_unit=p.base_unit
 WHERE p.restaurant_id=ANY(p_stores) AND a.valid_from<=now() AND (a.valid_until IS NULL OR a.valid_until>now()) AND a.catalog_snapshot=procurement_catalog_snapshot_v1(p,s)),
 catalog AS(SELECT p.restaurant_id,count(*) total,count(*) FILTER(WHERE valid.id IS NULL) missing FROM inventory_products p LEFT JOIN valid_catalog valid ON valid.id=p.id WHERE p.restaurant_id=ANY(p_stores) AND p.is_active AND p.is_orderable GROUP BY p.restaurant_id),
 policy AS(SELECT profile.restaurant_id,profile.revision,profile.template_id,profile.enforced,
  p.enabled AND p.two_stage_required AND NOT p.three_stage_required AND p.new_requests_enabled
  AND (p.stock_freshness_hours,p.high_value_amount,p.max_price_increase_percent,p.quantity_review_multiplier)
  IS NOT DISTINCT FROM ((t.policy->>'stock_freshness_hours')::integer,(t.policy->>'high_value_amount')::numeric,(t.policy->>'max_price_increase_percent')::numeric,(t.policy->>'quantity_review_multiplier')::numeric) valid
 FROM store_procurement_profiles profile JOIN procurement_policy_templates t ON t.id=profile.template_id JOIN procurement_store_policies p ON p.restaurant_id=profile.restaurant_id WHERE profile.restaurant_id=ANY(p_stores)),
 stage_summary AS(SELECT restaurant_id,jsonb_object_agg(stage,true) roles FROM stages GROUP BY restaurant_id),
 checks AS(SELECT shop.id,policy.revision,policy.template_id,coalesce(policy.enforced,false) enforced,coalesce(catalog.total,0) product_count,coalesce(catalog.missing,0) missing_catalog,
 jsonb_build_object('store_open_for_procurement',shop.is_active AND shop.lifecycle<>'closed','policy',coalesce(policy.valid,false),
 'requester',coalesce(roles?'requester',false),'store_manager',coalesce(roles?'store',false),'receiver',coalesce(roles?'receiver',false),'verifier',coalesce(roles?'verifier',false),
 'buyer',coalesce(roles?'purchase',false),'accounting',coalesce(roles?'finance',false),
 'office_connected',coalesce(o.office_connected,false),'catalog',coalesce(catalog.total>0 AND catalog.missing=0,false)) checks
 FROM shops shop LEFT JOIN policy ON policy.restaurant_id=shop.id LEFT JOIN catalog ON catalog.restaurant_id=shop.id LEFT JOIN stage_summary ON stage_summary.restaurant_id=shop.id LEFT JOIN procurement_store_onboarding o ON o.restaurant_id=shop.id)
 SELECT jsonb_agg(to_jsonb(c)||jsonb_build_object('ready',NOT EXISTS(SELECT 1 FROM jsonb_each(c.checks)v WHERE v.value<>'true'::jsonb)) ORDER BY id) INTO result FROM checks c;
 RETURN coalesce(result,'[]');
END $$;
REVOKE ALL ON FUNCTION public.store_procurement_readiness_v1(uuid[]) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.admin_get_procurement_setup_v1(p_store uuid,p_after uuid DEFAULT NULL,p_limit integer DEFAULT 100) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE rows jsonb; ids uuid[];
BEGIN
 PERFORM require_admin_actor_for_restaurant(p_store);
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'PROCUREMENT_PAGE_LIMIT'; END IF;
 SELECT array_agg(id) INTO ids FROM(SELECT id FROM inventory_products WHERE restaurant_id=p_store AND (p_after IS NULL OR id>p_after) ORDER BY id LIMIT p_limit)p;
 WITH suppliers AS(SELECT s.product_id,jsonb_agg(to_jsonb(s)||jsonb_build_object('supplier_name',supplier.supplier_name) ORDER BY s.id) rows FROM inventory_supplier_items s JOIN inventory_suppliers supplier ON supplier.id=s.supplier_id WHERE s.product_id=ANY(ids) AND s.is_active GROUP BY s.product_id),
 approvals AS(SELECT DISTINCT ON(product_id) * FROM procurement_catalog_approvals WHERE product_id=ANY(ids) ORDER BY product_id,approved_at DESC,id)
 SELECT coalesce(jsonb_agg(to_jsonb(p)||jsonb_build_object('suppliers',coalesce(s.rows,'[]'),'approval',to_jsonb(a)) ORDER BY p.id),'[]') INTO rows FROM inventory_products p LEFT JOIN suppliers s ON s.product_id=p.id LEFT JOIN approvals a ON a.product_id=p.id WHERE p.id=ANY(ids);
 RETURN jsonb_build_object('readiness',store_procurement_readiness_v1(ARRAY[p_store])->0,'products',rows,
  'templates',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY approved_at DESC,id) FROM(SELECT * FROM procurement_policy_templates ORDER BY approved_at DESC,id LIMIT 100)t),'[]'),
  'specs',coalesce((SELECT jsonb_agg(to_jsonb(s) ORDER BY code,revision DESC) FROM(SELECT * FROM procurement_material_specs ORDER BY approved_at DESC,id LIMIT 200)s),'[]'));
END $$;

CREATE FUNCTION public.store_guard_procurement_intake_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE ids uuid[]; readiness jsonb;
BEGIN
 IF TG_OP='UPDATE' THEN
  SELECT array_agg(DISTINCT n.restaurant_id) INTO ids FROM new_procurement n JOIN old_procurement before_row ON before_row.id=n.id
  WHERE n.status IS DISTINCT FROM before_row.status AND n.status IN('submitted','office_review','approved','allocated')
  AND (EXISTS(SELECT 1 FROM store_registration_requests q WHERE q.store_id=n.restaurant_id) OR EXISTS(SELECT 1 FROM store_procurement_profiles p WHERE p.restaurant_id=n.restaurant_id AND p.enforced));
 ELSE
 SELECT array_agg(DISTINCT n.restaurant_id) INTO ids FROM new_procurement n WHERE
 (EXISTS(SELECT 1 FROM store_registration_requests q WHERE q.store_id=n.restaurant_id) OR EXISTS(SELECT 1 FROM store_procurement_profiles p WHERE p.restaurant_id=n.restaurant_id AND p.enforced));
 END IF;
 IF ids IS NULL THEN RETURN NULL; END IF;
 -- Insert batches are bounded; no store-by-store readiness queries.
 readiness:=store_procurement_readiness_v1(ids);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(readiness)r WHERE r->>'ready'<>'true') THEN RAISE EXCEPTION 'STORE_PROCUREMENT_NOT_READY'; END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER store_guard_procurement_intake AFTER INSERT ON public.inventory_purchase_requests REFERENCING NEW TABLE AS new_procurement FOR EACH STATEMENT EXECUTE FUNCTION public.store_guard_procurement_intake_v1();
CREATE TRIGGER store_guard_procurement_progress AFTER UPDATE ON public.inventory_purchase_requests REFERENCING OLD TABLE AS old_procurement NEW TABLE AS new_procurement FOR EACH STATEMENT EXECUTE FUNCTION public.store_guard_procurement_intake_v1();
REVOKE ALL ON FUNCTION public.store_guard_procurement_intake_v1() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.admin_publish_procurement_template_v1(uuid,uuid,integer,text,jsonb),public.admin_publish_material_spec_v1(uuid,text,integer,text,text,text),public.admin_apply_procurement_template_v1(uuid,uuid,bigint),public.admin_approve_procurement_catalog_v1(uuid,jsonb),public.admin_get_procurement_setup_v1(uuid,uuid,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_publish_procurement_template_v1(uuid,uuid,integer,text,jsonb),public.admin_publish_material_spec_v1(uuid,text,integer,text,text,text),public.admin_apply_procurement_template_v1(uuid,uuid,bigint),public.admin_approve_procurement_catalog_v1(uuid,jsonb),public.admin_get_procurement_setup_v1(uuid,uuid,integer) TO authenticated;

CREATE FUNCTION public.admin_activate_procurement_profile_v1(p_store uuid,p_expected_revision bigint) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE ready jsonb; profile store_procurement_profiles;
BEGIN
 PERFORM require_brand_admin_v1();
 PERFORM pg_advisory_xact_lock(hashtextextended('store-procurement:'||p_store,0));
 SELECT * INTO profile FROM store_procurement_profiles WHERE restaurant_id=p_store FOR UPDATE;
 IF profile.restaurant_id IS NULL OR profile.revision IS DISTINCT FROM p_expected_revision THEN RAISE EXCEPTION 'PROCUREMENT_PROFILE_STALE'; END IF;
 ready:=store_procurement_readiness_v1(ARRAY[p_store])->0;
 IF ready->>'ready' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'STORE_PROCUREMENT_NOT_READY'; END IF;
 UPDATE store_procurement_profiles SET enforced=true WHERE restaurant_id=p_store RETURNING * INTO profile;
 RETURN to_jsonb(profile);
END $$;
REVOKE ALL ON FUNCTION public.admin_activate_procurement_profile_v1(uuid,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_activate_procurement_profile_v1(uuid,bigint) TO authenticated;

-- COMPONENT 20261022130000_procurement_quality_profiles.sql
-- Approved, immutable item criteria. PO lines freeze their version; an explicit
-- amendment is required to change criteria for an already-issued PO.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE TABLE public.procurement_quality_profiles (
 id uuid PRIMARY KEY,restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 product_id uuid NOT NULL REFERENCES public.inventory_products(id) ON DELETE CASCADE,revision integer NOT NULL CHECK(revision>0),
 criteria jsonb NOT NULL,reason text NOT NULL,approved_by uuid NOT NULL,approved_at timestamptz NOT NULL DEFAULT now(),UNIQUE(product_id,revision)
);
CREATE TABLE public.procurement_order_quality (
 order_line_id uuid PRIMARY KEY REFERENCES public.inventory_purchase_order_lines(id) ON DELETE CASCADE,
 restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 profile_id uuid NOT NULL REFERENCES public.procurement_quality_profiles(id),
 catalog_approval_id uuid NOT NULL REFERENCES public.procurement_catalog_approvals(id),
 template_id uuid NOT NULL REFERENCES public.procurement_policy_templates(id),
 captured_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.procurement_quality_amendments (
 id uuid PRIMARY KEY,order_line_id uuid NOT NULL REFERENCES public.procurement_order_quality(order_line_id) ON DELETE CASCADE,
 profile_id uuid NOT NULL REFERENCES public.procurement_quality_profiles(id),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 5 AND 1000),
 approved_by uuid NOT NULL,approved_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX procurement_quality_amendments_line ON public.procurement_quality_amendments(order_line_id,approved_at DESC,id);
ALTER TABLE public.procurement_quality_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.procurement_order_quality ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.procurement_quality_amendments ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.procurement_quality_profiles,public.procurement_order_quality,public.procurement_quality_amendments FROM PUBLIC,anon,authenticated;
CREATE TRIGGER procurement_quality_profiles_immutable BEFORE UPDATE ON public.procurement_quality_profiles FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TRIGGER procurement_order_quality_immutable BEFORE UPDATE ON public.procurement_order_quality FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TRIGGER procurement_quality_amendments_immutable BEFORE UPDATE ON public.procurement_quality_amendments FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE FUNCTION public.admin_publish_quality_profile_v1(p_id uuid,p_store uuid,p_product uuid,p_expected_revision integer,p_criteria jsonb,p_reason text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE prior procurement_quality_profiles;
BEGIN
 PERFORM require_brand_admin_v1();
 IF p_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR NOT EXISTS(SELECT 1 FROM inventory_products WHERE id=p_product AND restaurant_id=p_store AND is_active)
 OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 5 AND 1000 OR jsonb_typeof(p_criteria) IS DISTINCT FROM 'object' OR octet_length(p_criteria::text)>4096 THEN RAISE EXCEPTION 'QUALITY_PROFILE_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_criteria)k WHERE k NOT IN('temperature_required','temperature_min_c','temperature_max_c','expiry_required','min_remaining_days','min_sample_count','photo_required','lot_required'))
 OR EXISTS(SELECT 1 FROM unnest(ARRAY['temperature_required','expiry_required','photo_required','lot_required'])k WHERE jsonb_typeof(p_criteria->k) IS DISTINCT FROM 'boolean')
 OR jsonb_typeof(p_criteria->'min_sample_count') IS DISTINCT FROM 'number' OR (p_criteria->>'min_sample_count')::numeric NOT BETWEEN 1 AND 1000 OR (p_criteria->>'min_sample_count')::numeric<>trunc((p_criteria->>'min_sample_count')::numeric)
 THEN RAISE EXCEPTION 'QUALITY_PROFILE_INVALID'; END IF;
 IF (p_criteria->>'temperature_required')::boolean THEN
  IF jsonb_typeof(p_criteria->'temperature_min_c') IS DISTINCT FROM 'number' OR jsonb_typeof(p_criteria->'temperature_max_c') IS DISTINCT FROM 'number'
  OR (p_criteria->>'temperature_min_c')::numeric NOT BETWEEN -100 AND 100 OR (p_criteria->>'temperature_max_c')::numeric NOT BETWEEN -100 AND 100
  OR (p_criteria->>'temperature_min_c')::numeric>(p_criteria->>'temperature_max_c')::numeric THEN RAISE EXCEPTION 'QUALITY_TEMPERATURE_CRITERIA_REQUIRED'; END IF;
 ELSIF coalesce(p_criteria->'temperature_min_c','null')<>'null'::jsonb OR coalesce(p_criteria->'temperature_max_c','null')<>'null'::jsonb THEN RAISE EXCEPTION 'QUALITY_NOT_APPLICABLE_CONFLICT'; END IF;
 IF (p_criteria->>'expiry_required')::boolean THEN
  IF jsonb_typeof(p_criteria->'min_remaining_days') IS DISTINCT FROM 'number' OR (p_criteria->>'min_remaining_days')::numeric NOT BETWEEN 0 AND 3650
  OR (p_criteria->>'min_remaining_days')::numeric<>trunc((p_criteria->>'min_remaining_days')::numeric) THEN RAISE EXCEPTION 'QUALITY_EXPIRY_CRITERIA_REQUIRED'; END IF;
 ELSIF coalesce(p_criteria->'min_remaining_days','null')<>'null'::jsonb THEN RAISE EXCEPTION 'QUALITY_NOT_APPLICABLE_CONFLICT'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('quality-product:'||p_product,0));
 SELECT * INTO prior FROM procurement_quality_profiles WHERE id=p_id;
 IF FOUND THEN
  IF (prior.restaurant_id,prior.product_id,prior.revision,prior.criteria,prior.reason,prior.approved_by) IS DISTINCT FROM(p_store,p_product,p_expected_revision+1,p_criteria,btrim(p_reason),auth.uid()) THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
  RETURN to_jsonb(prior);
 END IF;
 IF coalesce((SELECT max(revision) FROM procurement_quality_profiles WHERE product_id=p_product),0)<>p_expected_revision THEN RAISE EXCEPTION 'QUALITY_PROFILE_STALE'; END IF;
 INSERT INTO procurement_quality_profiles VALUES(p_id,p_store,p_product,p_expected_revision+1,p_criteria,btrim(p_reason),auth.uid(),now()) RETURNING * INTO prior;
 RETURN to_jsonb(prior);
END $$;

CREATE FUNCTION public.store_capture_order_quality_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE ids uuid[];
BEGIN
 SELECT array_agg(n.id) INTO ids FROM new_quality_order_lines n JOIN inventory_purchase_orders o ON o.id=n.purchase_order_id
 WHERE EXISTS(SELECT 1 FROM store_registration_requests r WHERE r.store_id=o.restaurant_id)
 OR EXISTS(SELECT 1 FROM store_procurement_profiles p WHERE p.restaurant_id=o.restaurant_id AND p.enforced);
 IF ids IS NULL THEN RETURN NULL; END IF;
 IF cardinality(ids)>200 THEN RAISE EXCEPTION 'INVENTORY_RECEIPT_LINES_REQUIRED'; END IF;
 WITH profiles AS MATERIALIZED(SELECT DISTINCT ON(q.product_id) q.* FROM procurement_quality_profiles q JOIN new_quality_order_lines n ON n.product_id=q.product_id WHERE n.id=ANY(ids) ORDER BY q.product_id,q.revision DESC),
 catalogs AS MATERIALIZED(SELECT DISTINCT ON(n.id) n.id line_id,a.id catalog_id FROM new_quality_order_lines n JOIN inventory_products p ON p.id=n.product_id
 JOIN inventory_supplier_items s ON s.id=n.supplier_item_id JOIN procurement_catalog_approvals a ON a.product_id=n.product_id AND a.supplier_item_id=n.supplier_item_id AND a.restaurant_id=p.restaurant_id
 WHERE n.id=ANY(ids) AND a.valid_from<=now() AND (a.valid_until IS NULL OR a.valid_until>now()) AND a.catalog_snapshot=procurement_catalog_snapshot_v1(p,s) ORDER BY n.id,a.approved_at DESC,a.id)
 INSERT INTO procurement_order_quality(order_line_id,restaurant_id,profile_id,catalog_approval_id,template_id)
 SELECT n.id,o.restaurant_id,q.id,a.catalog_id,profile.template_id FROM new_quality_order_lines n JOIN inventory_purchase_orders o ON o.id=n.purchase_order_id
 JOIN profiles q ON q.product_id=n.product_id AND q.restaurant_id=o.restaurant_id JOIN catalogs a ON a.line_id=n.id JOIN store_procurement_profiles profile ON profile.restaurant_id=o.restaurant_id WHERE n.id=ANY(ids);
 IF (SELECT count(*) FROM procurement_order_quality WHERE order_line_id=ANY(ids))<>cardinality(ids) THEN RAISE EXCEPTION 'PROCUREMENT_ORDER_CRITERIA_REQUIRED'; END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER store_capture_order_quality AFTER INSERT ON public.inventory_purchase_order_lines REFERENCING NEW TABLE AS new_quality_order_lines FOR EACH STATEMENT EXECUTE FUNCTION public.store_capture_order_quality_v1();

CREATE FUNCTION public.admin_amend_order_quality_v1(p_id uuid,p_line uuid,p_profile uuid,p_reason text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE prior procurement_quality_amendments; ord uuid;
BEGIN
 PERFORM require_brand_admin_v1();
 SELECT purchase_order_id INTO ord FROM inventory_purchase_order_lines WHERE id=p_line;
 PERFORM 1 FROM inventory_purchase_orders WHERE id=ord FOR UPDATE;
 IF p_id IS NULL OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 5 AND 1000 OR NOT EXISTS(
  SELECT 1 FROM procurement_order_quality q JOIN inventory_purchase_order_lines l ON l.id=q.order_line_id
  JOIN procurement_quality_profiles p ON p.id=p_profile AND p.product_id=l.product_id AND p.restaurant_id=q.restaurant_id WHERE q.order_line_id=p_line) THEN RAISE EXCEPTION 'QUALITY_AMENDMENT_INVALID'; END IF;
 SELECT * INTO prior FROM procurement_quality_amendments WHERE id=p_id;
 IF FOUND THEN
  IF (prior.order_line_id,prior.profile_id,prior.reason,prior.approved_by) IS DISTINCT FROM (p_line,p_profile,btrim(p_reason),auth.uid()) THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
  RETURN to_jsonb(prior);
 END IF;
 INSERT INTO procurement_quality_amendments(id,order_line_id,profile_id,reason,approved_by) VALUES(p_id,p_line,p_profile,btrim(p_reason),auth.uid()) RETURNING * INTO prior;
 RETURN to_jsonb(prior);
END $$;

CREATE FUNCTION public.procurement_effective_quality_v1(p_lines uuid[]) RETURNS TABLE(order_line_id uuid,profile_id uuid,revision integer,criteria jsonb,amendment_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
 WITH amendments AS(SELECT DISTINCT ON(order_line_id) order_line_id,profile_id,id FROM procurement_quality_amendments WHERE order_line_id=ANY(p_lines) ORDER BY order_line_id,approved_at DESC,id DESC)
 SELECT q.order_line_id,p.id,p.revision,p.criteria,a.id FROM procurement_order_quality q LEFT JOIN amendments a ON a.order_line_id=q.order_line_id
 JOIN procurement_quality_profiles p ON p.id=coalesce(a.profile_id,q.profile_id) WHERE q.order_line_id=ANY(p_lines);
$$;
CREATE FUNCTION public.procurement_enrich_quality_lines_v1(p_store uuid,p_lines jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE ids uuid[]; result jsonb;
BEGIN
 IF jsonb_typeof(p_lines) IS DISTINCT FROM 'array' OR jsonb_array_length(p_lines) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'INVENTORY_RECEIPT_LINES_REQUIRED'; END IF;
 SELECT array_agg((l->>'purchase_order_line_id')::uuid) INTO ids FROM jsonb_array_elements(p_lines)l;
 IF EXISTS(SELECT 1 FROM procurement_order_quality WHERE order_line_id=ANY(ids) AND restaurant_id<>p_store) THEN RAISE EXCEPTION 'PROCUREMENT_SCOPE_FORBIDDEN'; END IF;
 SELECT jsonb_agg(CASE WHEN q.order_line_id IS NULL THEN l.value ELSE jsonb_set(l.value,'{inspection}',coalesce(l.value->'inspection','{}')||jsonb_build_object('quality_snapshot',to_jsonb(q),'employee_snapshot',CASE WHEN e.id IS NULL THEN NULL ELSE jsonb_build_object('id',e.id,'name',e.full_name,'employee_number',e.employee_number,'store_id',e.store_id) END)) END ORDER BY l.ordinality) INTO result
 FROM jsonb_array_elements(p_lines) WITH ORDINALITY l(value,ordinality) LEFT JOIN procurement_effective_quality_v1(ids)q ON q.order_line_id=(l.value->>'purchase_order_line_id')::uuid LEFT JOIN store_employees e ON e.id=nullif(l.value->'inspection'->>'employee_id','')::uuid AND e.store_id=p_store AND e.is_active;
 RETURN result;
END $$;
ALTER FUNCTION public.procurement_validate_inspection_batch(uuid,jsonb) RENAME TO procurement_validate_inspection_before_quality;
REVOKE ALL ON FUNCTION public.procurement_validate_inspection_before_quality(uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.procurement_validate_inspection_batch(p_store_id uuid,p_lines jsonb) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE inspected jsonb; ids uuid[]; today date:=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
BEGIN
 PERFORM procurement_validate_inspection_before_quality(p_store_id,p_lines);
 SELECT array_agg((x->>'purchase_order_line_id')::uuid) INTO ids FROM jsonb_array_elements(p_lines)x;
 SELECT coalesce(jsonb_agg(jsonb_build_object('line',x,'profile',to_jsonb(q),'accepted',coalesce((x->>'accepted_quantity_base')::numeric,(x->>'received_quantity_base')::numeric-coalesce((x->>'rejected_quantity_base')::numeric,0)))),'[]') INTO inspected
 FROM jsonb_array_elements(p_lines)x JOIN procurement_effective_quality_v1(ids)q ON q.order_line_id=(x->>'purchase_order_line_id')::uuid;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(inspected)x WHERE (x->'line'->>'received_quantity_base')::numeric>0 AND
  (x->'line'->'inspection'->>'quality_profile_id' IS DISTINCT FROM x->'profile'->>'profile_id'
  OR x->'line'->'inspection'->'quality_snapshot' IS DISTINCT FROM x->'profile')) THEN RAISE EXCEPTION 'QUALITY_REINSPECTION_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(inspected)x LEFT JOIN store_employees e ON e.id=nullif(x->'line'->'inspection'->>'employee_id','')::uuid AND e.store_id=p_store_id AND e.is_active WHERE (x->>'accepted')::numeric>0 AND e.id IS NULL) THEN RAISE EXCEPTION 'QUALITY_INSPECTOR_EMPLOYEE_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(inspected)x WHERE (x->>'accepted')::numeric>0 AND
  (coalesce(x->'line'->'inspection'->>'sample_count','')!~'^[0-9]{1,4}$' OR coalesce((nullif(x->'line'->'inspection'->>'sample_count',''))::integer,0)<(x->'profile'->'criteria'->>'min_sample_count')::integer)) THEN RAISE EXCEPTION 'QUALITY_SAMPLE_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(inspected)x WHERE (x->>'accepted')::numeric>0 AND (x->'profile'->'criteria'->>'temperature_required')::boolean AND
  (nullif(x->'line'->'inspection'->>'temperature_c','') IS NULL OR (x->'line'->'inspection'->>'temperature_c')::numeric::text IN('NaN','Infinity','-Infinity')
   OR (x->'line'->'inspection'->>'temperature_c')::numeric NOT BETWEEN (x->'profile'->'criteria'->>'temperature_min_c')::numeric AND (x->'profile'->'criteria'->>'temperature_max_c')::numeric)) THEN RAISE EXCEPTION 'QUALITY_TEMPERATURE_OUT_OF_RANGE'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(inspected)x WHERE (x->>'accepted')::numeric>0 AND (x->'profile'->'criteria'->>'expiry_required')::boolean AND
  (coalesce((x->'line'->'inspection'->>'expiry_not_applicable')::boolean,false) OR nullif(x->'line'->'inspection'->>'expiry_date','') IS NULL
   OR (x->'line'->'inspection'->>'expiry_date')::date<today+(x->'profile'->'criteria'->>'min_remaining_days')::integer)) THEN RAISE EXCEPTION 'QUALITY_REMAINING_SHELF_LIFE_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(inspected)x WHERE (x->>'accepted')::numeric>0 AND (x->'profile'->'criteria'->>'photo_required')::boolean
  AND (jsonb_typeof(x->'line'->'inspection'->'photo_paths') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'line'->'inspection'->'photo_paths')=0)) THEN RAISE EXCEPTION 'QUALITY_PHOTO_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(inspected)x CROSS JOIN LATERAL jsonb_array_elements_text(x->'line'->'inspection'->'photo_paths')photo(path)
 LEFT JOIN storage.objects o ON o.bucket_id='inventory-receipt-statements' AND o.name=photo.path
 WHERE (x->>'accepted')::numeric>0 AND (x->'profile'->'criteria'->>'photo_required')::boolean AND coalesce(lower(o.metadata->>'mimetype'),'') NOT IN('image/jpeg','image/png')) THEN RAISE EXCEPTION 'QUALITY_PHOTO_REQUIRED'; END IF;

END $$;
REVOKE ALL ON FUNCTION public.store_capture_order_quality_v1(),public.procurement_effective_quality_v1(uuid[]),public.procurement_enrich_quality_lines_v1(uuid,jsonb),public.procurement_validate_inspection_batch(uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;

DO $$ DECLARE d text; BEGIN
 d:=pg_get_functiondef('public.submit_inventory_receipt_batch(uuid,uuid,integer,integer,text,jsonb,text,text,text,date,text)'::regprocedure);
 IF position('IF v_order.workflow_version=2 AND v_order.procurement_status' IN d)=0 THEN RAISE EXCEPTION 'QUALITY_SUBMISSION_PATCH_MISMATCH'; END IF;
 d:=replace(d,'IF v_order.workflow_version=2 AND v_order.procurement_status','p_lines:=public.procurement_enrich_quality_lines_v1(v_order.restaurant_id,p_lines); IF v_order.workflow_version=2 AND v_order.procurement_status');
 EXECUTE d;
 d:=pg_get_functiondef('public.store_procurement_readiness_v1(uuid[])'::regprocedure);
 IF position('catalog AS(' IN d)=0 OR position('LEFT JOIN policy ON' IN d)=0 THEN RAISE EXCEPTION 'QUALITY_READINESS_PATCH_MISMATCH'; END IF;
 d:=replace(d,'catalog AS(', 'quality AS(SELECT p.restaurant_id,bool_and(q.product_id IS NOT NULL) ready FROM inventory_products p LEFT JOIN (SELECT DISTINCT product_id FROM procurement_quality_profiles WHERE restaurant_id=ANY(p_stores))q ON q.product_id=p.id WHERE p.restaurant_id=ANY(p_stores) AND p.is_active AND p.is_orderable GROUP BY p.restaurant_id), catalog AS(');
 d:=replace(d,'''catalog'',coalesce(catalog.total>0', '''quality'',coalesce(quality.ready,false),''catalog'',coalesce(catalog.total>0');
 d:=replace(d,'LEFT JOIN policy ON', 'LEFT JOIN quality ON quality.restaurant_id=shop.id LEFT JOIN policy ON');
 EXECUTE d;
 d:=pg_get_functiondef('public.admin_get_procurement_setup_v1(uuid,uuid,integer)'::regprocedure);
 d:=replace(d,'approvals AS(', 'quality AS(SELECT DISTINCT ON(product_id) * FROM procurement_quality_profiles WHERE product_id=ANY(ids) ORDER BY product_id,revision DESC), approvals AS(');
 d:=replace(d,'''approval'',to_jsonb(a)', '''approval'',to_jsonb(a),''quality'',to_jsonb(q)');
 d:=replace(d,'LEFT JOIN approvals a ON a.product_id=p.id', 'LEFT JOIN approvals a ON a.product_id=p.id LEFT JOIN quality q ON q.product_id=p.id');
 IF position('LEFT JOIN quality q' IN d)=0 THEN RAISE EXCEPTION 'QUALITY_SETUP_PATCH_MISMATCH'; END IF;
 EXECUTE d;
END $$;

ALTER FUNCTION public.get_inventory_workflow_detail(uuid) RENAME TO get_inventory_workflow_detail_before_quality;
REVOKE ALL ON FUNCTION public.get_inventory_workflow_detail_before_quality(uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.get_inventory_workflow_detail(p_purchase_order_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE result jsonb; ids uuid[]; lines jsonb;
BEGIN
 result:=get_inventory_workflow_detail_before_quality(p_purchase_order_id);
 SELECT array_agg(id) INTO ids FROM inventory_purchase_order_lines WHERE purchase_order_id=p_purchase_order_id;
 SELECT coalesce(jsonb_agg(l.value||jsonb_build_object('quality',to_jsonb(q)) ORDER BY l.ordinality),'[]') INTO lines
 FROM jsonb_array_elements(result->'lines') WITH ORDINALITY l(value,ordinality) LEFT JOIN procurement_effective_quality_v1(ids)q ON q.order_line_id=(l.value->>'id')::uuid;
 RETURN jsonb_set(result,'{lines}',lines)||jsonb_build_object('inspection_employees',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',full_name) ORDER BY employee_number) FROM (SELECT e.id,e.full_name,e.employee_number FROM store_employees e JOIN inventory_purchase_orders o ON o.restaurant_id=e.store_id WHERE o.id=p_purchase_order_id AND e.is_active ORDER BY e.employee_number LIMIT 200)e),'[]'));

END $$;
REVOKE ALL ON FUNCTION public.admin_publish_quality_profile_v1(uuid,uuid,uuid,integer,jsonb,text),public.admin_amend_order_quality_v1(uuid,uuid,uuid,text),public.get_inventory_workflow_detail(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_publish_quality_profile_v1(uuid,uuid,uuid,integer,jsonb,text),public.admin_amend_order_quality_v1(uuid,uuid,uuid,text),public.get_inventory_workflow_detail(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_inventory_workflow_detail(uuid) TO service_role;

CREATE FUNCTION public.store_guard_order_quality_identity_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM new_quality_lines n JOIN old_quality_lines prior ON prior.id=n.id JOIN procurement_order_quality q ON q.order_line_id=n.id
 WHERE (n.product_id,n.supplier_item_id,n.base_unit_snapshot,n.receipt_classification_snapshot) IS DISTINCT FROM(prior.product_id,prior.supplier_item_id,prior.base_unit_snapshot,prior.receipt_classification_snapshot)) THEN RAISE EXCEPTION 'QUALITY_PO_IDENTITY_IMMUTABLE'; END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER store_guard_order_quality_identity AFTER UPDATE ON public.inventory_purchase_order_lines REFERENCING OLD TABLE AS old_quality_lines NEW TABLE AS new_quality_lines FOR EACH STATEMENT EXECUTE FUNCTION public.store_guard_order_quality_identity_v1();
REVOKE ALL ON FUNCTION public.store_guard_order_quality_identity_v1() FROM PUBLIC,anon,authenticated,service_role;

-- COMPONENT 20261022140000_inventory_lot_foundation.sql
-- Opt-in lot balances attach to the existing signed inventory transaction.
-- A deferred, once-per-transaction set reconciliation also catches writes that
-- forget the journal. Legacy untracked ingredients retain their original path.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE TABLE public.inventory_locations (
 id uuid PRIMARY KEY,restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 80),kind text NOT NULL CHECK(kind IN('storage','quarantine','rejected')),
 is_active boolean NOT NULL DEFAULT true,revision bigint NOT NULL DEFAULT 1,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX inventory_locations_store ON public.inventory_locations(restaurant_id,id);
CREATE TABLE public.inventory_lot_counts (
 id uuid PRIMARY KEY,restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 employee_id uuid NOT NULL,employee_snapshot jsonb NOT NULL,rows jsonb NOT NULL,reason text NOT NULL,
 input_hash text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.inventory_lot_tracking (
 ingredient_id uuid PRIMARY KEY REFERENCES public.inventory_items(id) ON DELETE CASCADE,
 restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 opening_count_id uuid NOT NULL REFERENCES public.inventory_lot_counts(id),started_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.inventory_lots (
 id uuid PRIMARY KEY,restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 ingredient_id uuid NOT NULL REFERENCES public.inventory_items(id) ON DELETE CASCADE,
 location_id uuid NOT NULL REFERENCES public.inventory_locations(id),
 supplier_lot_code text,expiry_date date,quantity_base numeric(18,3) NOT NULL CHECK(quantity_base>=0 AND quantity_base::text NOT IN('NaN','Infinity','-Infinity')),
 state text NOT NULL CHECK(state IN('available','held','rejected','returned','waste')),
 source_kind text NOT NULL CHECK(source_kind IN('opening_count','count','receipt','hold_release','unknown_legacy','disposition')),
 source_id uuid NOT NULL,source_component integer NOT NULL,receipt_line_id uuid REFERENCES public.inventory_receipt_lines(id) ON DELETE CASCADE,
 parent_lot_id uuid REFERENCES public.inventory_lots(id) DEFERRABLE INITIALLY DEFERRED,
 created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_kind,source_id,source_component,state)
);
CREATE INDEX inventory_lots_available ON public.inventory_lots(ingredient_id,expiry_date,created_at,id) WHERE state='available' AND quantity_base>0;
CREATE INDEX inventory_lots_receipt ON public.inventory_lots(receipt_line_id,state) WHERE quantity_base>0;
CREATE INDEX inventory_lots_store ON public.inventory_lots(restaurant_id,id);
CREATE TABLE public.inventory_lot_movements (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lot_id uuid NOT NULL REFERENCES public.inventory_lots(id) ON DELETE CASCADE,
 event_kind text NOT NULL,event_id uuid NOT NULL,quantity_base numeric(18,3) NOT NULL,
 inventory_transaction_id uuid REFERENCES public.inventory_transactions(id) ON DELETE CASCADE,
 created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_kind,event_id,lot_id)
);
CREATE INDEX inventory_lot_movements_event ON public.inventory_lot_movements(inventory_transaction_id,lot_id);
CREATE TABLE public.inventory_lot_dispositions (
 id uuid PRIMARY KEY,restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 lot_id uuid NOT NULL REFERENCES public.inventory_lots(id),action text NOT NULL CHECK(action IN('release','reject','return','waste','move')),
 quantity_base numeric(18,3) NOT NULL CHECK(quantity_base>0),payload_hash text NOT NULL,payload jsonb NOT NULL,
 actor_id uuid NOT NULL,result jsonb,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.inventory_lot_receipt_origins (
 receipt_id uuid PRIMARY KEY REFERENCES public.inventory_receipts(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
 disposition_id uuid NOT NULL REFERENCES public.inventory_lot_dispositions(id),
 parent_lot_id uuid NOT NULL REFERENCES public.inventory_lots(id),quantity_base numeric(18,3) NOT NULL CHECK(quantity_base>0)
);
CREATE TABLE public.inventory_lot_reconcile_queue (transaction_id bigint PRIMARY KEY,ingredient_ids uuid[] NOT NULL);
ALTER TABLE public.inventory_locations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_lot_counts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_lot_tracking ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_lots ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_lot_movements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_lot_dispositions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_lot_receipt_origins ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.inventory_lot_reconcile_queue ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.inventory_locations,public.inventory_lot_counts,public.inventory_lot_tracking,public.inventory_lots,public.inventory_lot_movements,public.inventory_lot_dispositions,public.inventory_lot_receipt_origins,public.inventory_lot_reconcile_queue FROM PUBLIC,anon,authenticated;
CREATE TRIGGER inventory_lot_counts_immutable BEFORE UPDATE ON public.inventory_lot_counts FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TRIGGER inventory_lot_movements_immutable BEFORE UPDATE ON public.inventory_lot_movements FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();

CREATE FUNCTION public.inventory_queue_lot_reconciliation_v1(p_ids uuid[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF p_ids IS NULL OR cardinality(p_ids)=0 THEN RETURN; END IF;
 INSERT INTO inventory_lot_reconcile_queue VALUES(txid_current(),p_ids)
 ON CONFLICT(transaction_id) DO UPDATE SET ingredient_ids=ARRAY(SELECT DISTINCT id FROM unnest(inventory_lot_reconcile_queue.ingredient_ids||EXCLUDED.ingredient_ids)id);
END $$;
CREATE FUNCTION public.inventory_check_lot_reconciliation_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE ids uuid[];
BEGIN
 SELECT ingredient_ids INTO ids FROM inventory_lot_reconcile_queue WHERE transaction_id=NEW.transaction_id;
 IF ids IS NULL THEN RETURN NULL; END IF;
 IF EXISTS(WITH available AS(SELECT ingredient_id,sum(quantity_base) qty FROM inventory_lots WHERE ingredient_id=ANY(ids) AND state='available' GROUP BY ingredient_id)
 SELECT 1 FROM inventory_lot_tracking t JOIN inventory_items i ON i.id=t.ingredient_id LEFT JOIN available a ON a.ingredient_id=i.id WHERE i.id=ANY(ids) AND coalesce(i.current_stock,0)<>coalesce(a.qty,0)) THEN RAISE EXCEPTION 'INVENTORY_LOT_BALANCE_MISMATCH'; END IF;
 DELETE FROM inventory_lot_reconcile_queue WHERE transaction_id=NEW.transaction_id;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER inventory_lot_reconcile_at_commit AFTER INSERT ON public.inventory_lot_reconcile_queue DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.inventory_check_lot_reconciliation_v1();
CREATE FUNCTION public.inventory_queue_changed_lots_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE ids uuid[];
BEGIN
 SELECT array_agg(n.id) INTO ids FROM new_inventory_balances n JOIN old_inventory_balances p ON p.id=n.id JOIN inventory_lot_tracking t ON t.ingredient_id=n.id WHERE n.current_stock IS DISTINCT FROM p.current_stock;
 PERFORM inventory_queue_lot_reconciliation_v1(ids);
 RETURN NULL;
END $$;
CREATE TRIGGER inventory_queue_changed_lots AFTER UPDATE ON public.inventory_items REFERENCING OLD TABLE AS old_inventory_balances NEW TABLE AS new_inventory_balances FOR EACH STATEMENT EXECUTE FUNCTION public.inventory_queue_changed_lots_v1();

CREATE FUNCTION public.admin_save_inventory_location_v1(p_id uuid,p_store uuid,p_name text,p_kind text,p_active boolean,p_expected_revision bigint) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE loc inventory_locations;
BEGIN
 PERFORM require_brand_admin_v1();
 IF p_id IS NULL OR p_active IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 THEN RAISE EXCEPTION 'INVENTORY_LOCATION_INVALID'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('inventory-location:'||p_id,0));
 SELECT * INTO loc FROM inventory_locations WHERE id=p_id FOR UPDATE;
 IF loc.restaurant_id IS NOT NULL AND loc.restaurant_id<>p_store THEN RAISE EXCEPTION 'PROCUREMENT_SCOPE_FORBIDDEN'; END IF;
 IF (loc.name,loc.kind,loc.is_active,loc.revision) IS NOT DISTINCT FROM (btrim(p_name),p_kind,p_active,p_expected_revision+1) THEN RETURN to_jsonb(loc); END IF;
 IF coalesce(loc.revision,0)<>p_expected_revision THEN RAISE EXCEPTION 'INVENTORY_LOCATION_STALE'; END IF;
 IF (NOT p_active OR loc.kind IS DISTINCT FROM p_kind) AND EXISTS(SELECT 1 FROM inventory_lots WHERE location_id=p_id AND state IN('available','held','rejected') AND quantity_base>0) THEN RAISE EXCEPTION 'INVENTORY_LOCATION_HAS_STOCK'; END IF;
 INSERT INTO inventory_locations(id,restaurant_id,name,kind,is_active,revision,created_by) VALUES(p_id,p_store,btrim(p_name),p_kind,p_active,p_expected_revision+1,auth.uid())
 ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name,kind=EXCLUDED.kind,is_active=EXCLUDED.is_active,revision=EXCLUDED.revision RETURNING * INTO loc;
 RETURN to_jsonb(loc);
END $$;

CREATE FUNCTION public.inventory_attach_lot_transactions_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE ids uuid[]; allocations jsonb; today date:=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
BEGIN
 SELECT array_agg(DISTINCT n.ingredient_id) INTO ids FROM new_lot_transactions n JOIN inventory_lot_tracking t ON t.ingredient_id=n.ingredient_id AND t.restaurant_id=n.restaurant_id;
 IF ids IS NULL THEN RETURN NULL; END IF;
 IF (SELECT count(*) FROM new_lot_transactions)>10000 THEN RAISE EXCEPTION 'INVENTORY_LOT_TRANSACTION_LIMIT'; END IF;
 PERFORM 1 FROM inventory_lots WHERE ingredient_id=ANY(ids) AND state='available' AND quantity_base>0 ORDER BY ingredient_id,id FOR UPDATE;
 IF (SELECT count(*) FROM inventory_lots WHERE ingredient_id=ANY(ids) AND state='available' AND quantity_base>0)>20000 THEN RAISE EXCEPTION 'INVENTORY_LOT_ACTIVE_PAGE_LIMIT'; END IF;
 -- A positive balance must have a real inspected receipt or an explicit count.
 IF EXISTS(SELECT 1 FROM new_lot_transactions n WHERE n.ingredient_id=ANY(ids) AND n.quantity_g>0 AND
  NOT (n.reference_type='inventory_purchase_receipt' AND EXISTS(SELECT 1 FROM inventory_receipts r WHERE r.id=n.reference_id AND r.restaurant_id=n.restaurant_id))
  AND NOT (n.reference_type='inventory_lot_count' AND EXISTS(SELECT 1 FROM inventory_lot_counts c WHERE c.id=n.reference_id AND c.restaurant_id=n.restaurant_id))) THEN RAISE EXCEPTION 'INVENTORY_LOT_DETAILS_REQUIRED'; END IF;
 WITH received AS MATERIALIZED(SELECT n.id transaction_id,n.restaurant_id,n.ingredient_id,rl.id line_id,l.ordinality component,l.value lot,
  coalesce(origin.parent_lot_id,NULL::uuid) parent_id,CASE WHEN origin.receipt_id IS NULL THEN 'receipt' ELSE 'hold_release' END kind
  FROM new_lot_transactions n JOIN inventory_receipt_lines rl ON rl.receipt_id=n.reference_id JOIN inventory_products p ON p.id=rl.product_id AND p.inventory_item_id=n.ingredient_id
  CROSS JOIN LATERAL jsonb_array_elements(coalesce(rl.inspection->'lots','[]')) WITH ORDINALITY l(value,ordinality)
  LEFT JOIN inventory_lot_receipt_origins origin ON origin.receipt_id=rl.receipt_id
  WHERE n.ingredient_id=ANY(ids) AND n.quantity_g>0 AND n.reference_type='inventory_purchase_receipt'),
 created AS(INSERT INTO inventory_lots(id,restaurant_id,ingredient_id,location_id,supplier_lot_code,expiry_date,quantity_base,state,source_kind,source_id,source_component,receipt_line_id,parent_lot_id)
 SELECT md5(line_id::text||':'||component||':available')::uuid,restaurant_id,ingredient_id,(lot->>'location_id')::uuid,lot->>'code',nullif(lot->>'expiry_date','')::date,(lot->>'accepted')::numeric,
 'available',kind,line_id,component::integer,line_id,parent_id FROM received WHERE (lot->>'accepted')::numeric>0 RETURNING *)
 INSERT INTO inventory_lot_movements(lot_id,event_kind,event_id,quantity_base,inventory_transaction_id,created_by)
 SELECT c.id,'transaction',r.transaction_id,c.quantity_base,r.transaction_id,auth.uid() FROM created c JOIN received r ON r.line_id=c.source_id AND r.component=c.source_component;
 IF EXISTS(SELECT 1 FROM new_lot_transactions n LEFT JOIN (SELECT inventory_transaction_id,sum(quantity_base) qty FROM inventory_lot_movements WHERE inventory_transaction_id IN(SELECT id FROM new_lot_transactions) GROUP BY inventory_transaction_id)m ON m.inventory_transaction_id=n.id
 WHERE n.ingredient_id=ANY(ids) AND n.quantity_g>0 AND n.reference_type='inventory_purchase_receipt' AND n.quantity_g<>coalesce(m.qty,0)) THEN RAISE EXCEPTION 'INVENTORY_LOT_RECEIPT_TOTAL_MISMATCH'; END IF;
 -- All negative rows in one statement share a consumption scope per ingredient.
 -- Existing returns issue one event; recipe deductions form one bounded batch.
 IF EXISTS(SELECT ingredient_id FROM new_lot_transactions WHERE ingredient_id=ANY(ids) AND quantity_g<0 AND reference_type IS DISTINCT FROM 'inventory_lot_count'
 GROUP BY ingredient_id HAVING count(DISTINCT CASE WHEN reference_type IN('inventory_supplier_return','inventory_lot_disposition') THEN reference_type||':'||reference_id::text WHEN transaction_type='waste' THEN 'waste' ELSE 'general' END)>1) THEN RAISE EXCEPTION 'INVENTORY_LOT_MIXED_SCOPE'; END IF;
 WITH demand AS MATERIALIZED(SELECT n.*,CASE WHEN n.reference_type='inventory_supplier_return' THEN ret.receipt_line_id END return_line,
  CASE WHEN n.reference_type='inventory_lot_disposition' THEN disposition.lot_id END chosen_lot,
  sum(-n.quantity_g) OVER(PARTITION BY n.ingredient_id ORDER BY n.created_at,n.id) finish,
  sum(-n.quantity_g) OVER(PARTITION BY n.ingredient_id ORDER BY n.created_at,n.id)+n.quantity_g start
 FROM new_lot_transactions n LEFT JOIN inventory_supplier_returns ret ON n.reference_type='inventory_supplier_return' AND ret.id=n.reference_id
 LEFT JOIN inventory_lot_dispositions disposition ON n.reference_type='inventory_lot_disposition' AND disposition.id=n.reference_id
 WHERE n.ingredient_id=ANY(ids) AND n.quantity_g<0 AND n.reference_type IS DISTINCT FROM 'inventory_lot_count'),
 scope AS MATERIALIZED(SELECT ingredient_id,bool_or(transaction_type='waste') allow_expired,bool_or(reference_type='inventory_supplier_return') restrict_return,bool_or(reference_type='inventory_lot_disposition') selected,max(return_line::text)::uuid return_line,max(chosen_lot::text)::uuid chosen_lot FROM demand GROUP BY ingredient_id),
 supply AS MATERIALIZED(SELECT l.*,sum(l.quantity_base) OVER(PARTITION BY l.ingredient_id ORDER BY l.expiry_date NULLS LAST,l.created_at,l.id) finish,
 sum(l.quantity_base) OVER(PARTITION BY l.ingredient_id ORDER BY l.expiry_date NULLS LAST,l.created_at,l.id)-l.quantity_base start
 FROM inventory_lots l JOIN scope s ON s.ingredient_id=l.ingredient_id WHERE l.state='available' AND l.quantity_base>0
 AND (s.allow_expired OR s.chosen_lot IS NOT NULL OR l.expiry_date IS NULL OR l.expiry_date>=today)
 AND (NOT coalesce(s.restrict_return,false) OR l.receipt_line_id=s.return_line OR l.source_kind='unknown_legacy')
 AND (NOT coalesce(s.selected,false) OR l.id=s.chosen_lot))
 SELECT coalesce(jsonb_agg(jsonb_build_object('transaction',d.id,'lot',s.id,'quantity',least(d.finish,s.finish)-greatest(d.start,s.start))),'[]') INTO allocations
 FROM demand d JOIN supply s ON s.ingredient_id=d.ingredient_id AND d.finish>s.start AND s.finish>d.start;
 IF EXISTS(SELECT 1 FROM new_lot_transactions n LEFT JOIN(SELECT (x->>'transaction')::uuid id,sum((x->>'quantity')::numeric) qty FROM jsonb_array_elements(allocations)x GROUP BY x->>'transaction') a ON a.id=n.id
 WHERE n.ingredient_id=ANY(ids) AND n.quantity_g<0 AND n.reference_type IS DISTINCT FROM 'inventory_lot_count' AND -n.quantity_g<>coalesce(a.qty,0)) THEN RAISE EXCEPTION 'INVENTORY_AVAILABLE_LOT_SHORTAGE'; END IF;
 UPDATE inventory_lots l SET quantity_base=l.quantity_base-a.qty FROM(SELECT (x->>'lot')::uuid id,sum((x->>'quantity')::numeric) qty FROM jsonb_array_elements(allocations)x GROUP BY x->>'lot')a WHERE l.id=a.id;
 INSERT INTO inventory_lot_movements(lot_id,event_kind,event_id,quantity_base,inventory_transaction_id,created_by)
 SELECT (x->>'lot')::uuid,'transaction',(x->>'transaction')::uuid,-(x->>'quantity')::numeric,(x->>'transaction')::uuid,auth.uid() FROM jsonb_array_elements(allocations)x;
 PERFORM inventory_queue_lot_reconciliation_v1(ids);
 RETURN NULL;
END $$;
CREATE TRIGGER inventory_attach_lot_transactions AFTER INSERT ON public.inventory_transactions REFERENCING NEW TABLE AS new_lot_transactions FOR EACH STATEMENT EXECUTE FUNCTION public.inventory_attach_lot_transactions_v1();
REVOKE ALL ON FUNCTION public.inventory_queue_lot_reconciliation_v1(uuid[]),public.inventory_check_lot_reconciliation_v1(),public.inventory_queue_changed_lots_v1(),public.inventory_attach_lot_transactions_v1() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.admin_save_inventory_location_v1(uuid,uuid,text,text,boolean,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_save_inventory_location_v1(uuid,uuid,text,text,boolean,bigint) TO authenticated;

-- COMPONENT 20261022141000_inventory_lot_counts.sql
-- Explicit opening/count documents. Carry-forward stock is not a second receipt.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE TABLE public.inventory_lot_count_rows (
 count_id uuid NOT NULL REFERENCES public.inventory_lot_counts(id) ON DELETE CASCADE,
 ingredient_id uuid NOT NULL REFERENCES public.inventory_items(id) ON DELETE CASCADE,
 data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(count_id,ingredient_id)
);
CREATE INDEX inventory_lot_count_rows_latest ON public.inventory_lot_count_rows(ingredient_id,created_at DESC,count_id DESC);
ALTER TABLE public.inventory_lot_count_rows ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.inventory_lot_count_rows FROM PUBLIC,anon,authenticated;
CREATE TRIGGER inventory_lot_count_rows_immutable BEFORE UPDATE ON public.inventory_lot_count_rows FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE FUNCTION public.admin_record_inventory_lot_count_v1(p_id uuid,p_store uuid,p_employee uuid,p_rows jsonb,p_reason text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE previous inventory_lot_counts; worker store_employees; input_hash text; rows_data jsonb; ids uuid[]; was_tracked uuid[];
BEGIN
 PERFORM require_brand_admin_v1();
 IF p_id IS NULL OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 100 OR octet_length(p_rows::text)>524288 OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'INVENTORY_COUNT_INPUT_INVALID'; END IF;
 input_hash:=md5(jsonb_build_object('store',p_store,'employee',p_employee,'rows',p_rows,'reason',btrim(p_reason),'actor',auth.uid())::text);
 PERFORM pg_advisory_xact_lock(hashtextextended('inventory-count:'||p_id,0));
 SELECT * INTO previous FROM inventory_lot_counts WHERE id=p_id;
 IF FOUND THEN
  IF previous.input_hash<>input_hash THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
  RETURN to_jsonb(previous);
 END IF;
 SELECT * INTO worker FROM store_employees WHERE id=p_employee AND store_id=p_store AND is_active;
 IF NOT FOUND THEN RAISE EXCEPTION 'INVENTORY_COUNT_EMPLOYEE_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows)x LEFT JOIN inventory_products p ON p.id=(x->>'product_id')::uuid AND p.restaurant_id=p_store AND p.is_active AND p.receipt_classification='stock'
 LEFT JOIN inventory_items i ON i.id=p.inventory_item_id AND i.restaurant_id=p_store AND i.is_active
 WHERE p.id IS NULL OR i.id IS NULL OR i.id::text IS DISTINCT FROM x->>'inventory_item_id' OR p.base_unit IS DISTINCT FROM x->>'unit'
 OR jsonb_typeof(x->'actual_quantity_base') IS DISTINCT FROM 'number' OR (x->>'actual_quantity_base')::numeric<0 OR (x->>'actual_quantity_base')::numeric<>round((x->>'actual_quantity_base')::numeric,3)
 OR jsonb_typeof(x->'expected_stock') IS DISTINCT FROM 'number' OR jsonb_typeof(x->'unit_cost_base') IS DISTINCT FROM 'number' OR (x->>'unit_cost_base')::numeric<0
 OR length(btrim(coalesce(x->>'cost_source',''))) NOT BETWEEN 5 AND 500 OR jsonb_typeof(x->'track_lots') IS DISTINCT FROM 'boolean'
 OR nullif(x->>'counted_at','') IS NULL OR (x->>'counted_at')::timestamptz>clock_timestamp()+interval '5 minutes'
 OR (x->>'counted_at')::timestamptz<clock_timestamp()-interval '1 day') THEN RAISE EXCEPTION 'INVENTORY_COUNT_INPUT_INVALID'; END IF;
 IF EXISTS(SELECT x->>'inventory_item_id' FROM jsonb_array_elements(p_rows)x GROUP BY x->>'inventory_item_id' HAVING count(*)>1) THEN RAISE EXCEPTION 'INVENTORY_COUNT_DUPLICATE_INGREDIENT'; END IF;
 SELECT array_agg((x->>'inventory_item_id')::uuid) INTO ids FROM jsonb_array_elements(p_rows)x;
 PERFORM 1 FROM inventory_items WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 SELECT array_agg(ingredient_id) INTO was_tracked FROM inventory_lot_tracking WHERE ingredient_id=ANY(ids);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows)x JOIN inventory_items i ON i.id=(x->>'inventory_item_id')::uuid
 WHERE coalesce(i.current_stock,0)<>(x->>'expected_stock')::numeric OR i.updated_at>(x->>'counted_at')::timestamptz
 OR EXISTS(SELECT 1 FROM inventory_transactions tr WHERE tr.ingredient_id=i.id AND tr.created_at>(x->>'counted_at')::timestamptz)) THEN RAISE EXCEPTION 'INVENTORY_COUNT_STOCK_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows)x WHERE (x->>'inventory_item_id')::uuid=ANY(was_tracked) AND NOT (x->>'track_lots')::boolean) THEN RAISE EXCEPTION 'INVENTORY_LOT_TRACKING_CANNOT_DISABLE'; END IF;
 -- Do not interrupt receiving for POs issued before lot tracking was enabled.
 IF EXISTS(SELECT 1 FROM inventory_purchase_order_lines l JOIN inventory_purchase_orders o ON o.id=l.purchase_order_id JOIN inventory_products p ON p.id=l.product_id
 JOIN jsonb_array_elements(p_rows)x ON (x->>'inventory_item_id')::uuid=p.inventory_item_id AND (x->>'track_lots')::boolean
 WHERE o.status IN('draft','submitted','store_approved','brand_approved','office_approved','ordered','partially_received') AND NOT coalesce(p.inventory_item_id=ANY(was_tracked),false)) THEN RAISE EXCEPTION 'INVENTORY_LOT_EXISTING_PO_MUST_DRAIN'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows)x WHERE (x->>'track_lots')::boolean AND (jsonb_typeof(x->'lots') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'lots')>100)) THEN RAISE EXCEPTION 'INVENTORY_COUNT_LOTS_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows)x WHERE (x->>'track_lots')::boolean AND (x->>'actual_quantity_base')::numeric<>coalesce((SELECT sum((l->>'quantity_base')::numeric) FROM jsonb_array_elements(x->'lots')l),0)) THEN RAISE EXCEPTION 'INVENTORY_COUNT_LOT_TOTAL_MISMATCH'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows)x CROSS JOIN LATERAL jsonb_array_elements(coalesce(x->'lots','[]'))l
 LEFT JOIN inventory_locations loc ON loc.id=(l->>'location_id')::uuid AND loc.restaurant_id=p_store AND loc.is_active AND loc.kind='storage'
 WHERE (x->>'track_lots')::boolean AND (loc.id IS NULL OR jsonb_typeof(l->'quantity_base') IS DISTINCT FROM 'number' OR (l->>'quantity_base')::numeric<=0
 OR (l->>'quantity_base')::numeric<>round((l->>'quantity_base')::numeric,3) OR nullif(l->>'expiry_date','')::date<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date
 OR (nullif(btrim(l->>'code'),'') IS NULL AND NOT (coalesce((x->>'acknowledge_unknown_legacy')::boolean,false) AND (x->>'expected_stock')::numeric>0))
 OR length(coalesce(l->>'code',''))>160)) THEN RAISE EXCEPTION 'INVENTORY_COUNT_LOT_INVALID'; END IF;
 -- Every active purchasing alias of a tracked ingredient must explicitly use lots.
 IF EXISTS(WITH latest AS(SELECT DISTINCT ON(product_id) product_id,criteria FROM procurement_quality_profiles WHERE restaurant_id=p_store ORDER BY product_id,revision DESC)
 SELECT 1 FROM inventory_products p JOIN jsonb_array_elements(p_rows)x ON (x->>'inventory_item_id')::uuid=p.inventory_item_id AND (x->>'track_lots')::boolean
 LEFT JOIN latest q ON q.product_id=p.id WHERE p.is_active AND q.criteria->>'lot_required' IS DISTINCT FROM 'true') THEN RAISE EXCEPTION 'INVENTORY_LOT_CRITERIA_REQUIRED'; END IF;
 -- Known opening lots obey the approved expiry requirement; historical unknown
 -- stock remains explicitly marked, never assigned a fictitious supplier lot.
 IF EXISTS(WITH latest AS(SELECT DISTINCT ON(product_id) product_id,criteria FROM procurement_quality_profiles WHERE restaurant_id=p_store ORDER BY product_id,revision DESC)
 SELECT 1 FROM jsonb_array_elements(p_rows)x JOIN latest q ON q.product_id=(x->>'product_id')::uuid CROSS JOIN LATERAL jsonb_array_elements(coalesce(x->'lots','[]'))l
 WHERE (x->>'track_lots')::boolean AND (q.criteria->>'expiry_required')::boolean AND nullif(btrim(l->>'code'),'') IS NOT NULL AND nullif(l->>'expiry_date','') IS NULL) THEN RAISE EXCEPTION 'INVENTORY_COUNT_LOT_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM inventory_lots l WHERE l.ingredient_id=ANY(ids) AND l.state IN('held','rejected') AND l.quantity_base>0) THEN RAISE EXCEPTION 'INVENTORY_COUNT_QUARANTINE_SEPARATE'; END IF;
 IF EXISTS(SELECT l->>'id' FROM jsonb_array_elements(p_rows)x CROSS JOIN LATERAL jsonb_array_elements(coalesce(x->'lots','[]'))l WHERE l->>'id' IS NOT NULL GROUP BY l->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'INVENTORY_COUNT_DUPLICATE_LOT'; END IF;
 -- Existing available lots are retained by their ID. Counts cannot silently
 -- relabel or erase received-lot ancestry.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows)x CROSS JOIN LATERAL jsonb_array_elements(coalesce(x->'lots','[]'))l
 LEFT JOIN inventory_lots old_lot ON old_lot.id=nullif(l->>'id','')::uuid
 WHERE l->>'id' IS NOT NULL AND (old_lot.id IS NULL OR old_lot.ingredient_id<>(x->>'inventory_item_id')::uuid OR old_lot.state<>'available'
 OR (old_lot.location_id,old_lot.supplier_lot_code,old_lot.expiry_date) IS DISTINCT FROM ((l->>'location_id')::uuid,nullif(btrim(l->>'code'),''),nullif(l->>'expiry_date','')::date))) THEN RAISE EXCEPTION 'INVENTORY_COUNT_LOT_IDENTITY_CHANGED'; END IF;
 SELECT jsonb_agg(x||jsonb_build_object('was_tracked',coalesce((x->>'inventory_item_id')::uuid=ANY(was_tracked),false),
 'previous_lots',coalesce(prior.rows,'[]')) ORDER BY x->>'inventory_item_id') INTO rows_data
 FROM jsonb_array_elements(p_rows)x LEFT JOIN (SELECT ingredient_id,jsonb_agg(to_jsonb(l) ORDER BY id) rows FROM inventory_lots l WHERE ingredient_id=ANY(ids) AND state='available' AND quantity_base>0 GROUP BY ingredient_id)prior ON prior.ingredient_id=(x->>'inventory_item_id')::uuid;
 INSERT INTO inventory_lot_counts VALUES(p_id,p_store,p_employee,jsonb_build_object('id',worker.id,'name',worker.full_name,'number',worker.employee_number),rows_data,btrim(p_reason),input_hash,auth.uid(),clock_timestamp()) RETURNING * INTO previous;
 INSERT INTO inventory_lot_count_rows(count_id,ingredient_id,data) SELECT p_id,(x->>'inventory_item_id')::uuid,x FROM jsonb_array_elements(rows_data)x;
 INSERT INTO inventory_lot_tracking(ingredient_id,restaurant_id,opening_count_id) SELECT (x->>'inventory_item_id')::uuid,p_store,p_id FROM jsonb_array_elements(p_rows)x WHERE (x->>'track_lots')::boolean ON CONFLICT DO NOTHING;
 -- Count differences on existing lots; omitted IDs mean explicitly counted zero.
 WITH counted AS(SELECT (x->>'inventory_item_id')::uuid item_id,l FROM jsonb_array_elements(p_rows)x CROSS JOIN LATERAL jsonb_array_elements(coalesce(x->'lots','[]'))l WHERE l->>'id' IS NOT NULL)
 INSERT INTO inventory_lot_movements(lot_id,event_kind,event_id,quantity_base,created_by)
 SELECT old_lot.id,'count',p_id,coalesce((c.l->>'quantity_base')::numeric,0)-old_lot.quantity_base,auth.uid() FROM inventory_lots old_lot LEFT JOIN counted c ON c.l->>'id'=old_lot.id::text
 WHERE old_lot.ingredient_id=ANY(was_tracked) AND old_lot.state='available' AND old_lot.quantity_base<>coalesce((c.l->>'quantity_base')::numeric,0);
 UPDATE inventory_lots l SET quantity_base=l.quantity_base+m.quantity_base FROM inventory_lot_movements m WHERE m.event_kind='count' AND m.event_id=p_id AND m.lot_id=l.id;
 WITH counted AS(SELECT x,l.value lot,l.ordinality component FROM jsonb_array_elements(p_rows)x CROSS JOIN LATERAL jsonb_array_elements(coalesce(x->'lots','[]')) WITH ORDINALITY l(value,ordinality) WHERE (x->>'track_lots')::boolean AND l.value->>'id' IS NULL),
 created AS(INSERT INTO inventory_lots(id,restaurant_id,ingredient_id,location_id,supplier_lot_code,expiry_date,quantity_base,state,source_kind,source_id,source_component)
 SELECT md5(p_id::text||':'||(x->>'inventory_item_id')||':'||component)::uuid,p_store,(x->>'inventory_item_id')::uuid,(lot->>'location_id')::uuid,nullif(btrim(lot->>'code'),''),nullif(lot->>'expiry_date','')::date,(lot->>'quantity_base')::numeric,
 'available',CASE WHEN nullif(btrim(lot->>'code'),'') IS NULL THEN 'unknown_legacy' WHEN coalesce((x->>'inventory_item_id')::uuid=ANY(was_tracked),false) THEN 'count' ELSE 'opening_count' END,p_id,
 row_number() OVER(ORDER BY x->>'inventory_item_id',component)::integer FROM counted RETURNING *)
 INSERT INTO inventory_lot_movements(lot_id,event_kind,event_id,quantity_base,created_by) SELECT id,'count',p_id,quantity_base,auth.uid() FROM created;
 UPDATE inventory_items i SET current_stock=(x->>'actual_quantity_base')::numeric,quantity=(x->>'actual_quantity_base')::numeric,updated_at=clock_timestamp()
 FROM jsonb_array_elements(p_rows)x WHERE i.id=(x->>'inventory_item_id')::uuid;
 INSERT INTO inventory_transactions(restaurant_id,ingredient_id,transaction_type,quantity_g,reference_type,reference_id,note,created_by,performed_by_employee_id,stock_before,stock_after,effective_at,effective_date)
 SELECT p_store,(x->>'inventory_item_id')::uuid,'adjust',(x->>'actual_quantity_base')::numeric-(x->>'expected_stock')::numeric,'inventory_lot_count',p_id,btrim(p_reason),auth.uid(),p_employee,(x->>'expected_stock')::numeric,(x->>'actual_quantity_base')::numeric,(x->>'counted_at')::timestamptz,((x->>'counted_at')::timestamptz AT TIME ZONE 'Asia/Ho_Chi_Minh')::date FROM jsonb_array_elements(p_rows)x;
 PERFORM inventory_queue_lot_reconciliation_v1(ids);
 RETURN to_jsonb(previous);
END $$;
REVOKE ALL ON FUNCTION public.admin_record_inventory_lot_count_v1(uuid,uuid,uuid,jsonb,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_record_inventory_lot_count_v1(uuid,uuid,uuid,jsonb,text) TO authenticated;

-- COMPONENT 20261022142000_inventory_receipt_lots.sql
-- Physical receipt = accepted + held + rejected. Held quantities are excluded
-- from usable stock and shortage reservations until a recorded disposition.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
ALTER TABLE public.inventory_receipt_lines ADD COLUMN held_quantity_base numeric(12,3) NOT NULL DEFAULT 0 CHECK(held_quantity_base>=0 AND held_quantity_base::text NOT IN('NaN','Infinity','-Infinity'));
CREATE FUNCTION public.inventory_validate_receipt_lots_v1(p_store uuid,p_lines jsonb) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE lines jsonb; today date:=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date;
BEGIN
 SELECT coalesce(jsonb_agg(x||jsonb_build_object('tracked',t.ingredient_id IS NOT NULL,'accepted',coalesce((x->>'accepted_quantity_base')::numeric,(x->>'received_quantity_base')::numeric-coalesce((x->>'rejected_quantity_base')::numeric,0)-coalesce((x->>'held_quantity_base')::numeric,0)))),'[]') INTO lines
 FROM jsonb_array_elements(p_lines)x JOIN inventory_purchase_order_lines ol ON ol.id=(x->>'purchase_order_line_id')::uuid
 JOIN inventory_products p ON p.id=ol.product_id AND p.restaurant_id=p_store LEFT JOIN inventory_lot_tracking t ON t.ingredient_id=p.inventory_item_id AND t.restaurant_id=p_store;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(lines)x WHERE coalesce((x->>'held_quantity_base')::numeric,0)<0 OR coalesce((x->>'held_quantity_base')::numeric,0)::text IN('NaN','Infinity','-Infinity')
 OR (x->>'accepted')::numeric<0 OR coalesce((x->>'held_quantity_base')::numeric,0)>0 AND (NOT (x->>'tracked')::boolean OR length(btrim(coalesce(x->>'discrepancy_reason','')))<5 OR x->'inspection'->>'issue_type'='none')) THEN RAISE EXCEPTION 'INVENTORY_HOLD_QUANTITY_OR_REASON_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(lines)x WHERE (x->>'tracked')::boolean AND (x->>'received_quantity_base')::numeric>0 AND
 (jsonb_typeof(x->'inspection'->'lots') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'inspection'->'lots') NOT BETWEEN 1 AND 20)) THEN RAISE EXCEPTION 'INVENTORY_RECEIPT_LOTS_REQUIRED'; END IF;
 IF EXISTS(WITH totals AS(SELECT x,sum(coalesce((l->>'accepted')::numeric,0)) accepted,sum(coalesce((l->>'held')::numeric,0)) held,sum(coalesce((l->>'rejected')::numeric,0)) rejected
 FROM jsonb_array_elements(lines)x CROSS JOIN LATERAL jsonb_array_elements(coalesce(x->'inspection'->'lots','[]'))l WHERE (x->>'tracked')::boolean GROUP BY x)
 SELECT 1 FROM totals WHERE (accepted,held,rejected) IS DISTINCT FROM ((x->>'accepted')::numeric,coalesce((x->>'held_quantity_base')::numeric,0),coalesce((x->>'rejected_quantity_base')::numeric,0))) THEN RAISE EXCEPTION 'INVENTORY_RECEIPT_LOT_TOTAL_MISMATCH'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(lines)x CROSS JOIN LATERAL jsonb_array_elements(coalesce(x->'inspection'->'lots','[]'))l
 LEFT JOIN inventory_locations loc ON loc.id=nullif(l->>'location_id','')::uuid AND loc.restaurant_id=p_store AND loc.kind='storage' AND loc.is_active
 LEFT JOIN inventory_locations hold ON hold.id=nullif(l->>'held_location_id','')::uuid AND hold.restaurant_id=p_store AND hold.kind='quarantine' AND hold.is_active
 LEFT JOIN inventory_locations reject_location ON reject_location.id=nullif(l->>'rejected_location_id','')::uuid AND reject_location.restaurant_id=p_store AND reject_location.kind='rejected' AND reject_location.is_active
 WHERE (x->>'tracked')::boolean AND (length(btrim(coalesce(l->>'code',''))) NOT BETWEEN 1 AND 160
 OR jsonb_typeof(l->'accepted') IS DISTINCT FROM 'number' OR jsonb_typeof(l->'held') IS DISTINCT FROM 'number' OR jsonb_typeof(l->'rejected') IS DISTINCT FROM 'number'
 OR least((l->>'accepted')::numeric,(l->>'held')::numeric,(l->>'rejected')::numeric)<0
 OR (l->>'accepted')::numeric+(l->>'held')::numeric+(l->>'rejected')::numeric<=0
 OR (l->>'accepted')::numeric<>round((l->>'accepted')::numeric,3) OR (l->>'held')::numeric<>round((l->>'held')::numeric,3) OR (l->>'rejected')::numeric<>round((l->>'rejected')::numeric,3)
 OR ((l->>'accepted')::numeric>0 AND (loc.id IS NULL OR nullif(l->>'expiry_date','')::date<today))
 OR ((l->>'held')::numeric>0 AND hold.id IS NULL) OR ((l->>'rejected')::numeric>0 AND reject_location.id IS NULL)
 OR ((l->>'accepted')::numeric>0 AND coalesce((x->'inspection'->'quality_snapshot'->'criteria'->>'expiry_required')::boolean,false) AND
 (nullif(l->>'expiry_date','') IS NULL OR (l->>'expiry_date')::date<today+(x->'inspection'->'quality_snapshot'->'criteria'->>'min_remaining_days')::integer)))) THEN RAISE EXCEPTION 'INVENTORY_RECEIPT_LOT_INVALID'; END IF;
END $$;

CREATE FUNCTION public.inventory_capture_quarantine_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
BEGIN
 WITH physical AS MATERIALIZED(SELECT r.restaurant_id,rl.id line_id,p.inventory_item_id,l.value lot,l.ordinality component,kind.state,
  CASE WHEN kind.state='held' THEN (l.value->>'held')::numeric ELSE (l.value->>'rejected')::numeric END qty,
  CASE WHEN kind.state='held' THEN (l.value->>'held_location_id')::uuid ELSE (l.value->>'rejected_location_id')::uuid END location_id
 FROM new_lot_receipts r JOIN old_lot_receipts before_row ON before_row.id=r.id JOIN inventory_receipt_lines rl ON rl.receipt_id=r.id
 JOIN inventory_products p ON p.id=rl.product_id JOIN inventory_lot_tracking t ON t.ingredient_id=p.inventory_item_id
 CROSS JOIN LATERAL jsonb_array_elements(coalesce(rl.inspection->'lots','[]')) WITH ORDINALITY l(value,ordinality)
 CROSS JOIN (VALUES('held'),('rejected'))kind(state) WHERE r.status='confirmed' AND before_row.status<>'confirmed'),
 created AS(INSERT INTO inventory_lots(id,restaurant_id,ingredient_id,location_id,supplier_lot_code,expiry_date,quantity_base,state,source_kind,source_id,source_component,receipt_line_id)
 SELECT md5(line_id::text||':'||component||':'||state)::uuid,restaurant_id,inventory_item_id,location_id,lot->>'code',nullif(lot->>'expiry_date','')::date,qty,state,'receipt',line_id,component::integer,line_id FROM physical WHERE qty>0 RETURNING *)
 INSERT INTO inventory_lot_movements(lot_id,event_kind,event_id,quantity_base,created_by) SELECT id,'physical_receipt',receipt_line_id,quantity_base,auth.uid() FROM created;
 RETURN NULL;
END $$;
CREATE TRIGGER inventory_capture_quarantine AFTER UPDATE ON public.inventory_receipts REFERENCING OLD TABLE AS old_lot_receipts NEW TABLE AS new_lot_receipts FOR EACH STATEMENT EXECUTE FUNCTION public.inventory_capture_quarantine_v1();

CREATE FUNCTION public.inventory_held_by_order_line_v1(p_ids uuid[]) RETURNS TABLE(order_line_id uuid,quantity_base numeric)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
 SELECT rl.purchase_order_line_id,sum(l.quantity_base) FROM inventory_lots l JOIN inventory_receipt_lines rl ON rl.id=l.receipt_line_id
 WHERE l.state='held' AND l.quantity_base>0 AND rl.purchase_order_line_id=ANY(p_ids) GROUP BY rl.purchase_order_line_id;
$$;
CREATE FUNCTION public.inventory_guard_held_shortage_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE ids uuid[]; newly_issued jsonb:='[]';
BEGIN
 SELECT array_agg(DISTINCT original_order_line_id) INTO ids FROM new_hold_allocations WHERE status IN('reserved','issued');
 IF ids IS NULL THEN RETURN NULL; END IF;
 PERFORM 1 FROM inventory_purchase_orders WHERE id IN(SELECT purchase_order_id FROM inventory_purchase_order_lines WHERE id=ANY(ids)) ORDER BY id FOR UPDATE;
 IF TG_OP='UPDATE' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('line',n.original_order_line_id,'qty',n.quantity_base)),'[]') INTO newly_issued FROM new_hold_allocations n JOIN old_hold_allocations before_row ON before_row.id=n.id WHERE n.status='issued' AND before_row.status='reserved';
 END IF;
 IF EXISTS(WITH accepted AS(SELECT rl.purchase_order_line_id,sum(rl.accepted_quantity_base) qty FROM inventory_receipt_lines rl JOIN inventory_receipts r ON r.id=rl.receipt_id AND r.status='confirmed' WHERE rl.purchase_order_line_id=ANY(ids) GROUP BY rl.purchase_order_line_id),
 reserved AS(SELECT original_order_line_id,sum(quantity_base) qty FROM procurement_shortage_allocations WHERE original_order_line_id=ANY(ids) AND status='reserved' GROUP BY original_order_line_id),
 issued AS(SELECT (x->>'line')::uuid line,sum((x->>'qty')::numeric) qty FROM jsonb_array_elements(newly_issued)x GROUP BY x->>'line')
 SELECT 1 FROM inventory_purchase_order_lines ol JOIN inventory_held_by_order_line_v1(ids) held ON held.order_line_id=ol.id
 LEFT JOIN accepted a ON a.purchase_order_line_id=ol.id LEFT JOIN reserved r ON r.original_order_line_id=ol.id LEFT JOIN issued i ON i.line=ol.id
 WHERE ol.id=ANY(ids) AND coalesce(r.qty,0)+coalesce(i.qty,0)>greatest(0,ol.ordered_quantity_base-ol.cancelled_quantity_base-coalesce(a.qty,0)-held.quantity_base)) THEN RAISE EXCEPTION 'PROCUREMENT_SHORTAGE_EXCLUDES_HELD'; END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER inventory_guard_held_shortage_insert AFTER INSERT ON public.procurement_shortage_allocations REFERENCING NEW TABLE AS new_hold_allocations FOR EACH STATEMENT EXECUTE FUNCTION public.inventory_guard_held_shortage_v1();
CREATE TRIGGER inventory_guard_held_shortage_update AFTER UPDATE ON public.procurement_shortage_allocations REFERENCING OLD TABLE AS old_hold_allocations NEW TABLE AS new_hold_allocations FOR EACH STATEMENT EXECUTE FUNCTION public.inventory_guard_held_shortage_v1();

DO $$ DECLARE d text; BEGIN
 d:=pg_get_functiondef('public.procurement_enrich_quality_lines_v1(uuid,jsonb)'::regprocedure);
 d:=replace(d,' RETURN result;', 'SELECT jsonb_agg(x||jsonb_build_object(''accepted_quantity_base'',(x->>''received_quantity_base'')::numeric-coalesce((x->>''rejected_quantity_base'')::numeric,0)-coalesce((x->>''held_quantity_base'')::numeric,0))) INTO result FROM jsonb_array_elements(result)x; PERFORM public.inventory_validate_receipt_lots_v1(p_store,result); RETURN result;'); EXECUTE d;
 d:=pg_get_functiondef('public.procurement_validate_inspection_batch(uuid,jsonb)'::regprocedure);
 d:=replace(d,' PERFORM procurement_validate_inspection_before_quality(p_store_id,p_lines);', ' PERFORM public.inventory_validate_receipt_lots_v1(p_store_id,p_lines); PERFORM procurement_validate_inspection_before_quality(p_store_id,p_lines);'); EXECUTE d;
 d:=pg_get_functiondef('public.submit_inventory_receipt_batch(uuid,uuid,integer,integer,text,jsonb,text,text,text,date,text)'::regprocedure);
 IF position('rejected_quantity_base,actual_unit_price,discrepancy_reason,inspection,expected_quantity_base_snapshot)' IN d)=0 THEN RAISE EXCEPTION 'LOT_SUBMISSION_PATCH_MISMATCH'; END IF;
 d:=replace(d,'rejected_quantity_base,actual_unit_price,discrepancy_reason,inspection,expected_quantity_base_snapshot)', 'rejected_quantity_base,held_quantity_base,actual_unit_price,discrepancy_reason,inspection,expected_quantity_base_snapshot)');
 d:=replace(d,'(x->>''received_quantity_base'')::numeric-COALESCE((x->>''rejected_quantity_base'')::numeric,0),COALESCE((x->>''rejected_quantity_base'')::numeric,0),COALESCE((x->>''actual_unit_price'')::numeric,ol.unit_price)',
 '(x->>''received_quantity_base'')::numeric-COALESCE((x->>''rejected_quantity_base'')::numeric,0)-coalesce((x->>''held_quantity_base'')::numeric,0),COALESCE((x->>''rejected_quantity_base'')::numeric,0),coalesce((x->>''held_quantity_base'')::numeric,0),COALESCE((x->>''actual_unit_price'')::numeric,ol.unit_price)');
 d:=replace(d,'rejected_quantity_base=EXCLUDED.rejected_quantity_base,actual_unit_price', 'rejected_quantity_base=EXCLUDED.rejected_quantity_base,held_quantity_base=EXCLUDED.held_quantity_base,actual_unit_price'); EXECUTE d;
 d:=pg_get_functiondef('public.verify_inventory_receipt_p1(uuid,integer,text,jsonb,text)'::regprocedure);
 d:=replace(d,'+COALESCE((x->>''rejected_quantity_base'')::numeric,l.rejected_quantity_base),', '+COALESCE((x->>''rejected_quantity_base'')::numeric,l.rejected_quantity_base)+l.held_quantity_base,'); EXECUTE d;
 d:=pg_get_functiondef('public.procurement_shortages(uuid,jsonb,jsonb)'::regprocedure);
 d:=replace(d,'COALESCE(a.qty,0)-COALESCE(r.qty,0)', 'COALESCE(a.qty,0)-coalesce(held.quantity_base,0)-COALESCE(r.qty,0)');
 d:=replace(d,'LEFT JOIN accepted a ON a.purchase_order_line_id=ol.id', 'LEFT JOIN public.inventory_held_by_order_line_v1(ARRAY(SELECT l.id FROM public.inventory_purchase_order_lines l JOIN orders o2 ON o2.id=l.purchase_order_id)) held ON held.order_line_id=ol.id LEFT JOIN accepted a ON a.purchase_order_line_id=ol.id');
 d:=replace(d,'COALESCE(r.own,0) reserved_quantity_base', 'coalesce(held.quantity_base,0) held_quantity_base,COALESCE(r.own,0) reserved_quantity_base'); EXECUTE d;
 d:=pg_get_functiondef('public.procurement_create_receipt_report(uuid)'::regprocedure);
 d:=replace(d,'COALESCE(rl.received_quantity_base,0)/ol.order_unit_quantity_base_snapshot received_quantity,',
 'CASE WHEN origin.receipt_id IS NULL THEN COALESCE(rl.received_quantity_base,0) ELSE 0 END/ol.order_unit_quantity_base_snapshot received_quantity, CASE WHEN origin.receipt_id IS NULL THEN 0 ELSE COALESCE(rl.accepted_quantity_base,0) END/ol.order_unit_quantity_base_snapshot released_quantity, COALESCE(rl.held_quantity_base,0)/ol.order_unit_quantity_base_snapshot held_quantity,');
 d:=replace(d,'LEFT JOIN public.inventory_receipt_lines rl ON rl.receipt_id=cr.id AND rl.purchase_order_line_id=ol.id)', 'LEFT JOIN public.inventory_receipt_lines rl ON rl.receipt_id=cr.id AND rl.purchase_order_line_id=ol.id LEFT JOIN public.inventory_lot_receipt_origins origin ON origin.receipt_id=cr.id)');
 d:=replace(d,'''receipt_id'',cr.id,''purchase_order_id''', '''receipt_id'',cr.id,''receipt_origin'',CASE WHEN EXISTS(SELECT 1 FROM public.inventory_lot_receipt_origins o WHERE o.receipt_id=cr.id) THEN ''hold_release'' ELSE ''delivery'' END,''purchase_order_id'''); EXECUTE d;
END $$;
REVOKE ALL ON FUNCTION public.inventory_validate_receipt_lots_v1(uuid,jsonb),public.inventory_capture_quarantine_v1(),public.inventory_held_by_order_line_v1(uuid[]),public.inventory_guard_held_shortage_v1() FROM PUBLIC,anon,authenticated,service_role;

-- COMPONENT 20261022143000_inventory_lot_dispositions.sql
-- Retain the original inspection. A hold release is a new accepted receipt,
-- financially posting only the released quantity and referencing the held lot.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE FUNCTION public.inventory_dispose_lot_v1(p_id uuid,p_store uuid,p_lot uuid,p_action text,p_quantity numeric,p_payload jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE prior inventory_lot_dispositions; lot inventory_lots; ord inventory_purchase_orders; original inventory_receipt_lines;
 loc inventory_locations; worker store_employees; input_hash text; outcome jsonb; receipt_id uuid; lines jsonb; target_state text; target_id uuid:=gen_random_uuid(); stock numeric;
BEGIN
 PERFORM procurement_actor(p_store);
 IF NOT can_verify_inventory_receipt(p_store) THEN RAISE EXCEPTION 'INVENTORY_LOT_DISPOSITION_FORBIDDEN'; END IF;
 IF p_id IS NULL OR p_action NOT IN('release','reject','return','waste','move') OR p_action IS NULL OR p_quantity IS NULL OR p_quantity<=0 OR p_quantity::text IN('NaN','Infinity','-Infinity') OR p_quantity<>round(p_quantity,3)
 OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>262144 OR length(btrim(coalesce(p_payload->>'reason',''))) NOT BETWEEN 5 AND 1000
 OR length(btrim(coalesce(p_payload->>'evidence_reference',''))) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'INVENTORY_LOT_DISPOSITION_INVALID'; END IF;
 input_hash:=md5(jsonb_build_object('store',p_store,'lot',p_lot,'action',p_action,'quantity',p_quantity,'payload',p_payload,'actor',auth.uid())::text);
 PERFORM pg_advisory_xact_lock(hashtextextended('lot-disposition:'||p_id,0));
 SELECT * INTO prior FROM inventory_lot_dispositions WHERE id=p_id;
 IF FOUND THEN
  IF prior.payload_hash<>input_hash THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
  RETURN prior.result;
 END IF;
 SELECT * INTO lot FROM inventory_lots WHERE id=p_lot AND restaurant_id=p_store;
 IF NOT FOUND THEN RAISE EXCEPTION 'INVENTORY_LOT_NOT_FOUND'; END IF;
 SELECT * INTO original FROM inventory_receipt_lines WHERE id=lot.receipt_line_id;
 -- Same lock order as receiving/shortage issuance, then stock, then lot.
  SELECT o.* INTO ord FROM inventory_purchase_orders o JOIN inventory_purchase_order_lines l ON l.purchase_order_id=o.id WHERE l.id=original.purchase_order_line_id FOR UPDATE OF o;
 SELECT current_stock INTO stock FROM inventory_items WHERE id=lot.ingredient_id FOR UPDATE;
 SELECT * INTO lot FROM inventory_lots WHERE id=p_lot FOR UPDATE;
 IF lot.quantity_base<p_quantity OR lot.state NOT IN('available','held','rejected') THEN RAISE EXCEPTION 'INVENTORY_LOT_QUANTITY_CHANGED'; END IF;
 SELECT * INTO worker FROM store_employees WHERE id=nullif(p_payload->>'employee_id','')::uuid AND store_id=p_store AND is_active;
 IF NOT FOUND THEN RAISE EXCEPTION 'INVENTORY_COUNT_EMPLOYEE_REQUIRED'; END IF;
 IF p_action='release' AND (lot.state<>'held' OR original.id IS NULL OR ord.id IS NULL) THEN RAISE EXCEPTION 'INVENTORY_LOT_NOT_HELD'; END IF;
 IF p_action='reject' AND lot.state<>'held' THEN RAISE EXCEPTION 'INVENTORY_LOT_NOT_HELD'; END IF;
 IF p_action='return' AND lot.state='available' THEN RAISE EXCEPTION 'INVENTORY_USE_SUPPLIER_RETURN'; END IF;
 IF p_action IN('release','reject','move') THEN
  SELECT * INTO loc FROM inventory_locations WHERE id=nullif(p_payload->>'location_id','')::uuid AND restaurant_id=p_store AND is_active;
  IF loc.id IS NULL OR loc.kind IS DISTINCT FROM (CASE WHEN p_action='release' OR p_action='move' AND lot.state='available' THEN 'storage' WHEN p_action='reject' OR p_action='move' AND lot.state='rejected' THEN 'rejected' ELSE 'quarantine' END) THEN RAISE EXCEPTION 'INVENTORY_LOCATION_INVALID'; END IF;
 END IF;
 INSERT INTO inventory_lot_dispositions(id,restaurant_id,lot_id,action,quantity_base,payload_hash,payload,actor_id)
 VALUES(p_id,p_store,p_lot,p_action,p_quantity,input_hash,p_payload||jsonb_build_object('employee_snapshot',jsonb_build_object('id',worker.id,'name',worker.full_name,'number',worker.employee_number)),auth.uid());
 IF p_action='release' THEN
  receipt_id:=(p_payload->>'receipt_id')::uuid;
  IF receipt_id IS NULL OR (p_payload->>'expected_order_version')::integer IS DISTINCT FROM ord.row_version THEN RAISE EXCEPTION 'INVENTORY_RECEIPT_STALE_VERSION'; END IF;
  UPDATE inventory_lots SET quantity_base=quantity_base-p_quantity WHERE id=p_lot;
  INSERT INTO inventory_lot_receipt_origins VALUES(receipt_id,p_id,p_lot,p_quantity);
  SELECT jsonb_agg(jsonb_build_object('purchase_order_line_id',l.id,'received_quantity_base',CASE WHEN l.id=original.purchase_order_line_id THEN p_quantity ELSE 0 END,'rejected_quantity_base',0,'held_quantity_base',0,
   'discrepancy_reason',p_payload->>'reason',
   'inspection',CASE WHEN l.id=original.purchase_order_line_id THEN coalesce(p_payload->'inspection','{}')||jsonb_build_object('employee_id',worker.id,'lots',jsonb_build_array(jsonb_build_object('code',lot.supplier_lot_code,'expiry_date',lot.expiry_date,'location_id',loc.id,'accepted',p_quantity,'held',0,'rejected',0))) ELSE jsonb_build_object('issue_type','none') END) ORDER BY l.id) INTO lines
  FROM inventory_purchase_order_lines l WHERE l.purchase_order_id=ord.id;
  outcome:=finalize_procurement_receipt(jsonb_build_object('p_purchase_order_id',ord.id,'p_receipt_id',receipt_id,'p_expected_order_version',ord.row_version,'p_expected_receipt_version',0,'p_idempotency_key','hold-release:'||p_id,'p_inspector_name',worker.full_name,
   'p_statement_storage_path',p_payload->>'statement_storage_path','p_statement_number',p_payload->>'statement_number','p_statement_date',p_payload->>'statement_date','p_memo',p_payload->>'reason','p_lines',lines));
  INSERT INTO inventory_lot_movements(lot_id,event_kind,event_id,quantity_base,created_by) VALUES(p_lot,'disposition',p_id,-p_quantity,auth.uid());
 ELSE
  target_state:=CASE p_action WHEN 'reject' THEN 'rejected' WHEN 'return' THEN 'returned' WHEN 'waste' THEN 'waste' ELSE lot.state END;
  IF p_action='waste' AND lot.state='available' THEN
   UPDATE inventory_items SET current_stock=current_stock-p_quantity,quantity=current_stock-p_quantity,updated_at=clock_timestamp() WHERE id=lot.ingredient_id;
   INSERT INTO inventory_transactions(restaurant_id,ingredient_id,transaction_type,quantity_g,reference_type,reference_id,note,created_by,performed_by_employee_id,stock_before,stock_after)
   VALUES(p_store,lot.ingredient_id,'waste',-p_quantity,'inventory_lot_disposition',p_id,p_payload->>'reason',auth.uid(),worker.id,stock,stock-p_quantity);
  ELSE
   UPDATE inventory_lots SET quantity_base=quantity_base-p_quantity WHERE id=p_lot;
   INSERT INTO inventory_lot_movements(lot_id,event_kind,event_id,quantity_base,created_by) VALUES(p_lot,'disposition',p_id,-p_quantity,auth.uid());
  END IF;
  INSERT INTO inventory_lots(id,restaurant_id,ingredient_id,location_id,supplier_lot_code,expiry_date,quantity_base,state,source_kind,source_id,source_component,receipt_line_id,parent_lot_id)
  VALUES(target_id,p_store,lot.ingredient_id,coalesce(loc.id,lot.location_id),lot.supplier_lot_code,lot.expiry_date,p_quantity,target_state,'disposition',p_id,1,lot.receipt_line_id,p_lot);
  INSERT INTO inventory_lot_movements(lot_id,event_kind,event_id,quantity_base,created_by) VALUES(target_id,'disposition',p_id,p_quantity,auth.uid());
  outcome:=jsonb_build_object('id',p_id,'lot_id',target_id,'state',target_state,'quantity_base',p_quantity);
 END IF;
 PERFORM inventory_queue_lot_reconciliation_v1(ARRAY[lot.ingredient_id]);
 UPDATE inventory_lot_dispositions SET result=outcome WHERE id=p_id;
 RETURN outcome;
END $$;
REVOKE ALL ON FUNCTION public.inventory_dispose_lot_v1(uuid,uuid,uuid,text,numeric,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.inventory_dispose_lot_v1(uuid,uuid,uuid,text,numeric,jsonb) TO authenticated;

-- COMPONENT 20261022144000_inventory_lot_workspace.sql
-- Bounded lot workspace and count inputs; scope is checked before any rows leave
-- the server. Stock locations are independent of service areas and kitchens.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE FUNCTION public.inventory_lot_workspace_v1(p_store uuid,p_after uuid DEFAULT NULL,p_ingredient uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE actor jsonb; rows jsonb; tail uuid; result jsonb;
BEGIN
 actor:=procurement_actor(p_store);
 WITH page AS MATERIALIZED(SELECT l.* FROM inventory_lots l WHERE l.restaurant_id=p_store AND l.state IN('available','held','rejected') AND l.quantity_base>0 AND (p_after IS NULL OR l.id>p_after) AND (p_ingredient IS NULL OR l.ingredient_id=p_ingredient) ORDER BY l.id LIMIT 51),
 visible AS(SELECT * FROM page ORDER BY id LIMIT 50)
 SELECT jsonb_build_object('lots',coalesce(jsonb_agg(to_jsonb(l)||jsonb_build_object('ingredient_name',i.name,'unit',i.unit,'purchase_order_id',ol.purchase_order_id,'purchase_order_line_id',ol.id,'purchase_order_no',o.purchase_order_no,'order_version',o.row_version,'quality',to_jsonb(q)) ORDER BY l.id),'[]'),
 'next_cursor',CASE WHEN (SELECT count(*) FROM page)>50 THEN (SELECT id FROM visible ORDER BY id DESC LIMIT 1) END) INTO result
 FROM visible l JOIN inventory_items i ON i.id=l.ingredient_id LEFT JOIN inventory_receipt_lines rl ON rl.id=l.receipt_line_id
 LEFT JOIN inventory_purchase_order_lines ol ON ol.id=rl.purchase_order_line_id LEFT JOIN inventory_purchase_orders o ON o.id=ol.purchase_order_id
 LEFT JOIN procurement_effective_quality_v1(ARRAY(SELECT DISTINCT rl.purchase_order_line_id FROM visible v JOIN inventory_receipt_lines rl ON rl.id=v.receipt_line_id))q ON q.order_line_id=ol.id;
 RETURN result||jsonb_build_object('locations',coalesce((SELECT jsonb_agg(to_jsonb(loc) ORDER BY loc.id) FROM (SELECT id,name,kind,revision FROM inventory_locations WHERE restaurant_id=p_store AND is_active ORDER BY id LIMIT 101)loc),'[]'),
 'employees',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'name',e.full_name) ORDER BY e.id) FROM (SELECT id,full_name FROM store_employees WHERE store_id=p_store AND is_active ORDER BY id LIMIT 201)e),'[]'),
 'can_dispose',can_verify_inventory_receipt(p_store));
END $$;
CREATE FUNCTION public.admin_get_inventory_count_inputs_v1(p_store uuid,p_after uuid DEFAULT NULL,p_ingredient uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 PERFORM require_brand_admin_v1();
 WITH page AS MATERIALIZED(SELECT i.id,i.name,i.unit,i.current_stock,i.updated_at FROM inventory_items i WHERE i.restaurant_id=p_store AND i.is_active AND (p_after IS NULL OR i.id>p_after) AND (p_ingredient IS NULL OR i.id=p_ingredient) ORDER BY i.id LIMIT 51),
 visible AS(SELECT * FROM page ORDER BY id LIMIT 50),
 products AS(SELECT DISTINCT ON(p.inventory_item_id) p.inventory_item_id,p.id,p.base_unit FROM inventory_products p JOIN visible i ON i.id=p.inventory_item_id WHERE p.is_active AND p.receipt_classification='stock' ORDER BY p.inventory_item_id,p.id),
 counts AS(SELECT DISTINCT ON(c.ingredient_id) c.ingredient_id,c.data x,c.count_id id,c.created_at FROM inventory_lot_count_rows c JOIN visible v ON v.id=c.ingredient_id ORDER BY c.ingredient_id,c.created_at DESC,c.count_id DESC)
 SELECT jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(i)||jsonb_build_object('product_id',p.id,'base_unit',p.base_unit,'tracked',t.ingredient_id IS NOT NULL,'last_count_id',c.id,'last_count_at',c.created_at,'last_unit_cost_base',c.x->'unit_cost_base') ORDER BY i.id),'[]'),
 'next_cursor',CASE WHEN (SELECT count(*) FROM page)>50 THEN (SELECT id FROM visible ORDER BY id DESC LIMIT 1) END) INTO result
 FROM visible i LEFT JOIN products p ON p.inventory_item_id=i.id LEFT JOIN inventory_lot_tracking t ON t.ingredient_id=i.id LEFT JOIN counts c ON c.ingredient_id=i.id;
 RETURN result;
END $$;
-- Keep lot selection requirements explicit in the real receiving view.
ALTER FUNCTION public.get_inventory_workflow_detail(uuid) RENAME TO get_inventory_workflow_detail_before_lots;
REVOKE ALL ON FUNCTION public.get_inventory_workflow_detail_before_lots(uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.get_inventory_workflow_detail(p_purchase_order_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE result jsonb; shop uuid; lines jsonb;
BEGIN
 result:=get_inventory_workflow_detail_before_lots(p_purchase_order_id);
 SELECT restaurant_id INTO shop FROM inventory_purchase_orders WHERE id=p_purchase_order_id;
 SELECT coalesce(jsonb_agg(x.value||jsonb_build_object('lot_tracking',t.ingredient_id IS NOT NULL,'held_quantity_base',coalesce(h.quantity_base,0)) ORDER BY x.ordinality),'[]') INTO lines
 FROM jsonb_array_elements(result->'lines') WITH ORDINALITY x(value,ordinality) JOIN inventory_purchase_order_lines ol ON ol.id=(x.value->>'id')::uuid JOIN inventory_products p ON p.id=ol.product_id LEFT JOIN inventory_lot_tracking t ON t.ingredient_id=p.inventory_item_id
 LEFT JOIN inventory_held_by_order_line_v1(ARRAY(SELECT id FROM inventory_purchase_order_lines WHERE purchase_order_id=p_purchase_order_id))h ON h.order_line_id=ol.id;
 RETURN jsonb_set(result,'{lines}',lines)||jsonb_build_object('inventory_locations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'kind',kind) ORDER BY id) FROM inventory_locations WHERE restaurant_id=shop AND is_active),'[]'));
END $$;
-- Do not let a tracked ingredient silently opt out via a new quality version.
CREATE FUNCTION public.inventory_guard_lot_quality_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM new_lot_profiles q JOIN inventory_products p ON p.id=q.product_id JOIN inventory_lot_tracking t ON t.ingredient_id=p.inventory_item_id WHERE q.criteria->>'lot_required' IS DISTINCT FROM 'true') THEN RAISE EXCEPTION 'INVENTORY_LOT_TRACKING_CANNOT_DISABLE'; END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER inventory_guard_lot_quality AFTER INSERT ON public.procurement_quality_profiles REFERENCING NEW TABLE AS new_lot_profiles FOR EACH STATEMENT EXECUTE FUNCTION public.inventory_guard_lot_quality_v1();
-- Location/employee response caps are explicit, never silently missing choices.
CREATE FUNCTION public.inventory_guard_location_limit_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF EXISTS(SELECT restaurant_id FROM inventory_locations WHERE restaurant_id IN(SELECT restaurant_id FROM new_inventory_locations) AND is_active GROUP BY restaurant_id HAVING count(*)>100) THEN RAISE EXCEPTION 'INVENTORY_LOCATION_LIMIT'; END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER inventory_guard_location_limit_insert AFTER INSERT ON public.inventory_locations REFERENCING NEW TABLE AS new_inventory_locations FOR EACH STATEMENT EXECUTE FUNCTION public.inventory_guard_location_limit_v1();
CREATE TRIGGER inventory_guard_location_limit_update AFTER UPDATE ON public.inventory_locations REFERENCING NEW TABLE AS new_inventory_locations FOR EACH STATEMENT EXECUTE FUNCTION public.inventory_guard_location_limit_v1();
REVOKE ALL ON FUNCTION public.inventory_guard_lot_quality_v1(),public.inventory_guard_location_limit_v1() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.inventory_lot_workspace_v1(uuid,uuid,uuid),public.admin_get_inventory_count_inputs_v1(uuid,uuid,uuid),public.get_inventory_workflow_detail(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.inventory_lot_workspace_v1(uuid,uuid,uuid),public.admin_get_inventory_count_inputs_v1(uuid,uuid,uuid),public.get_inventory_workflow_detail(uuid) TO authenticated;

-- COMPONENT 20261022145000_inventory_lot_boundaries.sql
-- Prevent receiving and shortage transfer from independently claiming a held
-- balance. PO locks serialize all three paths; no stock changes on rejection.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE FUNCTION public.inventory_assert_held_order_balance_v1(p_orders uuid[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF EXISTS(WITH lines AS MATERIALIZED(SELECT id,ordered_quantity_base,cancelled_quantity_base FROM inventory_purchase_order_lines WHERE purchase_order_id=ANY(p_orders)),
 accepted AS(SELECT rl.purchase_order_line_id,sum(rl.accepted_quantity_base) qty FROM inventory_receipt_lines rl JOIN inventory_receipts r ON r.id=rl.receipt_id AND r.status='confirmed' JOIN lines l ON l.id=rl.purchase_order_line_id GROUP BY rl.purchase_order_line_id),
 reserved AS(SELECT original_order_line_id,sum(quantity_base) qty FROM procurement_shortage_allocations a JOIN lines l ON l.id=a.original_order_line_id WHERE status='reserved' GROUP BY original_order_line_id)
 SELECT 1 FROM lines l JOIN inventory_held_by_order_line_v1(ARRAY(SELECT id FROM lines))h ON h.order_line_id=l.id LEFT JOIN accepted a ON a.purchase_order_line_id=l.id LEFT JOIN reserved r ON r.original_order_line_id=l.id
 WHERE coalesce(a.qty,0)+coalesce(r.qty,0)+h.quantity_base>l.ordered_quantity_base-l.cancelled_quantity_base) THEN RAISE EXCEPTION 'INVENTORY_HELD_ORDER_BALANCE_CONFLICT'; END IF;
END $$;
DO $$ DECLARE d text; BEGIN
 d:=pg_get_functiondef('public.inventory_capture_quarantine_v1()'::regprocedure);
 d:=replace(d,E'\n RETURN NULL;', E'\n PERFORM inventory_assert_held_order_balance_v1(ARRAY(SELECT DISTINCT purchase_order_id FROM new_lot_receipts WHERE status=''confirmed'')); RETURN NULL;'); EXECUTE d;
 d:=pg_get_functiondef('public.store_capture_order_quality_v1()'::regprocedure);
 d:=replace(d,E'\n RETURN NULL;', E'\n IF EXISTS(SELECT 1 FROM procurement_order_quality q JOIN procurement_quality_profiles profile ON profile.id=q.profile_id JOIN inventory_purchase_order_lines l ON l.id=q.order_line_id JOIN inventory_products p ON p.id=l.product_id LEFT JOIN inventory_lot_tracking t ON t.ingredient_id=p.inventory_item_id WHERE q.order_line_id=ANY(ids) AND profile.criteria->>''lot_required''=''true'' AND t.ingredient_id IS NULL) THEN RAISE EXCEPTION ''INVENTORY_OPENING_LOT_COUNT_REQUIRED''; END IF; RETURN NULL;'); EXECUTE d;
END $$;
REVOKE ALL ON FUNCTION public.inventory_assert_held_order_balance_v1(uuid[]) FROM PUBLIC,anon,authenticated,service_role;

