-- COMPONENT 20261022160000_store_closure_boundaries.sql
-- Every deactivation path shares the same pending-work boundary. Closing retains
-- accounting/sales history and never fabricates a paid/reported external state.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE FUNCTION public.store_closure_pending_v1(p_store uuid) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
 SELECT jsonb_build_object(
  'orders',(SELECT count(*) FROM orders WHERE restaurant_id=p_store AND status IN('pending','confirmed','serving')),
  'occupied_tables',(SELECT count(*) FROM tables WHERE restaurant_id=p_store AND status='occupied'),
  'direct_requests',(SELECT count(*) FROM direct_order_requests WHERE restaurant_id=p_store AND state IN('awaiting_quote','quoted','awaiting_payment_review')),
  'account_jobs',(SELECT count(*) FROM store_account_onboarding_jobs WHERE store_id=p_store AND status<>'complete'),
  'purchase_requests',(SELECT count(*) FROM inventory_purchase_requests WHERE restaurant_id=p_store AND status NOT IN('allocated','cancelled')),
  'purchase_orders',(SELECT count(*) FROM inventory_purchase_orders WHERE restaurant_id=p_store AND status NOT IN('received','cancelled','office_rejected')),
  'draft_receipts',(SELECT count(*) FROM inventory_receipts WHERE restaurant_id=p_store AND status='draft'),
  'held_lots',(SELECT count(*) FROM inventory_lots WHERE restaurant_id=p_store AND state IN('held','rejected') AND quantity_base>0),
  'accounting',(SELECT count(*) FROM inventory_purchase_orders o LEFT JOIN procurement_accounting_status a ON a.purchase_order_id=o.id
    WHERE o.restaurant_id=p_store AND EXISTS(SELECT 1 FROM inventory_receipts r WHERE r.purchase_order_id=o.id AND r.status='confirmed')
    AND (a.purchase_order_id IS NULL OR a.source_order_version<>o.row_version OR a.reconciliation_required OR a.held_count>0 OR a.payable_count>a.paid_count)),
  'supplier_reports',(SELECT count(*) FROM procurement_receipt_reports WHERE restaurant_id=p_store AND sent_at IS NULL),
  'print_retries',(SELECT count(*) FROM print_jobs WHERE restaurant_id=p_store AND status IN('pending','failed','printing')),
  'misa_retries',(SELECT count(*) FROM meinvoice_jobs WHERE store_id=p_store AND status IN('pending_manual_config','pending','dispatch_paused','failed','manual_action_required')),
  'invoice_retries',(SELECT count(*) FROM einvoice_jobs j JOIN orders o ON o.id=j.order_id WHERE o.restaurant_id=p_store AND j.status IN('pending','failed_terminal','stale')),
  'device_outbox',(SELECT count(*) FROM store_workflow_devices WHERE restaurant_id=p_store AND pending_count>0)
 );
$$;
CREATE FUNCTION public.admin_get_store_closure_readiness_v1(p_store uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE pending jsonb;
BEGIN
 PERFORM require_brand_admin_v1();
 IF NOT EXISTS(SELECT 1 FROM restaurants WHERE id=p_store) THEN RAISE EXCEPTION 'STORE_NOT_FOUND'; END IF;
 pending:=store_closure_pending_v1(p_store);
 RETURN jsonb_build_object('pending',pending,'ready',NOT EXISTS(SELECT 1 FROM jsonb_each_text(pending)x WHERE x.value::bigint>0));
END $$;
CREATE FUNCTION public.store_guard_closure_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE pending jsonb;
BEGIN
 IF OLD.is_active AND NOT NEW.is_active THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('store-opening:'||OLD.id,0));
  pending:=store_closure_pending_v1(OLD.id);
  IF EXISTS(SELECT 1 FROM jsonb_each_text(pending)x WHERE x.value::bigint>0) THEN RAISE EXCEPTION 'STORE_CLOSURE_PENDING' USING DETAIL=pending::text; END IF;
  UPDATE store_lifecycle SET state='closed',revision=revision+1,changed_by=auth.uid(),changed_at=now() WHERE restaurant_id=OLD.id;
 ELSIF NOT OLD.is_active AND NEW.is_active AND EXISTS(SELECT 1 FROM store_lifecycle WHERE restaurant_id=OLD.id AND state='closed') THEN
  RAISE EXCEPTION 'STORE_REOPEN_REQUIRES_PREPARATION';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER store_closure_guard BEFORE UPDATE OF is_active ON public.restaurants FOR EACH ROW EXECUTE FUNCTION public.store_guard_closure_v1();
-- Equivalent claims refresh for the entire affected set, with each relation
-- aggregated once. The old per-user function remains available to its callers.
CREATE FUNCTION public.store_refresh_closed_claims_v1(p_store uuid) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE n integer;
BEGIN
 WITH affected AS MATERIALIZED(SELECT u.* FROM users u WHERE u.auth_id IS NOT NULL AND (u.restaurant_id=p_store OR u.primary_store_id=p_store OR EXISTS(SELECT 1 FROM user_store_access s WHERE s.user_id=u.id AND s.store_id=p_store))),
 store_scope AS MATERIALIZED(SELECT u.id user_id,s.store_id FROM affected u JOIN user_store_access s ON s.user_id=u.id AND s.is_active JOIN restaurants r ON r.id=s.store_id AND r.is_active WHERE u.is_active
 UNION SELECT u.id,r.id FROM affected u JOIN restaurants r ON r.id=coalesce(u.primary_store_id,u.restaurant_id) AND r.is_active WHERE u.is_active),
 brand_scope AS(SELECT u.id user_id,b.brand_id FROM affected u JOIN user_brand_access b ON b.user_id=u.id AND b.is_active WHERE u.is_active UNION SELECT id,brand_id FROM affected WHERE is_active AND brand_id IS NOT NULL),
 entity_scope AS(SELECT u.id user_id,e.tax_entity_id FROM affected u JOIN user_tax_entity_access e ON e.user_id=u.id AND e.is_active WHERE u.is_active UNION SELECT s.user_id,r.tax_entity_id FROM store_scope s JOIN restaurants r ON r.id=s.store_id WHERE r.tax_entity_id IS NOT NULL),
 stores AS(SELECT user_id,jsonb_agg(store_id ORDER BY store_id) ids FROM store_scope GROUP BY user_id),
 brands AS(SELECT user_id,jsonb_agg(brand_id ORDER BY brand_id) ids FROM brand_scope GROUP BY user_id),
 entities AS(SELECT user_id,jsonb_agg(tax_entity_id ORDER BY tax_entity_id) ids FROM entity_scope GROUP BY user_id)
 UPDATE auth.users a SET raw_app_meta_data=coalesce(a.raw_app_meta_data,'{}')||jsonb_build_object('role',CASE WHEN u.is_active THEN u.role END,'brand_ids',coalesce(b.ids,'[]'),'accessible_store_ids',coalesce(s.ids,'[]'),'accessible_tax_entity_ids',coalesce(e.ids,'[]'),'primary_store_id',CASE WHEN u.is_active THEN coalesce(u.primary_store_id,u.restaurant_id) END)
 FROM affected u LEFT JOIN stores s ON s.user_id=u.id LEFT JOIN brands b ON b.user_id=u.id LEFT JOIN entities e ON e.user_id=u.id WHERE a.id=u.auth_id;
 GET DIAGNOSTICS n=ROW_COUNT;
 RETURN n;
END $$;
DO $$ DECLARE d text; start_at integer; end_at integer; BEGIN
 d:=pg_get_functiondef('public.admin_close_store(uuid,text)'::regprocedure);
 d:=replace(d,'  SELECT * INTO v_store FROM public.restaurants', '  PERFORM pg_advisory_xact_lock(hashtextextended(''store-opening:''||p_store_id,0)); SELECT * INTO v_store FROM public.restaurants');
 start_at:=position('  FOR v_auth IN' IN d); end_at:=position('END LOOP;' IN d);
 IF start_at=0 OR end_at<start_at THEN RAISE EXCEPTION 'STORE_CLOSURE_BATCH_PATCH_MISMATCH'; END IF;
 d:=substring(d FROM 1 FOR start_at-1)||'  v_claims_refreshed:=public.store_refresh_closed_claims_v1(p_store_id);'||substring(d FROM end_at+length('END LOOP;')); EXECUTE d;
END $$;
CREATE OR REPLACE FUNCTION public.admin_deactivate_restaurant(p_store_id uuid) RETURNS public.stores
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE result stores;
BEGIN
 PERFORM admin_close_store(p_store_id,'Closure through compatible deactivation entry point');
 SELECT * INTO result FROM stores WHERE id=p_store_id;
 RETURN result;
END $$;
CREATE FUNCTION public.store_guard_closed_procurement_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('store-opening:'||restaurant_id,0)) FROM (SELECT DISTINCT restaurant_id FROM new_procurement_intake ORDER BY restaurant_id)s;
 IF EXISTS(SELECT 1 FROM new_procurement_intake n JOIN restaurants r ON r.id=n.restaurant_id WHERE NOT r.is_active) THEN RAISE EXCEPTION 'STORE_CLOSED_FOR_NEW_PROCUREMENT'; END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER store_procurement_intake_requests AFTER INSERT ON public.inventory_purchase_requests REFERENCING NEW TABLE AS new_procurement_intake FOR EACH STATEMENT EXECUTE FUNCTION public.store_guard_closed_procurement_v1();
CREATE TRIGGER store_procurement_intake_orders AFTER INSERT ON public.inventory_purchase_orders REFERENCING NEW TABLE AS new_procurement_intake FOR EACH STATEMENT EXECUTE FUNCTION public.store_guard_closed_procurement_v1();
REVOKE ALL ON FUNCTION public.store_closure_pending_v1(uuid),public.store_guard_closure_v1(),public.store_refresh_closed_claims_v1(uuid),public.store_guard_closed_procurement_v1() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.admin_get_store_closure_readiness_v1(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_get_store_closure_readiness_v1(uuid) TO authenticated;

-- COMPONENT 20261022170000_store_operational_acceptance.sql
-- Human evidence complements executable checks. Unknown opening cash, stock,
-- recipes and external Office identity are never inferred from a POS template.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE TABLE public.store_external_links (
 restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,provider text NOT NULL CHECK(provider='office'),
 external_id uuid NOT NULL,tax_entity_id uuid NOT NULL REFERENCES public.tax_entity(id),contract_version text NOT NULL,evidence_reference text NOT NULL,
 verified_by uuid NOT NULL,verified_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(restaurant_id,provider),UNIQUE(provider,external_id)
);
ALTER TABLE public.store_external_links ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_external_links FROM PUBLIC,anon,authenticated;
CREATE TRIGGER store_external_links_immutable BEFORE UPDATE ON public.store_external_links FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TABLE public.store_operational_acceptances (
 id uuid PRIMARY KEY,restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 employee_id uuid NOT NULL,source_hash text NOT NULL,payload jsonb NOT NULL,input_hash text NOT NULL,
 actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX store_operational_acceptances_store ON public.store_operational_acceptances(restaurant_id,created_at DESC,id DESC);
ALTER TABLE public.store_operational_acceptances ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_operational_acceptances FROM PUBLIC,anon,authenticated;
CREATE TRIGGER store_operational_acceptances_immutable BEFORE UPDATE ON public.store_operational_acceptances FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE FUNCTION public.store_operational_source_v1(p_store uuid) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
 SELECT md5(jsonb_build_object('workflow',store_workflow_source(p_store),'identity',(SELECT jsonb_build_array(brand_id,tax_entity_id,name,address) FROM restaurants WHERE id=p_store),
 'external_links',(SELECT jsonb_agg(jsonb_build_array(provider,external_id,tax_entity_id,contract_version) ORDER BY provider) FROM store_external_links WHERE restaurant_id=p_store),'settings',(SELECT md5(coalesce(settings_json,'{}')::text) FROM restaurant_settings WHERE restaurant_id=p_store),
 'recipes',(SELECT jsonb_agg(jsonb_build_array(id,menu_item_id,ingredient_id,quantity_g) ORDER BY id) FROM menu_recipes WHERE restaurant_id=p_store),
 'ingredients',(SELECT jsonb_agg(jsonb_build_array(id,unit,is_active) ORDER BY id) FROM inventory_items WHERE restaurant_id=p_store AND is_active),
 'products',(SELECT jsonb_agg(jsonb_build_array(id,inventory_item_id,base_unit,is_active,is_orderable,receipt_classification) ORDER BY id) FROM inventory_products WHERE restaurant_id=p_store AND is_active))::text);
$$;
CREATE FUNCTION public.admin_get_store_operational_inputs_v1(p_store uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 PERFORM require_brand_admin_v1();
 IF (SELECT count(*) FROM menu_items WHERE restaurant_id=p_store)>4000 OR (SELECT count(*) FROM inventory_products WHERE restaurant_id=p_store)>2000 OR (SELECT count(*) FROM menu_recipes WHERE restaurant_id=p_store)>20000 THEN RAISE EXCEPTION 'STORE_CONFIGURATION_LIMIT'; END IF;
 SELECT jsonb_build_object('source_hash',store_operational_source_v1(p_store),'office_store_id',(SELECT external_id FROM store_external_links WHERE restaurant_id=p_store AND provider='office'),'office_required',EXISTS(SELECT 1 FROM inventory_products WHERE restaurant_id=p_store AND is_active AND is_orderable),
 'menus_without_recipe',coalesce((SELECT jsonb_agg(jsonb_build_object('id',m.id,'name',m.name) ORDER BY m.id) FROM menu_items m WHERE m.restaurant_id=p_store AND m.is_available AND NOT m.is_archived AND m.size_parent_id IS NULL AND NOT EXISTS(SELECT 1 FROM menu_recipes recipe WHERE recipe.menu_item_id=m.id)),'[]'),
 'unmeasured_inventory',(SELECT count(*) FROM inventory_items i WHERE i.restaurant_id=p_store AND i.is_active AND NOT EXISTS(SELECT 1 FROM inventory_lot_count_rows c WHERE c.ingredient_id=i.id)),
 'last_acceptance',(SELECT jsonb_build_object('id',a.id,'created_at',a.created_at,'payload',a.payload,'source_current',a.source_hash=store_operational_source_v1(p_store)) FROM store_operational_acceptances a WHERE a.restaurant_id=p_store ORDER BY created_at DESC,id DESC LIMIT 1)) INTO result FROM restaurants r WHERE r.id=p_store;
 IF result IS NULL THEN RAISE EXCEPTION 'STORE_NOT_FOUND'; END IF;
 RETURN result;
END $$;
CREATE FUNCTION public.admin_record_store_operational_acceptance_v1(p_id uuid,p_store uuid,p_employee uuid,p_source_hash text,p_payload jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE previous store_operational_acceptances; input_hash text; source text; employee store_employees; shop restaurants; office_link store_external_links;
BEGIN
 PERFORM require_brand_admin_v1();
 IF p_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>1048576
 OR jsonb_typeof(p_payload->'opening_cash_amount') IS DISTINCT FROM 'number' OR (p_payload->>'opening_cash_amount')::numeric<0
 OR p_payload->>'currency' IS DISTINCT FROM 'VND' OR p_payload->>'timezone' IS DISTINCT FROM 'Asia/Ho_Chi_Minh'
 OR length(btrim(coalesce(p_payload->>'evidence_reference',''))) NOT BETWEEN 5 AND 1000
 OR EXISTS(SELECT 1 FROM unnest(ARRAY['channels','payments_refunds','cash_closing','offline_recovery','device_handover','reporting_owner'])key WHERE p_payload->'checks'->key IS DISTINCT FROM 'true'::jsonb)
 OR jsonb_typeof(p_payload->'recipe_exemptions') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'recipe_exemptions')>4000
 THEN RAISE EXCEPTION 'STORE_OPERATIONAL_EVIDENCE_REQUIRED'; END IF;
 input_hash:=md5(jsonb_build_object('store',p_store,'employee',p_employee,'source',p_source_hash,'payload',p_payload,'actor',auth.uid())::text);
 PERFORM pg_advisory_xact_lock(hashtextextended('store-opening:'||p_store,0));
 SELECT * INTO previous FROM store_operational_acceptances WHERE id=p_id;
 IF FOUND THEN
  IF previous.input_hash<>input_hash THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
  RETURN to_jsonb(previous);
 END IF;
 SELECT * INTO employee FROM store_employees WHERE id=p_employee AND store_id=p_store AND is_active;
 IF NOT FOUND THEN RAISE EXCEPTION 'HANDOVER_EMPLOYEE_REQUIRED'; END IF;
 SELECT * INTO shop FROM restaurants WHERE id=p_store FOR UPDATE;
 source:=store_operational_source_v1(p_store);
 IF p_source_hash IS DISTINCT FROM source THEN RAISE EXCEPTION 'STORE_CONFIGURATION_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'recipe_exemptions')x LEFT JOIN menu_items m ON m.id=(x->>'menu_id')::uuid AND m.restaurant_id=p_store AND m.is_available AND NOT m.is_archived
 WHERE m.id IS NULL OR length(btrim(coalesce(x->>'reason','')))<5) THEN RAISE EXCEPTION 'STORE_RECIPE_EXEMPTION_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM inventory_products WHERE restaurant_id=p_store AND is_active AND is_orderable) THEN
  IF nullif(p_payload->>'office_store_id','') IS NULL OR length(btrim(coalesce(p_payload->>'office_evidence','')))<5 OR length(btrim(coalesce(p_payload->>'office_contract_version','')))<1
   OR NOT coalesce((SELECT office_connected FROM procurement_store_onboarding WHERE restaurant_id=p_store),false) THEN RAISE EXCEPTION 'STORE_OFFICE_VERIFICATION_REQUIRED'; END IF;
  SELECT * INTO office_link FROM store_external_links WHERE restaurant_id=p_store AND provider='office';
  IF office_link.external_id IS NOT NULL AND (office_link.external_id<>(p_payload->>'office_store_id')::uuid OR office_link.tax_entity_id<>shop.tax_entity_id) THEN RAISE EXCEPTION 'STORE_OFFICE_IDENTITY_CHANGED'; END IF;
  INSERT INTO store_external_links(restaurant_id,provider,external_id,tax_entity_id,contract_version,evidence_reference,verified_by) VALUES(p_store,'office',(p_payload->>'office_store_id')::uuid,shop.tax_entity_id,p_payload->>'office_contract_version',p_payload->>'office_evidence',auth.uid()) ON CONFLICT(restaurant_id,provider) DO NOTHING;
 END IF;
 INSERT INTO store_operational_acceptances VALUES(p_id,p_store,p_employee,store_operational_source_v1(p_store),p_payload||jsonb_build_object('employee_snapshot',jsonb_build_object('id',employee.id,'name',employee.full_name,'number',employee.employee_number)),input_hash,auth.uid(),clock_timestamp()) RETURNING * INTO previous;
 RETURN to_jsonb(previous);
END $$;
ALTER FUNCTION public.admin_get_store_lifecycle_v1(uuid) RENAME TO admin_get_store_lifecycle_before_operational;
REVOKE ALL ON FUNCTION public.admin_get_store_lifecycle_before_operational(uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.admin_get_store_lifecycle_v1(p_store_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE result jsonb; acceptance store_operational_acceptances; checks jsonb; source text; valid boolean;
BEGIN
 result:=admin_get_store_lifecycle_before_operational(p_store_id);
 IF (SELECT count(*) FROM inventory_products WHERE restaurant_id=p_store_id)>2000 OR (SELECT count(*) FROM menu_recipes WHERE restaurant_id=p_store_id)>20000 THEN RAISE EXCEPTION 'STORE_CONFIGURATION_LIMIT'; END IF;
 SELECT * INTO acceptance FROM store_operational_acceptances WHERE restaurant_id=p_store_id ORDER BY created_at DESC,id DESC LIMIT 1;
 valid:=coalesce(acceptance.source_hash=store_operational_source_v1(p_store_id) AND EXISTS(SELECT 1 FROM store_employees WHERE id=acceptance.employee_id AND store_id=p_store_id AND is_active),false);
 checks:=result->'checks'||jsonb_build_object('operational_acceptance',valid,
 'initial_inventory',NOT EXISTS(SELECT 1 FROM inventory_items i WHERE i.restaurant_id=p_store_id AND i.is_active AND NOT EXISTS(SELECT 1 FROM inventory_lot_count_rows c WHERE c.ingredient_id=i.id)),
 'recipes',NOT EXISTS(SELECT 1 FROM menu_recipes recipe LEFT JOIN inventory_items i ON i.id=recipe.ingredient_id AND i.restaurant_id=p_store_id AND i.is_active WHERE recipe.restaurant_id=p_store_id AND (i.id IS NULL OR recipe.quantity_g<=0)) AND
 NOT EXISTS(SELECT 1 FROM menu_items m WHERE m.restaurant_id=p_store_id AND m.is_available AND NOT m.is_archived AND m.size_parent_id IS NULL AND NOT EXISTS(SELECT 1 FROM menu_recipes r WHERE r.menu_item_id=m.id) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(acceptance.payload->'recipe_exemptions','[]'))x WHERE x->>'menu_id'=m.id::text)));
 source:=md5(jsonb_build_array(result->>'source_hash',store_operational_source_v1(p_store_id),acceptance.id,checks-'field_verification')::text);
 checks:=checks||jsonb_build_object('field_verification',EXISTS(SELECT 1 FROM store_opening_verifications WHERE restaurant_id=p_store_id AND source_hash=source));
 RETURN result||jsonb_build_object('checks',checks,'source_hash',source,'business_ready',NOT EXISTS(SELECT 1 FROM jsonb_each(checks)x WHERE x.value<>'true'::jsonb),'closure',store_closure_pending_v1(p_store_id));
END $$;
REVOKE ALL ON FUNCTION public.store_operational_source_v1(uuid) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.admin_get_store_operational_inputs_v1(uuid),public.admin_record_store_operational_acceptance_v1(uuid,uuid,uuid,text,jsonb),public.admin_get_store_lifecycle_v1(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_get_store_operational_inputs_v1(uuid),public.admin_record_store_operational_acceptance_v1(uuid,uuid,uuid,text,jsonb),public.admin_get_store_lifecycle_v1(uuid) TO authenticated;

-- COMPONENT 20261022180000_procurement_reconciliation_evidence.sql
-- POS exposes its immutable source and records evidence of Office reconciliation.
-- This creates no payment, supplier credit or invoice in either system.
-- production-gate: self-verifying

SET LOCAL lock_timeout='5s';
CREATE TABLE public.procurement_store_identity (
 purchase_order_id uuid PRIMARY KEY REFERENCES public.inventory_purchase_orders(id) ON DELETE CASCADE,
 restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,tax_entity_id uuid,brand_id uuid,
 store_code text,store_name text NOT NULL,office_store_id uuid,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.procurement_reconciliation_evidence (
 id uuid PRIMARY KEY,restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 purchase_order_id uuid NOT NULL REFERENCES public.inventory_purchase_orders(id) ON DELETE CASCADE,
 source_hash text NOT NULL,source_order_version integer NOT NULL,payload jsonb NOT NULL,input_hash text NOT NULL,
 expected_gross numeric NOT NULL,expected_credit numeric NOT NULL,matched boolean NOT NULL,settled boolean NOT NULL,
 actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX procurement_reconciliation_evidence_order ON public.procurement_reconciliation_evidence(purchase_order_id,created_at DESC,id DESC);
ALTER TABLE public.procurement_store_identity ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.procurement_reconciliation_evidence ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.procurement_store_identity,public.procurement_reconciliation_evidence FROM PUBLIC,anon,authenticated;
CREATE TRIGGER procurement_store_identity_immutable BEFORE UPDATE ON public.procurement_store_identity FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TRIGGER procurement_reconciliation_evidence_immutable BEFORE UPDATE ON public.procurement_reconciliation_evidence FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE FUNCTION public.procurement_capture_store_identity_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 INSERT INTO procurement_store_identity(purchase_order_id,restaurant_id,tax_entity_id,brand_id,store_code,store_name,office_store_id)
 SELECT n.id,r.id,r.tax_entity_id,r.brand_id,r.short_code,r.name,l.external_id FROM new_identity_purchase_orders n JOIN restaurants r ON r.id=n.restaurant_id LEFT JOIN store_external_links l ON l.restaurant_id=r.id AND l.provider='office';
 RETURN NULL;
END $$;
CREATE TRIGGER procurement_capture_store_identity AFTER INSERT ON public.inventory_purchase_orders REFERENCING NEW TABLE AS new_identity_purchase_orders FOR EACH STATEMENT EXECUTE FUNCTION public.procurement_capture_store_identity_v1();
CREATE FUNCTION public.get_procurement_reconciliation_source_v1(p_store uuid,p_orders uuid[]) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE data jsonb; result jsonb; actor jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN
  actor:=procurement_actor(p_store);
  IF NOT coalesce((actor->>'can_view_prices')::boolean,false) THEN RAISE EXCEPTION 'PROCUREMENT_PRICE_FORBIDDEN'; END IF;
 END IF;
 IF p_orders IS NULL OR cardinality(p_orders) NOT BETWEEN 1 AND 50 OR array_position(p_orders,NULL) IS NOT NULL THEN RAISE EXCEPTION 'PROCUREMENT_SCOPE_FORBIDDEN'; END IF;
 IF (SELECT count(*) FROM inventory_receipt_lines l JOIN inventory_receipts r ON r.id=l.receipt_id WHERE r.purchase_order_id=ANY(p_orders))>10000 THEN RAISE EXCEPTION 'PROCUREMENT_RECONCILIATION_PAGE_LIMIT'; END IF;
 data:=procurement_snapshots_data(ARRAY[p_store],p_orders);
 WITH credit AS(SELECT t.purchase_order_id,sum(round(round(t.quantity_base/ol.order_unit_quantity_base_snapshot,3)*rl.actual_unit_price,2)+round(round(t.quantity_base/ol.order_unit_quantity_base_snapshot,3)*rl.actual_unit_price*ol.tax_rate_snapshot/100,2)) amount
 FROM inventory_supplier_returns t JOIN inventory_receipt_lines rl ON rl.id=t.receipt_line_id JOIN inventory_purchase_order_lines ol ON ol.id=rl.purchase_order_line_id WHERE t.purchase_order_id=ANY(p_orders) GROUP BY t.purchase_order_id),
 previous AS(SELECT DISTINCT ON(purchase_order_id) * FROM procurement_reconciliation_evidence WHERE purchase_order_id=ANY(p_orders) ORDER BY purchase_order_id,created_at DESC,id DESC)
 SELECT jsonb_agg(jsonb_build_object('purchase_order_id',x->'order'->'id','store_id',p_store,'identity',CASE WHEN identity.purchase_order_id IS NOT NULL THEN to_jsonb(identity)||'{"basis":"order_snapshot"}' ELSE jsonb_build_object('restaurant_id',r.id,'tax_entity_id',r.tax_entity_id,'brand_id',r.brand_id,'store_code',r.short_code,'store_name',r.name,'basis','current_registry') END,
 'source_order_version',x->'order'->'row_version','source_hash',md5(jsonb_build_array(x,coalesce(to_jsonb(identity),jsonb_build_object('store',r.id,'entity',r.tax_entity_id,'brand',r.brand_id,'code',r.short_code,'name',r.name)))::text),'currency','VND',
 'expected_gross',coalesce((SELECT sum((receipt->>'total_amount')::numeric) FROM jsonb_array_elements(x->'receipts')receipt),0),
 'expected_credit',coalesce(c.amount,0),'source',x,'last_evidence',to_jsonb(previous)) ORDER BY x->'order'->>'id') INTO result
 FROM jsonb_array_elements(data)x JOIN restaurants r ON r.id=p_store LEFT JOIN procurement_store_identity identity ON identity.purchase_order_id=(x->'order'->>'id')::uuid LEFT JOIN credit c ON c.purchase_order_id=(x->'order'->>'id')::uuid LEFT JOIN previous ON previous.purchase_order_id=(x->'order'->>'id')::uuid;
 IF octet_length(result::text)>8388608 THEN RAISE EXCEPTION 'PROCUREMENT_RECONCILIATION_PAGE_LIMIT'; END IF;
 RETURN coalesce(result,'[]');
END $$;
CREATE FUNCTION public.admin_record_procurement_reconciliation_v1(p_id uuid,p_store uuid,p_order uuid,p_source_hash text,p_payload jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE prior procurement_reconciliation_evidence; source jsonb; input_hash text; matched boolean; settled boolean; gross numeric; credit numeric; net numeric;
BEGIN
 PERFORM require_brand_admin_v1();
 IF p_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>65536
 OR p_payload->>'currency' IS DISTINCT FROM 'VND' OR jsonb_typeof(p_payload->'invoice_ids') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'invoice_ids')>100
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'invoice_ids') x WHERE jsonb_typeof(x) IS DISTINCT FROM 'string' OR length(btrim(x#>>'{}')) NOT BETWEEN 1 AND 200)
 OR (SELECT count(*)<>count(DISTINCT x) FROM jsonb_array_elements(p_payload->'invoice_ids')x)
 OR length(btrim(coalesce(p_payload->>'office_reference',''))) NOT BETWEEN 5 AND 1000
 OR EXISTS(SELECT 1 FROM unnest(ARRAY['invoice_amount','credit_amount','paid_amount'])key WHERE jsonb_typeof(p_payload->key) IS DISTINCT FROM 'number' OR (p_payload->>key)::numeric<0 OR (p_payload->>key)::numeric<>round((p_payload->>key)::numeric,2))
 THEN RAISE EXCEPTION 'PROCUREMENT_ACCOUNTING_EVIDENCE_INVALID'; END IF;
 input_hash:=md5(jsonb_build_object('store',p_store,'order',p_order,'source',p_source_hash,'payload',p_payload,'actor',auth.uid())::text);
 PERFORM pg_advisory_xact_lock(hashtextextended('procurement-reconciliation:'||p_id,0));
 SELECT * INTO prior FROM procurement_reconciliation_evidence WHERE id=p_id;
 IF FOUND THEN IF prior.input_hash<>input_hash THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF; RETURN to_jsonb(prior); END IF;
 PERFORM 1 FROM inventory_purchase_orders WHERE id=p_order AND restaurant_id=p_store FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PROCUREMENT_SCOPE_FORBIDDEN'; END IF;
 source:=get_procurement_reconciliation_source_v1(p_store,ARRAY[p_order])->0;
 IF p_source_hash IS DISTINCT FROM source->>'source_hash' THEN RAISE EXCEPTION 'PROCUREMENT_ACCOUNTING_SOURCE_CHANGED'; END IF;
 gross:=(source->>'expected_gross')::numeric; credit:=(source->>'expected_credit')::numeric; net:=gross-credit;
 matched:=(p_payload->>'invoice_amount')::numeric=gross AND (p_payload->>'credit_amount')::numeric=credit AND net>=0 AND (p_payload->>'paid_amount')::numeric<=net AND (gross=0 OR jsonb_array_length(p_payload->'invoice_ids')>0);
 settled:=matched AND (p_payload->>'paid_amount')::numeric=net;
 INSERT INTO procurement_reconciliation_evidence VALUES(p_id,p_store,p_order,p_source_hash,(source->>'source_order_version')::integer,p_payload,input_hash,gross,credit,matched,settled,auth.uid(),clock_timestamp()) RETURNING * INTO prior;
 -- Compatibility projection describes the recorded external evidence. It is
 -- never used to create a new payment or to mark a supplier transmission sent.
 INSERT INTO procurement_accounting_status(purchase_order_id,restaurant_id,source_order_version,invoice_count,payable_count,held_count,paid_count,reconciliation_required,observed_at)
 VALUES(p_order,p_store,(source->>'source_order_version')::integer,jsonb_array_length(p_payload->'invoice_ids'),CASE WHEN net>0 THEN 1 ELSE 0 END,CASE WHEN matched THEN 0 ELSE 1 END,CASE WHEN settled AND net>0 THEN 1 ELSE 0 END,NOT matched,clock_timestamp())
 ON CONFLICT(purchase_order_id) DO UPDATE SET source_order_version=EXCLUDED.source_order_version,invoice_count=EXCLUDED.invoice_count,payable_count=EXCLUDED.payable_count,held_count=EXCLUDED.held_count,paid_count=EXCLUDED.paid_count,reconciliation_required=EXCLUDED.reconciliation_required,observed_at=EXCLUDED.observed_at;
 RETURN to_jsonb(prior);
END $$;
REVOKE ALL ON FUNCTION public.procurement_capture_store_identity_v1() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.get_procurement_reconciliation_source_v1(uuid,uuid[]),public.admin_record_procurement_reconciliation_v1(uuid,uuid,uuid,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_procurement_reconciliation_source_v1(uuid,uuid[]) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.admin_record_procurement_reconciliation_v1(uuid,uuid,uuid,text,jsonb) TO authenticated;

-- COMPONENT 20261022181000_store_reopening_preparation.sql
-- Reopening restores the same identity to preparation, requiring new handover
-- and field evidence. Suspending/resuming trading remains a separate transition.
-- production-gate: self-verifying

CREATE TABLE public.store_reopening_events (
 id uuid PRIMARY KEY,restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE,
 previous_revision bigint NOT NULL,reason text NOT NULL,actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX store_reopening_events_store ON public.store_reopening_events(restaurant_id,created_at DESC);
ALTER TABLE public.store_reopening_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_reopening_events FROM PUBLIC,anon,authenticated;
CREATE TRIGGER store_reopening_events_immutable BEFORE UPDATE ON public.store_reopening_events FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE FUNCTION public.admin_prepare_store_reopening_v1(p_id uuid,p_store uuid,p_expected_revision bigint,p_reason text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE lifecycle store_lifecycle; prior store_reopening_events;
BEGIN
 PERFORM require_brand_admin_v1();
 IF p_id IS NULL OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'STORE_REOPEN_REASON_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('store-opening:'||p_store,0));
 SELECT * INTO prior FROM store_reopening_events WHERE id=p_id;
 IF FOUND THEN
  IF prior.restaurant_id<>p_store OR prior.previous_revision<>p_expected_revision OR prior.reason<>btrim(p_reason) OR prior.actor_id<>auth.uid() THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF;
  RETURN admin_get_store_lifecycle_v1(p_store);
 END IF;
 SELECT * INTO lifecycle FROM store_lifecycle WHERE restaurant_id=p_store FOR UPDATE;
 IF NOT FOUND OR lifecycle.state<>'closed' OR lifecycle.revision<>p_expected_revision THEN RAISE EXCEPTION 'LIFECYCLE_CHANGED'; END IF;
 PERFORM 1 FROM restaurants WHERE id=p_store FOR UPDATE;
 INSERT INTO store_reopening_events VALUES(p_id,p_store,p_expected_revision,btrim(p_reason),auth.uid(),now());
 UPDATE store_lifecycle SET state='preparing',revision=revision+1,activated_source_hash=NULL,changed_by=auth.uid(),changed_at=now() WHERE restaurant_id=p_store;
 UPDATE restaurants SET is_active=true WHERE id=p_store;
 UPDATE user_store_access access SET is_active=true,updated_at=now() FROM users u WHERE access.user_id=u.id AND access.store_id=p_store AND u.is_active
 AND EXISTS(SELECT 1 FROM store_fixed_account_requirements req WHERE req.store_id=p_store AND req.provisioned_user_id=u.id AND req.is_active AND req.account_code=u.fixed_account_code AND req.role=u.role);
 PERFORM store_refresh_closed_claims_v1(p_store);
 RETURN admin_get_store_lifecycle_v1(p_store);
END $$;
DO $$ DECLARE d text; BEGIN
 d:=pg_get_functiondef('public.store_operational_source_v1(uuid)'::regprocedure);
 d:=replace(d,'''workflow'',store_workflow_source(p_store)', '''reopening'',(SELECT max(created_at) FROM store_reopening_events WHERE restaurant_id=p_store),''workflow'',store_workflow_source(p_store)'); EXECUTE d;
 d:=pg_get_functiondef('public.admin_get_store_lifecycle_before_operational(uuid)'::regprocedure);
 d:=replace(d,'h.account_snapshot=accounts)', 'h.account_snapshot=accounts AND h.created_at>=coalesce((SELECT max(created_at) FROM store_reopening_events WHERE restaurant_id=p_store_id),''-infinity''::timestamptz))'); EXECUTE d;
END $$;
REVOKE ALL ON FUNCTION public.admin_prepare_store_reopening_v1(uuid,uuid,bigint,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_prepare_store_reopening_v1(uuid,uuid,bigint,text) TO authenticated;

-- COMPONENT 20261022182000_procurement_quality_review.sql
-- Bounded comparison of frozen criteria and the latest approved version.
-- production-gate: self-verifying

CREATE FUNCTION public.admin_get_order_quality_review_v1(p_store uuid,p_order uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE ids uuid[];
BEGIN
 PERFORM require_brand_admin_v1();
 IF NOT EXISTS(SELECT 1 FROM inventory_purchase_orders WHERE id=p_order AND restaurant_id=p_store) THEN RAISE EXCEPTION 'PROCUREMENT_SCOPE_FORBIDDEN'; END IF;
 SELECT array_agg(id ORDER BY id) INTO ids FROM inventory_purchase_order_lines WHERE purchase_order_id=p_order;
 IF cardinality(ids)>200 THEN RAISE EXCEPTION 'QUALITY_ORDER_LINE_LIMIT'; END IF;
 RETURN coalesce((WITH latest AS(SELECT DISTINCT ON(product_id) id,product_id,revision,criteria,reason FROM procurement_quality_profiles WHERE restaurant_id=p_store AND product_id IN(SELECT product_id FROM inventory_purchase_order_lines WHERE id=ANY(ids)) ORDER BY product_id,revision DESC)
 SELECT jsonb_agg(jsonb_build_object('line_id',l.id,'product_name',p.name,'current',to_jsonb(q),'latest',to_jsonb(v)) ORDER BY l.id)
 FROM inventory_purchase_order_lines l JOIN inventory_products p ON p.id=l.product_id JOIN procurement_effective_quality_v1(ids)q ON q.order_line_id=l.id LEFT JOIN latest v ON v.product_id=l.product_id WHERE l.id=ANY(ids)),'[]');
END $$;
REVOKE ALL ON FUNCTION public.admin_get_order_quality_review_v1(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_get_order_quality_review_v1(uuid,uuid) TO authenticated;

-- COMPONENT 20261022190000_procurement_demand_initial_plans.sql
-- Initial quantities require an owner's evidence. Demand facts are bounded,
-- distinguish held stock and exclude transferred/reserved inbound double counts.
-- production-gate: self-verifying

CREATE TABLE public.procurement_initial_plans(
 id uuid PRIMARY KEY,restaurant_id uuid NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
 payload_hash text NOT NULL,reason text NOT NULL,actor_id uuid NOT NULL,approved_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE public.procurement_initial_plan_lines(
 plan_id uuid NOT NULL REFERENCES procurement_initial_plans(id) ON DELETE CASCADE,restaurant_id uuid NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
 product_id uuid NOT NULL REFERENCES inventory_products(id) ON DELETE CASCADE,quantity_base numeric(18,3) NOT NULL CHECK(quantity_base>=0),base_unit text NOT NULL,
 valid_until date NOT NULL,approved_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(plan_id,product_id)
);
CREATE INDEX procurement_initial_plan_latest ON public.procurement_initial_plan_lines(restaurant_id,product_id,approved_at DESC,plan_id DESC);
ALTER TABLE public.procurement_initial_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.procurement_initial_plan_lines ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.procurement_initial_plans,public.procurement_initial_plan_lines FROM PUBLIC,anon,authenticated;
CREATE TRIGGER procurement_initial_plans_immutable BEFORE UPDATE ON public.procurement_initial_plans FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE TRIGGER procurement_initial_plan_lines_immutable BEFORE UPDATE ON public.procurement_initial_plan_lines FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE FUNCTION public.admin_approve_initial_purchase_plan_v1(p_id uuid,p_store uuid,p_rows jsonb,p_valid_until date,p_reason text) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE hash text; prior procurement_initial_plans;
BEGIN
 PERFORM require_brand_admin_v1();
 IF p_id IS NULL OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 100 OR octet_length(p_rows::text)>65536 OR p_valid_until IS NULL OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'INITIAL_PLAN_INVALID'; END IF;
 hash:=md5(jsonb_build_object('actor',auth.uid(),'store',p_store,'rows',p_rows,'until',p_valid_until,'reason',btrim(p_reason))::text);
 PERFORM pg_advisory_xact_lock(hashtextextended('initial-plan:'||p_id,0));
 SELECT * INTO prior FROM procurement_initial_plans WHERE id=p_id;
 IF FOUND THEN IF prior.payload_hash<>hash THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF; RETURN prior.id; END IF;
 IF p_valid_until<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date OR p_valid_until>(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date+365 THEN RAISE EXCEPTION 'INITIAL_PLAN_EXPIRY_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows)x LEFT JOIN inventory_products p ON p.id=(x->>'product_id')::uuid AND p.restaurant_id=p_store AND p.is_active AND p.is_orderable AND p.receipt_classification='stock'
 WHERE p.id IS NULL OR x->>'base_unit' IS DISTINCT FROM p.base_unit OR jsonb_typeof(x->'quantity_base') IS DISTINCT FROM 'number' OR (x->>'quantity_base')::numeric<0 OR (x->>'quantity_base')::numeric<>round((x->>'quantity_base')::numeric,3))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows)x GROUP BY x->>'product_id' HAVING count(*)>1) THEN RAISE EXCEPTION 'INITIAL_PLAN_ITEM_INVALID'; END IF;
 INSERT INTO procurement_initial_plans VALUES(p_id,p_store,hash,btrim(p_reason),auth.uid(),clock_timestamp());
 INSERT INTO procurement_initial_plan_lines(plan_id,restaurant_id,product_id,quantity_base,base_unit,valid_until) SELECT p_id,p_store,(x->>'product_id')::uuid,(x->>'quantity_base')::numeric,x->>'base_unit',p_valid_until FROM jsonb_array_elements(p_rows)x;
 RETURN p_id;
END $$;
CREATE OR REPLACE FUNCTION public.procurement_demand_evidence_v2(p_store_id uuid,p_office_actor jsonb DEFAULT NULL,p_products uuid[] DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth AS $$
DECLARE actor jsonb;fresh_hours integer;
BEGIN
 IF p_products IS NOT NULL AND cardinality(p_products)>100 THEN RAISE EXCEPTION 'DEMAND_PAGE_LIMIT'; END IF;
 IF p_products IS NULL AND (SELECT count(*) FROM inventory_products WHERE restaurant_id=p_store_id AND is_active AND is_orderable)>2000 THEN RAISE EXCEPTION 'DEMAND_USE_PAGED_READ'; END IF;
 actor:=public.procurement_actor(p_store_id,p_office_actor);
 SELECT COALESCE(stock_freshness_hours,24) INTO fresh_hours FROM public.procurement_store_policies WHERE restaurant_id=p_store_id;
 RETURN (WITH products AS MATERIALIZED(SELECT * FROM public.inventory_products WHERE restaurant_id=p_store_id AND is_active AND is_orderable AND receipt_classification='stock' AND (p_products IS NULL OR id=ANY(p_products))),
 mappings AS(SELECT inventory_item_id,count(*) count FROM products GROUP BY inventory_item_id),
 usage AS(SELECT tx.ingredient_id,sum(CASE WHEN tx.transaction_type='deduct' THEN abs(tx.quantity_g) ELSE 0 END) actual_usage,
   sum(CASE WHEN tx.transaction_type='waste' THEN abs(tx.quantity_g) ELSE 0 END) waste_usage,count(DISTINCT (tx.created_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) observed_days
   FROM public.inventory_transactions tx WHERE tx.restaurant_id=p_store_id AND tx.transaction_type IN ('deduct','waste') AND COALESCE(tx.reference_type,'')<>'inventory_supplier_return'
   AND tx.ingredient_id IN(SELECT inventory_item_id FROM products) AND tx.created_at>=((now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date-28)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'
   AND tx.created_at<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh' GROUP BY tx.ingredient_id),
 open_lines AS MATERIALIZED(SELECT l.* FROM inventory_purchase_order_lines l JOIN inventory_purchase_orders po ON po.id=l.purchase_order_id WHERE po.restaurant_id=p_store_id AND po.status IN('office_approved','ordered','partially_received') AND l.product_id IN(SELECT id FROM products)),
 held AS(SELECT order_line_id purchase_order_line_id,quantity_base qty FROM inventory_held_by_order_line_v1(ARRAY(SELECT id FROM open_lines))),
 reserved AS(SELECT s.original_order_line_id,sum(s.quantity_base) qty FROM procurement_shortage_allocations s WHERE s.status='reserved' AND s.original_order_line_id IN(SELECT id FROM open_lines) GROUP BY s.original_order_line_id),
 accepted AS(SELECT l.purchase_order_line_id,sum(l.accepted_quantity_base) qty FROM public.inventory_receipt_lines l JOIN public.inventory_receipts r ON r.id=l.receipt_id
   WHERE l.purchase_order_line_id IN(SELECT id FROM open_lines) AND r.status='confirmed' GROUP BY l.purchase_order_line_id),
 inbound AS(SELECT l.product_id,sum(greatest(0,l.ordered_quantity_base-l.cancelled_quantity_base-COALESCE(a.qty,0)-coalesce(h.qty,0)-coalesce(s.qty,0))) qty FROM open_lines l
   JOIN public.inventory_purchase_orders po ON po.id=l.purchase_order_id LEFT JOIN accepted a ON a.purchase_order_line_id=l.id LEFT JOIN held h ON h.purchase_order_line_id=l.id LEFT JOIN reserved s ON s.original_order_line_id=l.id
   WHERE po.restaurant_id=p_store_id AND po.status IN ('office_approved','ordered','partially_received') GROUP BY l.product_id),
 allocated AS(SELECT a.request_line_id,sum(a.quantity_base) qty FROM public.procurement_allocations a JOIN public.inventory_purchase_request_lines l ON l.id=a.request_line_id
   JOIN public.inventory_purchase_requests r ON r.id=l.request_id WHERE r.restaurant_id=p_store_id AND l.product_id IN(SELECT id FROM products) GROUP BY a.request_line_id),
 requested AS(SELECT l.product_id,sum(greatest(0,l.quantity_base-COALESCE(a.qty,0))) qty FROM public.inventory_purchase_request_lines l
   JOIN public.inventory_purchase_requests r ON r.id=l.request_id LEFT JOIN allocated a ON a.request_line_id=l.id WHERE r.restaurant_id=p_store_id AND l.product_id IN(SELECT id FROM products) AND l.active AND r.status NOT IN ('cancelled','allocated') GROUP BY l.product_id),
 history AS(SELECT l.product_id,max(r.received_at) last_received,avg(l.accepted_quantity_base) average_qty,
   (array_agg(l.actual_unit_price ORDER BY r.received_at DESC,r.id DESC,l.id DESC))[1] last_price FROM public.inventory_receipt_lines l JOIN public.inventory_receipts r ON r.id=l.receipt_id
   WHERE r.restaurant_id=p_store_id AND r.status='confirmed' AND l.accepted_quantity_base>0 AND l.product_id IN(SELECT id FROM products) AND r.received_at>=now()-interval '90 days' AND NOT EXISTS(SELECT 1 FROM inventory_lot_receipt_origins origin WHERE origin.receipt_id=r.id) GROUP BY l.product_id),
 lot_stock AS(SELECT ingredient_id,sum(quantity_base) FILTER(WHERE state='held') held,sum(quantity_base) FILTER(WHERE state='available' AND (expiry_date IS NULL OR expiry_date>=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date)) usable FROM inventory_lots WHERE restaurant_id=p_store_id AND ingredient_id IN(SELECT inventory_item_id FROM products) GROUP BY ingredient_id),
 plans AS(SELECT DISTINCT ON(product_id) * FROM procurement_initial_plan_lines WHERE restaurant_id=p_store_id AND product_id IN(SELECT id FROM products) ORDER BY product_id,approved_at DESC,plan_id DESC),
 suppliers AS(SELECT s.product_id,jsonb_agg(jsonb_build_object('supplier_id',s.supplier_id,'lead_time_days',s.lead_time_days,'min_order_quantity',s.min_order_quantity,'order_unit_quantity_base',s.order_unit_quantity_base) ORDER BY s.id) terms FROM inventory_supplier_items s WHERE s.product_id IN(SELECT id FROM products) AND s.is_active GROUP BY s.product_id)
 SELECT COALESCE(jsonb_agg(jsonb_build_object('product_id',p.id,'product_name',p.name,'base_unit',p.base_unit,'stock_unit',p.stock_unit,'stock_conversion',p.base_unit_factor,
   'current_stock_base',it.current_stock,'stock_updated_at',it.updated_at,'minimum_stock_base',it.reorder_point,'mapping_count',m.count,
   'stock_fresh',it.updated_at>=now()-make_interval(hours=>COALESCE(fresh_hours,24)),
   'actual_daily_usage_base',COALESCE(u.actual_usage,0)/28,'waste_daily_base',COALESCE(u.waste_usage,0)/28,'observed_usage_days',COALESCE(u.observed_days,0),
   'usage_window_days',28,'evidence_version','usage28d-v2','recommendation_formula_version','weighted4-7-v1','recommendation_formula','max(0,target_days*(avg4*0.7+avg7*0.3)-current_stock)','history_window_days',90,'held_quantity_base',coalesce(ls.held,0),'usable_stock_base',CASE WHEN tracking.ingredient_id IS NOT NULL THEN coalesce(ls.usable,0) ELSE it.current_stock END,'supplier_terms',coalesce(supplier.terms,'[]'),'initial_plan',CASE WHEN plan.valid_until>=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date AND plan.base_unit=p.base_unit THEN to_jsonb(plan) END,'needs_initial_plan',coalesce(u.observed_days,0)=0 AND (plan.plan_id IS NULL OR plan.valid_until<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date OR plan.base_unit<>p.base_unit),'can_approve_initial_plan',is_super_admin(),'usage_as_of',(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date-1,'inbound_quantity_base',COALESCE(i.qty,0),'pending_request_quantity_base',COALESCE(r.qty,0),
   'last_received_at',h.last_received,'average_received_quantity_base',h.average_qty,'recent_unit_price',CASE WHEN COALESCE((actor->>'can_view_prices')::boolean,false) THEN h.last_price ELSE NULL END) ORDER BY p.name,p.id),'[]')
 FROM products p LEFT JOIN public.inventory_items it ON it.id=p.inventory_item_id AND it.restaurant_id=p_store_id
 LEFT JOIN mappings m ON m.inventory_item_id=p.inventory_item_id LEFT JOIN usage u ON u.ingredient_id=p.inventory_item_id LEFT JOIN inbound i ON i.product_id=p.id
 LEFT JOIN requested r ON r.product_id=p.id LEFT JOIN history h ON h.product_id=p.id LEFT JOIN lot_stock ls ON ls.ingredient_id=p.inventory_item_id LEFT JOIN inventory_lot_tracking tracking ON tracking.ingredient_id=p.inventory_item_id LEFT JOIN plans plan ON plan.product_id=p.id LEFT JOIN suppliers supplier ON supplier.product_id=p.id);
END $$;
CREATE OR REPLACE FUNCTION public.procurement_demand_evidence(p_store_id uuid,p_office_actor jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$ SELECT procurement_demand_evidence_v2(p_store_id,p_office_actor,NULL); $$;
CREATE FUNCTION public.procurement_demand_page_v1(p_store_id uuid,p_after uuid DEFAULT NULL,p_office_actor jsonb DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE ids uuid[]; next_id uuid;
BEGIN
 PERFORM procurement_actor(p_store_id,p_office_actor);
 SELECT array_agg(id ORDER BY id) INTO ids FROM(SELECT id FROM inventory_products WHERE restaurant_id=p_store_id AND is_active AND is_orderable AND receipt_classification='stock' AND (p_after IS NULL OR id>p_after) ORDER BY id LIMIT 51)p;
 IF cardinality(ids)>50 THEN next_id:=ids[50]; END IF;
 RETURN jsonb_build_object('demand',procurement_demand_evidence_v2(p_store_id,p_office_actor,coalesce(ids[1:50],'{}')),'demand_next_cursor',next_id);
END $$;
DO $$ DECLARE d text; BEGIN
 d:=pg_get_functiondef('public.procurement_workspace_page_core(uuid,jsonb,jsonb)'::regprocedure);
 IF position('jsonb_build_object(''demand'',public.procurement_demand_evidence(p_store_id,p_office_actor))' IN d)=0 THEN RAISE EXCEPTION 'DEMAND_PAGE_PATCH_MISMATCH'; END IF;
 d:=replace(d,'jsonb_build_object(''demand'',public.procurement_demand_evidence(p_store_id,p_office_actor))','CASE WHEN p_query->>''demand_page_size''=''50'' THEN public.procurement_demand_page_v1(p_store_id,nullif(p_query->>''demand_after'','''')::uuid,p_office_actor) ELSE jsonb_build_object(''demand'',public.procurement_demand_evidence(p_store_id,p_office_actor)) END'); EXECUTE d;
 -- A release after reinspection is not another supplier delivery. Only receipts
 -- with a promised date enter the punctuality denominator.
 d:=pg_get_functiondef('public.procurement_supplier_evidence(uuid,jsonb)'::regprocedure);
 d:=replace(d,'count(*) count,count(*) FILTER(WHERE (r.received_at','count(*) count,count(*) FILTER(WHERE po.requested_delivery_date IS NOT NULL) scheduled,count(*) FILTER(WHERE (r.received_at');
 d:=replace(d,'AND r.received_at>=now()-interval ''90 days'' GROUP BY r.supplier_id','AND r.received_at>=now()-interval ''90 days'' AND NOT EXISTS(SELECT 1 FROM inventory_lot_receipt_origins origin WHERE origin.receipt_id=r.id) GROUP BY r.supplier_id');
 d:=replace(d, 'issues AS(', 'quality AS(SELECT r.supplier_id,count(*) inspected_lines,count(*) FILTER(WHERE l.rejected_quantity_base>0 OR l.held_quantity_base>0) nonconforming_lines FROM inventory_receipt_lines l JOIN inventory_receipts r ON r.id=l.receipt_id WHERE r.restaurant_id=p_store_id AND r.status=''confirmed'' AND r.received_at>=now()-interval ''90 days'' AND NOT EXISTS(SELECT 1 FROM inventory_lot_receipt_origins origin WHERE origin.receipt_id=r.id) GROUP BY r.supplier_id),issues AS(');
 d:=replace(d,'LEFT JOIN issues i ON i.supplier_id=s.id','LEFT JOIN issues i ON i.supplier_id=s.id LEFT JOIN quality q ON q.supplier_id=s.id');
 d:=replace(d,'''open_issues'',COALESCE(i.count,0)','''inspected_lines_90d'',coalesce(q.inspected_lines,0),''nonconforming_lines_90d'',coalesce(q.nonconforming_lines,0),''open_issues'',COALESCE(i.count,0)');
 d:=replace(d,'''on_time_receipts_90d'',COALESCE(r.on_time,0)', '''scheduled_receipts_90d'',COALESCE(r.scheduled,0),''metric_version'',''physical-deliveries-v2'',''on_time_receipts_90d'',COALESCE(r.on_time,0)'); EXECUTE d;
 -- Replace the older per-product supplier lookup with one ranked supplier set;
 -- retain its quantities and ordering choices for existing stores.
 d:=pg_get_functiondef('public.run_inventory_purchase_recommendation(uuid,numeric,date)'::regprocedure);
 d:=replace(d,'LEFT JOIN LATERAL (','LEFT JOIN (');
 d:=replace(d,E'SELECT\n      isi.supplier_id',E'SELECT DISTINCT ON(isi.product_id)\n      isi.product_id, isi.supplier_id');
 d:=replace(d,'WHERE isi.product_id = status.product_id','WHERE isi.product_id IN(SELECT id FROM inventory_products WHERE restaurant_id=p_store_id AND is_active)');
 d:=replace(d,'ORDER BY isi.is_preferred DESC, isi.updated_at DESC','ORDER BY isi.product_id, isi.is_preferred DESC, isi.updated_at DESC,isi.id');
 d:=replace(d,E'    LIMIT 1\n  ) supplier_pick ON TRUE',E'  ) supplier_pick ON supplier_pick.product_id=status.product_id'); EXECUTE d;
END $$;
REVOKE ALL ON FUNCTION public.procurement_demand_evidence_v2(uuid,jsonb,uuid[]),public.procurement_demand_page_v1(uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.admin_approve_initial_purchase_plan_v1(uuid,uuid,jsonb,date,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_approve_initial_purchase_plan_v1(uuid,uuid,jsonb,date,text) TO authenticated;

-- COMPONENT 20261022191000_store_identity_transfers.sql
-- A legal/brand transfer is an explicit closed-store operation. It retains IDs,
-- issued documents and effective legal history, and requires reopening checks.
-- production-gate: self-verifying

CREATE TABLE public.store_identity_transfers (
 id uuid PRIMARY KEY,restaurant_id uuid NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
 source_brand uuid,source_entity uuid,target_brand uuid NOT NULL,target_entity uuid NOT NULL,
 expected_revision bigint NOT NULL,input_hash text NOT NULL,evidence jsonb NOT NULL,previous_scope jsonb NOT NULL,
 actor_id uuid NOT NULL,transaction_id bigint NOT NULL,effective_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX store_identity_transfers_store ON public.store_identity_transfers(restaurant_id,effective_at DESC,id DESC);
ALTER TABLE public.store_identity_transfers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.store_identity_transfers FROM PUBLIC,anon,authenticated;
CREATE TRIGGER store_identity_transfers_immutable BEFORE UPDATE ON public.store_identity_transfers FOR EACH ROW EXECUTE FUNCTION public.store_operating_immutable_v1();
CREATE OR REPLACE FUNCTION public.store_guard_registered_identity_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 IF (NEW.brand_id,NEW.tax_entity_id,NEW.short_code) IS DISTINCT FROM (OLD.brand_id,OLD.tax_entity_id,OLD.short_code)
 AND ((NEW.brand_id,NEW.tax_entity_id) IS DISTINCT FROM (OLD.brand_id,OLD.tax_entity_id) OR EXISTS(SELECT 1 FROM store_account_onboarding_jobs WHERE store_id=OLD.id))
 AND NOT (NEW.short_code IS NOT DISTINCT FROM OLD.short_code AND EXISTS(SELECT 1 FROM store_identity_transfers t WHERE t.restaurant_id=OLD.id AND t.transaction_id=txid_current() AND t.actor_id=auth.uid() AND (t.source_brand,t.source_entity,t.target_brand,t.target_entity) IS NOT DISTINCT FROM (OLD.brand_id,OLD.tax_entity_id,NEW.brand_id,NEW.tax_entity_id))) THEN RAISE EXCEPTION 'STORE_REGISTERED_IDENTITY_FROZEN'; END IF;
 RETURN NEW;
END $$;
CREATE FUNCTION public.admin_get_store_transfer_options_v1(p_store uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
BEGIN
 PERFORM require_brand_admin_v1();
 IF (SELECT count(*) FROM tax_entity_brands)>500 THEN RAISE EXCEPTION 'STORE_TRANSFER_SCOPE_LIMIT'; END IF;
 RETURN jsonb_build_object('current',(SELECT jsonb_build_object('brand_id',brand_id,'tax_entity_id',tax_entity_id,'name',name) FROM restaurants WHERE id=p_store),
 'targets',(SELECT jsonb_agg(jsonb_build_object('brand_id',b.id,'brand_name',b.name,'entity_id',e.id,'entity_name',e.name) ORDER BY b.name,e.name) FROM tax_entity_brands t JOIN brands b ON b.id=t.brand_id JOIN tax_entity e ON e.id=t.tax_entity_id));
END $$;
CREATE FUNCTION public.admin_transfer_store_identity_v1(p_id uuid,p_store uuid,p_expected_revision bigint,p_brand uuid,p_entity uuid,p_evidence jsonb) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,auth,pg_catalog AS $$
DECLARE old restaurants; lifecycle store_lifecycle; prior store_identity_transfers; hash text; pending jsonb; previous jsonb; replacement jsonb; actor uuid; effective_time timestamptz:=clock_timestamp();
BEGIN
 PERFORM require_brand_admin_v1();
 IF p_id IS NULL OR jsonb_typeof(p_evidence) IS DISTINCT FROM 'object' OR octet_length(p_evidence::text)>8192 OR length(btrim(coalesce(p_evidence->>'reason','')))<5 OR length(btrim(coalesce(p_evidence->>'scope_review','')))<5 THEN RAISE EXCEPTION 'STORE_TRANSFER_EVIDENCE_REQUIRED'; END IF;
 hash:=md5(jsonb_build_array(p_store,p_expected_revision,p_brand,p_entity,p_evidence,auth.uid())::text);
 PERFORM pg_advisory_xact_lock(hashtextextended('store-opening:'||p_store,0));
 SELECT * INTO prior FROM store_identity_transfers WHERE id=p_id;
 IF FOUND THEN IF prior.input_hash<>hash THEN RAISE EXCEPTION 'REQUEST_CONFLICT'; END IF; RETURN p_id; END IF;
 SELECT * INTO lifecycle FROM store_lifecycle WHERE restaurant_id=p_store FOR UPDATE;
 SELECT * INTO old FROM restaurants WHERE id=p_store FOR UPDATE;
 IF lifecycle.state IS DISTINCT FROM 'closed' OR lifecycle.revision IS DISTINCT FROM p_expected_revision OR old.is_active IS DISTINCT FROM false THEN RAISE EXCEPTION 'STORE_TRANSFER_REQUIRES_CLOSED'; END IF;
 IF (p_brand,p_entity) IS NOT DISTINCT FROM (old.brand_id,old.tax_entity_id) OR NOT EXISTS(SELECT 1 FROM tax_entity_brands WHERE brand_id=p_brand AND tax_entity_id=p_entity) THEN RAISE EXCEPTION 'STORE_TRANSFER_TARGET_INVALID'; END IF;
 pending:=store_closure_pending_v1(p_store);
 IF EXISTS(SELECT 1 FROM jsonb_each_text(pending)x WHERE x.value::bigint>0) THEN RAISE EXCEPTION 'STORE_CLOSURE_PENDING'; END IF;
 -- A shared brand login must already exist in the destination; it is never
 -- renamed or moved away from the previous brand's other stores.
 WITH candidates AS(SELECT DISTINCT ON(q.id) q.id requirement_id,u.id user_id,u.fixed_account_code code,u.full_name name FROM store_fixed_account_requirements q
 JOIN users u ON u.brand_id=p_brand AND u.role=q.role AND u.account_type=q.account_type AND u.is_active AND u.auth_id IS NOT NULL AND u.fixed_account_code IS NOT NULL
 WHERE q.store_id=p_store AND q.scope='brand' AND q.is_active ORDER BY q.id,u.id)
 SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') INTO replacement FROM candidates c;
 IF p_brand<>old.brand_id AND jsonb_array_length(replacement)<>(SELECT count(*) FROM store_fixed_account_requirements WHERE store_id=p_store AND scope='brand' AND is_active) THEN RAISE EXCEPTION 'STORE_TRANSFER_TARGET_BRAND_ACCOUNTS_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM store_external_links WHERE restaurant_id=p_store) OR EXISTS(SELECT 1 FROM inventory_products WHERE restaurant_id=p_store AND is_active AND is_orderable) THEN
  IF nullif(p_evidence->>'office_store_id','') IS NULL OR length(btrim(coalesce(p_evidence->>'office_contract_version','')))<1 OR length(btrim(coalesce(p_evidence->>'office_evidence','')))<5 THEN RAISE EXCEPTION 'STORE_TRANSFER_OFFICE_EVIDENCE_REQUIRED'; END IF;
 END IF;
 SELECT jsonb_build_object('procurement_role_roster',(SELECT jsonb_agg(to_jsonb(rr)) FROM procurement_role_roster rr WHERE restaurant_id=p_store),'requirements',(SELECT jsonb_agg(to_jsonb(q) ORDER BY id) FROM store_fixed_account_requirements q WHERE store_id=p_store),'external_links',(SELECT jsonb_agg(to_jsonb(l)) FROM store_external_links l WHERE restaurant_id=p_store)) INTO previous;
 INSERT INTO store_identity_transfers VALUES(p_id,p_store,old.brand_id,old.tax_entity_id,p_brand,p_entity,p_expected_revision,hash,p_evidence,previous,auth.uid(),txid_current(),effective_time);
 SELECT id INTO actor FROM users WHERE auth_id=auth.uid();
 UPDATE restaurants SET brand_id=p_brand,tax_entity_id=p_entity,store_type=(SELECT CASE owner_type WHEN 'internal' THEN 'direct' ELSE 'external' END FROM tax_entity WHERE id=p_entity) WHERE id=p_store;
 IF old.tax_entity_id IS DISTINCT FROM p_entity THEN
  UPDATE store_tax_entity_history SET effective_to=effective_time WHERE store_id=p_store AND effective_to IS NULL;
  INSERT INTO store_tax_entity_history(store_id,tax_entity_id,effective_from,reason,created_by) VALUES(p_store,p_entity,effective_time,'store_identity_transfer:'||p_id,actor);
 END IF;
 UPDATE user_store_access SET is_active=false,updated_at=now() WHERE store_id=p_store;
 -- Preserve the previous grants in the transfer audit, then require explicit
 -- provisioning for the destination organization, including future grants.
 DELETE FROM procurement_role_roster WHERE restaurant_id=p_store;
 UPDATE procurement_store_onboarding SET office_connected=false WHERE restaurant_id=p_store;
 UPDATE user_tax_entity_access SET is_active=false,updated_at=now() WHERE user_id IN(SELECT provisioned_user_id FROM store_fixed_account_requirements WHERE store_id=p_store AND scope='store');
 IF p_brand IS DISTINCT FROM old.brand_id THEN
  UPDATE user_brand_access a SET is_active=false,updated_at=now() WHERE a.user_id IN(SELECT provisioned_user_id FROM store_fixed_account_requirements WHERE store_id=p_store AND scope='store');
  UPDATE users u SET brand_id=p_brand WHERE u.id IN(SELECT provisioned_user_id FROM store_fixed_account_requirements WHERE store_id=p_store AND scope='store') AND (u.restaurant_id=p_store OR u.primary_store_id=p_store);
  UPDATE store_fixed_account_requirements q SET provisioned_user_id=(x->>'user_id')::uuid,account_code=x->>'code',display_name=x->>'name',updated_at=now() FROM jsonb_array_elements(replacement)x WHERE q.id=(x->>'requirement_id')::uuid;
  INSERT INTO user_store_access(user_id,store_id,is_active,source_type) SELECT (x->>'user_id')::uuid,p_store,false,'direct' FROM jsonb_array_elements(replacement)x ON CONFLICT(user_id,store_id,source_type) DO UPDATE SET is_active=false,updated_at=now();
  UPDATE inventory_products SET brand_id=p_brand WHERE restaurant_id=p_store;
 END IF;
 DELETE FROM store_external_links WHERE restaurant_id=p_store;
 IF nullif(p_evidence->>'office_store_id','') IS NOT NULL THEN INSERT INTO store_external_links(restaurant_id,provider,external_id,tax_entity_id,contract_version,evidence_reference,verified_by) VALUES(p_store,'office',(p_evidence->>'office_store_id')::uuid,p_entity,p_evidence->>'office_contract_version',p_evidence->>'office_evidence',auth.uid()); END IF;
 UPDATE store_lifecycle SET revision=revision+1,changed_by=auth.uid(),changed_at=now(),activated_source_hash=NULL WHERE restaurant_id=p_store;
 PERFORM store_refresh_closed_claims_v1(p_store);
 RETURN p_id;
END $$;
-- Every transferred store must review purchasing under the new ownership before
-- accepting a new PR/PO. Historical approvals remain immutable.
CREATE FUNCTION public.store_transfer_procurement_ready_v1(p_stores uuid[]) RETURNS TABLE(store_id uuid,ready boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
 WITH moved AS(SELECT restaurant_id,max(effective_at) at FROM store_identity_transfers WHERE restaurant_id=ANY(p_stores) GROUP BY restaurant_id),
 approvals AS(SELECT a.product_id,max(approved_at) at FROM procurement_catalog_approvals a WHERE restaurant_id=ANY(p_stores) GROUP BY product_id)
 SELECT s,NOT EXISTS(SELECT 1 FROM moved m JOIN inventory_products p ON p.restaurant_id=m.restaurant_id AND p.is_active AND p.is_orderable LEFT JOIN approvals a ON a.product_id=p.id WHERE m.restaurant_id=s AND (a.at IS NULL OR a.at<m.at)) FROM unnest(p_stores)s;
$$;
ALTER FUNCTION public.store_procurement_readiness_v1(uuid[]) RENAME TO store_procurement_readiness_before_transfer;
REVOKE ALL ON FUNCTION public.store_procurement_readiness_before_transfer(uuid[]) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.store_procurement_readiness_v1(p_stores uuid[]) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 result:=store_procurement_readiness_before_transfer(p_stores);
 RETURN(SELECT jsonb_agg(x||jsonb_build_object('checks',x->'checks'||jsonb_build_object('identity_transfer_review',t.ready),'ready',(x->>'ready')::boolean AND t.ready) ORDER BY x->>'id') FROM jsonb_array_elements(result)x JOIN store_transfer_procurement_ready_v1(p_stores)t ON t.store_id=(x->>'id')::uuid);
END $$;
DO $$ DECLARE d text; BEGIN
 d:=pg_get_functiondef('public.store_guard_closed_procurement_v1()'::regprocedure);
 d:=replace(d,' RETURN NULL;', ' IF EXISTS(SELECT 1 FROM store_transfer_procurement_ready_v1(ARRAY(SELECT DISTINCT restaurant_id FROM new_procurement_intake)) WHERE NOT ready) THEN RAISE EXCEPTION ''STORE_TRANSFER_PROCUREMENT_REVIEW_REQUIRED''; END IF; RETURN NULL;'); EXECUTE d;
END $$;
REVOKE ALL ON FUNCTION public.store_transfer_procurement_ready_v1(uuid[]),public.store_procurement_readiness_v1(uuid[]) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.admin_get_store_transfer_options_v1(uuid),public.admin_transfer_store_identity_v1(uuid,uuid,bigint,uuid,uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_get_store_transfer_options_v1(uuid),public.admin_transfer_store_identity_v1(uuid,uuid,bigint,uuid,uuid,jsonb) TO authenticated;

-- COMPONENT 20261022192000_lifecycle_read_boundaries.sql
-- Explicit bounded reference pages; no truncated readiness hashes. Closing also
-- waits for prepaid delivery/pickup and unfinished packaging.
-- production-gate: self-verifying

CREATE FUNCTION public.admin_procurement_reference_page_v1(p_kind text,p_after uuid DEFAULT NULL,p_search text DEFAULT '') RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE result jsonb;
BEGIN
 PERFORM require_brand_admin_v1();
 IF length(coalesce(p_search,''))>160 THEN RAISE EXCEPTION 'REFERENCE_SEARCH_LIMIT'; END IF;
 IF p_kind='specs' THEN
  WITH latest AS(SELECT DISTINCT ON(code) id,code,revision,name,base_unit,specification FROM procurement_material_specs WHERE coalesce(p_search,'')='' OR code ILIKE '%'||p_search||'%' OR name ILIKE '%'||p_search||'%' ORDER BY code,revision DESC),
  page AS MATERIALIZED(SELECT * FROM latest WHERE p_after IS NULL OR id>p_after ORDER BY id LIMIT 51), visible AS(SELECT * FROM page ORDER BY id LIMIT 50)
  SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(v) ORDER BY id) FROM visible v),'[]'),'next_cursor',CASE WHEN (SELECT count(*) FROM page)>50 THEN (SELECT id FROM visible ORDER BY id DESC LIMIT 1) END) INTO result;
 ELSIF p_kind='templates' THEN
  WITH latest AS(SELECT DISTINCT ON(family_id) id,family_id,revision,name,policy FROM procurement_policy_templates WHERE coalesce(p_search,'')='' OR name ILIKE '%'||p_search||'%' ORDER BY family_id,revision DESC),
  page AS MATERIALIZED(SELECT * FROM latest WHERE p_after IS NULL OR id>p_after ORDER BY id LIMIT 51), visible AS(SELECT * FROM page ORDER BY id LIMIT 50)
  SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(v) ORDER BY id) FROM visible v),'[]'),'next_cursor',CASE WHEN (SELECT count(*) FROM page)>50 THEN (SELECT id FROM visible ORDER BY id DESC LIMIT 1) END) INTO result;
 ELSE RAISE EXCEPTION 'REFERENCE_KIND_INVALID'; END IF;
 RETURN result;
END $$;
DO $$ DECLARE d text; signature text; BEGIN
 d:=pg_get_functiondef('public.store_closure_pending_v1(uuid)'::regprocedure);
 d:=replace(d,'''orders'',', '''leftover_packaging'',(SELECT count(*) FROM leftover_packaging_requests WHERE restaurant_id=p_store AND status NOT IN(''completed'',''cancelled'')),''prepaid_handoffs'',(SELECT count(*) FROM direct_delivery_fulfillment_tickets WHERE restaurant_id=p_store AND status NOT IN(''completed'',''cancelled'')),''orders'','); EXECUTE d;
 d:=pg_get_functiondef('public.admin_get_store_lifecycle_before_operational(uuid)'::regprocedure);
 d:=replace(d,' accounts:=public.store_credential_snapshot_v1', ' IF (SELECT count(*) FROM store_employees WHERE store_id=p_store_id AND is_active)>200 OR (SELECT count(*) FROM printer_destinations WHERE restaurant_id=p_store_id)>20 OR (SELECT count(*) FROM printer_endpoints WHERE physical_printer_id IN(SELECT physical_printer_id FROM printer_destinations WHERE restaurant_id=p_store_id))>100 THEN RAISE EXCEPTION ''STORE_SETUP_SCOPE_LIMIT''; END IF; accounts:=public.store_credential_snapshot_v1');
 d:=replace(d,'''accounts'',jsonb_array_length(accounts)>0', '''accounts'',NOT EXISTS(SELECT 1 FROM store_account_onboarding_jobs j CROSS JOIN LATERAL jsonb_array_elements(j.accounts) a WHERE j.store_id=p_store_id AND a->>''scope''=''store'' AND NOT (p_store_id=''273b057e-3b69-46e3-93c1-6194c2802849''::uuid AND a->>''account_code''=''jgbt_tray1'') AND NOT EXISTS(SELECT 1 FROM store_fixed_account_requirements req WHERE req.store_id=p_store_id AND req.account_code=a->>''account_code'' AND req.is_active)) AND jsonb_array_length(accounts)>0'); EXECUTE d;
 FOREACH signature IN ARRAY ARRAY['public.admin_get_store_operational_inputs_v1(uuid)','public.admin_get_store_lifecycle_v1(uuid)'] LOOP
  d:=pg_get_functiondef(signature::regprocedure);
  d:=replace(d,' AND m.size_parent_id IS NULL','');
  d:=replace(d,'>20000 THEN RAISE', '>20000 OR (SELECT count(*) FROM inventory_items WHERE restaurant_id='||CASE WHEN signature LIKE '%inputs%' THEN 'p_store' ELSE 'p_store_id' END||' AND is_active)>2000 THEN RAISE');
  -- An old count cannot establish the reopening stock balance.
  d:=replace(d,'c.ingredient_id=i.id)', 'c.ingredient_id=i.id AND c.created_at>=coalesce((SELECT max(created_at) FROM store_reopening_events WHERE restaurant_id=i.restaurant_id),''-infinity''::timestamptz))'); EXECUTE d;
 END LOOP;
 d:=pg_get_functiondef('public.inventory_lot_workspace_v1(uuid,uuid,uuid)'::regprocedure);
 d:=replace(d,' WITH page AS', ' IF (SELECT count(*) FROM store_employees WHERE store_id=p_store AND is_active)>200 THEN RAISE EXCEPTION ''INVENTORY_EMPLOYEE_SCOPE_LIMIT''; END IF; WITH page AS'); EXECUTE d;
 d:=pg_get_functiondef('public.admin_save_inventory_location_v1(uuid,uuid,text,text,boolean,bigint)'::regprocedure);
 d:=replace(d,'''inventory-location:''||p_id','''inventory-locations-store:''||p_store'); EXECUTE d;
END $$;
REVOKE ALL ON FUNCTION public.admin_procurement_reference_page_v1(text,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_procurement_reference_page_v1(text,uuid,text) TO authenticated;

-- COMPONENT 20261022193000_lifecycle_financial_boundaries.sql
-- Held goods retain the original inspected price; external evidence cannot
-- reconcile an unknown historical conversion as a zero credit.
-- production-gate: self-verifying

DO $$ DECLARE d text; BEGIN
 d:=pg_get_functiondef('public.submit_inventory_receipt_batch(uuid,uuid,integer,integer,text,jsonb,text,text,text,date,text)'::regprocedure);
 IF position('COALESCE((x->>''actual_unit_price'')::numeric,ol.unit_price)' IN d)=0 THEN RAISE EXCEPTION 'HELD_PRICE_PATCH_MISMATCH'; END IF;
 d:=replace(d,'COALESCE((x->>''actual_unit_price'')::numeric,ol.unit_price)','COALESCE(parent_receipt.actual_unit_price,(x->>''actual_unit_price'')::numeric,ol.unit_price)');
 d:=replace(d,'LEFT JOIN accepted a ON a.purchase_order_line_id=ol.id', 'LEFT JOIN accepted a ON a.purchase_order_line_id=ol.id LEFT JOIN inventory_lot_receipt_origins origin ON origin.receipt_id=p_receipt_id LEFT JOIN inventory_lots parent_lot ON parent_lot.id=origin.parent_lot_id LEFT JOIN inventory_receipt_lines parent_receipt ON parent_receipt.id=parent_lot.receipt_line_id AND parent_receipt.purchase_order_line_id=ol.id'); EXECUTE d;
 d:=pg_get_functiondef('public.get_procurement_reconciliation_source_v1(uuid,uuid[])'::regprocedure);
 d:=replace(d,'/ol.order_unit_quantity_base_snapshot','/nullif(ol.order_unit_quantity_base_snapshot,0)');
 d:=replace(d,'t.purchase_order_id,sum(', 't.purchase_order_id,bool_and(coalesce(ol.order_unit_quantity_base_snapshot>0 AND ol.tax_rate_snapshot IS NOT NULL AND rl.actual_unit_price IS NOT NULL,false)) terms_complete,sum(');
 d:=replace(d,'''expected_credit'',coalesce(c.amount,0)', '''terms_complete'',coalesce(c.terms_complete,true),''expected_credit'',coalesce(c.amount,0)'); EXECUTE d;
 d:=pg_get_functiondef('public.admin_record_procurement_reconciliation_v1(uuid,uuid,uuid,text,jsonb)'::regprocedure);
 d:=replace(d,'matched:=(p_payload', 'matched:=coalesce((source->>''terms_complete'')::boolean,false) AND (p_payload'); EXECUTE d;
 d:=pg_get_functiondef('public.store_closure_pending_v1(uuid)'::regprocedure);
 d:=replace(d,'''orders'',', '''kds_handoffs'',(SELECT count(*) FROM (SELECT order_id FROM emergency_fulfillment_items WHERE restaurant_id=p_store AND NOT is_cancelled AND floor_served_quantity+excused_quantity<ordered_quantity UNION ALL SELECT order_id FROM emergency_combo_component_items WHERE restaurant_id=p_store AND NOT is_cancelled AND floor_served_quantity+excused_quantity<ordered_quantity UNION ALL SELECT order_id FROM emergency_floor_direct_items WHERE restaurant_id=p_store AND NOT is_cancelled AND floor_served_quantity+excused_quantity<ordered_quantity)i WHERE NOT EXISTS(SELECT 1 FROM direct_order_financials f JOIN direct_delivery_fulfillment_tickets t ON t.request_id=f.request_id WHERE f.order_id=i.order_id AND t.status IN(''completed'',''cancelled''))),''orders'','); EXECUTE d;
END $$;
-- Compare the existing rows only; concurrently committed new receipts do not
-- change these immutable anchors. Nothing is written to a sales/payment ledger.
DO $preserve$
BEGIN
 IF EXISTS(SELECT 1 FROM lifecycle_store_anchors a LEFT JOIN public.restaurants r USING(id) WHERE r.id IS NULL OR a.fingerprint<>md5(jsonb_build_array(r.name,r.address,r.is_active,r.brand_id,r.tax_entity_id,r.short_code)::text))
 OR EXISTS(SELECT 1 FROM lifecycle_settings_anchors a LEFT JOIN public.restaurant_settings s USING(restaurant_id) WHERE s.restaurant_id IS NULL OR a.fingerprint<>md5(jsonb_build_array(s.kds_workflow,s.fulfillment_mode,to_jsonb(s)->'floor_direct_beverage_enabled')::text))
 OR EXISTS(SELECT 1 FROM lifecycle_user_anchors a LEFT JOIN public.users u USING(id) WHERE u.id IS NULL OR a.fingerprint<>md5(jsonb_build_array(u.auth_id,u.restaurant_id,u.brand_id,u.role,u.account_type,u.fixed_account_code,u.is_active)::text))
 OR EXISTS(SELECT 1 FROM lifecycle_assignment_anchors a LEFT JOIN public.emergency_station_assignments s USING(id) WHERE s.id IS NULL OR a.fingerprint<>md5(jsonb_build_array(s.restaurant_id,s.user_id,s.station_type,s.floor_label,s.is_active)::text))
 OR EXISTS(SELECT 1 FROM lifecycle_menu_anchors a LEFT JOIN public.menu_items m USING(id) WHERE m.id IS NULL OR a.fingerprint<>md5(jsonb_build_array(m.restaurant_id,m.name,m.name_vi,m.name_en,m.price,m.effective_vat_rate,m.is_archived,m.is_available,to_jsonb(m)->'size_prices',to_jsonb(m)->'meal_choices')::text))
 OR EXISTS(SELECT 1 FROM lifecycle_receipt_anchors a LEFT JOIN public.digital_receipts r USING(id) WHERE r.id IS NULL OR a.fingerprint<>md5(r.snapshot::text)) THEN
  RAISE EXCEPTION 'LIFECYCLE_RELEASE_EXISTING_DATA_DRIFT';
 END IF;
END $preserve$;
-- The official deploy gate records the bundle version after this transaction.
-- Component history is recorded atomically with the actual component DDL.
INSERT INTO supabase_migrations.schema_migrations(version,name,statements)
 SELECT version,name,ARRAY['Applied by atomic lifecycle release 20261022200000; canonical SHA256='||sha256] FROM lifecycle_release_components;
-- Safe both inside the atomic release and as a post-commit read-only verification.
DO $verify$
BEGIN
 IF (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version BETWEEN '20261021163000' AND '20261022193000' AND version<>'20261021230000')<>35
 OR to_regprocedure('public.admin_preview_store_registration_v1(uuid,uuid,jsonb,text)') IS NULL
 OR to_regprocedure('public.admin_get_store_lifecycle_v1(uuid)') IS NULL
 OR to_regprocedure('public.admin_transition_store_lifecycle_v1(uuid,bigint,text,text,text)') IS NULL
 OR to_regprocedure('public.inventory_lot_workspace_v1(uuid,uuid,uuid)') IS NULL
 OR to_regprocedure('public.procurement_demand_page_v1(uuid,uuid,jsonb)') IS NULL
 OR to_regprocedure('public.admin_get_order_quality_review_v1(uuid,uuid)') IS NULL
 OR to_regprocedure('public.process_payment(uuid,uuid,numeric,text)') IS NULL
 OR to_regprocedure('public.kds_complete_kitchen_batch_v1(uuid,jsonb)') IS NULL THEN
  RAISE EXCEPTION 'LIFECYCLE_RELEASE_API_OR_HISTORY_INCOMPLETE';
 END IF;
 IF EXISTS(SELECT 1 FROM public.restaurants r LEFT JOIN public.store_lifecycle l ON l.restaurant_id=r.id WHERE r.id IN('273b057e-3b69-46e3-93c1-6194c2802849','8bc9eef5-dcd5-46b1-b931-23f77132322c') AND (NOT r.is_active OR l.state IS DISTINCT FROM 'active' OR l.legacy_operational IS DISTINCT FROM true))
 OR EXISTS(SELECT 1 FROM public.store_workflow_configs WHERE restaurant_id IN('273b057e-3b69-46e3-93c1-6194c2802849','8bc9eef5-dcd5-46b1-b931-23f77132322c') AND active_id IS NOT NULL)
 OR EXISTS(SELECT 1 FROM public.users WHERE fixed_account_code='jgbt_tray1' AND is_active)
 OR NOT EXISTS(SELECT 1 FROM public.restaurant_settings WHERE restaurant_id='273b057e-3b69-46e3-93c1-6194c2802849' AND kds_workflow='kitchen_floor')
 OR NOT EXISTS(SELECT 1 FROM public.restaurant_settings WHERE restaurant_id='8bc9eef5-dcd5-46b1-b931-23f77132322c' AND kds_workflow='kitchen_tray_floor') THEN
  RAISE EXCEPTION 'LIFECYCLE_RELEASE_LEGACY_RUNTIME_DRIFT';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.emergency_station_assignments a JOIN public.users u ON u.id=a.user_id WHERE u.fixed_account_code='jgbt_floor_1f' AND a.floor_label='2F')
 OR NOT EXISTS(SELECT 1 FROM public.emergency_station_assignments a JOIN public.users u ON u.id=a.user_id WHERE u.fixed_account_code='jgbt_floor_2f' AND a.floor_label='3F') THEN
  RAISE EXCEPTION 'LIFECYCLE_RELEASE_JEONGABOK_FLOOR_DRIFT';
 END IF;
 IF has_function_privilege('anon','public.admin_get_store_lifecycle_v1(uuid)','EXECUTE')
 OR has_table_privilege('authenticated','public.inventory_lots','INSERT')
 OR has_table_privilege('authenticated','public.sales_reporting_batches','UPDATE')
 OR EXISTS(SELECT 1 FROM pg_class WHERE oid IN('public.inventory_lots'::regclass,'public.sales_reporting_batches'::regclass,'public.store_identity_transfers'::regclass) AND NOT relrowsecurity) THEN
  RAISE EXCEPTION 'LIFECYCLE_RELEASE_ACCESS_DRIFT';
 END IF;
END $verify$;
SELECT 'LIFECYCLE_RELEASE_VERIFY=PASS APIs, history, legacy runtime, floor mapping, private ledgers' AS result;
NOTIFY pgrst, 'reload schema';
COMMIT;
